void find(int pos, int count,int burnSnext,int burnEnext, vector<int>& x, vector<vector<long>>& memo){
    if(count == x.size())return;
    else{
        {
            long nt = memo[burnSnext][burnEnext] + (x[burnSnext] > pos ? x[burnSnext] - pos : (l + x[burnSnext]) - pos);
            if(burnSnext == burnEnext){
                if(maxVal < nt)maxVal = nt;
            }
            else if(memo[burnSnext + 1][burnEnext] < nt){
                memo[burnSnext + 1][burnEnext] = nt;
                find(x[burnSnext],count + 1,burnSnext + 1,burnEnext,x,memo);
            }
        }
        {
            long nt = memo[burnSnext][burnEnext] + (x[burnEnext] < pos ? pos - x[burnEnext] : (l + pos) - x[burnEnext]);
            if(burnSnext == burnEnext){
                if(maxVal < nt)maxVal = nt;
            }
            else if(memo[burnSnext][burnEnext - 1] < nt){
                memo[burnSnext][burnEnext - 1] = nt;
                find(x[burnEnext],count + 1,burnSnext,burnEnext - 1,x,memo);
            }
        }
    }

}


