ll l, n;

ll solve(VLL& x) {
  ll res = l - x[0];
  VLL acc(x.size()+1); rep(i, x.size()) acc[i+1] = acc[i] + x[i];
  rep(i, n/2) {
    ll tmp = acc[i+1] * 2 - x[i] + 2 * (l*(i+1) - acc[i*2+2] + acc[i+1]);
    chmax(res, tmp);
  }
  rep(i, (n-1)/2) {
    ll tmp = 2 * acc[i+1] + 2 * (l*(i+1) - acc[i*2+3] + acc[i+2]) + l - x[i+1];
    chmax(res, tmp);
  }
  return res;
}

int main() {
  IN >> l >> n;
  auto x = IN.vll(n);
  ll res = solve(x);
  rep(i, n) x[i] = l-x[i];
  reverse(all(x));
  OUT(max(res, solve(x)));
}

