ll calc(const vector<ll>& sumx, const vector<ll>& sumy, int n) {
  ll ret = 0;
  for(int d=0; d<n; d++) {
    // skip d-th tree at first
    ll now = 0;
    int cnt = n-d;
    int xpos = d+cnt/2;
    int ypos = (cnt-1)/2;
    now += (sumx[xpos] - sumx[d])*2;
    now += sumy[ypos]*2;
    if (cnt%2 == 0) {
      now += sumy[ypos+1] - sumy[ypos];
    } else {
      now += sumx[xpos+1] - sumx[xpos];
    }
    chmax(ret, now);
  }
  return ret;
}

