using namespace std;

long long memo[MAXN][MAXN][2];
int X[MAXN];
int N, L;

static long long dp(int left, int right, int last_left) {
	if (left + 1 == right)
		return 0;
	if (memo[left][right][last_left] > -1)
		return memo[left][right][last_left];
	long long first, second;
	if (last_left == 1) {
		first = X[left + 1] - X[left] + dp(left + 1, right, 1);
		second = X[left] + (L - X[right - 1]) + dp(left, right - 1, 0);		
	}
	else {
		first = X[right] - X[right - 1] + dp(left, right - 1, 0);
		second = (L - X[right]) + X[left + 1] + dp(left + 1, right, 1);
	}
	long long ans = max(first, second);
	memo[left][right][last_left] = ans;
	return ans;
}

