int l, n, x[N];

ll solvep(int cp, int cm) {
	assert(cp >= 1 && cm >= 0);
	int p = min(cp, cm + 1);
	int m = min(cm, cp);
	assert(p <= m + 1);
	assert(m <= p);
	ll sum = 0;
	for (int i = cp - p; i < cp; ++i) {
		sum += 2 * x[i];
	}
	for (int i = cm - m; i < cm; ++i) {
		sum += 2 * (l - x[n - 1 - i]);
	}
	sum -= x[cp - 1];
	return sum;
}

ll solvem(int cp, int cm) {
	assert(cp >= 0 && cm >= 1);
	int p = min(cp, cm);
	int m = min(cm, cp + 1);
	assert(p <= m);
	assert(m <= p + 1);
	ll sum = 0;
	for (int i = cp - p; i < cp; ++i) {
		sum += 2 * x[i];
	}
	for (int i = cm - m; i < cm; ++i) {
		sum += 2 * (l - x[n - 1 - i]);
	}
	sum -= l - x[n - 1 - (cm - 1)];
	return sum;
}

