i64 dfs(int i, int j, int k) {
    if (i + 1 == j) {
        return 0;
    }

    auto t = make_tuple(i, j, k);

    if (memo.count(t)) {
        return memo[t];
    } 

    i64 ret = 0;

    if (k == i) {
        ret = max(
            x[i + 1] - x[i] + dfs(i + 1, j, i + 1),
            x[i] + l - x[j - 1] + dfs(i, j - 1, j - 1)  
        );
    } else if (k == j) {
        ret = max(
            x[j] - x[j - 1] + dfs(i, j - 1, j - 1),
            l - x[j] + x[i + 1] + dfs(i + 1, j, i + 1)
        );
    } else {
        assert(false);
    }

    return memo[t] = ret;
}

