int64_t diff(int32_t big, int32_t small)
{
	assert(big >= small);
	int64_t right_pass = X[big] - X[small];
	if (right_pass < 0) {
		right_pass += L;
	}
	return right_pass;
}

int64_t func(int l, int r, bool left)
{
	if (l == r) { return 0; }

	auto& memo = dp[l][r][left];
	if (memo != -1) { return memo; }

	int64_t npos = 0;
	if (l == 0 && r == N) {
		npos = 0;
	}
	else if (left) {
		npos = X[l-1];
	}
	else {
		npos = X[r];
	}

	int64_t right_pass = 0;
	right_pass = npos - X[r - 1];
	if (right_pass < 0) {
		right_pass += L;
	}
	int64_t left_pass = 0;
	left_pass = (X[l] - npos);
	if (left_pass < 0) {
		left_pass += L;
	}

	return memo = std::max(func(l + 1, r, true) + left_pass, func(l, r - 1, false) + right_pass);
}

