	std::sort(X, X + N);

	tmp = X[N - 1];
	res = std::max(tmp, res);
	if (N % 2 == 0)
	{
		tmp = X[N - 1];
		for (int32_t c = 1; c < N / 2; c++)
		{
			tmp += 2 * (L - (X[N - 1] - X[N - 2 * c - 1]));

			tmp += 2 * (X[N - 1] - X[N - c]);
			tmp -= 2 * (X[N - c - 1] - X[N - 2 * c]);

			tmp -= (X[N - c] - X[N - c - 1]);
			res = std::max(tmp, res);
		}
	}
	else {

		tmp = X[N - 1] + L - 2 * (X[N - 1] - X[N - 2 * 1]);
		res = std::max(tmp, res);
		for (int32_t c = 2; c <= N / 2; c++)
		{
			tmp += 2 * (L - (X[N - 1] - X[N - 2 * c]));

			tmp += 2 * (X[N - 1] - X[N - c]);
			tmp -= 2 * (X[N - (c - 1) - 1] - X[N - 2 * (c - 1) - 1]);
			//tmp -= (X[N - c] - X[N - c - 1]);
			tmp -= (X[N - c + 1] - X[N - c]);
			res = std::max(tmp, res);
		}
	}

	out << res << endl;

	return 0;
}
