long long solve(vector<long long> X, long long L){
  long long N = X.size();
  vector<long long> C(N+1,0);
  for(int i = 1; i <= N; ++i) C[i] = C[i-1] + X[i-1];

  long long ans = max(L-X[0], X[N-1]);

  for(long long i = 1; i < N; ++i){
    long long j = N-i, m = min(i, j);
    long long l = L*m - (C[i+m] - C[i]) + C[i-1] - C[i-1-min(j,i-1)];
