using namespace std;

int opposite_distance(const vector<uint32_t>& trees, uint32_t l, size_t i, size_t j)
{
	assert(i != 0);
	assert(j != 0);
	uint32_t r_p = trees[i];
	uint32_t l_p = trees[trees.size() - j];
	auto ret = r_p + (l - l_p);
	return ret;
}

int distance_right(const vector<uint32_t>& trees, size_t i, size_t j)
{
	assert(i != 0);
	assert(j != 0);
	assert(j > i);
	auto ret = trees[j] - trees[i];
	return ret;
}

int distance_left(const vector<uint32_t>& trees, size_t i, size_t j)
{
	assert(i != 0);
	assert(j != 0);
	assert(j > i);
	auto ret = trees[trees.size() - i] - trees[trees.size() - j];
	return ret;
}

int main()
{
	int l, n;
	cin >> l >> n;


	vector<uint32_t> trees(n+1);
	for (int i = 0; i < n; i++) {
		cin >> trees[i+1];
	}

	// first: 右, second: 左
	vector < vector<pair<uint64_t, uint64_t>>> states(n + 1);
	for (auto& state : states) {
		state = vector<pair<uint64_t, uint64_t>>(n + 1);
	}

	//dp
	states[1][0].first = trees[1];
	states[0][1].second = l - trees[trees.size() - 1];
	for (int i = 2; i <= n; i++) {
		for (int j = 0; j <= i; j++) {
			// 右
			if (i - j != 0) {
				uint64_t from_left  = 0;
				uint64_t from_right = 0;
				if (j != 0) {
					from_left = states[i - j - 1][j].second + opposite_distance(trees, l, i - j, j);
				}
				if (i - j - 1 != 0) {
					from_right = states[i - j - 1][j].first + distance_right(trees, i - j - 1, i - j);
				}

				states[i - j][j].first = max(from_left, from_right);
			}

			// 左
			if (j != 0) {
				uint64_t from_left = 0;
				uint64_t from_right = 0;
				if (j - 1 != 0) {
					from_left = states[i - j][j - 1].second + distance_left(trees, j - 1, j);
				}
				if (i - j != 0) {
					from_right = states[i - j][j - 1].first + opposite_distance(trees, l, i - j, j);
				}

				states[i - j][j].second = max(from_left, from_right);
			}
		}
	}

	// 回答
	uint64_t max_value = 0;
	for (int i = 0; i <= n; i++) {
		uint64_t first  = states[i][n - i].first;
		uint64_t second = states[i][n - i].second;
		max_value = max(max_value, first);
		max_value = max(max_value, second);
	}
	cout << max_value << endl;

	return 0;
}

