long long recur(int i, int j, int w) {
    if (i == j) return 0;
    if (!dp[w][i][j]) {
        if (w == 0) {
            dp[w][i][j] = max(a[i + 1] - a[i] + recur(i + 1, j, 0),
                              a[i] + l - a[j] + recur(i + 1, j, 1));
        } else {
            dp[w][i][j] = max(a[j] - a[j - 1] + recur(i, j - 1, 1),
                              a[i] + l - a[j] + recur(i, j - 1, 0));
        }
    }
    return dp[w][i][j];
}

