    for (int i = 0; i < n; i++)
    {
        if (i) pf[i] = pf[i - 1];
        pf[i] += 2 * a[i];
    }
    for (int i = n - 1; i >= 0; i--)
    {
        if (n - i - 1) sf[i] = sf[i + 1];
        sf[i] += 2 * (L - a[i]);
    }
    //for (auto e : pf) cout << e << " "; cout << endl;
    //for (auto e : sf) cout << e << " "; cout << endl;
    pair<int, int> kek;
    kek.first = n / 2;
    kek.second = n % 2;
    for (int i = 0; i < n; i++)
    {
        if (kek.second == 0)
        {
            res = max(res, sf[kek.first] + pf[kek.first - 1] - (i ? pf[i - 1] : 0) - (L - a[kek.first]));
            kek.second = 1;
        }
        else
        {
            res = max(res, (kek.first + 1 < n ? sf[kek.first + 1] : 0) + pf[kek.first] - (i ? pf[i - 1] : 0) - a[kek.first]);
            kek.first++;
            kek.second = 0;
        }
    }
    //cout << res << endl << endl;
