const int INF = 1<<28;
const double EPS = 1e-8;
const int MOD = 1000000007;


int T, m;

ll solve(deque<ll> d) {
    deque<ll> ld, rd;
    ll sum = 0, rsum = 0, lsum = 0;
    while(d.size() > 1) {
        sum += lsum + rsum + d.front();
        rsum += d.front();
        rd.push_back(d.front()); d.pop_front();
        if (d.size() > 1) {
            sum += lsum + rsum + d.back();
            lsum += d.back();
            ld.push_back(d.back()); d.pop_back();
        }
        cout << sum << " " << lsum << " " << rsum << endl;
    }
    ll ans = sum;
    REP(i, m - 1) {
        sum -= lsum;
        sum += rsum - rd.front() * 2;
        ll x = rd.front();
        rd.pop_front();
        rd.front() += x;
        if ((ld.size() + rd.size()) % 2 == 1) {
            sum += d.back();
            lsum -= ld.back();
            rsum += d.back();
            rd.push_back(d.back());
            d.back() = ld.front();
            ld.pop_front();
        }
        ans = max(ans, sum);
    }
    return ans;
}

int main(int argc, char *argv[]){
    ios::sync_with_stdio(false);
    while(cin >> m >> m){
        deque<ll> d, revd;
        int p = 0;
        REP(i, m) {
            ll x;
            cin >> x;
            d.push_back(x - p);
            revd.push_front(x - p);
            p = x;
        }
        d.push_back(m - p);
        revd.push_front(m - p);
        cout << max(solve(d), solve(revd)) << endl;
    }
    return 0;
}

