using namespace std;
using ll = long long;


ll X[200002];
ll L;
int N;
ll memo[2010][2010][2];

ll dfs(int l, int r, int is_l) {
	if (r - l <= 1) return 0;
	if (memo[l + 1][r + 1][is_l] != -1) return memo[l + 1][r + 1][is_l];
	int nl = l + 1;
	int nr = r - 1;
	assert(0 <= nl && nr < N);
	ll ret = 0;
	if(is_l) {
		ret = max(ret, abs(X[(N + l) % N] - X[nl]) + dfs(nl, r, 1));
		ret = max(ret, L - abs(X[(N + l) % N] - X[nr]) + dfs(l, nr, 0));
	}else {
		ret = max(ret, L - abs(X[(N + r) % N] - X[nl]) + dfs(nl, r, 1));
		ret = max(ret, abs(X[(N + r) % N] - X[nr]) + dfs(l, nr, 0));
	}
	memo[l + 1][r + 1][is_l] = ret;
	return ret;
}


int main() {
	cin >> L >> N;

	for(int i=0;i<N;i++) {
		cin >> X[i];
	}

	assert(N <= 2000);
	if (N == 1) {
		cout << max(X[0], L - X[0]) << endl;
	}else {
		memset(memo, -1, sizeof(memo));
		ll ans = dfs(0, N, 1) + X[0];
		memset(memo, -1, sizeof(memo));
		ans = max(ans, dfs(-1, N - 1, 0) + L - X[N - 1]);
		cout << ans << endl;
	}

	return 0;
}

