using namespace std;

struct Node{
    ll pos;
    ll l;
    ll r;
    ll cost;
    bool operator< (const Node &r) const{
        return cost < r.cost;
    }
};

int main(){
    ios::sync_with_stdio(0);
    cin.tie(0);


    ll l, n;
    cin >> l >> n;
    vector<ll> x(n+1, 0);
    rep(i, n) cin >> x[i+1];

    queue<Node> que;
    que.push({1, 1, n+1, x[1]});
    que.push({n, 0, n, l-x[n]});

    ll maxx = 0;
    while(!que.empty()){
        Node node = que.front(); que.pop();
        if(abs(node.l-node.r) <= 1){
            maxx = max(maxx, node.cost);
            continue;//break;
        }

        ll lcost;
        if(node.pos < node.l+1) lcost = x[node.l+1]-x[node.pos];
        else                    lcost = x[node.l+1]+(l-x[node.pos]);

        ll rcost;
        if(node.r-1 < node.pos) rcost = x[node.pos]-x[node.r-1];
        else                    rcost = x[node.pos]+(l-x[node.r-1]);

        if(lcost == rcost){
            que.push({node.l+1, node.l+1, node.r, node.cost+lcost});
            que.push({node.r-1, node.l, node.r-1, node.cost+rcost});
        }
        else if(lcost < rcost) que.push({node.r-1, node.l, node.r-1, node.cost+rcost});
        else                   que.push({node.l+1, node.l+1, node.r, node.cost+lcost});
    }

    cout << maxx << endl;

    return 0;
}

