int l, n;
long long dfs(int pos, vector<int> rest, long long dist) {
  int sz = rest.size();
  if (sz == 0) return dist;
  int pos1 = rest.front(), pos2 = rest.back();
  long long dist1 = dist, dist2 = dist;
  if (pos > rest.front()) dist1 += l - pos + rest.front();
  else dist1 += rest.front() - pos;
  if (pos < rest.back()) dist2 += pos + l - rest.back();
  else dist2 += pos - rest.back();
  vector<int> rest2(rest);
  rest.erase(rest.begin());
