		}else{
			cerr << max(rui[pos][1] + rui[left][0], rui[pos][0] - rui[left][0]) << endl;
			return max(rui[pos][1] + rui[left][0], rui[pos][0] - rui[left][0]);
		}
	}

	llong ret1 = 0, ret2 = 0;
	if(pos < left){
		ret1 = dp(left, left+1, right) + rui[left][0] - rui[pos][0];
	}else{
		ret1 = dp(left, left+1, right) + rui[pos][1] + rui[left][0];
	}
	if(pos < right){
		ret2 = dp(right, left, right-1) + rui[pos][0] + rui[right][1];
	}else{
		ret2 = dp(right, left, right-1) + rui[right][1] - rui[pos][1];
	}

	// cerr << pos << " " << left << " " << right << " " << endl << ret1 << " " << ret2 << endl;

	return memo[PP(pos, P(left, right))] = max(ret1, ret2);
}

