ll solve() {
    function<ll(ll, ll, ll, ll)> traverse = [&](ll left, ll right, ll pos, ll length) {
        if (left > right) {
            cerr << length << endl;
            return length;
        }
        ll len_l = X[left] > pos ? X[left] - pos : L - pos + X[left];
        ll len_r = pos > X[right] ? pos - X[right] : L - X[right] + pos;
        if (len_l > len_r) {
            return traverse(left + 1, right, X[left], length + len_l);
        } else if (len_l < len_r) {
            return traverse(left, right - 1, X[right], length + len_r);
        } else {
            return max(traverse(left + 1, right, X[left], length + len_l),
                       traverse(left, right - 1, X[right], length + len_r));
        }
    };
    return traverse(0, N - 1, 0, 0);
}


