ll calc(int l, int r) {
    return psum[r] - (l? psum[l - 1] : 0);
}

void solve() {
    ans = max(ans, 1LL * L - X[0]);
    for(int i = 0; i < N; i++) {
        psum[i] = X[i];
        if(i) psum[i] += psum[i - 1];
    }
    for(int i = 0; i < N / 2; i++) {
        ll tmp = 0;
        tmp += 2 * psum[i];
        tmp += 2 * (1LL * L * i - calc(i + 2, 2 * i + 1)) + (L - X[i + 1]);
