            tmp = 0;
            tmp += 2 * psum[i];
            tmp += 2 * (1LL * L * (i + 1) - calc(i + 2, 2 * i + 2));
            tmp += (L - X[i + 1]);
            ans = max(ans, tmp);
        }
    }
}

