typedef vector<vector<int> > DP;

lint L;
DP dp;
lint cnt = 0;

lint calc(int i, int j, vector<lint> &X) {
  if(dp[i][j] != -1) return dp[i][j];

  lint val;
  if(i == j) val = 0;

  if(i < j) {
    val = max(calc(i+1, j, X) + X[i+1]-X[i], calc(j, i+1,X) + X[i] - X[j] + L);
  }

  if(i > j) {
    val = max(calc(i-1, j,X) + X[i]-X[i-1], calc(j, i-1,X) + X[j] - X[i] + L);
  }

  dp[i][j] = val;
  return val;
}
