    REP(i, N-1) {
      lint res2 = X[i+1];
      if(i != N-2) {
        lint p = N - i - 2;
        res2 += p*L;
        res2 += S[p+2+i] - S[2+i];
        res2 -= S[2*N-1] - S[2*N-p-1];
      }
      if(res == -1) {
        res = res2;
      } else {
        res = max(res, res2);
      }

    }

    for(lint i=N-1; i>0;i--) {
      lint j = N - i -1; 
      lint res2 = L-X[i-1];

      if(i != 1) {
        lint p = i - 1;
        res2 += p*L;
        res2 += S[p-1];
