#define LLINF 9223372036854775807
#define MOD ll(1e9+7)

vector<ll> ldiff(200006);
vector<ll> rdiff(200006);

ll solve_roughly(ll n, ll lnum2){
    ll lnum = n-lnum2;
    ll rnum = lnum2;
    ll tmpans = 0;
    ll lcnt = 1;
    for(int j = lnum-1; j >= 0; j--){
        tmpans += (min(2*lcnt-1,2*rnum+1))*ldiff[j];
        lcnt++;
    }
    ll rcnt = rnum;
    for(int j = 0; j < rnum; j++){
        tmpans += (min(2*rcnt,lnum*2))*rdiff[j];
        rcnt--;
    }
    return tmpans;

}

ll solve_roughly2(ll n, ll lnum2){
    ll lnum = n-lnum2;
    ll rnum = lnum2;
    ll tmpans = 0;
    ll lcnt = 1;
    for(int j = lnum-1; j >= 0; j--){
        tmpans += (min(2*lcnt,2*rnum))*ldiff[j];
        lcnt++;
    }
    ll rcnt = rnum;
    for(int j = 0; j < rnum; j++){
        tmpans += (min(2*rcnt-1,lnum*2+1))*rdiff[j];
        rcnt--;
    }
    return tmpans;
}

int main(){
    ll l, n;
    cin >> l >> n;
    vector<ll> x(n);
    vector<ll> left(n);
    vector<ll> right(n);
    for(int i = 0; i < n; i++){
        cin >> x[i];
    }
    for(int i = 0; i < n; i++){
        left[i] = l - x[n-1-i];
        right[i] = x[i];
    }
    ldiff[0] = left[0];
    rdiff[0] = right[0];
    for(int i = 0; i < n-1; i++){
        ldiff[i+1] = left[i+1]-left[i];
        rdiff[i+1] = right[i+1]-right[i];
    }
    ll ans = 0;

    ll ok = 0, ng = n;
    ll mid = (ok+ng)/2;
    while(abs(ok-ng)>80){
        ll t1 = solve_roughly(n,mid);
        ll t2 = solve_roughly(n,mid+30);
        if(t2-t1>0){ok = mid;}
        else{ng = mid;}
        mid = (ok+ng)/2;
    }

    for(int i = max(0LL,mid-1000LL); i <= min(n,mid+1000LL); i++){
        ll lnum = n-i;
        ll rnum = i;
        ll tmpans = 0;
        ll lcnt = 1;
        for(int j = lnum-1; j >= 0; j--){
            tmpans += (min(2*lcnt-1,2*rnum+1))*ldiff[j];
            lcnt++;
        }
        ll rcnt = rnum;
        for(int j = 0; j < rnum; j++){
            tmpans += (min(2*rcnt,lnum*2))*rdiff[j];
            rcnt--;
        }
        ans = max(ans, tmpans);
    }

    ok = 0, ng = n;
    mid = (ok+ng)/2;
    while(abs(ok-ng)>80){
        ll t1 = solve_roughly2(n,mid);
        ll t2 = solve_roughly2(n,mid+30);
        if(t2-t1>0){ok = mid;}
        else{ng = mid;}
        mid = (ok+ng)/2;
    }

    for(int i = max(0LL,mid-1000LL); i <= min(n,mid+1000LL); i++){
        ll lnum = n-i;
        ll rnum = i;
        ll tmpans = 0;
        ll lcnt = 1;
        for(int j = lnum-1; j >= 0; j--){
            tmpans += (min(2*lcnt,2*rnum))*ldiff[j];
            lcnt++;
        }
        ll rcnt = rnum;
        for(int j = 0; j < rnum; j++){
            tmpans += (min(2*rcnt-1,lnum*2+1))*rdiff[j];
            rcnt--;
        }
        ans = max(ans, tmpans);
    }
    cout << ans << endl;
    return 0;
}

