  while (!d.empty()) {
    // cout << hidari(iti, d.front(), l) << " " << migi(iti, d.back(), l) << " "
    //      << ans << " " << iti << endl;

    if (hidari(iti, d.front(), l) >= migi(iti, d.back(), l)) {
      ans += hidari(iti, d.front(), l);
      iti = d.front();
      d.pop_front();
    } else {
      ans += migi(iti, d.back(), l);
      iti = d.back();
      d.pop_back();
    }
  }
  cout << ans << endl;
}

