int main()
{
  ll l, n;
  cin >> l >> n;
  vector<ll> x(n);
  int more = 0, less = 0;
  for (auto &e : x)
  {
    cin >> e;
    if (e > l / 2)
      more++;
    else if (e < l / 2)
      less++;
  }
  bool check[20001] = {};

  ll ans = 0;
  int pos = 0, next = 0, last = n - 1;
  if (less < more)
  {
    ans += x[0];
    check[0] = true;
    pos = 0, next = 1;
  }
  else
  {
    ans += l - x[n - 1];
    check[n - 1] = true;
    pos = n - 1;
    last = n - 2;
  }

  while (true)
  {
    bool flag = true;
    for (int i = 0; i < n; ++i)
    {
      if (!check[i])
        flag = false;
    }
    if (flag)
      break;
    ll ndiff = 0, pdiff = 0;
    if (pos < next)
    {
      pdiff = x[next] - x[pos];
    }
    else
    {
      pdiff = l - x[pos] + x[next];
    }
    if (pos > last)
    {
      ndiff = x[pos] - x[last];
    }
    else
    {
      ndiff = l - x[last] + x[pos];
    }
    if (pdiff > ndiff)
    {
      ans += pdiff;
      check[next] = true;
      pos = next;
      next++;
    }
    else
    {
      ans += ndiff;
      check[last] = true;
      pos = last;
      last--;
    }
  }

  cout << ans << endl;

  return 0;
}

