template<class T> inline bool MX(T &l,const T &r){return l<r?l=r,1:0;}
template<class T> inline bool MN(T &l,const T &r){return l>r?l=r,1:0;}

int N;
LL L;
LL X[214514];
LL ans = 0;

void Process() {
  sort(X, X+N);

  int R = (N+1)/2;
  LL cand = 0;
  rep(i, R) {
    cand += X[i] * 2;
  }
  reps(i, R, N) {
    cand += (L-X[i]) * 2;
  }

  if (N%2) {
    cand -= X[R-1];
  } else {
    cand -= L - X[R];
  }
  MX(ans, cand);

  LL ini = cand;
  int pR = R;
  int idx = 0;
  int rem = N;
  while (rem > 0) {
    if (rem%2) {
      cand -= X[idx] * 2;
      cand += X[R-1];
      cand -= L - X[R];
    } else {
      cand -= X[idx] * 2;
      cand -= L - X[R];
      cand += X[R];
      R += 1;
    }
    MX(ans, cand);
    idx++;
    rem--;
  }
  assert(idx == N);
  assert(R == N);

  cand = ini;
  R = pR-1;
  rem = N;
  idx = N-1;
  while (rem > 0) {
    if (rem%2 == 0) {
      cand -= (L - X[idx]) * 2;
      cand += L - X[R+1];
      cand -= X[R];
    } else {
      cand -= (L - X[idx]) * 2;
      cand -= X[R];
      cand += L - X[R];
      R--;
    }
    MX(ans, cand);
    idx--;
    rem--;
  }
  assert(R == -1);
  assert(idx == -1);
}

