  cout<<fixed<<setprecision(0);

  cin >> L >> N;
  deque<LL> deq;
  rep(i, N) {
    cin >> X[i];
  }

  Process();
  rep(i, N) {
    X[i] = L - X[i];
  }
  Process();
  cout << ans << endl;
}

