int64 L, N;
vector<int64> X, l, r;

int64 calc(vector<int64>& ll, vector<int64>& rr){
	int32 l=0, r=0, t=0;
	int64 res = 0, sum = 0, len = 0;
	REP(i, N){
		if(i%2 == 0){
			r++;
			len += rr[r]-rr[r-1];
			sum += len;
		}else{
			l++;
			len += ll[l]-ll[l-1];
			sum += len;
		}
	}
	res = sum;
	REP(i, N){
		t++;
		if(l > 0){
			sum -= rr[t]+ll[l];
		}else{
			sum -= rr[t]-rr[-l];
		}
		if((N+i)%2 == 0){
			r++; l--;
		}
		sum += rr[r]-rr[t];
		res = max(res, sum);
	}
	return res;
}

int main(void){
	cin.tie(0);
