	cin >> L >> N;
	X.resize(N);
	REP(i, N) cin >> X[i];
	l.push_back(0);
	REP(i, N){
		l.push_back(X[i]);
	}
	l.push_back(L);
	REP(i, N+2) r.push_back(L-l[N+1-i]);
	int64 res = max(calc(l, r), calc(r, l));
	cout << res << endl;
}

