using INT = long long;

INT dist_f(INT pos, INT l, INT x)
{
	INT tmp = x - pos;
	return tmp < 0 ? tmp + l : tmp;
}

INT dist_b(INT pos, INT l, INT x)
{
	INT tmp = pos - x;
	return tmp < 0 ? tmp + l : tmp;
}

int main()
{
	unsigned long long ans = 0;

	INT l, n, *x;

	cin >> l >> n;

	x = new INT[n];
	for (size_t i = 0; i < n; i++)
	{
		cin >> x[i];
	}

	sort(x, x + n);

	INT pos = 0, nf = 0, nb = n - 1;
	for (size_t i = 0; i < n; i++)
	{
		auto df = dist_f(pos, l, x[nf]), db = dist_b(pos, l, x[nb]);
		if ( df > db )
		{
			pos = x[nf];
			nf++;
			ans += df;
			continue;
		}
		else
		{
			pos = x[nb];
			nb--;
			ans += db;
			continue;
		}
	}
	cout << ans << endl;
	return 0;
}

