const int MOD = 1000000007;

int dist(int src, int dst, int L, bool goCw) 
{
    int dist = 0;
    if (goCw) {
        dist = (src < dst) ? (src + L - dst) : (src - dst);
    } else {
        dist = (src < dst) ? (dst - src) : (L - src + dst);
    }
    return dist;
}

LL calc(const vector<int>& X, int L, bool firstCw, bool goCw)
{
    int head = 0;
    int tail = X.size()-1;
    int pos = firstCw ? X[tail--] : X[head++];
    LL total = dist(0, pos, L, firstCw);
    while (head <= tail) {
        int nextPos = goCw ? X[tail--] : X[head++];
        total += dist(pos, nextPos, L, goCw);
        goCw = !goCw;
        pos = nextPos;
    }
    return total;
}



int main()
{
    int L, N;
    cin >> L >> N;

    vector<int> X(N);

    rep(i,N) cin >> X[i];
    sort(X.begin(), X.end());

    LL ans = 0;
    rep(i,2) rep(j, 2) {
        ans = max(ans, calc(X, L, i, j));
    }

    cout << ans << endl;

    return 0;
}

