int L, N;
vector<int> X;
ll rec(int i, int j, int front, vector<vector<vector<ll>>>& memo) {
    // printf("%d %d %d", i, j, front);
    if (memo.at(i).at(j).at(front) != 0) {
        return memo.at(i).at(j).at(front);
    }
    else {
        ll max_dist;
        if (i == j) {
            max_dist = 0;
        }
        else {
            int head = X.at(i);
            int tail = X.at(j - 1);
            if (front == 1) {
                int k = X.at(i - 1);
                max_dist = max(rec(i + 1, j, 1, memo) + head - k, rec(i, j - 1, 0, memo) + L + k - tail);
            }
            else {
                int k = X.at(j);
                max_dist = max(rec(i + 1, j, 1, memo) + L + head - k, rec(i, j - 1, 0, memo) + k - tail);
            }
        }
        memo.at(i).at(j).at(front) = max_dist;
        return max_dist;
    }
}


