ll length_l(int i)
{
  int c_u = 0;	//とってないとこ
  int c_d = n - 1;
  ll le = 0;
  if (i == n - 1)
  {
    le = x[n - 1];
  }
  else
  {
    le += x[i];
    c_u = i + 1;
    int ps = -1;
    while (c_d - c_u > 0)
    {
      if (ps == -1)
      {
        le += x[c_u - 1] + l - x[c_d];
        c_d--;
        ps *= -1;
      }
      else
      {
        le += l - x[c_d + 1] + x[c_u];
        c_u++;
        ps *= -1;
      }
    }
    if (ps == 1)
    {
      le += max({x[c_d + 1] - x[c_d], l - x[c_d + 1] + x[c_d]});
    }
    else
    {
      le +=  max({x[c_d] - x[c_d - 1], l - x[c_d] + x[c_d - 1]});
    }
  }
  return le;
}

