typedef long long LL;
const int MAXN=200011;
LL ld[MAXN], rd[MAXN];
LL a[MAXN];
int n, m;
LL l, ans;

int main() {
	scanf("%lld%d", &l, &n);
	for(int i=1;i<=n;++i) {
		scanf("%lld", &a[i]);
	}
	ld[n]=0; ld[n-1]=l-(a[n]-a[n-1]);
	int pre=n;
	for(int i=n-2;i;--i) {
		if((n-i+1)&1) {
			ld[i]=ld[i+1]-(a[pre-1]-a[i+1])+(l-(a[pre]-a[i]));
		} else {
			ld[i]=ld[i+1]-(a[pre-1]-a[i+1])+(l-(a[pre-1]-a[i]));
			--pre;
		}
	}
	rd[1]=0; rd[2]=l-(a[2]-a[1]);
	pre=1;
	for(int i=3;i<=n;++i) {
		if(i&1) {
			rd[i]=rd[i-1]-(a[i-1]-a[pre+1])+(l-(a[i]-a[pre]));
		} else {
			rd[i]=rd[i-1]-(a[i-1]-a[pre+1])+(l-(a[i]-a[pre+1]));
			++pre;
		}
	}
	ans=0;
	for(int i=1;i<=n;++i) {
		ans=max(ans, a[i]+ld[i]);
		ans=max(ans, l-a[i]+rd[i]);
	}
	printf("%lld\n", ans);
	return 0;
}

#include <bits/stdc++.h>
