typedef long long ll;
typedef pair<int, int> pii;
typedef vector<int> vi;

#define RIGHT true
#define LEFT false

ll solve(ll L, int apos, int bpos, const vector<ll>& T, bool at) {
    ll res = 0;
    while (apos != bpos) {
        if (at == LEFT) {
            ll left = T[apos] - T[apos - 1];
            ll right = T[bpos] + L - T[apos];
            if (left == right) {
                return
                    res + max(
                            solve(L, apos - 1, bpos, T, at) + left,
                            solve(L, apos - 1, bpos, T, !at) + left);
            } else if (left > right) {
                res += left;
                apos--;
            } else {
                res += right;
                apos--;
                at = !at;
            }
        } else {
            ll right = T[bpos + 1] - T[bpos];
            ll left = T[bpos] + L - T[apos];
            if (left == right) {
                return
                    res + max(
                            solve(L, apos - 1, bpos, T, at) + left,
                            solve(L, apos - 1, bpos, T, !at) + left);
            } else if (left > right) {
                res += left;
                bpos++;
                at = !at;
            } else {
                res += right;
                bpos++;
            }
        }
    }
    return res;
}

ll go(ll L, const vector<ll> T) {
    return max(
            T[0] + solve(L, sz(T) - 1, 0, T, RIGHT),
            L - T[sz(T) - 1] + solve(L, sz(T) - 1, 0, T, LEFT));
}

int main() {
	cin.sync_with_stdio(0); cin.tie(0);
	cin.exceptions(cin.failbit);

    int L, N;
    cin >> L >> N;
    vector<ll> T(N);
    rep(i,0,N) cin >> T[i];

    if (N == 1) {
        cout << max(T[0], L - T[0]) << endl;
        return 0;
    }

    ll ans = go(L, T);
    reverse(all(T));
    trav(it, T) it = L - it;

    ans = max(ans, go(L, T));
    cout << ans << endl;
}

