int n, l;
int num[2*N];
ll psum[2*N];
int lb, rb;

int main(){
	scanf("%d%d", &l, &n);
	for(int i = 1; i <= n; i++){
		scanf("%d", &num[i]);
	}
	num[0] = 0;
	n++;
	for(int i = 0; i < n; i++) num[i + n] = num[i] + l;

	ll res = 0;
	for(int i = 1; i < 2 * n; i++){
		psum[i] = psum[i-1] + num[i];
	}
	for(int step = (n + 1) % 2; step < n; step += 2){

		int m1 = n - step;
		int rem = (n - 1 - step) / 2;
		int l1 = m1 - rem, r1 = n + rem;
		ll cur_res = (num[n] - num[m1]) + 2 * ((psum[r1] - psum[n]) - (psum[m1-1] - psum[l1-1]));
		res = max(res, cur_res + max(num[l1] - num[m1], num[m1] - num[r1]));
