		m1 = n + step;
		rem = (n - 1 - step) / 2;
		l1 = n - rem, r1 = m1 + rem;
		cur_res = (num[m1] - num[n]) + 2 * ((psum[r1] - psum[m1]) - (psum[n-1] - psum[l1-1]));
		res = max(res, cur_res + max(num[l1] - num[m1], num[m1] - num[r1]));
