using namespace std;

struct Config {
  int L;
  deque<int> trees;
};

Config readConfig() {
  Config output;
  size_t N;
  cin >> output.L >> N;
  while (output.trees.size() < N) {
    int t;
    cin >> t;
    output.trees.push_back(t);
  }
  return output;
}

int clockwiseDistance(int next, int curr, int L) {
  if (next < curr) {
    return curr - next;
  } else {
    return curr + (L - next);
  }
}

int counterClockwiseDistance(int next, int curr, int L) {
  if (next > curr) {
    return next - curr;
  } else {
    return next + (L - curr);
  }
}


int maxDistance(const deque<int>& trees, int current, int L, size_t frontOffset, size_t backOffset) {
  // get location of front and back trees
  auto front = trees.begin()[frontOffset];
  auto back = trees.rbegin()[backOffset];

  if (distance(trees.begin() + frontOffset, trees.end() - backOffset) == 1) {
    return max(counterClockwiseDistance(front, current, L), clockwiseDistance(back, current, L));
  }

  // move counterclockwise and recurse
  auto frontDistance = counterClockwiseDistance(front, current, L) + maxDistance(trees, front, L, frontOffset + 1, backOffset);
  // move clockwise and recurse
  auto backDistance = clockwiseDistance(back, current, L) + maxDistance(trees, back, L, frontOffset, backOffset + 1);

  return max(frontDistance, backDistance);
}

int recursive(const Config& config) {
  return maxDistance(config.trees, 0, config.L, 0u, 0u);
}

int main() {
  const auto config = readConfig();
  cout << "recursive: " << recursive(config) << endl;
  return 0;
}

