using namespace std;
template <class T, class U> inline void chmax(T & a, U const & b) { a = max<T>(a, b); }

ll solve1(ll perimeter, int n, vector<ll> const & x) {
    ll dist = 0;
    {  // compute the dist when start = 0
        const int start = 0;
        int l = start + 1;
        int r = n;
        dist += x[start];
        while (l != r) {
            dist += x[l - 1] + perimeter - x[r - 1];
            -- r;
            if (l == r) break;
            dist += x[l] + perimeter - x[r];
            ++ l;
        }
    }

    // compute the dist when start = n + 1
    ll answer = dist;
    REP (start, n - 1) {
        int last = start + (n - start) / 2;
        dist -= x[start];
        dist += x[last] - x[start];
        if ((n - start) % 2 == 0) {
            dist -= perimeter - x[last];
        } else {
            if (last != n - 1) {
                dist -= perimeter - x[last + 1];
            }
        }
        chmax(answer, dist);
    }
    return answer;
}

ll solve(ll perimeter, int n, vector<ll> const & x) {
    vector<ll> y(n);
    REP (i, n) y[i] = perimeter - x[n - i - 1];
    return max(solve1(perimeter, n, x), solve1(perimeter, n, y));
}

int main() {
    int l, n; cin >> l >> n;
    vector<ll> x(n);
    REP (i, n) cin >> x[i];
    cout << solve(l, n, x) << endl;
    return 0;
}

