priority_queue<Edge,vector<Edge>> qu;

void update(int last, int far, ll cost) {
    if (dp[last][far] < cost) {
        dp[last][far] = cost;
        qu.push({cost, last, far});
    }
}


ll solve(int last, int far) {
    if (last == 0 || last == n+1) return 0LL;
    if (last > far) {
        return L - (x[last] - x[far]) + solve(far, last+1);
    } else {
        return L - (x[last] - x[far]) + solve(far, last-1);
    }
}

