int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    ll L;
    int N;

    cin >> L >> N;

    vll X(N);
    for(int i=0;i<N;i++) cin >> X[i];

    sort(X.begin(), X.end());
    vll Y(N);
    for(int i=0;i<N;i++) Y[i] = L - X[N-1-i];

    vll S(N+1, 0);
    vll T(N+1, 0);
    for(int i=1;i<=N;i++) {
        S[i] = S[i-1] + X[i-1];
        T[i] = T[i-1] + Y[i-1];
    }

    ll best = max(X[N-1], Y[N-1]);
    for(int n=1; n<N; n++) {
        int m = N-n;
        ll cur = 0;
        if (n > m) {
            cur = max(2*(S[n] - S[n-m]) + 2*T[m] - min(X[n-1], Y[m-1]),
                      2*(S[n] - S[n-m-1]) + 2*T[m] - X[n-1]);
        } else if (m > n) {
            cur = max(2*S[n] + 2*(T[m] - T[m-n]) - min(X[n-1], Y[m-1]),
                      2*S[n] + 2*(T[m] - T[m-n-1]) - Y[m-1]);
        } else {
            cur = 2*(S[n] + T[m]) - min(X[n-1], Y[m-1]);
        }

        // cout << n << " " << cur << endl;
        best = max(best, cur);
    }

    cout << best << endl;

    return 0;
}

