#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
ll L, N;

ll solve(vector<ll> &A, vector<ll> &X) {
    ll res = -1;
    for(int i=1; i<=N; ++i) {
        ll tmp;
        if((i + N) % 2) {
            int m = (i + N + 1) / 2;
            tmp = 2LL * (A[m - 1] - A[i - 1]) + X[m - 1] - 2LL * (A[N] - A[m - 1]);
        } else {
            int m = (i + N) / 2;
            tmp = 2LL * (A[m] - A[i - 1]) - X[m - 1] - 2LL * (A[N] - A[m]);
        }
        tmp += (N - i) * L;
        res = max(res, tmp);
    }
    return res;
}

int main() {
    cin >> L >> N;
    vector<ll> X(N);
    vector<ll> Y(N);
    for(int i=0; i<N; ++i) {
        cin >> X[i];
    }
    for(int i=0; i<N; ++i) Y[i] = L - X[N - i - 1];

    vector<ll> A(N+1, 0);
    vector<ll> B(N+1, 0);
    for(int i=0; i<N; ++i) {
        A[i+1] = A[i] + X[i];
        B[i+1] = B[i] + Y[i];
    }

    ll res = max(solve(A, X), solve(B, Y));
    cout << res << endl;
}

