int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    ll L,N; cin >> L >> N;
    vector<ll> X(N);
    rep(i,N) cin >> X[i];

    ll ans = 0;
    auto solve=[&]() {
        vector<ll> S(N+1);
        rep(i,N) S[i+1] += S[i] + X[i];
        auto get=[&](int l, int r) {return S[r] - S[l];};

        rep(i,N) {
            ll val = L*(N-1-i);
            if ((N-1-i)&1) {
                int mid = (N+i+1)/2;
                val += get(i,mid)*2 - get(mid,N)*2;
                val += X[mid];
                chmax(ans,val);
            } else {
                int mid = (N+i+1)/2;
                val += get(i,mid)*2 - get(mid,N)*2;
                val -= X[mid-1];
                chmax(ans,val);
            }
        }
    };

    solve();
    rep(i,N) X[i] = L-X[i];
    reverse(all(X));
    solve();
    cout << ans << ln;
}

