int main(){
	cin >> L >> N;
	for(int i=0; i<N; i++) cin >> X[i];
	for(int i=0; i<N; i++) sum[0][i] = (i == 0 ? 0 : sum[0][i-1]) + 2*X[i];
	for(int i=N-1; i>=0; i--) sum[1][i] = (i == N-1 ? 0 : sum[1][i+1]) + 2*(L-X[i]);
	//時計回りで一気に
	LL ans = 0;
	for(int i=N-1; i>=0; i--){
		if(i == 0){
			ans = max(ans, L-X[0]);
			break;
		}
		LL tmp = (L - X[i]) * 2;
		if(i%2 == 0){
			tmp += sum[0][i/2-1];
			tmp += sum[1][i/2];
			tmp -= sum[1][i];
			tmp -= L-X[i/2];
		}
		else{
			tmp += sum[0][i/2];
			tmp -= X[i/2];
			tmp += sum[1][i/2+1];
			tmp -= sum[1][i];
		}
		ans = max(ans, tmp);
	}
	//反時計回りで一気に
	for(int i=0; i<N; i++){
		if(i == N-1){
			ans = max(ans, X[N-1]);
			break;
		}
		LL tmp = X[i] * 2;
		if((i+N)%2 == 0){
			tmp += sum[0][(N+i)/2-1];
			tmp -= sum[0][i];
			tmp += sum[1][(N+i)/2];
			tmp -= L-X[(N+i)/2];
		}
		else{
			tmp += sum[0][(N+i)/2];
			tmp -= sum[0][i];
			tmp -= X[(N+i)/2];
			tmp += sum[1][(N+i)/2+1];
		}
		ans = max(ans, tmp);
	}
	cout << ans << endl;
}

