#include <bits/stdc++.h>
using namespace std;

using LL = long long;
const LL maxn = 200200;
int n;
LL x[maxn], L;
bool vis[maxn];

LL gao(LL cx, int lo, int hi) {
  LL ret = 0;
  for(int i = 2; i <= n; i++) {
    LL left = -1, right = -1;
    if(!vis[lo]) {
      if(x[lo] < cx) {
        left = L - cx + x[lo];
      }
      else {
        left = x[lo] - cx;
      }
    }
    if(!vis[hi]) {
      if(x[hi] > cx) {
        right = cx + L - x[hi];
      }
      else {
        right = cx - x[hi];
      }
    }
    if(left > right) {
      vis[lo] = 1;
      cx = x[lo++];
    }
    else {
      vis[hi] = 1;
      cx = x[hi--];
    }
    ret += max(left, right);
  }
  return ret;
}

signed main() {
  // freopen("in", "r", stdin);
  while(~scanf("%lld%d",&L,&n)) {
    LL ret = 0;
    for(int i = 1; i <= n; i++) {
      scanf("%lld", &x[i]);
    }
    memset(vis, 0, sizeof vis);
    vis[1] = 1;
    ret = x[1] + gao(x[1], 2, n);
    memset(vis, 0, sizeof vis);
    vis[n] = 1;
    ret = max(ret, L-x[n]+gao(x[n], 1, n-1));
    printf("%lld\n", ret); 
  }
  return 0;
}

