}

#include <bits/stdc++.h>
using namespace std;
typedef long long LL;
constexpr LL MOD = 998244353;
LL dp[3001][3001];
class Solution {
  vector<int> A;
  LL L, N;
  LL DFS(int from, int to) {
    if (dp[from][to] != -1) return dp[from][to];
    if (from == to) return dp[from][to] = 0;
    if (from < to) {
      return dp[from][to] = max(
        DFS(to, from + 1) + A[from] + L - A[to],
        DFS(from + 1, to) + A[from + 1] - A[from]);
    }
    else {
      return dp[from][to] = max(
        DFS(to, from - 1) + L - A[from] + A[to],
        DFS(from - 1, to) + A[from] - A[from - 1]);
    }
  }
public:
  void run(istream &in, ostream &out) {
    in >> L >> N;
    A.resize(N);
    for (int i = 0; i < N; ++i) in >> A[i];
    memset(dp, -1, sizeof(dp));
    LL ans = DFS(0, N - 1) + A[0];
    out << max(ans, DFS(N - 1, 0) + L - A.back()) << '\n';
  }
};

