ll memo[2200][2200][2];
ll L, N;
ll x[2200];

ll rec(ll i, ll j, ll k) {
    if(i>j) return 0;

    if(memo[i][j][k]!=-1) return memo[i][j][k];

    ll res=0;
    if(k==0) {
        res=max(res, rec(i+1, j, 0)+x[i]-x[i-1]);

        res=max(res, rec(i, j-1, 1)+x[i-1]+L-x[j]);

    }else {
        res=max(res, rec(i+1, j, 0)+x[i]+L-x[j+1]);

        res=max(res, rec(i, j-1, 1)+x[j+1]-x[j]);

    }
    return memo[i][j][k]=res;
}




