ll dp[2020][2020][2];
ll X[2020];

ll l, N;

ll rec(ll R, ll L, bool is_right){
	if(dp[R][L][is_right]>=0) return dp[R][L][is_right];
	ll res;
	if(R==0 && L==N-1){
		if(is_right) res = X[0] + 2*(l-X[N-1]);
		else res = 2*X[0] + (l-X[N-1]);
	}else if(R==0 && is_right){
		res = X[0] + 2*(l-X[L]);
	}else if(L==N-1 && !is_right){
		res = 2*X[R] + (l-X[N-1]);
	}else{
		ll cand1, cand2;
		if(is_right){
			cand1 = rec(R-1, L, true) + (X[R]-X[R-1]);
			cand2 = rec(R-1, L, false) + (X[N-1]-X[L]) + (l-X[N-1]) + X[0] + (X[R]-X[0]);
		}else{
			cand1 = rec(R, L+1, true) + (X[N-1]-X[L]) + (l-X[N-1]) + X[0] + (X[R]-X[0]);
			cand2 = rec(R, L+1, false) + (X[L+1]-X[L]);
		}
		res = max(cand1, cand2);
	}
	dp[R][L][is_right] = res;
	return res;
}

int main(){
	cin >> l >> N;
	REP(i, N) cin >> X[i];

	if(N==1){
		cout << max(X[0], l-X[0]) << endl;
		} 
	REP(i, 2020)REP(j, 2020)REP(k, 2) dp[i][j][k] = -1;

	ll res = 0;

	REP(i, N-1)REP(k, 2){
		res = max(res, rec(i, i+1, k));
	}

	res = max(res, l-X[0]);
	res = max(res, X[N-1]);
	cout << res << endl;
    return 0;
}

