using ll = long long;

ll dists[2000001];
ll work[2000001];
ll max_from_left[2000001];
ll max_from_right[2000001];

int main()
{
  ll l, n;
  cin >> l >> n;
  ll sum = 0;
  ll prev = 0;
  for (int i = 0; i < n; i++) {
    ll pos;
    cin >> pos;
    dists[i] = pos - prev;
    sum += dists[i];
    prev = pos;
  }
  dists[n] = l - prev;
  if (n == 1) {
    printf("%lld\n", max(dists[0], dists[1]));
    return 0;
  }

  for (int i = 0; i < n+1; i++) {
    work[i] = dists[i];
    // printf("dist: %lld\n", dists[i]);
  }
  max_from_left[0] = dists[0];
  for (int i = 1; i < n+1; i++) {
    max_from_left[i] = max(dists[i], max_from_left[i-1]);
  }
  max_from_right[n] = dists[n];
  for (int i = n-1; 0 <= i; i--) {
    max_from_right[i] = max(dists[i], max_from_right[i+1]);
  }
  ll from_left = 0;
  int i;
  int right_pos = n;
  for (i = 0; (i < right_pos) && (max_from_right[i+1] > work[right_pos]); i++) {
    from_left += work[i];
    // printf("%lld\n", from_left);
    work[right_pos] += work[i];
  }
  //printf("%d, %d, %d\n", i, right_pos, max_from_right[i+1]);
  bool left = false;
  while (i < right_pos) {
    if (left) {
      from_left += work[i];
      // printf("from_left = %lld\n", from_left);
      work[right_pos] += work[i];
      i++;
    }
    else {
      from_left += work[right_pos];
      // printf("from_left %lld\n", from_left);
      work[i] += work[right_pos];
      right_pos--;
    }
    left = !left;
  }

  for (int i = 0; i < n+1; i++) {
    work[i] = dists[i];
  }
  ll from_right = 0;
  int left_pos = 0;
  for (i = n; (left_pos < i) && (max_from_left[i-1] > work[left_pos]); i--) {
    // printf("max_from_left[i-1] > work[left_pos] (%lld <= %lld)\n", max_from_left[i-1], work[left_pos]);
    from_right += work[i];
    // printf("%lld\n", from_right);
    work[left_pos] += work[i];
  }
  left = true;
  while (left_pos < i) {
    if (left) {
      from_right += work[left_pos];
      // printf("L -> %lld\n", from_right);
      work[i] += work[left_pos];
      left_pos++;
    }
    else {
      from_right += work[i];
      // printf("R -> %lld\n", from_right);
      work[left_pos] += work[i];
      i--;
    }
    left = !left;
  }
  printf("%lld\n", max(from_left, from_right));
  return 0;
}

