#define ll long long

int n, L;
vector <int> a, b;

ll get_sum(vector <ll> &s, int l, int r){
    if(r < l || l < 0 || r >= n) return 0;
    return s[r] - (l == 0 ? 0 : s[l - 1]);
}
ll calc(){
    vector <ll> sum_a(n), sum_b(n);
    sum_a[0] = a[0];
    sum_b[0] = b[0];
    for(int i = 1 ; i < n ; i++){
        sum_a[i] = sum_a[i - 1] + a[i];
        sum_b[i] = sum_b[i - 1] + b[i];
    }
    ll ret = 0;
    for(int i = 0 ; i < n ; i++){
        int len = min(i + 1, n - i - 1);
        if(i + 1 < n){
            ret = max(ret, 2 * (get_sum(sum_a, i - len + 1, i) + get_sum(sum_b, i + 1, i + len)) - min(a[i], b[i + 1]));
        }
        len = min(i, n - i - 1);
        ret = max(ret, 2 * (get_sum(sum_a, i - len, i - 1) + get_sum(sum_b, i + 1, i + len)) + max(a[i], b[i]));
    }
    return ret;
}
int main(){
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    cin >> L >> n;
    a.resize(n);
    for(auto &i : a) cin >> i;
    b.resize(n);
    for(int i = 0 ; i < n ; i++){
        b[i] = L - a[i];
    }
    ll ans = calc();
    reverse(a.begin(), a.end());
    reverse(b.begin(), b.end());
    swap(a, b);
    ans = max(ans, calc());
    cout << ans << endl;
}

