	vector<uint32_t> trees(n);
	for (int i = 0; i < n; i++) {
		cin >> trees[i];
	}
	vector<uint32_t> rtrees(n);
	auto ref = trees.rbegin();
	auto dst = rtrees.begin();
	while (ref != trees.rend()) {
		*dst = l - *ref;
		ref++;
		dst++;
	}

	uint64_t max_val = 0;
	// 左回り
	{
		int right_end = (n + 1) & 1;
		int right_pos = (n / 2) - 1;
		int left_pos  = ((n - 1) / 2);

		uint64_t dist = 0;
		for (int i = 0; i <= right_pos; i++) {
			dist += trees[i] * 2;
		}
		for (int i = 0; i <= left_pos; i++) {
			dist += rtrees[i] * 2;
		}

		if (right_end) {
			dist -= trees[right_pos];
		}
		else {
			dist -= rtrees[left_pos];
		}

		max_val = max(dist, max_val);

		for (int i = 1; i < n; i++) {
			right_end = 1 - right_end;

			dist -= 2 * rtrees[i - 1];
			if (!right_end) {
				dist -= trees[right_pos];
				dist += rtrees[left_pos + 1];
				right_pos--;
				left_pos++;
			}
			else {
				dist -= trees[right_pos];
				dist += rtrees[left_pos];
			}
			max_val = max(dist, max_val);
		}

	}
	// 左回り
	{
		int left_end = (n + 1) & 1;
		int left_pos = (n / 2) - 1;
