		for (int i = 0; i <= left_pos; i++) {
			dist += rtrees[i] * 2;
		}

		if (left_end) {
			dist -= rtrees[left_pos];
		}
		else {
			dist -= trees[right_pos];
		}

		max_val = max(dist, max_val);

		for (int i = 1; i < n; i++) {
			left_end = 1 - left_end;

			dist -= 2 * trees[i - 1];
			if (!left_end) {
				dist -= rtrees[left_pos];
