ll solve() {
	ll ans = 0;
	for (int i = 1; i < n; i++) {
		int j = n - i;
		if (j < i) {
			ans = max(ans, (a[i] - a[i - j]) * 2 + b[j] * 2 - y[j]);
			ans = max(ans, (a[i] - a[i - j]) * 2 + b[j] * 2 - x[i]);
		}
	}

	for (int i = 1; i < n; i++) {
		int j = n - i;
		if (i - 1 > j) {
			ans = max(ans, (a[i] - a[i - j - 1]) * 2 - x[i] + b[j] * 2);
		}
	}

	for (int i = 1; i < n; i++) {
		int j = n - i;
		if (i > j - 1) {
			ans = max(ans, (a[i] - a[i - j + 1]) * 2 + b[j] * 2 - y[j]);
		}
	}

	return ans;
}

