    }
    //! 時計回りにiまで進み、そこから交互に燃やす
    for (int i = N - 1; i >= 0; --i)
    {
        ll m = L - X[i] + dpR[i];
        //! X[0]->X[i-1]->X[1]->...
        max = std::max(m, max);
        //cout << "R:" << i << ":" << dpR[i] << endl;
    }
    cout << max << endl;
