	if(n>2001)return 0;
	LL ans=0;
	queue<pair<pair<int,int>,pair<int,LL>>> q;
	FOR(t,0,2){
		FOR(i,0,n-1){
			int l=0,r=n-1,nw=0,d=0;
			LL mx=0;
			if(t==0){
				mx=a[i];
				l=i+1;
				nw=i;
				d=0;
			}else{
				mx=lg-a[n-1-i];
				r=n-1-i-1;
				nw=n-1-i;
				d=1;
			}
			while(l<=r){
				if((sub(a[l],a[nw])==sub(a[nw],a[r]))){
					q.push(MP(MP(l,r),MP(nw,mx)));
				}
				if(sub(a[l],a[nw])>sub(a[nw],a[r])){
					mx+=sub(a[l],a[nw]);
					nw=l;
					l++;
					d=0;
				}else{
					mx+=sub(a[nw],a[r]);
					nw=r;
					r--;
					d=1;
				}
			}
			ans=max(mx,ans);
		}
	}
	while(q.size()){
		pair<pair<int,int>,pair<int,LL>> tpl=q.front();
		q.pop();
		int l=tpl.ST.ST,r=tpl.ST.ND,nw=tpl.ND.ST,d=0;
		LL mx=tpl.ND.ND;
		int f=1;
		while(l<=r){
			if(f==1){
				f=0;
				mx+=sub(a[l],a[nw]);
				nw=l;
				l++;
				d=0;
				continue;
			}else if((sub(a[l],a[nw])==sub(a[nw],a[r])&&d==1)){
				q.push(MP(MP(l,r),MP(nw,mx)));
			}
			if(sub(a[l],a[nw])>sub(a[nw],a[r])){
				mx+=sub(a[l],a[nw]);
				nw=l;
				l++;
				d=0;
			}else{
				mx+=sub(a[nw],a[r]);
				nw=r;
				r--;
				d=1;
			}
		}
		ans=max(mx,ans);
	}

	cout<<ans<<endl;
  return 0;
}

