		ll now = 0,m = (i+N+1)/2;
		if((i+N)%2==0){
			now = 2*(S[m]-S[i-1])- X[m] + (N-i)*L - 2*(S[N]-S[m]);
		}else{
			now = 2*(S[m-1]-S[i-1]) + (N-i)*L - 2*(S[N]-S[m-1]) + X[m];
