const int INF = 1 << 30;
vector<long long int> X;
long long int L, N;
long long int il, ir, in;

long long int search(long long int il, long long int ir, long long int in, long long int ans) {
	long long int left = 0, right = 0;
	if (ir == il) {
		if (il > in) left = X[il] - X[in];
		else left = (L - X[in]) + X[il];
		if (ir > in) right = (L - X[ir]) + X[in];
		else right = X[in] - X[ir];
		if (left > right) {
			in = il;
			ans += left;
			il++;
		}
		else {
			in = ir;
			ans += right;
			ir++;
		}
		return ans;
	}

	if (il > in) left = X[il] - X[in];
	else left = (L - X[in]) + X[il];
	if (ir > in) right = (L - X[ir]) + X[in];
	else right = X[in] - X[ir];
	if (left > right) {
		in = il;
		ans += left;
		il++;
		return search(il, ir, in, ans);
	}
	else if(left < right){
		in = ir;
		ans += right;
		ir--;
		return search(il, ir, in, ans);
	}
	else {
		if (il + 1 <= N) {
			if (0 <= ir - 1) {
				return max(search(il + 1, ir, il, ans + left), search(il, ir - 1, ir, ans + right));
			}
			else {
				return search(il + 1, ir, il, ans + left);
			}
		}
		else {
			return search(il, ir - 1, ir, ans + right);
		}

	}
}

