long long int go(long long int l, int y, int z){
	long long int go=z-y;
	if(go<0){
		go=go+l;
	}
	return go;
}
long long int re(long long int l, int y, int z){
	long long int go=y-z;
	if(go<0){
		go=go+l;
	}
	return go;
}
long long int kyori(long long int l,int n,int i,int m, int x[1000000]){
	long long int sum=0;
	if(i==0){
		sum=x[m];
		for(int j=0;n-j-1>m+j+1;j++){
			sum=sum+go(l, x[n-j-1],x[m+j+1]);
		}
		for(int j=0;n-j-1>m+j;j++){
			sum=sum+re(l, x[m+j], x[n-j-1]);
		}
		return sum;
	}else{
		sum=l-x[m];
		for(int j=0;m-j>j;j++){
			sum=sum+go(l, x[m-j],x[j]);
		}
		for(int j=0;m-1-j>j;j++){
			sum=sum+re(l, x[j],x[m-1-j]);
		}
		return sum;
	}
}


