#include<bits/stdc++.h>
using namespace std;
typedef long long ll;

ll tr[200005];
ll l,n;

ll dist(ll left, ll right, ll now){  
  ll ccw = tr[left] > now ? tr[left] - now : l - now + tr[left];
  ll cw = tr[right-1] > now ? now + l - tr[right-1] : now - tr[right-1];

  if(right == left){
    return 0;
  }else if(ccw > cw){
    return ccw + dist(left+1, right, tr[left]);
  }else if(ccw < cw){
    return cw + dist(left, right-1, tr[right-1]);
  }else if(cw == ccw){
    return max(ccw + dist(left+1, right, tr[left]), cw + dist(left, right-1, tr[right-1]));
  }
}


