int main(void) {
	ll L, N;
	cin >> L >> N;
	vector<ll> X(N, 0);
	REP(i, N) cin >> X[i];
	vector<ll> tl(N+10, 0L);
	vector<ll> tr(N+10, 0L);
	REP(i, N) tl[i+1] = X[i];
	REP(i, N) tr[i] = (L - X[i]);
	REP(i, N+1) tl[i+1] += tl[i];
	tr[0] = (L - X[0]);
	for(int i = N; i > 0; i--) tr[i-1] += tr[i];

	ll ans = 0L;
	REP(i, N) {
		int left = i, right = N - 1;
		ll res = 0L;
		int med = (right - left + 1) / 2;
		ll x = (tl[left + med] - tl[left]) * 2;
		res += x;
		ll y = (tr[right - med + 1] - tr[right+1]) * 2;
		res += y;
		left += med; right -= med; 
		if(left == right) res += X[left];
		else res -= (L - X[right+1]);
		ans = max(ans, res);
	}
	RREP(i, N) {
		int left = 0, right = i;
		ll res = 0L;
		int med = (right - left + 1) / 2;
		res += (tl[left + med] - tl[left]) * 2;
		res += (tr[right - med + 1] - tr[right+1]) * 2;
		left += med; right -= med;
		if(left == right) res += (L - X[right]);
		else res -= X[left-1];
		ans = max(ans, res);
	}
	cout << ans << endl;
}

