using namespace std;

typedef long long ll;

const int maxn = 200 * 1000 + 218;

int n;
ll partialSums[maxn];
ll rightSums[maxn];
ll leftSums[maxn];

ll PartialSum(int count) {
  return partialSums[count];
}

ll Compute(bool toTheRight, bool odd, int start, int count) {
  ll result = 0;
  ll sum = 0;

  if (!toTheRight) {
    sum = PartialSum(start) - PartialSum(start - count);
    ll weightedSum = rightSums[start] - rightSums[start - count];
    result = sum * (start + 1) - weightedSum;
  }

  if (toTheRight) {
    sum = PartialSum(start + count) - PartialSum(start);
    ll weightedSum = leftSums[n - start] - leftSums[n - start - count];
    result = sum * (n - start + 1) - weightedSum;
  }

  result *= 2;
  if (odd) {
    result -= sum;
  }
  return result;
}

ll Solve(vector<ll> a) {
  int n = a.size();

  for (int i = 0; i < n; ++i) {
    partialSums[i + 1] = partialSums[i] + a[i];
  }

  ll w = 0;
  for (int i = 0; i < n; ++i) {
    w++;
    rightSums[i + 1] = rightSums[i] + a[i] * w;
  }

  w = 0;
  for (int i = n - 1; i >= 0; --i) {
    w++;
    leftSums[n - i] = leftSums[n - i - 1] + a[i] * w;
  }

  ll result = 0;
  for (int k = 0; k + 1 <= n; ++k) {
    int r = n - k - 1;
    int l = k;
    if (r > l) continue;

    // Odd case:
    ll current = Compute(true, true, k + 1, r) + Compute(false, false, k, r - 1) + PartialSum(l - r + 1) * 2 * r;
    result = max(result, current);

    if (l == r) continue;
    // Even case:
    current = Compute(true, false, k + 1, r) + Compute(false, true, k, r) + PartialSum(l - r) * (2 * r + 1);
    result = max(result, current);
  }
  return result;
}

