			return mm - p;
		else
			return L - p + mm;
	}
	else
	{
		//
		//右
		if (p < mm)
			return p + L - mm;
		else
			return p - mm;

	}
	return 0;
}

int main(void)
{
	cin >> L >> N;

	X = new unsigned long long int[N];

	for (int i = 0; i < N; i++)
		cin >> X[i];

	unsigned long long int left = 0 , right = N - 1;

	unsigned long long int mm = 0;

	unsigned long long int p = 0;

	bool flag = false;
	unsigned long long int cnt = 0;

	left = 0;
	right = N - 1;
	cnt = 0;
	p = 0;

	int tree_num = N;
	while(1)
	{
		if (tree_num == 0)
			break;
		unsigned long long int pl , pr;
		pl = PPP(p, X[left], true);
		pr = PPP(p, X[right], false);

		if (pl > pr)
		{
			p = X[left];
			mm += pl;
			left++;
		}
		else
		{
			p = X[right];
			mm += pr;
			right--;
		}

		tree_num--;
		cnt++;
	}

	cout << mm << endl;

	return 0;
}

