ll L, N;

ll go_forward(int from, int to) {
	if (to >= from) {
		return Xs[to] - Xs[from];
	}
	else {
		return Xs[to] + (L - Xs[from]);
	}
}

ll go_backward(int from, int to) {
	if (to <= from) {
		return Xs[from] - Xs[to];
	}
	else {
		return Xs[from] + (L - Xs[to]);
	}
}

