int search(
  int l,
  int n,
  int* x,
  int z,
  int leng
  )
{
  int i, leng0, leng1, add, k;
  int j;
  int z_ = z;
  //cout << " z=" << z << " leng=" << leng << "\n";
  //for(i=0; i<n; i++){
  //  cout << x[i] <<" ";
  //}
  //cout << "\n";
  if(n!=1){
    for(j=0; j<=1; j++, z=z_){
      for(i=0; i<n-1; i++){
        if(z < x[0] || x[n-1] < z){
          i = n-1;
          break;
        }
        if(x[i] < z && z < x[i+1]){
          break;
        }
      }
      if(j==0){ // 時計回り
        int x_[n];
        for(k=0; k<n; k++){
          x_[k] = x[k];
        }
        add = z - x[i];
        if(i!=n-1){
          z = x[i];
          for(; i<n-1; i++){
            x_[i] = x_[i+1];
          }
        }else{ // i = n-1
          add = (add+l) % l;
          z = x[i];
        }
        leng0 = leng + add;
        if(n!=1){
          leng0 = search(l, n-1, &x_[0], z, leng0);
        }
      }
      else{// 反時計回り
        int x__[n];
        for(k=0; k<n; k++){
          x__[k] = x[k];
        }
        if(i!=n-1){
          leng += x[i+1] - z;
          z = x[i+1];
          for(; i<n-2; i++){
            x__[i+1] = x__[i+2];
          }
        }else{
          leng += (- z + x[0] + l) % l;
          //if(z > x_[n-1]){
          //  leng += l;
          //}
          z = x[0];
          for(i=0; i<n-1; i++){
            x__[i] = x__[i+1];
          }
        }
        if(n==1){
          leng1 = leng;
        }else{

          leng1 = search(l, n-1, &x__[0], z, leng);
        }
      }
    }
  }else{
    if(x[0]<z){
      leng0 = leng + z-x[0];
      leng1 = leng + l-z+x[0];
    }else{
      leng0 = leng + l+z-x[0];
      leng1 = leng + -z+x[0];
    }
  }
  return max(leng0, leng1);
}

