#include <stdio.h>
#include <stdlib.h>
#include <math.h>

enum Dir {
	d_head,
	d_tail
};

long move(long l,enum Dir dir,long x[],int num,long now)
{
	if (dir == d_head) {
		if (x[num] > now) return x[num] - now;
		else              return x[num] + l - now;
	} else if (dir == d_tail) {
		if (x[num] < now) return now - x[num];
		else              return l - x[num] + now;
	}
}

long searchAll(long l,int n,long x[])
{
	int num,head,tail,counter;
	long i,j,res,now,dist,dist_max;
	enum Dir dir;

	dist_max = 0;

	for (i=0;i<pow(2,n);i++) {
		now = 0;
		head = 0;
		tail = n-1;
		dist = 0;
		for (counter=0,j=1;counter<n;counter++,j*=2) {
			res = i & j;
			if (res == 0) {
				// to head
				dir = d_head;
				num = head;
				head += 1;
			} else {
				// to tail
				dir = d_tail;
				num = tail;
				tail -= 1;
			}
			dist += move(l,dir,x,num,now);
			now = x[num];
		}
		if (dist_max < dist) dist_max = dist;
	}

	return dist_max;
}

long searchGreedy(long l,int n,long x[])
{
	int num,head,tail,counter;
	long i,now,dist,toHead,toTail;
	enum Dir dir;

	now = 0;
	head = 0;
	tail = n-1;
	dist = 0;

	for (i=0;i<n;i++) {
		dir = d_head;
		toHead = move(l,dir,x,head,now);
		dir = d_tail;
		toTail = move(l,dir,x,tail,now);

		if (toHead > toTail) {
			dist += toHead;
			now = x[head];
			head += 1;
		} else {
			dist += toTail;
			now = x[tail];
			tail -= 1;
		}
	}
	return dist;
}

