using namespace std;

int opposite_distance(const vector<uint32_t>& trees, uint32_t l, size_t i, size_t j)
{
	assert(i != 0);
	assert(j != 0);
	uint32_t r_p = trees[i];
	uint32_t l_p = trees[trees.size() - j];
	auto ret = r_p + (l - l_p);
	return ret;
}

int distance_right(const vector<uint32_t>& trees, size_t i, size_t j)
{
	assert(i != 0);
	assert(j != 0);
	assert(j > i);
	auto ret = trees[j] - trees[i];
	return ret;
}

int distance_left(const vector<uint32_t>& trees, size_t i, size_t j)
{
	assert(i != 0);
	assert(j != 0);
	assert(j > i);
	auto ret = trees[trees.size() - i] - trees[trees.size() - j];
	return ret;
}

int main()
{
	int l, n;
	cin >> l >> n;

	if (n > 2000) return 0;

	vector<uint32_t> trees(n+1);
	for (int i = 0; i < n; i++) {
		cin >> trees[i+1];
	}

	// first: 右, second: 左
	vector < vector<pair<uint64_t, uint64_t>>> states(n + 1);
	for (auto& state : states) {
		state = vector<pair<uint64_t, uint64_t>>(n + 1);
	}

	//dp
	states[1][0].first = trees[1];
	states[0][1].second = l - trees[trees.size() - 1];
	for (int i = 2; i <= n; i++) {
		for (int j = 0; j <= i; j++) {
			// 右
			if (i - j != 0) {
				uint64_t from_left  = 0;
				uint64_t from_right = 0;
				if (j != 0) {
					from_left = states[i - j - 1][j].second + opposite_distance(trees, l, i - j, j);
				}
				if (i - j - 1 != 0) {
					from_right = states[i - j - 1][j].first + distance_right(trees, i - j - 1, i - j);
				}

				states[i - j][j].first = max(from_left, from_right);
			}

			// 左
			if (j != 0) {
				uint64_t from_left = 0;
				uint64_t from_right = 0;
				if (j - 1 != 0) {
					from_left = states[i - j][j - 1].second + distance_left(trees, j - 1, j);
				}
				if (i - j != 0) {
					from_right = states[i - j][j - 1].first + opposite_distance(trees, l, i - j, j);
				}

				states[i - j][j].second = max(from_left, from_right);
			}
		}
	}

	// 回答
	uint64_t max_value = 0;
	for (int i = 0; i <= n; i++) {
		uint64_t first  = states[i][n - i].first;
		uint64_t second = states[i][n - i].second;
		max_value = max(max_value, first);
		max_value = max(max_value, second);
	}
	cout << max_value << endl;

	return 0;
}

#include <bits/stdc++.h>
#define N 200002
using namespace std;
int n,L,X[N*3];
long long ans;
stack <int> s1,s2;
int dis(int x,int y){return y>x ? y-x:L+y-x;}
long long calc(int x,int d){
    if(d==1){
        int y=s1.top();
        s1.pop();
        if(x==y)return 0;
        return dis(x,y)+calc(y,-1);
    }
    else{
        int y=s2.top();
        s2.pop();
        if(x==y)return 0;
        return dis(y,x)+calc(y,1);
    }
}
void solve(){
    for(int i=n;i;--i)s1.push(X[i]);
    for(int i=1;i<=n;++i)s2.push(X[i]);
    long long sum=calc(0,1);
    ans=max(ans,sum);
    for(int i=n+1;i<=n*3+2;++i)X[i]=X[i-n-1];
    int l=(n+1)/2+1,r=n+1+(n+1)/2;
    for(int i=n+2;i<n*2+1;++i)
        if(i&1){
            sum+=dis(X[i],X[r])-dis(X[l],X[i]);
            ans=max(ans,sum);
        }
        else{
            sum+=dis(X[i],X[r+1])-dis(X[l],X[i]);
            ans=max(ans,sum);
            ++l,++r;
        }
}
int main(){
    scanf("%d%d",&L,&n);
    for(int i=1;i<=n;++i)scanf("%d",&X[i]);
    solve();
    for(int i=1;i<=n;++i)X[i]=L-X[i];
    for(int i=1;i<=n/2;++i)swap(X[i],X[n-i+1]);
    solve();
    cout<<ans<<endl;
}

