              else if (i <= N) tmp += dist2[i]*(2*(i-(N+l+2)/2)-1);
              else tmp += dist2[i]*(N-l-1);
          } else {
              if (i <= l+1) tmp += dist2[i]*(N-l);
              else if (N+l-2*i+2 >= 0) tmp += dist2[i]*(N+l-2*i+2);
              else if (i <= N) tmp += dist2[i]*(i-(N+l+1)/2 - 1)*2;
              else tmp += dist2[i]*(N-l-1);
          }
      }
      ma = max(ma, tmp);
      for (int r = 1; r+l < N; ++l) {
          if ((N-(l+r))%2 == 0) {
              tmp += L - 2*X2[l+(N-(l+r))/2 - 1] - dist2[l+(N-(l+r))/2+1 - 1];
          } else {
              tmp += L - 2*X2[l + (N-(l+r)+1)/2 - 1];
          }
          ma = max(ma, tmp);
      }
  }

  cout << ma << endl;
}

