      ans -= (X[max]);
      while(1) {
         if (idR == -1) break;
         ans += 2 * X[idR];
         idR--;
         if (idL == N) break;
         ans += 2 * (L - X[idL]);
         idL++;
      }
      max_ans =  ans>max_ans?ans:max_ans;
   }
   {
      long long ans = 0;
      int idR = max-1;
      int idL = max;
      ans -= (L-X[max]);
      while(1) {
         if (idL == N) break;
         ans += 2 * (L - X[idL]);
         idL++;
         if (idR == -1) break;
         ans += 2 * X[idR];
         idR--;
      }
      max_ans =  ans>max_ans?ans:max_ans;
      // cout<<ans<<endl;
   }
   return max_ans;
}

long long GetMaxLenDiff(int max) {
   return GetMaxLen(max+1)-GetMaxLen(max);
}

