    vector<bool> used(n*2);
    long cp=l;
    for (int i = 0; i < n; ++i) {
        bloop:;
        auto itl=lower_bound(x.begin(),x.end(),cp);
        auto itu=upper_bound(x.begin(),x.end(),cp);
        --itl;
        while(used[itl-x.begin()]){
            if(itl==x.begin()){
                cp+=l;
                goto bloop;
            }
            --itl;
        }
        while(used[itu-x.begin()]){
            if(itu==x.end()){
                cp-=l;
                goto bloop;
            }
            ++itu;
        }

        int dl=abs(cp-*itl),du=abs(*itu-cp);

        if(dl<du){
            ans+=du;
            used[itu-x.begin()]=true;
            if(itu-x.begin()>=n)used[itu-x.begin()-n]=true;
            else used[itu-x.begin()+n]=true;
            cp=*itu;
        }
        else {
            ans+=dl;
            used[itl-x.begin()]=true;
            if(itl-x.begin()>=n)used[itl-x.begin()-n]=true;
            else used[itl-x.begin()+n]=true;
            cp=*itl;
        }
    }
    cout<<ans<<endl;
    return 0;
}

