ll getlength(ll x[],ll n,ll i,ll l){
    vector<ll> a(n,0);
    a[i]=1;
    ll ans=0;
    ll pnum=i;

    while(true){
        ll k1=0,k2=0;
        k1=(i+1+n)%(n)+1;
        k2=(i-1+n)%(n)+1;
        if (a[k1]+a[k2]==2)return ans;
        if (a[k1]==1){
            k1=(i-2+n)%(n)+1;

        }else if (a[k2]==1){
            k2=(i+2+n)%(n)+1;

        }
        //候補二つから選ぶ
        ll a1=abs(x[k1]-x[pnum]);
        ll a2=abs(x[k2]-x[pnum]);
        if(pnum>k1)a1=max(a1,(l-x[pnum])+x[k1]);
        if(pnum>k2)a2=max(a2,(l-x[pnum])+x[k2]);
        if(pnum<k1)a1=max(a1,x[pnum]+(l-x[k1]));
        if(pnum<k2)a2=max(a2,x[pnum]+(l-x[k2]));
        if (a1<a2){ans+=a2;a[k2]=1;pnum=k2;}
        else{ans+=a1;a[k1]=1;pnum=k1;}
    }

    return ans;

}

