    x[0]=0;
    for(int i=1;i<=n;i++){
        cin >>x[i];
    }
    for(int i=1;i<=n;i++){
        ans=max(ans,getlength(x,n,i,l));
    }
    cout <<ans<<endl;

    return 0;
}

