int main() {
  int l, n;
  cin>>l>>n;
  vecll x(n);
  REP(i,n)cin>>x[i];
  vecll psum(n+2);
  partial_sum(ALL(x), begin(psum)+1);
  psum.back() = psum[n] + l;
  vecll fwd0(n+2, 0);
  vecll fwd1(n+2, 0);
  FOR(i,1,n) {
    ll start0 = 0;
    ll start1 = 0;
    ll rnum = n-1-i;
    if (i > rnum) {
      start0 = i - rnum;
      start1 = i - rnum - 1;
    }
    fwd0[i] = (psum[i] - psum[start0]) * 2;
    fwd1[i] = (psum[i] - psum[start1]) * 2;
  }
  vecll bwd0(n+2, 0);
  vecll bwd1(n+2, 0);
  REP(ri,n-1) {
    ll i = n-ri;
    ll num = ri+1;
    ll start0 = n+1;
    ll start1 = n+1;
    ll rnum = n-1-num;
    if (num > rnum) {
      start0 = i-1 + rnum;
      start1 = i-1 + rnum + 1;
    }
    bwd0[i] = (l * (start0 + 1 - i) - (psum[start0] - psum[i-1])) * 2;
    bwd1[i] = (l * (start1 + 1 - i) - (psum[start1] - psum[i-1])) * 2;
  }
  ll mx = 0;
  FOR(i,0,n) {
    int fi = i-1;
    int fnum = fi+1;
    int bi = i+1;
    int bnum = n-bi;
    mx = max(mx, fwd0[fi+1] + x[i] + bwd0[bi+1]);
    mx = max(mx, fwd0[fi+1] + (l - x[i]) + bwd0[bi+1]);
    if (fnum > bnum) {
      mx = max(mx, fwd1[fi+1] + (l - x[i]) + bwd0[bi+1]);
    }
    if (fnum < bnum) {
      mx = max(mx, fwd0[fi+1] + x[i] + bwd1[bi+1]);
    }
  }
  cout << mx << endl;
  return 0;
}

