#include <iostream>
#include <vector>

using namespace std;
typedef long long ll;

int main()
{

    ll L, N;
    cin>>L>>N;
    vector<ll> clock;
    vector<ll> counterClock;
    vector<ll> sum_a(N+1, 0);
    vector<ll> sum_b(N+1, 0);
    clock.resize(N);
    counterClock.resize(N);

    for(ll i=0; i<N; ++i)
    {
        ll num;
        cin>>num;
        counterClock[i]=num;
    }

    for(ll i=0; i<N; ++i)
        clock[i]=(L-counterClock[N-1-i]);

    //まずは計算量節約のために合計を計算する
    for(ll i=0; i<N; ++i)
        sum_a[i+1] = sum_a[i] + counterClock[i];

    for(ll i=0; i<N; ++i)
        sum_b[i+1] = sum_b[i] + clock[i];

    ll ans=0; //答えを格納する箱

    //kkを半時計回りと時計回りの本数差とする
    //方針としては反時計周りで当たる本数をLとしてこのLの総当りでやっていく
    //まずは半時計回りスタートとして考える
    for(ll kk=0; kk<N; ++kk)
    {
        //まずは中心点を求める
        long p=(N-kk)/2;
        ll sum=0; //毎回のループの結果を格納

        //周回する場合は2種類あり、ひとつは半時計回りが多めに回る場合と半時計回りと時計回りが同じ場合の2種類がある
        if((N-kk)%2==0)//周回数が同じ
        {
            sum += (sum_a[kk+p]-sum_a[kk])*2; //反時計回りの場合の歩く距離
            //時計回りで終了するので
            sum += ((sum_b[p-1])*2+clock[p-1]);
        }
        else//半時計回りで終了する場合
        {
            sum += (sum_a[kk+p]-sum_a[kk])+counterClock[kk+p];
            sum += ((p>0)? sum_b[p]*2 : 0);
        }

        if(sum>ans)
            ans = sum;
    }

    //次に時計回りスタートの場合を考える
    for(ll kk=0; kk<N; kk++)
    {
        //まずは中心点(行ける最大値までを求める)
        //kkはスタート位置として考えても良い
        long p= (N-kk)/2;
        ll sum = 0;

        if((N-kk)%2==0)
        {
            /*
             * この場合clockwiseはp+1までいけてcounterClockWiseはpまでいける。
             * ただし半時計回りで終了するので半時計回りの方は最後は片道分だけをたせばok
             */
            sum += (sum_b[kk+p]-sum_b[kk])*2;
            sum += ((sum_a[p-1])*2+counterClock[p-1]);
        }
        else
        {
            /*
             * この場合は時計回りのほうがpまで行って終了する
             */
            sum+= (sum_b[kk+p]-sum_b[kk])*2 + clock[kk+p];
            sum += (p>0 ? (sum_a[p])*2 : 0);
        }

        if(sum>ans)
            ans = sum;
    }


    cout<<ans<<endl;


    return 0;
}

