    auto naive = [&](const int s) {
        bool clock = false;
        ll sum = X[s];
        std::set<int> res;
        for (int i = s + 1; i < N; i++) { res.insert(i); }
        for (int p = s; not res.empty(); clock = not clock) {
            if (clock) {
                const int nxt = *res.begin();
                sum += cwd(p, nxt), res.erase(nxt), p = nxt;
            } else {
                const int nxt = *res.rbegin();
                sum += cwd(nxt, p), res.erase(nxt), p = nxt;
            }
        }
        return sum;
    };
