int main()
{
    const ll L = read<ll>();
    const int N = read<int>();
    auto X = readVec<ll>(N);
    auto d = [&](const int s, const int t, const bool cl) {
        const ll l = (t > s ? X[t] - X[s] : X[t] - X[s] + L);
        return cl ? l : L - l;
    };
    auto solve = [&]() -> ll {
        int s = 0;
        ll ans = X[s];
        int p = s;
        for (;;) {
            const bool small = 2 * p < N;
            const int nxt = (small ? N - 1 - p : N - p);
            if (p == nxt) { break; }
            if (small ^ (p < nxt)) { break; }
            ans += d(p, nxt, nxt < p), p = nxt;
        }
        int t = p;
        ll sum = ans;
        SHOW(t, ans);
        bool small = 2 * t < N;
        for (int i = 0; i < N - 2; i++) {
            if (N % 2 == 1) {
                sum += d(s, t, true) - d(small ? (t + 1) % N : t, s, true);
            } else {
                sum += d(s, small ? (t + N - 1) % N : t, true) - d(t, s, true);
            }
            chmax(ans, sum);
            s = (s + 1) % N, t = (t + 1) % N;
            SHOW(s, t, sum);
        }
        return ans;
    };
    ll ans = std::max(L - X.front(), X.back());
    chmax(ans, solve());
