  if (n == 1) {
    printf("%lld\n", max(dists[0], dists[1]));
    return 0;
  }

  for (int i = 0; i < n+1; i++) {
    work[n-i] = dists[i];
    // printf("dist: %lld\n", dists[i]);
  }
  sum_from_left[0] = dists[0];
  for (int i = 1; i < n+1; i++) {
    sum_from_left[i] = sum_from_left[i-1]+dists[i];
  }
  sum_from_right[n] = dists[n];
  for (int i = n-1; 0 <= i; i--) {
    sum_from_right[i] = sum_from_right[i+1]+dists[i];
  }
  sum_from_right[n+1] = 0;
  sum_from_left[n] = work[n];
  for (int i = n-1; 0 <= i; i--) {
    sum_from_left[i] = sum_from_left[i+1]+work[i];
  }
  sum_from_left[n+1] = 0;

  int i;
  ll maximum = 0;
  ll cur = 0;
  ll last = dists[n];
  for (i = 0; i < n; i++) {
