    last -= dists[i];

    // printf("last-dn+last = %lld\n", last-dists[n]+last);
    cur = last - dists[n];
    ll to_subtract_delta = (sum_from_right[i+1] - sum_from_right[n-((n-i)/2)]) * 2;
    // printf("to_subtract_delta = sum [d_%d, ... , d_%d] = %lld\n", i+1, n-((n-i)/2)-1, to_subtract_delta);
    if ((n-i)%2 == 0) {
      to_subtract_delta += dists[n-((n-i)/2)];
    }
    to_subtract += to_subtract_delta;
    cur += last + (last + sum_from_right[i] - dists[n]) * (n-i-1) - to_subtract;
    // printf("cur = %lld\n", cur);
    maximum = max(cur, maximum);
  }

  cur = 0;
  last = work[n];
  for (i = 0; i < n; i++) {
    last += work[i];
  }
  cur += last;
  maximum = max(cur, maximum);
  to_subtract = 0;
  for (i = n-1; 0 <= i; i--) {
