long dfs(int p, int i, int j) {
  if (i > j)
    return 0;

  int d1 = CDIFF(L, X[i], p);
  int d2 = CDIFF(L, p, X[j]);
  return max(dfs(X[i], i + 1, j) + d1, dfs(X[j], i, j - 1) + d2);
}

