lli L,N;
lli dist(lli n,lli obj,int f){
    lli maxL=1000000001;
    if(f==1){
        return min(obj-n<0? maxL: obj-n,L+obj-n<0? maxL: L+obj-n);
    }else{
        return min(n-obj<0? maxL: n-obj,L+n-obj<0? maxL: L+n-obj);
    }
}
lli solve(lli s,lli n,vector<lli> x){
    if(x.size()==1){
        return s+max(dist(n,x[0],0),dist(n,x[0],1));
    }
    if(dist(n,x[0],1)>dist(n,x.back(),0)){
        vector<lli> xp(x);
        xp.erase(xp.begin());
        return solve(dist(n,x[0],1)+s,x[0],xp);
    }else if(dist(n,x[0],1)<dist(n,x.back(),0)){
        vector<lli> xp(x);
        xp.pop_back();
        return solve(dist(n,x.back(),0)+s,x.back(),xp);
    }else{
        vector<lli> xp1(x);
        vector<lli> xp2(x);
        xp1.erase(xp1.begin());
        xp2.pop_back();
        return max(solve(dist(n,x[0],1)+s,x[0],xp1),solve(dist(n,x.back(),0)+s,x.back(),xp2));
    }
}
