				ans = max (ans, x[0] + m - (x[n - 1] - x[0]) + m - (x[n - 1] - x[i]) + calc (i, n - 2, 0));
			}	
		}
		reverse (x, x + n);
		for (int i = 0; i < n; i++) x[i] = m - x[i];
	}
