  // freopen("input.txt", "r", stdin);

  int l, n; cin >> l >> n;
  vector<int> x(n+1, 0), rev_x(n+1, 0);
  FOR(i, 1, n+1) cin >> x[i];
  FOR(i, 1, n+1) rev_x[i] = l - x[n+1-i];
  // dp[i][j][k] = 高橋君の家から反時計回りに i 本，時計回りに j 本燃やしたときの歩く距離の最大値
  //               k = 0 のとき時計回り  の移動で立ち止まっている
  //                   1       反時計回り
  vector<vector<vector<long long>>> dp(n+1, vector<vector<long long>>(n+1, vector<long long>(2, 0)));
  REP(i, n+1) REP(j, n+1-i) {
    if (i < n) {
      dp[i+1][j][0] = max(dp[i+1][j][0], dp[i][j][0] + x[i+1] - x[i]);
      dp[i+1][j][0] = max(dp[i+1][j][0], dp[i][j][1] + rev_x[j] + x[i+1]);
    }
    if (j < n) {
      dp[i][j+1][1] = max(dp[i][j+1][1], dp[i][j][0] + x[i] + rev_x[j+1]);
      dp[i][j+1][1] = max(dp[i][j+1][1], dp[i][j][1] + rev_x[j+1] - rev_x[j]);
    }
  }
  long long ans = 0;
  REP(i, n+1) ans = max({ans, dp[i][n-i][0], dp[i][n-i][1]});
  cout << ans << '\n';
  return 0;
}

