long long solve(int *x, int n, long long L) {
    long long ans = 0;
    long long s[n+1] = {0};
    for (int i = 0; i < n; i++) s[i+1] = s[i] + x[i];
    for (int i = 0; i < n; i++)
        if (2 * (i + 1) <= n)
            ans = max(ans, x[i] + 2 * (s[i] + L * (i + 1) - (s[2*i+2] - s[i+1])));
        else
            ans = max(ans, x[i] + 2 * (s[i] - s[2*i + 1 - n] + L * (n - i - 1) - (s[n] - s[i+1])));
    return ans;
}

