void chmax(ll& x, ll y) {if (x<y) x=y;}

struct solver {
  ll dp[2002][2002][2], x[2002];
  int n; ll l; 
  void input() {
    cin>>l>>n;
    if (n > 2000) exit(0);
    x[0] = 0; x[n+1] = l;
    for(int i=1;i<=n;i++) cin>>x[i];
    fill(dp[0][0], dp[n+2][0], -2);
  }
  ll solve(int i, int j, bool b) {
    //cout << i << " " << j << " "<< b << endl;
    // 左端、右端、左にいるかどうか
    if (j-i == 1) {
      return 0;
    } else if (dp[i][j][b] != -2) {
      return dp[i][j][b];
    } else {
      if (b) {
        ll x1 = solve(i+1, j, true) + x[i+1] - x[i]; // 左を掘り下げる
        ll x2 = solve(i, j-1, false) + l - x[j-1] + x[i]; // 左から右に移って掘る
        //cout << i << " " << j << " " << x1 << " " << x2 << endl;
        return dp[i][j][b] = max(x1, x2);
      } else {
        ll x1 = solve(i+1, j, true) + l - x[j] + x[i+1];
        ll x2 = solve(i, j-1, false) + x[j] - x[j-1];
        //cout << i << " " << j << " " << x1 << " " << x2 << endl;
        return dp[i][j][b] = max(x1, x2);
      }
    }
  }
  void output() {
    dp[1][n+1][0] = x[1];
    dp[0][n][1] = x[n];

    cout << solve(0, n+1, true) << endl;
  }
  void print() {
    for(int i=0;i<=n+1;i++) {
      for(int j=0;j<=n+1;j++) {
        cout<<dp[i][j][0]<<" ";
      } cout<<": ";
      for(int j=0;j<=n+1;j++) {
        cout<<dp[i][j][1]<<" ";
      } cout<<endl;
    }
    cout<<endl;
  }
};

int main() {
  solver ss; 
  ss.input();
  ss.output();
  //ss.print();
}

