#include <iostream>
#include <algorithm>
#include <vector>
using namespace std;
typedef long long ll;

ll L, N;
ll X[200002];
ll memo[2002][2002][2];

ll solve(int bi, int bj, int b) {
    if (bi + 1 == bj) {
        return 0;
    }

    if (memo[bi][bj][b] > 0) {
        return memo[bi][bj][b];
    }

    ll ans;
    if (b) {
        ans = max(X[bi + 1] - X[bi] + solve(bi + 1, bj, 1),
            L - X[bj - 1] + X[bi] + solve(bi, bj - 1, 0));
    } else {
        ans = max(L - X[bj] + X[bi + 1] + solve(bi + 1, bj, 1),
            X[bj] - X[bj - 1] + solve(bi, bj - 1, 0));
    }

    memo[bi][bj][b] = ans;
    return ans;
}

int main() {

    cin >> L >> N;
    for (int i = 1; i <= N; i++) {
        cin >> X[i];
    }
    X[0] = 0;
    X[N + 1] = L;

    if (N > 2000) {
        cout << "WA" << endl;
        return 0;
    }

    cout << solve(0, N + 1, 1) << endl;

    return 0;
}

