        if(3 <= rest) val += (lsum[i + (rest-1)/2] - lsum[i]) * 2;
        if(rest && rest % 2 == 0) val += (lsum[rest/2 + i] - lsum[rest/2 + i-1]);
        chmax(ret, val);
    }

    return ret;
}

int main() {
    cin >> L >> N;
    V<ll> X(N);
    for(auto &&ele : X) cin >> ele;

    ll ans = calc(X);
    reverse(ALL(X));
    for(auto &&ele : X) ele = L - ele;
    chmax(ans, calc(X));

    cout << ans << endl;
    return 0;
}

