ll f(int p, int q, bool s)
{
    if (p > q) return 0;
    if (DP[p][q][s] != -1)
        return DP[p][q][s];

    ll x = s ? a[q + 1] : a[p - 1];
    ll dp = s ? l - x + a[p] : a[p] - x;
    ll dq = s ? x - a[q] : x + l - a[q];
    ll bst = max(f(p + 1, q, false) + dp, f(p, q - 1, true) + dq);
    return DP[p][q][s] = bst;
}

