long long dist(long long pos, double pole){
  if(pos < pole){
    return pos;
  } else {
   	long long c = ceil(pole);
   	long long f = floor(pole);
    return c - (pos - f);
  }
}

int main() {
  long long l,n;
  cin >> l >> n;
  double pole = l / 2;

  vector<long long> treeList;
  while(n--) {
    long long pos;
    cin >> pos;
    treeList.push_back(pos);
  }

  long long i = 0;
  long long s = treeList.size();
  long long total = 0;
  long long ld = 0;
  while(i < s) {
    int dir = 0;
    long long curS = treeList.size();
    if(curS <= 1) {
      long long fd = dist(treeList[0], pole);
      int fdir = treeList[0] > pole ? 1: 0;
      if(fdir == dir){
      	total += fd;
      }else {
      	total += fd + ld;
      }
      break;
    }
    long long w = treeList[0];
    long long e = treeList[curS - 1];
    long long wd = dist(w, pole);
    long long ed = dist(e, pole);

    if(wd > ed){
      if(dir == 0){
      	total += wd;
      }else {
      	total += wd + ld;
      }
      dir = 0;
      ld = wd;
      remove(treeList, 0);
    }else {
      if(dir == 0){
      	total += ed + ld;
      }else {
      	total += ed;
      }
      dir = 1;
      ld = ed;
      remove(treeList, curS - 1);
    }
    // cout << treeList[i] << "|" << test << "|" << test2 << endl;
    i++;
  }
  cout << total << endl;
}

