void solve() {

	cin >> L >> N;
	for (ll i = 0; i < N; i++) {
		ll tmp;
		cin >> tmp;
		X.emplace_back(tmp);
	}
	X.emplace_back(L);

	ll ans = 0;
	int front = 0;
	int back = N - 1;
	ll num = N;
	bool dir;
	/*
	if (X[front] >= L - X[back]) {
		ans += X[front];
		dir = true;
	}
	else {
		ans += L - X[back];
		dir = false;
	}*/
	dir = true;
	ans += X[front];
	num--;
	while (num > 0) {
		if (dir == true) {
			ll tmp = X[front + 1] - X[front];
			ll tmp2 = X[front] + (L - X[back]);
			if (tmp >= tmp2) {
				ans += tmp;
				dir = true;
			}
			else {
				ans += tmp2;
				dir = false;
			}
			front++;
		}
		else {
			ll tmp = X[back] - X[back - 1];
			ll tmp2 = (L - X[back]) + X[front];
			if (tmp >= tmp2) {
				ans += tmp;
				dir = false;
			}
			else {
				ans += tmp2;
				dir = true;
			}
			back--;
		}
		num--;
	}
	ll ans2 = 0;
	num = N;
	front = 0;
	back = N - 1;
	ans2 += L - X[back];
	dir = false;
	num--;
	while (num > 0) {
		if (dir == true) {
			ll tmp = X[front + 1] - X[front];
			ll tmp2 = X[front] + (L - X[back]);
			if (tmp >= tmp2) {
				ans2 += tmp;
				dir = true;
			}
			else {
				ans2 += tmp2;
				dir = false;
			}
			front++;
