		else {
			ll tmp = X[back] - X[back - 1];
			ll tmp2 = (L - X[back]) + X[front];
			if (tmp >= tmp2) {
				ans2 += tmp;
				dir = false;
			}
			else {
				ans2 += tmp2;
				dir = true;
			}
			back--;
		}
		num--;
	}

	cout << max(ans, ans2) << endl;

	return;

}

