// The templates end here.
ll solve(int l, vi x) {
    ll ans = 0;
    vl xs(x.size() + 1);
    lv(i, x) xs[i + 1] = x[i] + xs[i];
    auto sm = [&](int i, int j) {
        // ou(i, j);
        return xs[j + 1] - xs[i];
    };
    lv(i, x) {
        // debu(i);
        ll t = x[i];
        int cnt = x.size() - i;
        int u = (cnt - 1) / 2 - 1;
        t += sm(i, i + u);
        t += 2 * ll(l) * (u + 1);
        t -= 2 * sm(x.size() - 1 - u, x.size() - 1);
        t += sm(i + 1, i + u + 1);
        if (cnt % 2 == 0)
            t += x[i + u + 1] + l - x[i + u + 2];
        // debu(t);
        tmax(ans, t);
    }
    return ans;
}
