int L,N; //Nは配列の残りサイズ

int saidai(int *X){
    int result=0;
    int x; //移動量、反時計を正とする
    int j;
    int x1 = X[0];
    int x2 = L - X[N-1];

    //cout << x1 << " " << x2 << endl;

    if(x1>=x2){x = x1;result += x1;j=0;}
    else {x = -1*x2;result += x2;j=N-1;}
    int k=0;
    for(int i=0;i<N;i++){
        if(i!=j){X[k] = X[i]- x;/*cout << X[k];*/k++;}
    }
    //cout << endl;
    N -= 1;
    //cout <<result << endl;
    return result;
}

int main(){
