ll x[200001];
ll L, N;

ll f(ll idL, ll idR){
  ll ans = 0;
  ll idC = 0;
  ll n = 0;
  if(idL != 1){
    idC = idL - 1;
    ans = x[idL - 1];
    n = N - (idL - 1);
  }else if(idR != N){
    idC = idR + 1;
    ans = L - x[idR + 1];
    n = idR;
  }else{
    idC = 0;
    ans = 0;
    n = N;
  }

  rep(i, n){
    ll posC = x[idC];
    ll posR = x[idR];
    ll posL = x[idL];
    ll lenL;
    ll lenR;
    if(posC < posL){
      lenL = posL - posC;
      lenR = L - posR + posC;
    }else{
      lenL = L - posC + posL;
      lenR = posC - posR;
    }
    if(lenL > lenR){
      ans += lenL;
      idC = idL;
      idL++;
    }else{
      ans += lenR;
      idC = idR;
      idR--;
    }
  }
