ll solve(deque<ll> d) {
    deque<ll> ld, rd;
    ll sum = 0, rsum = 0, lsum = 0;
    while(d.size() > 1) {
        sum += lsum + rsum + d.front();
        rsum += d.front();
        rd.push_back(d.front()); d.pop_front();
        if (d.size() > 1) {
            sum += lsum + rsum + d.back();
            lsum += d.back();
            ld.push_back(d.back()); d.pop_back();
        }
    }
    ll ans = sum;
    REP(i, m - 1) {
