using namespace std;

int l, n;
deque<long long> dqx;

void input() {
	cin >> l >> n;
	for(int i = 0; i < n; i++){
	    long long x;
	    cin >> x;
	    dqx.push_back(x);
	}
}

long long solve(deque<long long> dq, long long coordinate, bool cycleLeft){
    int nCurrent = dq.size();
    if(nCurrent == 0) return 0;

    long long coordinateNext;
    deque<long long> cdq;
    long long dx;
    if(cycleLeft){
        long long sumA;
        cdq = dq;
        dx = cdq.at(0) - coordinate;
        coordinateNext = cdq.at(0);
        cdq.pop_front();
        sumA = dx + solve(cdq, coordinateNext, true);

        long long sumB;
        cdq = dq;
        dx = l - (cdq.at(nCurrent - 1) - coordinate);
        coordinateNext = cdq.at(nCurrent - 1);
        cdq.pop_back();
        sumB = dx + solve(cdq, coordinateNext, false);

        return max(sumA, sumB);
    }
    else{
        long long sumA;
        cdq = dq;
        dx = cdq.at(0) + (l - coordinate);
        coordinateNext = cdq.at(0);
        cdq.pop_front();
        sumA = dx + solve(cdq, coordinateNext, true);

        long long sumB;
        cdq = dq;
        dx = coordinate - cdq.at(nCurrent - 1);
        coordinateNext = cdq.at(nCurrent - 1);
        cdq.pop_back();
        sumB = dx + solve(cdq, coordinateNext, false);

        return max(sumA, sumB);
    }
}

int main(void)
{
	cin.tie(0);
	ios::sync_with_stdio(false);

	input();

    if(n > 3000) return 0;

    deque<long long> cdqx;
    long long coordinateNext;
    long long dx;
    long long sumA;
    cdqx = dqx;
    coordinateNext = cdqx.at(0);
    dx = cdqx.at(0);
    cdqx.pop_front();
    sumA = dx + solve(cdqx, coordinateNext, true);

    long long sumB;
    cdqx = dqx;
    coordinateNext = cdqx.at(n - 1);
    dx = l - cdqx.at(n - 1);
    cdqx.pop_back();
    sumB = dx + solve(cdqx, coordinateNext, false);
	cout << max(sumA, sumB) << "\n";

	return 0;
}

