#define REP(i, n) for (int i = 0; i < (n); i++)
#define RREP(i, n) for (int i = (n) - 1; i >= 0; i--)
#define FOR(i, a, b) for (int i = (a); i < (b); i++)
#define RFOR(i, a, b) for (int i = (a); i > (b); i--)
#define ALL(a) (a).begin(), (a).end()

int L, N, dx[200001];

ll count(int non_return, bool front) {
    int f = 0, b = N;
    ll ret = 0, cs = 0;
    if (front) {
        REP(i, non_return) cs += dx[N - i];
        b -= non_return;
    }
    else {
        REP(i, non_return) cs += dx[i];
        f += non_return;
    }

    while (f <= b) {
        ret += cs;
        if (front) cs += dx[f++];
        else       cs += dx[b--];
        front = !front;
    }
    return ret;
}

int main() {
    int x, bx = 0;
    cin >> L >> N;
    REP(i, N) {
        cin >> x;
        dx[i] = x - bx;
        bx = x;
    }
    dx[N] = L - bx;

    ll ans = 0;
    REP(i, N + 1) ans = max(count(i, false), ans);
    REP(i, N + 1) ans = max(count(i, true), ans);
    cout << ans << endl;
    return 0;
}

