LL L, n;

LL A[MAXN + 5];

inline void input()
{
	L = read<LL>(), n = read<LL>();
	for(LL i = 1; i <= n; ++i) A[i] = read<LL>();
}

inline void solve()
{
	static LL dp[MAXN + 5][MAXN + 5][2];

	LL ans = 0;
	dp[1][0][0] = A[1];
	dp[0][1][1] = L - A[n];
	for(LL i = 0; i <= n; ++i) for(LL j = 0; j <= n - i; ++j)
		if(i + j == n)
		{
			chkmax(ans, dp[i][j][0]);
			chkmax(ans, dp[i][j][1]);
		}
		else
		{
			if(dp[i][j][0]) chkmax(dp[i + 1][j][0], dp[i][j][0] + A[i + 1] - A[i]);
			if(dp[i][j][1]) chkmax(dp[i + 1][j][0], dp[i][j][1] + A[i + 1] + L - A[n - j + 1]);

			if(dp[i][j][0]) chkmax(dp[i][j + 1][1], dp[i][j][0] + A[i] - A[n - j] + L);
			if(dp[i][j][1]) chkmax(dp[i][j + 1][1], dp[i][j][1] + A[n - j + 1] - A[n - j]);
		}
	printf("%lld\n", ans);
}

