long long L;
int N;
vector<long long> X;

long long Dist(int Left, int Right) {
	if (Left <= Right) {
		return X[Right] - X[Left];
	}
	else {
		return X[Right] + L - X[Left];
	}
}

int main() {
	ios_base::sync_with_stdio(0);
	cin.tie(0);
	cin >> L >> N;
	X.resize(N + 2);
	X[0] = 0, X[N + 1] = L;
	for (int i = 1; i <= N; i++) cin >> X[i];
	long long NOW = 0, MAX = 0;
	int LP = 0, RP = N, LM = N, RM = N;
	for (int i = 0; i < N * 2; i++) {
		NOW += Dist(LP, RP);
		NOW -= Dist(LM, RM);
		if (i % 2 == 0) LP == 0 ? LP = N : LP--;
		RP == 0 ? RP = N : RP--;
		LM == 0 ? LM = N : LM--;
		if (i % 2 == 1) RM == 0 ? RM = N : RM--;
		if (MAX < NOW) MAX = NOW;
	}
	cout << MAX << endl;
}

