int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    ll L,N; cin >> L >> N;
    vector<ll> X(N);
    rep(i,N) cin >> X[i];
    if (N==1) {
        cout << max(X[0],L-X[0]) << ln;
        return 0;
    }

    auto pos=[&](ll x) {
        if (x < 0) return x+N;
        if (x >= N) return x-N;
        return x;
    };
    auto calc=[&](int l, int r) {
        ll ret = X[r] - X[l];
        if (ret < 0) ret += L;
        return ret;
    };
    auto func=[&](bool f, bool s) {
        int l,r,p;
        ll val;
        if (f and s) {
            val = X[0] + calc(0,1);
            l = 0; r = 1; p = 0;
        } else if (f and !s) {
            val = X[0] + calc(N-1,0);
            l = N-1; r = 0; p = 1;
        } else if (!f and s) {
            val = L - X[N-1] + calc(N-1,0);
            l = N-1; r = 0; p = 0;
        } else {
            val = L - X[N-1] + calc(N-2,N-1);
            l = N-2; r = N-1; p = 1;
        }
        rep(i,N-2) {
            if (p) {
                int nex = pos(r+1);
                val += calc(l,nex);
                r = nex;
                p = 0;
            } else {
                int nex = pos(l-1);
                val += calc(nex,r);
                l = nex;
                p = 1;
            }
        }

        return val;
    };

    cout << max({func(0,0),func(0,1),func(1,0),func(1,1)}) << ln;
}

