    rep(i,n){
        if(i > 0) suml[i] = suml[i-1];
        suml[i] += a[i] * 2;
    }
    drep(i,n){
        if(i < n-1) sumr[i] = sumr[i+1];
        sumr[i] += (L-a[i]) * 2;
    }

