#include "bits/stdc++.h"
using namespace std;
typedef long long li;

li solve(const li l, vector<li> xs) {
    const li n = xs.size() - 1;
    li ans = xs.back();

    li accum = ans;
    for (int rb = n - 1; rb > 0; --rb) {
        int step = n - rb;
        int prev_rb = rb + 1;
        int last_r = n - 2 * step;
        li l_dist = l - xs[prev_rb];

        if (last_r >= 0) {
            accum += 2 * l_dist;
            accum += 2 * xs[last_r];
            accum += 2 * xs[last_r + 1];
            accum -= xs[prev_rb] + xs[rb];
            ans = max(ans, accum);
        } else {
            accum += 2 * l_dist;
            accum -= xs[prev_rb] + xs[rb];
            const int cancel_r = last_r + n + 1;
            accum -= 2 * (l - xs[cancel_r]);
            if (cancel_r + 1 <= n) {
                accum -= 2 * (l - xs[cancel_r + 1]);
            }
            ans = max(ans, accum);
        }
    }

    return ans;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    li l, n;
    cin >> l >> n;
    vector<li> xs(n + 1), ys(n + 1);
    for (int i = 0; i < n; ++i) {
        cin >> xs[i + 1];
        ys[n - i] = l - xs[i + 1];
    }

    const li ans = max(solve(l, xs), solve(l, ys));
    cout << ans << endl;
    return 0;
}

#include <iostream>
#include <deque>

using namespace std;

struct Config {
  int L;
  deque<int> trees;
};

Config readConfig() {
  Config output;
  size_t N;
  cin >> output.L >> N;
  while (output.trees.size() < N) {
    int t;
    cin >> t;
    output.trees.push_back(t);
  }
  return output;
}

int clockwiseDistance(int next, int curr, int L) {
  if (next < curr) {
    return curr - next;
  } else {
    return curr + (L - next);
  }
}

int counterClockwiseDistance(int next, int curr, int L) {
  if (next > curr) {
    return next - curr;
  } else {
    return next + (L - curr);
  }
}

int greedy(const Config& config) {
  auto trees = config.trees;
  long path = 0;
  int currentPosition = 0;


  while (!trees.empty()) {
    auto frontDistance = counterClockwiseDistance(trees.front(), currentPosition, config.L);
    auto backDistance = clockwiseDistance(trees.back(), currentPosition, config.L);

    if (frontDistance >= backDistance) {
      path += frontDistance;
      currentPosition = trees.front();
      trees.pop_front();
    } else {
      path += backDistance;
      currentPosition = trees.back();
      trees.pop_back();
    }
  }
  return path;
}

int fixedTurns(const Config& originalConfig, unsigned int turns, bool clockwise) {
    auto config = originalConfig;
    auto skip = config.trees.size() - 1 - turns;
    while (skip > 0) {
        if (clockwise) {
            config.trees.pop_back();
        } else {
            config.trees.pop_front();
        }
        skip--;
    }
    return greedy(config);
}

int allTurns(const Config& config) {
    int best = 0;
    for (auto turns = 0u; turns < config.trees.size(); turns++) {
        best = max(best, fixedTurns(config, turns, true));
        best = max(best, fixedTurns(config, turns, false));
    }
    return best;
}

int main() {
  const auto config = readConfig();
  cout << allTurns(config) << endl;
  return 0;
}

