  while (b_index <= e_index) {
    if (cclockwise) {
      cnt += x[b_index] + (l - pos) % l;

      pos = x[b_index];
      ++b_index;
      cclockwise = !cclockwise;
    } else {
      cnt += (l-x[e_index]) + pos;

      pos = x[e_index];
      --e_index;
      cclockwise = !cclockwise;
    }
  }

  return cnt;
}


int main() {
  LL l, n; std::cin >> l >> n;
  std::vector<LL> x(n);
  for (int i = 0; i < n; ++i) std::cin >> x[i];

  LL max_cnt = 0;
  for (int start = -1; start < n; ++start) {
    // counter clockwise start
    LL pos  = (start<0) ? 0 : x[start];
    LL b_index = start + 1;
    LL e_index = n - 1;

    LL cnt1 = pos + walk(x, l, pos, b_index, e_index, false);

    // clockwise start
    pos  = (start<0) ? 0 : x[n-start-1];
    b_index = 0;
    e_index = n - start - 2;
    LL cnt2 = ((l - pos)%l) + walk(x, l, pos, b_index, e_index, true);

    max_cnt = std::max({max_cnt,  cnt1,  cnt2});
  }

  std::cout << max_cnt << std::endl;
}

