#include <bits/stdc++.h>

using namespace std;

using int64 = long long;

template< class T >
struct BinaryIndexedTree {
  vector< T > data;

  BinaryIndexedTree(int sz) {
    data.assign(++sz, 0);
  }

  T sum(int k) {
    T ret = 0;
    for(++k; k > 0; k -= k & -k) ret += data[k];
    return (ret);
  }

  void add(int k, T x) {
    for(++k; k < data.size(); k += k & -k) data[k] += x;
  }
};

int N, L;

int64 solve(vector< int > X) {
  int N = (int) X.size();
  X.push_back(L);
  BinaryIndexedTree< __int128_t > uku(X.size());
  for(int i = 0; i + 1 < X.size(); i++) uku.add(i, X[i + 1] - X[i]);

  BinaryIndexedTree< __int128_t > beet(X.size());
  for(int i = 0; i + 1 < X.size(); i++) beet.add(i, 1LL * (X[i + 1] - X[i]) * i);


  int64 ret = 0;
  for(int i = N - 1; i >= 0; i--) { // 右端を固定
    int64 sub = 0;

    {
      int ok = i, ng = -1;
      while(ok - ng > 1) {
        int j = (ok + ng) / 2;
        int64 rightRest = (i - j - 1); //i-j-1はjが大きいほど小さくなる
        int64 leftLeft = (N - i - 1);

        if(rightRest < leftLeft) ok = j;
        else ng = j;
      }

      sub += 1LL * uku.sum(ok - 1) * (N - i - 1);
      sub += 1LL * (uku.sum(i - 1) - uku.sum(ok - 1)) * i;
      sub -= 1LL * (uku.sum(i - 1) - uku.sum(ok - 1));
      sub -= 1LL * (beet.sum(i - 1) - beet.sum(ok - 1));
    }

    {

      int ok = i, ng = N;
      while(ng - ok > 1) {
        int j = (ok + ng) / 2;

        int64 rightRest = i;
        int64 leftLeft = j - i; // jが大きいほど大きくなる

        if(leftLeft < rightRest) ok = j;
        else ng = j;
      }

      sub -= 1LL * (uku.sum(ok) - uku.sum(i)) * i;
      sub += 1LL * (beet.sum(ok) - beet.sum(i));


      sub += 1LL * (uku.sum(N - 1) - uku.sum(ok)) * i;

    }
    sub *= 2;

    ret = max(ret, sub + X[i]);
  }

  return ret;
}

int main() {
  cin >> L >> N;
  vector< int > X(N + 1);
  X[0] = 0;
  for(int i = 1; i <= N; i++) cin >> X[i];
  int64 ret = solve(X);
  for(auto &p : X) p = (L - p) % L;
  sort(begin(X), end(X));
  cout << max(ret, solve(X)) << endl;
}

