void solve(int n,int L){
	for(int i=1;i<=n;i++)
		s0[i] = s0[i-1]+a[i];
	for(int i=1;i<=n;i++)
		s1[i] = s1[i-1]+ (L-a[n-i+1]);
	for(int i=1;i<=n;i++){
		ll cur = 0;
		int x = (n-i) >> 1;
		if((n-i)&1){
			cur += 2 * (s0[i+x] - s0[i-1]);
			cur += s1[x+1]-s1[x];
			cur += 2 * s1[x];
		}
		else{
			cur += 2 * s1[x];
			cur += 2 * (s0[i+x-1] - s0[i-1]);
			cur += s0[i+x] - s0[i+x-1];
		}
		ans = max(ans,cur);
	}
}
