			ll offset = 0;
			ll dif = (rend - rstart) - (lend - lstart) + 1; // -1 if we ending on the right
			if (k)dif -= 2;
			if (dif > 0){
				rend -= dif;
				offset = R[rend+1];
			}else if (dif < 0){
				lstart -= dif;
				offset = L[lstart-1];
			}
			ll tot = 2*(range_right(rstart,rend) + range_left(lstart,lend));
			if (k == 0)tot -= L[lend];
			else tot -= R[rstart];
			if (dif > 0 && k == 0)tot = tot + offset*2;
			if (dif < 0 && k == 1)tot = tot + offset*2;

