long calc(int l){
    long tmp = 0;
    if(l == N-l){
        tmp += 2*(sum[l]-sum[0]);
        tmp += (2*L*(N-l) - 2*(sum[N]-sum[l]));
        tmp -= min(x[l], L-x[l+1]);
    }else if(l < N-l){
        tmp += 2*(sum[l]-sum[0]);
        tmp += (2*L*l - 2*(sum[2*l]-sum[l]));        
        tmp -= min(x[l], L-x[l+1]);
        long tmp2 = 0;
        tmp2 += 2*(sum[l]-sum[0]);
        tmp2 += (2*L*(l+1) - 2*(sum[2*l+1]-sum[l]));     
        tmp2 -= (L-x[l+1]);
        tmp = max(tmp, tmp2);
    }else{
        tmp += 2*(sum[l]-sum[2*l-N]);
        tmp += (2*L*(N-l) - 2*(sum[N]-sum[l])); 
        tmp -= min(x[l], L-x[l+1]);
        long tmp2 = 0;
        tmp2 += 2*(sum[l]-sum[2*l-N-1]);
        tmp2 += (2*L*(N-l) - 2*(sum[N]-sum[l])); 
        tmp2 -= x[l];
        tmp = max(tmp, tmp2);
    }
}

