const int N = 2e5 + 5;
ll x[N], y[N], a[N], b[N];
int len, n;

ll solve() {
	ll ans = 0;
	for (int i = 1; i < n; i++) {
		int j = n - i;
		if (j <= i) {
			ans = max(ans, (a[i] - a[i - j]) * 2 + b[j] * 2 - y[j]);
			ans = max(ans, (a[i] - a[i - j]) * 2 + b[j] * 2 - x[i]);
		}
	}

	for (int i = 1; i < n; i++) {
		int j = n - i;
		if (i - 1 >= j) {
			ans = max(ans, (a[i] - a[i - j - 1]) * 2 - x[i] + b[j] * 2);
		}
	}

	for (int i = 1; i < n; i++) {
		int j = n - i;
		if (i >= j - 1) {
			ans = max(ans, (a[i] - a[i - j + 1]) * 2 + b[j] * 2 - y[j]);
		}
	}

	return ans;
}

signed main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    cin >> len >> n;

    for (int i = 1; i <= n; i++) {
    	cin >> x[i];
    	y[i] = len - x[i];
    }

    reverse(y + 1, y + n + 1);

    for (int i = 1; i <= n; i++) {
		a[i] = a[i - 1] + x[i];
	}

	for (int i = 1; i <= n; i++) {
		b[i] = b[i - 1] + y[i];
	}

	ll ans = max(x[n], y[n]);

	ans = max(ans, solve());

	for (int i = 1; i <= n; i++) {
		swap(a[i], b[i]);
		swap(x[i], y[i]);
	}

	ans = max(ans, solve());

	cout << ans;

    return 0;
}

