pair<i64, vector<int>> dfs(int i, int j, int k) {
    if (i + 1 == j) {
        return {0, vector<int>()};
    }

    auto t = make_tuple(i, j, k);

    if (memo.count(t)) {
        return memo[t];
    } 

    pair<i64, vector<int>> ret;

    if (k == i) {
        /*ret = max(
            x[i + 1] - x[i] + dfs(i + 1, j, i + 1),
            x[i] + l - x[j - 1] + dfs(i, j - 1, j - 1)  
        );*/

        auto r1 = dfs(i + 1, j, i + 1);
        auto r2 = dfs(i, j - 1, j -1);

        i64 c1 = r1.first + x[i + 1] - x[i];
        i64 c2 = r2.first + x[i] + l - x[j - 1];

        if (c1 > c2) {
            ret.first = c1;
            ret.second = r1.second;
            ret.second.push_back(i + 1);
        } else {
            ret.first = c2;
            ret.second = r2.second;
            ret.second.push_back(j - 1);
        }
    } else if (k == j) {
        /*ret = max(
            x[j] - x[j - 1] + dfs(i, j - 1, j - 1),
            l - x[j] + x[i + 1] + dfs(i + 1, j, i + 1)
        );*/
        auto r1 = dfs(i, j - 1, j - 1);
        auto r2 = dfs(i + 1, j, i + 1);

        i64 c1 = r1.first + x[j] - x[j - 1];
        i64 c2 = r2.first + l - x[j] + x[i + 1];

        if (c1 > c2) {
            ret.first = c1;
            ret.second = r1.second;
            ret.second.push_back(j - 1);
        } else {
            ret.first = c2;
            ret.second = r2.second;
            ret.second.push_back(i + 1);
        }

    } else {
        assert(false);
    }

    return memo[t] = ret;
}

int main() {
    in(l, n);

    x = vin<i64>(n);

    vector<i64> y(n);

    for (int i = 0; i < n; i++) {
        y[i] = l - x[i];
    }

    i64 ans = 0;

    vector<i64> cumsum1(n), cumsum2(n);

    cumsum1[0] = x[0];
    for (int i = 1; i < n; i++) {
        cumsum1[i] = cumsum1[i - 1] + x[i];
    }

    cumsum2[n - 1] = y[n - 1];
    for (int i = n - 2; i >= 0; i--) {
        cumsum2[i] = cumsum2[i + 1] + y[i];
    }

    for (int i = 0; i < n; i++) {
        // x[i] が最後に訪れる場所

        if (i == 0) {
            ans = max(ans, y[i + 1] + max(x[i + 1] - x[i], y[i + 1] + x[i]));
        } else if (i == n - 1) {
            ans = max(ans, x[i - 1] + max(x[i] - x[i - 1], x[i - 1] + y[i]));
        } else {
            {
                // x[i - 1] が最後から2番目に訪れる場所

                i64 s = 0;

                int j1 = i - 1;
                int j2 = i + 1;

                vector<int> v1, v2;

                s += x[j1--];

                int k1 = j1 + 1;
                int k2 = n - j2;

                if (j1 >= 0) {
                    s += 2 * cumsum1[j1];
                }

                s += 2 * cumsum2[j2];

                if (k2 <= k1) {
                    if (j1 - k2 >= 0) {
                        s -= 2 * cumsum1[j1 - k2];
                    }
                } else {
                    if (j2 + k1 + 1 < n) {
                        s -= 2 * cumsum2[j2 + k1 + 1];
                    }
                }

                ans = max(ans, s + max(x[i] - x[i - 1], x[i - 1] + y[i]));
            }

            {
                // x[i + 1] が最後から2番目に訪れる場所

                debug(i);

                i64 s = 0;

                int j1 = i - 1;
                int j2 = i + 1;

                vector<int> v1, v2;

                s += y[j2++];

                int k1 = j1 + 1;
                int k2 = n - j2;

                if (j2 < n) {
                    s += 2 * cumsum2[j2];
                }

                s += 2 * cumsum1[j1];

                if (k1 <= k2) {
                    if (j2 + k1 < n) {
                        s -= 2 * cumsum2[j2 + k1];
                    }
                } else {
                    if (j1 - k2 - 1 >= 0) {
                        s -= 2 * cumsum1[j1 - k2 - 1];
                    }
                }

                ans = max(ans, s + max(x[i + 1] - x[i], y[i + 1] + x[i]));
            }
        }
    }

    out(ans);
}

