ll func(ll p, ll q){
	if(dp[p][q] != 0) return dp[p][q];
	ll res;
	if(p == q) res = 0;
	else if(abs(p - q) == 1) res = max(x[max(p, q)] - x[min(p, q)], l - x[max(p, q)] + x[min(p, q)]);
