void solve()
{
    FOR(i, 0, n)
    pref[i + 1] = pref[i] + x[i];
    int ans = 0;
    FOR(i, 0, n)
    {
        int k = min(i, n - 1 - i);
        int cur = x[i];
        cur += 2 * (pref[i] - pref[i - k]);
        if (i + k + 1 < n)
            k++;
        cur += 2 * (k * L - pref[i + k + 1] + pref[i + 1]);
        ans = max(cur, ans);
    }
    FOR(i, 0, n)
    {
        int k = min(i, n - 1 - i);
        int cur = L - x[i];
        cur += 2 * (k * L - pref[i + k + 1] + pref[i + 1]);
        if (i > k)
            k++;
        cur += 2 * (pref[i] - pref[i - k]);
        ans = max(cur, ans);
    }
    cout << ans << endl;
}

