long long get(vector<long long> X){
	long long ret = X.back();

	vector<long long> S0(N+1,0LL),S1(N+1,0LL);
	for(int i=1;i<=N;i++){
		S0[i] = X[i-1]*2;
		S1[i] = (L-X[i-1])*2;
		S0[i]+=S0[i-1];
		S1[i]+=S1[i-1];
	}

	for(int i=0;i+1<N;i++){
		long long t = X[i]*2;
		int n = N-i-1;
