std::vector<long long> dx;

long long cache[2][2048][2048];

long long solve(int l, int r, int p, long long acm = 0)
{
  if (l >= r) return 0;

  auto& res = cache[p][l][r];
  if (res) return res;

  auto r1 = dx[l] + (p == 1 ? acm : 0) + solve(l+1, r, 0, acm + dx[l]);
  auto r2 = dx[r] + (p == 0 ? acm : 0) + solve(l, r-1, 1, acm + dx[r]);
  res = std::max(r1, r2);
  return res;
}

int main(int argc, char* argv[])
{
  std::ios::sync_with_stdio(false);
  cin.tie(nullptr);

  int L, N;
  cin >> L >> N;


  dx.reserve(N+1);

  int prev = 0;
  for (int i = 0; i < N; ++i)
  {
    int xi; cin >> xi;
    dx.push_back(xi - prev);
    prev = xi;
  }
  dx.push_back(L - prev);

  auto r1 = solve(0, N, 0);
  auto r2 = solve(0, N, 1);

  cout << std::max(r1, r2) << "\n";


  return 0;
}

