  std::cin >> L >> N;

  X[0] = 0;

  for (int i = 1; i <= N; i ++)
    std::cin >> X[i];

  long long dp[2222][2222];

  memset(dp, -1, sizeof(dp));

  for (int i = 0; i <= N; i ++)
    dp[i][i] = 0;

  std::set<std::pair<int, int>> set;

  for (int i = 1; i < N; i ++) {
    int j = i + 1, d1 = X[j] - X[i], d2 = L - d1, d = std::max(d1, d2);

    dp[i][j] = dp[j][i] = d;

    set.emplace(i, j);
  }

  while (1) {
    std::set<std::pair<int, int>> s;

    for (const auto& pair : set) {
      int i = pair.first, j = pair.second;

      if (i > 1) {
        int ii = i - 1, jj = j, u = X[i] - X[ii], v = X[ii] - X[j];

        if (u < 0)
          u += L;

        if (v < 0)
          v += L;

        dp[ii][jj] = std::max(std::max(dp[i][j] + u,
                                       dp[j][i] + v), dp[ii][jj]);

        s.emplace(ii, jj);
      }

      if (j < N) {
        int ii = i, jj = j + 1, u = X[i] - X[jj], v = X[jj] - X[j];

        if (u < 0)
          u += L;

        if (v < 0)
          v += L;

        dp[jj][ii] = std::max(std::max(dp[i][j] + u,
                                       dp[j][i] + v), dp[jj][ii]);

        s.emplace(ii, jj);
      }
    }

    if (s.empty())
      break;

    set = std::move(s);
  }

  dp[0][N] = std::max(dp[1][N] + X[1],
                      dp[N][1] + L - X[N]);

  std::cout << dp[0][N] << std::endl;

  return 0;
}

