using ll = long long;
using pii = pair<int, int>;
using vi = vector<int>;
using vll = vector<ll>;

void solve() {
    int L, N;
    cin >> L >> N;
    vll XX(N + 1), YY(N + 1), X(N), Y(N);
    rep(i, N) {
        cin >> X[i];
        Y[i] = L - X[i];
        XX[i + 1] = XX[i] + X[i];
        YY[i + 1] = YY[i] + Y[i];
    }

    ll ans = min(X[N-1], Y[0]);
    for (int m = 1; m < N; ++m) {
        int n = min(m, N - m);
        ll z = ((XX[m] - XX[m - n]) + (YY[m + n] - YY[m])) * 2;
        ll w = z - min(X[m - 1], Y[m]);
        smax(ans, w);
        if (m > N - m) {
            w = z + X[m - n - 1] * 2 - X[m - 1];
        } else if (N - m > m) {
            w = z + Y[m + n] * 2 - Y[m];
        }
        smax(ans, w);
    }
    cout << ans << endl;
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);
	cout << fixed << setprecision(15);
	solve();
	return 0;
}

