int dp[2010][2010][2];

int calc(int a, int b, int dir){
    if(a >= b) return -INF;
    if(dp[a][b][dir] != -1) return dp[a][b][dir];
    int res = 0;
    if(a + 1 == b) return 0;
    if(a + 1 < b){
        int dist = x[a + 1] - x[a];
        if(dir == 1) dist = l - x[b] + x[a + 1];
        // dp[a + 1][b][0] = max(dp[a + 1][b][0], calc(a + 1, b, 0) + dist);
        res = max(res, calc(a + 1, b, 0) + dist);
    }
    if(a < b - 1){
        int dist2 = x[b] - x[b - 1];
        if(dir == 0) dist2 = l - x[b - 1] + x[a];
        // dp[a][b - 1][1] = max(dp[a][b - 1][1], calc(a, b - 1, 1), dist2);
        res = max(res, calc(a, b - 1, 1) + dist2);
    }
    // cout << a << ' ' << b << ' ' << dir << ' ' << res << endl;
    return dp[a][b][dir] = res;
}

