    for (int i = 0; i < 2 * n; i++) {
      d[i] = new_x[i + 1] - new_x[i];
    }
    debug(d);
    vector<long long> pref(2 * n + 1);
    vector<long long> pref_mul(2 * n + 1);
    for (int i = 0; i < 2 * n; i++) {
      pref[i + 1] = pref[i] + d[i];
      pref_mul[i + 1] = pref_mul[i] + d[i] * (2 * i);
    }
    for (int start = 0; start <= n; start++) {
      int left = n - start;
      int right = start;
      int from1 = start;
      int to1 = n - 1;
      int from2 = n;
      int to2 = start + n - 1;
