using namespace std;

int opposite_distance(const vector<uint32_t>& trees, uint32_t l, size_t i, size_t j)
{
	assert(i != 0);
	assert(j != 0);
	uint32_t r_p = trees[i];
	uint32_t l_p = trees[trees.size() - j];
	auto ret = r_p + (l - l_p);
	return ret;
}

int distance_right(const vector<uint32_t>& trees, size_t i, size_t j)
{
	assert(i != 0);
	assert(j != 0);
	assert(j > i);
	auto ret = trees[j] - trees[i];
	return ret;
}

int distance_left(const vector<uint32_t>& trees, size_t i, size_t j)
{
	assert(i != 0);
	assert(j != 0);
	assert(j > i);
	auto ret = trees[trees.size() - i] - trees[trees.size() - j];
	return ret;
}

int main()
{
	int l, n;
	cin >> l >> n;

	vector<uint32_t> trees(n + 1);
	for (int i = 0; i < n; i++) {
		cin >> trees[i + 1];
	}

	vector<uint64_t> states(n*2 + 4);
	vector<uint64_t> prev_states(n*2 + 4);

	states[0] = l - trees[trees.size() - 1];
	states[1] = 0; 
	states[2] = 0;
	states[3] = trees[1];

	for (int i = 2; i <= n; i++) {
		int prev_n = i * 2;
		memcpy(&prev_states[0], &states[0], sizeof(uint64_t) * prev_n);

		for (int j = 0; j <= i; j++) {
			int l_num = i - j;
			int r_num = j;

			int p = j * 2;
			if (l_num != 0) {
				uint64_t from_left = 0;
				if (l_num != 1) {
					from_left  = prev_states[p] + distance_left(trees, l_num - 1, l_num);
				}
				uint64_t from_right = 0;
				if (r_num != 0) {
					from_right = prev_states[p + 1] + opposite_distance(trees, l, r_num, l_num);
				}
				states[p] = max(from_left, from_right);
			}
			if (r_num != 0) {
				uint64_t from_left = 0;
				if (l_num != 0) {
					from_left = prev_states[p - 2] + opposite_distance(trees, l, r_num, l_num);
				}
				uint64_t from_right = 0;
				if (r_num != 1) {
					from_right = prev_states[p - 1] + distance_right(trees, r_num - 1, r_num);
				}
				states[p + 1] = max(from_left, from_right);
			}
		}
	}

	uint64_t max_value = 0;
	for (auto& val : states) {
		max_value = max(max_value, val);
	}

	cout << max_value << endl;

	return 0;
}

