    for(ll k = 1; k < t; ++k){
        for(ll i = 0, j = k; j < t; ++i, ++j){
            for(ll l = 0; l < 2; ++l){
                dp[i][j][1] = max(dp[i][j][1], dp[i][j - 1][1] + a[j] - a[j - 1]);
                dp[i][j][1] = max(dp[i][j][1], dp[i][j - 1][0] + a[j] - a[i]);
                dp[i][j][0] = max(dp[i][j][0], dp[i + 1][j][0] + a[i + 1] - a[i]);
                dp[i][j][0] = max(dp[i][j][0], dp[i + 1][j][1] + a[j] - a[i]);
            }
        }
    }

    ll ans = 0;

    for(ll i = 0; i + n - 1 < t; ++i){
        ans = max(dp[i][i + n - 1][0], ans);
        ans = max(dp[i][i + n - 1][1], ans);
    }
    cout << ans << endl;

}

