        left[i] = l - x[n-1-i];
        right[i] = x[i];
    }
    ldiff[0] = left[0];
    rdiff[0] = right[0];
    for(int i = 0; i < n-1; i++){
        ldiff[i+1] = left[i+1]-left[i];
        rdiff[i+1] = right[i+1]-right[i];
    }
    ll ans = 0;

