ll solve (int n) {
  ll ans = 0;

  int ptr = 0;
  deque<int> lfs = {0};
  deque<int> rfs = {1};
  ll cur = arr[0] + 2 * (L - arr[1]);

  ans = max(ans, cur);

  while (ptr + 1 != n - 1) {
    cur += arr[ptr];
    ptr++;
    cur -= 2 * (L - arr[ptr]);
    cur += arr[ptr];

    lfs.push_back(ptr);
    rfs.pop_front();

    while ((int) rfs.size() < (int) lfs.size() && rfs.back() != n - 1) {
      int nxt = rfs.back() + 1;
      rfs.push_back(nxt);
      cur += 2 * (L - arr[nxt]);
    }

    while ((int) lfs.size() > (int) rfs.size()) {
      cur -= 2 * (arr[lfs[0]]);
      lfs.pop_front();
    }

    int flag = 0;
    if (lfs[0] != 0) {
      cur += 2 * arr[lfs[0] - 1];
      flag = 1;
    }

    ans = max(ans, cur);

    if (flag) {
      cur -= 2 * arr[lfs[0] - 1];
    }
  }

  return ans;
}

