void rec(ll x[], const long &n, const ll &l, const ll &pos, const long &index, const ll &cost, const long &num, const bool &left, V<ll> &dp, V<bool> table, ll &ans) {
	if (n == num) {
		Max(ans, cost);

		return;
	}
	if (table[index]) return;

	table[index] = 1;

	ll c;

	if (left) {
		if (pos < x[index]) c = cost + (x[index] - pos);
		else c = cost + (l - pos) + x[index];
	} else {
		if (x[index] < pos) c = cost + (pos - x[index]);
		else c = cost + pos + (l - x[index]);
	}

	cerr << index << ", " << num << ", " << c << ", " << left <<  endl;

	if (c < dp[num]) return;

	dp[num] = c;

	long i;

	i = (index + 1) % n;
	while (i != index && table[i]) i = (i + 1) % n;

	rec(x, n, l, x[index], i, c, num + 1, true, dp, table, ans);

	i = index - 1 < 0 ? n - 1 : index - 1;
	while (i != index && table[i]) i = i - 1 < 0 ? n - 1 : i - 1;

	rec(x, n, l, x[index], i, c, num + 1, false, dp, table, ans);
}

void solve(ll x[], const long &n, const ll &l) {
	ll ans = 0;
	V<bool> table(n, 0);
    V<ll> dp(n, 0);

	rec(x, n, l, 0, 0, 0, 0, true, dp, table, ans);
	rec(x, n, l, 0, n - 1, 0, 0, false, dp, table, ans);

	Out(ans);
}

