Long solveOne(deque<Long> &q) {
    int cnt = SIZE(q) -1;

    int l = 0;
    int r = cnt;

    Long ans = 0;
    bool isR = true;
    while (r > l) {
        if (isR) {
            ans += q[r] * cnt;
            --r;
        } else {
            ans += q[l]*cnt;
            ++l;
        }

        --cnt;
        isR = !isR;
    }

    return ans;

}

Long solve(deque<Long> v) {
    Long ans = 0;
    Long tans = 0;
    while (v.size() > 1) {
        ans = max(ans, tans + solveOne(v));
        tans += v.front();
        v.back() += v.front();
        v.pop_front();
    }

    return ans;

}

class BTreeBurning {
public:
    void solve(std::istream& in, std::ostream& out) {
        int n, l, a;

        deque<Long> d;
        int p = 0;
        in >> l >> n;
        REP(i,n) {
            in >> a;
            d.pb(a-p);
            p = a;
        }

        d.pb(l - p);


        Long ans = ::solve(d);
        reverse(ALL(d));

        ans = max(ans, ::solve(d));

        out << ans << endl;

    }
};


int main() {
	BTreeBurning solver;
	std::istream& in(std::cin);
	std::ostream& out(std::cout);
	solver.solve(in, out);
	return 0;
}

