using namespace std;

using int64 = long long;


int N, L;

int64 solve(vector< int > X) {
  int N = (int) X.size();
  X.push_back(L);
  int64 uku = 0;
  auto Z = [&](int i) {
    int64 ret = 0;
    int64 sub = 0;

    {
      vector< int > add(N);
      for(int j = 0; j < i; j++) {
        int64 rightRest = (i - j - 1);
        int64 leftLeft = (N - i - 1);

        add[j + 1] += min(rightRest, leftLeft);
        add[j] -= min(rightRest, leftLeft);
        sub += 1LL * (X[j + 1] - X[j]) * min(rightRest, leftLeft);
      }

    }

    for(int j = N - 1; j > i; j--) {
      int64 rightRest = i;
      int64 leftLeft = j - i;
      sub += 1LL * (X[j + 1] - X[j]) * min(rightRest, leftLeft);
    }

    sub *= 2;

    sub += X[i];
    ret = max(ret, sub);
    uku = max(uku, ret);
    return ret;
  };

  int from = 0;
  int to = N;
  for(; to - from > 1;) {
    int mid = (from + to) / 2;
    (Z(mid) - Z(mid - 1) > 0 ? from : to) = mid;
  }

  return max(uku, Z(from));
}

int main() {
  cin >> L >> N;
  vector< int > X(N + 1);
  X[0] = 0;
  for(int i = 1; i <= N; i++) cin >> X[i];
  int64 ret = solve(X);
  for(auto &p : X) p = (L - p) % L;
  sort(begin(X), end(X));
  cout << max(ret, solve(X)) << endl;
}

#include <bits/stdc++.h>
using namespace std;
using Int = long long;
Int solve(int L, int N, const vector<int>& X)
{
    vector<Int> Y(N+1), Z(N+1);
    Y[0] = Z[0] = 0;
    for (int i = 0; i < N; i++) {
        Y[i+1] = Y[i] + X[i];
        Z[i+1] = Z[i] + L - X[N-1-i];
    }
    Int ans = 0;
    for (int i = 1; i <= N; i++) {
        int r = i + (N - i) / 2;
        int l = N - r;
        Int d = -2*Y[i-1] + 2*Y[r] + 2*Z[l] - ((N - i) % 2 ? L - X[N-l] : X[r-1]);
        ans = max(ans, d);
    }
    return ans;
}
int main()
{
    int L, N; cin >> L >> N;
    vector<int> X(N);
    for (int& x : X) cin >> x;
    Int a = solve(L, N, X);
    reverse(begin(X), end(X));
    for (auto& x : X) x = L - x;
    Int b = solve(L, N, X);
    cout << max(a, b) << endl;
    return 0;
}

