int dp[2000][2000][2] = {};
int solve(int a, int b, int state){ //stateが0のとき今いるのはa-1、1のときb+1
    if(dp[a][b][state] != 0) return dp[a][b][state];
    if(a == b){
        if(state == 0) return max(X[a]-X[a-1], X[a-1]+L-X[b]);
        else return max(X[a]+L-X[b+1], X[b+1]-X[b]);
    }
    int ans = 0;
    if(state == 0){
        ans = max(ans, solve(a+1, b, 0) + X[a]-X[a-1]);
        ans = max(ans, solve(a, b-1, 1) + X[a-1]+L-X[b]);
    }
    else{
        ans = max(ans, solve(a+1, b, 0) + X[a]+L-X[b+1]);
        ans = max(ans, solve(a, b-1, 1) + X[b+1]-X[b]);
    }
    return dp[a][b][state] = ans;
}

