		d = pr - 1 - le;
		rLe = (SR[i + 1] - SR[n  + 1 - d]) * 2 + SL[i - 1] * 2 + tab[i];
	} else {
		d = le - pr;
		rLe = SR[i + 1] * 2 + (SL[i - 1] - SL[d]) * 2 + tab[i];
