//library
ll solve(int n, ll l, vl x){
    ll finalAns = 0;
    ll ans = x[0];
    rep(i, 1, n){
        if(i%2==0)ans+=(l-x[n-(i+1)/2])+x[(i)/2];
        else ans+=x[i/2]+(l-x[n-(i+1)/2]);
    }
    finalAns = ans;

    rep(i, 1, n){
        if((n-i)%2){
            int r = (n-i-1)/2;
            ans+=(2*(x[i+r]-x[i-1])-l);
        }else{
            int r = (n-i-2)/2;
            ans+=(2*((x[i+r]-x[i-1]))-(l-x[i+r+1]+x[i+r]));
        }
        chmax(finalAns, ans);
    }

    return finalAns;
}
