	x[0] = 0LL;
	rep(i,1,n+1) cin >> x[i];

	rx[0] = 0LL;
	rep(i,1,n+1) rx[n + 1 - i] = l - x[i];

	rep(i,1,n+1){
		sx[i] = sx[i - 1] + x[i];
		srx[i] = srx[i - 1] + rx[i];
	}

	ll ans = 0LL;

	rep(i,n+1){
		const int j = n - i;
		const int cmin = min(i,j);

		// i start
		{
			ll cur = 0LL;
			if(i > j) {
				cur += 2LL * (sx[i] - sx[i - cmin - 1]);
				cur += 2LL * srx[j];
			} else {
				cur += 2LL * sx[i];
				cur += 2LL * (srx[j] - srx[j - cmin]);
			}
			chmax(ans, cur - x[i]);
		}

		// j start
		{
			ll cur = 0LL;
			if(i > j) {
				cur += 2LL * (sx[i] - sx[i - cmin]);
				cur += 2LL * srx[j];
			} else {
				cur += 2LL * sx[i];
				cur += 2LL * (srx[j] - srx[j - cmin - 1]);
			}
