#include <bits/stdc++.h>
using namespace std;

#define ll long long
#define N 200010
ll l, a[N], sum[N], res;
int n;

void work()
{
	for (int i = n; i >= 1; --i)
	{
		int use = (n - i + 1);
		if (use > i - 1) break; 
		ll tmp = 2 * (l * use - sum[n] + sum[i - 1]) + 2 * (sum[i - 1] - sum[i - use - 1]);
		tmp -= l - a[n];  
		res = max(res, tmp);
	}
}

int main()
{
	while (scanf("%lld%d", &l, &n) != EOF)
	{
		for (int i = 1; i <= n; ++i) scanf("%lld", a + i);
		for (int i = 1; i <= n; ++i) sum[i] = sum[i - 1] + a[i];
		res = a[n];
		work();
		for (int i = 1; i <= n; ++i) a[i] = l - a[i];
		sort(a + 1, a + 1 + n);
		for (int i = 1; i <= n; ++i) sum[i] = sum[i - 1] + a[i];
		res = max(res, a[n]);
		work();		
		printf("%lld\n", res);
	}
	return 0;
}

