int dist[MAX];
int p[MAX], n, L;

void gen_p() {
  REP(i, n-1)
    dist[i] = p[i+1] - p[i];
  dist[n-1] = L + p[0] - p[n-1];

  REP(i, n) {
    pref[i] = (i ? pref[i-1] : 0) + dist[i];
    pref_i[i] = (i ? pref_i[i-1] : 0) + 2ll * i * dist[i];
  }
}

ll get_sum(ll t[], int poc, int kraj) {
  assert(kraj >= poc);
  return t[kraj] - (poc ? t[poc-1] : 0);
}

ll get_forward(int poc, int kraj, int prvi_koef) {
  //  assert(kraj >= poc);
  if (kraj < poc) return 0;
  return get_sum(pref_i, poc, kraj) +
    get_sum(pref, poc, kraj) * (prvi_koef - 2ll * poc);
}

ll get_backward(int poc, int kraj, int prvi_koef) {
