int solve(const std::vector<int>& A, int L) {
	int res = 0;
	int maxRes = 0;
	//RLRLRLRL...のとき
	int w = A.size();
	int dw = -2;
	for (int i = 0; i < A.size(); ++i) {
		w += dw;
		res += std::max({ w, 0LL }) * A[i];
