const ll INF = 1e9;
const ll MOD = 1000000007;  // 1e9 + 7

ll powmod(ll x, ll n) { // like pow(x, n)
  ll r = 1;
  while (n) {
    if (n & 1) {
      r = r * x % MOD;
    }
    x = x * x % MOD;
    n >>= 1;
  }
  return r;
}

ll N, L;

ll solve(const vector<ll>& x) {
  vector<ll> sumx(x);
  for (int i = 1; i < N; i++) {
    sumx[i] += sumx[i - 1];
  }

  ll res = 0;
  for (int i = 0; i < N-1; ++i) {  // i: starting point of turn.
    int mid = i + (N - i) / 2;  // The last index. e.g. If N = 10 and i = 0, then mid = 5.
    if ((N - i) % 2 == 0) {  // The number of remaining is odd. e.g. 0, 1, ... 9 exist, and i = 0. remaining is 1, 2, ... 9. mid is 5.
      // The result is (X[i]) + (X[i] + revX[N-1]) + (revX[N-1] + X[i+1]) + ... + (X[mid-1] + revX[mid]) = (X[i]*2 + X[i+1]*2 + ... X[mid-1]*2) + ((L-X[mid+1])*2 + (L-X[mid+2])*2 + ... + (L-X[N-1])*2) + (L - X[mid])
      // = (X[i] + X[i+1] + ... + X[mid-1])*2 + (L-X[mid]) + (L-X[mid+1] + L-X[mid+2] + ... + L-X[N-1])*2

      ll val = 2 * (sumx[mid] - sumx[i] - x[mid] + x[i]) - x[mid] - 2 * (sumx[N - 1] - sumx[mid]) + (N - 1 - i) * L;
      res = max(res, val);
    } else {  // The number of remaining is even. e.g. 0, 1, ... 8 exist, and i = 0. remaining is 1, 2, ... 8. mid is 4.
      // (X[i] + X[i+1] + ... + X[mid-1])*2 + X[mid] + (L-X[mid+1] + L-X[mid+2] + ... + L-X[N-1])*2

      ll val = 2 * (sumx[mid] - sumx[i] - x[mid] + x[i]) + x[mid] - 2 * (sumx[N - 1] - sumx[mid]) + (N - 1 - i) * L;
      res = max(res, val);
    }
  }
  return res;
}

int main(int argc, char** argv) {
  cin >> L >> N;
  vector<ll> X(N);
  rep(i, N) {
    cin >> X[i];
  }
  // Try anti-clock order at first.
  ll ans = 0;
  ans = max(ans, solve(X));

  // Calculate reversed.
  reverse(all(X));
  rep(i, N) {
    X[i] = L - X[i];
  }
  ans = max(ans, solve(X));

  cout << ans << endl;
}

