			tmp+=min(abs(x.front()-cx),l-abs(x.front()-cx));
			cx=x.front();
			x.pop_front();
		}
		else {
			tmp+=min(l-abs(x.back()-cx),abs(x.back()-cx));
			cx=x.back();
			x.pop_back();
		}
		ans+=tmp;
	}
	}
