long burn(int l, int r, bool is_l){
    if(l + 1 == r){
        return 0;
    }else if(dp[l][r][is_l] != -1){
        return dp[l][r][is_l];
    }
    if(is_l){
        return dp[l][r][is_l] = max(burn(l + 1, r, true) + X[l + 1] - X[l], burn(l, r - 1, false) + X[l] + L - X[r - 1]);
