typedef struct Adj {
    int left; //反時計
    int right; //時計
} Adj;

int L, N;

long long tree_dist(int a, int b) {
    if (a > b) {
        return max(a - b, L - (a - b));
    } else {
        return max(b - a, L - (b - a));
    }
}

long long tree_dist_l(int a, int b) {
    if (a > b) {
        return L - (a - b);
    } else {
        return b - a;
    }
}

long long tree_dist_r(int a, int b) {
    if (a > b) {
        return a - b;
    } else {
        return L - (b - a);
    }
}

long long max_walk(map<int, Adj> tree, int rest, int pos) {
    if (rest == 1) {
        return tree_dist(pos, tree[pos].left);
    } else if (rest == 0) {
        return 0;
    } else {
        //左
        map<int, Adj> tree_l = tree;
        long long left = tree_dist_l(tree[pos].left, pos);
        tree_l[tree[pos].left].right = tree[pos].right;
        tree_l[tree[pos].right].left = tree[pos].left;
        //右
        map<int, Adj> tree_r = tree;
        long long right = tree_dist_r(tree[pos].right, pos);
        tree_l[tree[pos].left].right = tree[pos].right;
        tree_l[tree[pos].right].left = tree[pos].left;
        return max(left + max_walk(tree_l, rest - 1, tree[pos].left), right + max_walk(tree_r, rest - 1, tree[pos].right));
    }
    return 0;
}

int main(void) {
    cin >> L >> N;
    int X[N];
    map<int, Adj> tree;

    for (int i=0; i<N; i++) {
        cin >> X[i];
    }

    for (int i=0; i<N; i++) {
        if (i == 0) {
            tree[X[i]].left = X[i+1];
            tree[X[i]].right = X[N-1];
        } else if (i == N-1) {
            tree[X[i]].left = X[0];
            tree[X[i]].right = X[N-2];
        } else {
            tree[X[i]].left = X[i+1];
            tree[X[i]].right = X[i-1];
        }
    }
    //左に行く場合
    long long go_to_left = max_walk(tree, N-1, X[0]) + X[0];
    //右に行く場合
    long long go_to_right = max_walk(tree, N-1, X[N-1]) + L - X[N-1];

    // cout << min(go_to_left, go_to_right) << endl;
    return 0;
}

