const int max_n = 200222, inf = 1000111222;

int n, l, a[max_n];
long long sum[max_n];

long long get_sum(int l, int r) {
    if (l > r) {
        return 0;
    }
    if (l == 0) {
        return sum[r];
    }
    return sum[r] - sum[l - 1];
}

long long solve() {
    sum[0] = a[0];
    for (int i = 1; i < n; ++i) {
        sum[i] = a[i] + sum[i - 1];
    }
    long long ans = a[n - 1];
    for (int i = 0; i + 1 < n; ++i) {
        int cnt = n - i;
        long long res = -a[i];
        if (cnt % 2) {
            res -= 2 * get_sum(i + 1, i + cnt / 2 - 1);
            res -= a[i + cnt / 2];
            res += 2 * get_sum(i + cnt / 2 + 1, n - 1);
        } else {
            res -= 2 * get_sum(i + 1, i + cnt / 2 - 1);
            res += a[i + cnt / 2];
            res += 2 * get_sum(i + cnt / 2 + 1, n - 1);
        }
        res = 1LL * l * (cnt - 1) - res + a[i];
        ans = max(ans, res);
    }
    return ans;
}

