int dfs(int p, int i, int j, int ans) {
  if (i > j)
    return ans;

  int d1 = CDIFF(L, X[i], p);
  int d2 = CDIFF(L, p, X[j]);
  return max(dfs(X[i], i + 1, j, ans + d1), dfs(X[j], i, j - 1, ans + d2));
}

