ll L, N;

ll solve(vector<ll> &X){
	vector<ll> S(N+1, 0), T(N+1, 0);
	REP(i, N) S[i+1] = S[i] + X[i];
	REP(i, N) T[i+1] = T[i] + (L-X[N-1-i]);

	ll res = 0;

	for(int t=N;t>=1;t--){
		ll tmp = 0;
		tmp += 2*T[t/2];
		tmp += 2*(S[N-t+(t+1)/2] - S[N-t]);
		if(t%2==0){
			tmp -= (L-X[N-t/2]);
		}else{
			tmp -= X[N/2+(N-t)/2];
		}
		chmax(res, tmp);
	}

	return res;
}

