	int len = (x[n - r - 1 + n] - x[pos]) % L;
	//cout << "ret = " << L - len << endl;
	return L - len;
}

int dfs(int l, int r, int way) {
	if (l + r == n) return 0;
	if (dp[l][r][way] != -1) return dp[l][r][way];

	int u = dfs(l + 1, r, 0) + fL(l, r, way);
	int v = dfs(l, r + 1, 1) + fR(l, r, way);
	//cout << l << ", " << r << ", " << way << ", ret = " << max(u, v) << endl;
	return dp[l][r][way] = max(u, v);
}

