ll get(int l, int len) {
    int r = l + len - 1;
    ll ret = 0;
    for (int i = l, k = 1; i <= r; ) {
        int ind = i / S;
        int st = ind * S;
        int fin = min(st + S - 1, n - 1);
        if (l <= st && r >= fin) {
            ret += sum[ind] * (k - 1) + res[ind];
            k += 2LL * (fin - st + 1);
            i = fin + 1;
        } else {
            ret += d[i] * k;
            ++i;
            k += 2;
        }

    }
    return ret;
}


ll solve(vl dd) {
    d = dd;
    n = d.size();
    pref[0] = d[0];
    for (int i = 1; i < n; ++i) pref[i] = pref[i - 1] + d[i];

    for (int i = 0; i < n; ++i) {
        int ind = i / S;
        int st = ind * S;
        int fin = min(st + S - 1, n - 1);
        res[ind] = sum[ind] = 0;
        for (int j = st, k = 1; j <= fin; ++j, k += 2) {
            res[ind] += d[j] * k;
            sum[ind] += d[j];
        }

        i = fin;
    }

    ll ret = get_pref(1, n - 1);
    ll add = 0, sm = 0;
    for (int i = 1; i < n; ++i) {
        if (i * 2 > n - 1) break;
        add += d[i - 1];
        sm += add;
        add += d[i - 1];
        ll a = get_pref(0, i - 1) + sm + get(i + 1, i) + (i * 2 + 1) * get_pref(i * 2 + 1, n - 1);
        ll b = get_pref(i + 1, n - 1) + sm + get(i + 1, i) + (i * 2 - 1) * get_pref(i * 2 + 1, n - 1);
//        ll cur = max(get_pref(0, i - 1), get_pref(i + 1, n - 1)) + sm + get(i + 1, i) + ((i - 1) * 2 + 1)  * get_pref(i * 2 + 1, n - 1);
        ll cur = max(a, b);
        inmax(ret, cur);
    }
    return ret;
}

