llint d[200005], sumd[200005];

llint calc()
{
	llint ret = 0, sum = 0;
	llint s = n-n/2, l = 2*s-n;
	for(int i = s+1, t = 0; i <= n; i++, t+=2) sum += t*d[i];
	for(int i = s, t = 1; i > l; i--, t+=2) sum += t*d[i];
	for(int i = 1; i <= l; i++) sum += (2*(n-s)-1)*d[i];

	ret = sum;
	for(int i = s+2; i <= n; i++){
		sum -= (sumd[n]-sumd[i-1])*2;
		sum += d[i-1];
		sum -= sumd[l+1]*2;
		sum += (sumd[i-2]-sumd[l+2])*2;
		l++;
	}
	ret = max(ret, sum);

	sum = 0;
	s = n-n/2+1, l = 2*s-n-1;
	for(int i = s+1, t = 1; i <= n; i++, t+=2) sum += t*d[i];
	for(int i = s, t = 0; i > l; i--, t+=2) sum += t*d[i];
	for(int i = 1; i <= l; i++) sum += 2*(n-s)*d[i];

	ret = max(ret, sum);
	for(int i = s+2; i <= n; i++){
		sum -= (sumd[n]-sumd[i-1])*2;
		sum -= d[i-1];
		sum -= sumd[l+1]*2;
		sum += (sumd[i-2]-sumd[l+2])*2;
		l++;
	}
	ret = max(ret, sum);

	return ret;
}

