	n++;

	for(int i = 1; i <= n; i++) sumd[i] = sumd[i-1] + d[i]; 
	llint ans = calc();

	//for(int i = 1; i <= n; i++) cout << d[i] << " "; cout << endl;

	reverse(d+1, d+n+1);
	for(int i = 1; i <= n; i++) sumd[i] = sumd[i-1] + d[i]; 
	ans = max(ans, calc());

	cout << ans << endl;
	return 0;
}

