  range(i, 0, n) {
    cin >> a[i];
  }
  vector<long long> pref(n);
  vector<long long> rev(n);
  range(i, 0, n) {
    pref[i] = a[i];
    if(i > 0) pref[i] += pref[i - 1];
  }
  husk(i, n - 1, -1) {
    rev[i] = s - a[i];
    if(i < n - 1) rev[i] += rev[i + 1];
  }
  auto get = [&](int p, int c, int z) {
    if(c == 0) return 0LL;
    if(!z) {
      return pref[p] - (c <= p ? pref[p - c] : 0);
    } else {
      return rev[p] - (p + c < n ? rev[p + c] : 0);
    }
  };
  long long res = 0;
  range(p, 0, n) {
    int x = min(p, n - p - 1);
    long long cur = max(a[p], s - a[p]);
    cur += get(p - 1, x, 0) * 2;
    cur += get(p + 1, x, 1) * 2;
    res = max(res, cur);
    cur = a[p];
    x = min(p, n - p - 2);
    if(x > -1) {
      cur += get(p + 1, x + 1, 1) * 2;
      cur += get(p - 1, x, 0) * 2;
    }
    res = max(res, cur);
    cur = s - a[p];
    x = min(p - 1, n - p - 1);
    if(x > -1) {
      cur += get(p - 1, x + 1, 0) * 2;
      cur += get(p + 1, x, 1) * 2;
    }
    res = max(res, cur);
  }
  cout << res;
  return 0;
}

