int L, n;

int getle(int l, int r, int core) {
	assert(l <= r);
	return (sumle[r] - sumle[l - 1]) - core * (r - l + 1);
}

int getri(int l, int r, int core) {
	assert(l <= r);
	return (sumri[l] - sumri[r + 1]) + core * (r - l + 1);
}

void init() {
	memset(sumle, 0, sizeof(sumle)); memset(sumri, 0, sizeof(sumri));
	loop(i, 1, n) sumle[i] = sumle[i - 1] + a[i];
	rloop(i, n, 1) sumri[i] = sumri[i + 1] + (L - a[i]);
}

int cal(int l, int r) {
	if (l == r) return a[l];
	int ret = a[l];
	int midPoint = (r - l + 2) / 2 + l - 1;
	int key = 0; if ((r - l + 1) % 2 == 1) key = 1;
	ret += (getle(l, midPoint, a[l])) * 2 + getri(midPoint + 1, r, a[l]) * 2;
	if (key == 0) ret -= (getle(midPoint, midPoint, a[l])) + getri(midPoint + 1, midPoint + 1, a[l]) * 2;
	else ret -= getri(midPoint + 1, midPoint + 1, a[l]) + (getle(midPoint, midPoint, a[l])) * 2;
	ret += max(a[midPoint + 1] - a[midPoint], a[midPoint] + L - a[midPoint + 1]);
	return ret;
}

