        int tp = (N-i+1)/2+i-1; //+方向に燃やす最後の木の番号
        int mp = tp+1; //-方向に燃やす最後の木の番号
        int dist;
        if ((N-i) % 2 == 0) { //-で終了
            if (i==0) dist = 2*(s[tp]+t[mp]);
            else dist = 2*(s[tp]-s[i-1]+t[mp]);
            dist -= (L-X[mp]);
