    for(int i=0; i<N; i++) { //i:最初に折り返す木の番号
        int mp = N-1-((N-i+1)/2+i-1); //-方向に燃やす最後の木の番号
        int tp = mp-1; //+方向に燃やす最後の木の番号
        int dist;
        if ((N-i) % 2 == 0) { //+で終了
            if (i==0) dist = 2*(s[tp]+t[mp]);
            else dist = 2*(s[tp]+t[mp]-t[N-1-i+1]);
            dist -= X[tp];
        } else { //-で終了
            if (i==0) dist = 2*(s[tp]+t[mp]);
            else if (i==N-1) dist = 2*(t[mp]-t[mp+1]);
            else dist = 2*(s[tp]+t[mp]-t[N-1-i+1]);
            dist -= (L-X[mp]);
        }
        ans=max(ans, dist);
    }
    cout << ans << endl;
    return 0;

}

