inline int rev(int x) { return n-x+1; }

//left: 0 b
//right: 1 a
LL calc(int dir, int l, int r) {
    int mid = (l+r)>>1;
    if (r-mid == mid-l) {
        LL ret = (pa[mid-1] - pa[l-1] + pb[rev(mid+1)] - pb[rev(r+1)]) * 2ll;
        if (dir) ret += a[mid];
        else ret += b[mid];
        return ret;
    }
    return (pa[mid] - pa[l-1] + pb[rev(mid+1)] - pb[rev(r+1)]) * 2ll;
}

