typedef long long LL;
constexpr LL MOD = 998244353;
class Solution {
  vector<int> A;
  LL L, N;
  LL DFS(int from, int to) {
    if (from == to) return 0;
    LL ch1, ch2;
    if (from < to) {
      return (ch1 = A[from] + L - A[to]) >= (ch2 = A[from + 1] - A[from]) ? 
             DFS(to, from + 1) + ch1 : DFS(from + 1, to) + ch2; 
    }
    else {
      return (ch1 = L - A[from] + A[to]) >= (ch2 = A[from] - A[from - 1]) ? 
        DFS(to, from - 1) + ch1 : DFS(from - 1, to) + ch2;
    }
  }
public:
  void run(istream &in, ostream &out) {
    in >> L >> N;
    A.resize(N);
    for (int i = 0; i < N; ++i) in >> A[i];
    LL ans = DFS(0, N - 1) + A[0];
    out << max(ans, DFS(N - 1, 0) + L - A.back()) << '\n';
  }
};

int main() { 
  ios_base::sync_with_stdio(false); cin.tie(0);
  Solution().run(cin, cout);
  return 0;
}

