int dfs(int max_index, int min_index, int pos){

	if(max_index == min_index){
		if(pos > X[max_index]){
			return std::max(pos - X[max_index], (L - pos) + X[max_index]);
		}
		else{
			return std::max(X[max_index] - pos, (L - X[max_index]) + pos);
		}
	}

	int res = 0;

	//Choose max
	if(pos > X[max_index]){
		res = dfs(max_index - 1, min_index, X[max_index]) + pos - X[max_index];
	}
	else{
		res = dfs(max_index - 1, min_index, X[max_index]) + pos + L - X[max_index];
	}

	//Choose min
	if(pos < X[min_index]){
		res = std::max(res, dfs(max_index, min_index + 1, X[min_index]) + X[min_index] - pos);
	}
	else{
		res = std::max(res, dfs(max_index, min_index + 1, X[min_index]) + X[min_index] + L - pos);
	}

	return res;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

const int MAXN = 200055;

ll S[MAXN*2], W[MAXN*2];

int B[MAXN*2];
int A[MAXN];

ll Ans;
int N, L;

ll getSum(int s, int e) {
	if(s > e) return 0;
	return S[s] - S[e+1];
}
ll f(int s, int e) {
	return W[s] - W[e+1] - S[e+1]*(e-s+1)*2;
}
ll g(int s, int e) {
	return getSum(s, e)*(e-s+1)*2 - f(s, e);
}

void goRight(int s, int e) {
	int lc = N-s+1, rc = e-N-1;
	ll t = 0, rt = 0;
	if(lc+1 <= rc) {
		t += g(e-lc-1, e-1) + getSum(N+1, e-lc-2) * (lc*2+1);
		t += f(s, N) + getSum(s, N);
	} else {
		t += g(N+1, e-1);
		t += f(s, s+rc-1) + getSum(s, s+rc-1);
		t += getSum(s+rc, N) * rc*2;
	}
	if(Ans < t) Ans = t;
}

void solve() {
	for(int i = 1; i <= N; i++) {
		B[N+i+1] = A[i];
		B[i] = A[i]-L;
	}
	for(int i = N*2+1; 0 <= i; i--)
		S[i] = S[i+1] + (B[i+1]-B[i]);
	for(int i = N*2+1; i; i--)
		W[i] = W[i+1] + S[i+1]*2 + (B[i+1]-B[i]);

	for(int s = 2, e = N+2; e <= N*2+1; s++, e++)
		goRight(s, e);
}

int main() {
	ios::sync_with_stdio(false);

	cin >> L >> N;
	for(int i = 1; i <= N; i++) cin >> A[i];

	solve();
	reverse(A+1, A+N+1);
	for(int i = 1; i <= N; i++) A[i] = L-A[i];
	solve();

	cout << Ans << endl;
	return 0;
}

