ll DP(int l, int r, int f) {
	if (~dp[l][r][f]) return dp[l][r][f];
	if (l > r) return 0;
	if (!f) dp[l][r][f] = max(DP(l + 1, r, 0) + x[l] - x[l - 1], DP(l, r - 1, 1) + x[l - 1] + L - x[r]);
	else dp[l][r][f] = max(DP(l, r - 1, 1) + x[r + 1] - x[r], DP(l + 1, r, 0) + x[l] + L - x[r + 1]);
	return dp[l][r][f];
}

