const int N=200005;
int n,L;
int x[N];
LL tl[N],tr[N];
LL sv(){
	LL ans=0;
	for (int i=1;i<=n;i++)
		tl[i]=tl[i-1]+x[i];
	for (int i=n;i>=1;i--)
		tr[i]=tr[i+1]+L-x[i];
	for (int i=1;i<n;i++){
		int las=max(x[i+1]-x[i],x[i]+L-x[i+1]);
		if (i==n-1){
			ans=max(ans,(LL)x[i]+las);
			continue;
		}
		LL tmp=x[i]+las;
		int d=i-1-(n-i-1);
		if (d>=0){
			tmp+=tl[i-1]*2-tl[d]*2;
			tmp+=tr[i+2]*2;
		}
		else {
			d=-d;
			tmp+=tl[i-1]*2;
			tmp+=tr[i+2]*2-tr[n-d+2]*2;
		}
		ans=max(ans,tmp);
	}
	return ans;
}
