ll suma(int l, int r)
{
	if(l>r) return 0;
	if(l==0) return sa[r];
	else return sa[r]-sa[l-1];
}

ll sumb(int l, int r)
{
	if(l>r) return 0;
	if(l==0) return sb[r];
	else return sb[r]-sb[l-1];
}

int main()
{
	ios_base::sync_with_stdio(0); cin.tie(0);
	ll L, n; cin>>L>>n;
	for(int i=0;i<n;i++)
	{
		cin>>a[i];b[i]=L-a[i];
	}
	for(int i=0;i<n;i++)
	{
		sa[i]=a[i]; sb[i]=b[i];
		if(i>0) 
		{
			sa[i]+=sa[i-1]; sb[i]+=sb[i-1];
		}
	}
	ll ans = max(a[n-1], b[0]);
	for(int i=0;i<n-1;i++)
	{
		//L for a[0],a[1],...,a[i] and R for a[i+1],...,a[n-1]
		int l = i+1; int r = n-(i+1);
		//left first
		{
			ll res = 0;
			if(l>r)
			{
				res = 2LL*(suma(i-r,i)+sumb(i+1,i+r)) - a[i];
				res = max(res, 2LL*(suma(i-r+1,i)+sumb(i+1,i+r)) - b[i+1]);
