            mid = lo + (hi - lo) / 2;
            if (f(h, mid) > f(h, mid + 1)) hi = mid;
            else lo = mid + 1;
        }
        For(k, lo - 2, lo + 3) f(h, k);
    }
    writeln(ans);
    return 0;
}

