ll l, N;

ll rec(ll R, ll L, bool is_right){
	if(dp[R][L][is_right]>=0) return dp[R][L][is_right];
	ll res;
	if(R==0 && L==N-1){
		if(is_right) res = X[0] + 2*(l-X[N-1]);
		else res = 2*X[0] + (l-X[N-1]);
	}else if(R==0 && is_right){
		res = X[0] + 2*(l-X[L]);
	}else if(L==N-1 && !is_right){
		res = 2*X[R] + (l-X[N-1]);
	}else{
		ll cand1, cand2;
		if(is_right){
			cand1 = rec(R-1, L, true) + (X[R]-X[R-1]);
			cand2 = rec(R-1, L, false) + (X[N-1]-X[L]) + (l-X[N-1]) + X[0] + (X[R]-X[0]);
		}else{
			cand1 = rec(R, L+1, true) + (X[N-1]-X[L]) + (l-X[N-1]) + X[0] + (X[R]-X[0]);
			cand2 = rec(R, L+1, false) + (X[L+1]-X[L]);
		}
		res = max(cand1, cand2);
	}
	dp[R][L][is_right] = res;
	return res;
}

