LL L, N;
LL dp[2003][2003][2];
LL x[200002];

LL ff(int v1, int v2, bool f) {
	LL& sub = dp[v1][v2][f];
	if (~sub) return sub;
	sub = -1e18;
	auto Cost = [&](LL dist,int i) {
		return abs(dist - x[i]) % L;
	};
	int neXt = (v1 + 1) % N;
	if (neXt == v2)return sub = 0;
	if (f) {
		sub = max(sub, ff(neXt, v2, 1) + abs(x[neXt] - x[v1]));
	}
	else {
		sub = max(sub, ff(neXt, v2, 1) + Cost(L, v2) + Cost(0, neXt));
	}
	neXt = (v2 - 1 + N) % N;
	if (neXt == v1)return sub = 0;
	if (!f) {
		LL c;
		if (v2 == 0)c = abs(L - x[neXt]);
		else c = abs(x[neXt] - x[v2]);
		sub = max(sub, ff(v1, neXt, 0) + c);
	}
	else {
		sub = max(sub, ff(v1, neXt, 0) + Cost(0, v1) + Cost(L, neXt));
	}
	return sub;
}


