ll walk_len(bool is_ucw, int ucw, int cw, const VL& x) {
    if(ucw == cw) return 0;
    if(memo[ucw][cw][is_ucw] != -1) return memo[ucw][cw][is_ucw];
    ll ucw_len, cw_len;
    int next_ucw, next_cw;
    if(is_ucw) {
        ucw_len = (x[ucw + 1] - x[ucw] + l) % l;
        cw_len = (x[ucw] - x[cw] + l) % l;
        next_ucw = ucw + 1;
        next_cw = cw;
    } else {
        ucw_len = (x[ucw] - x[cw] + l) % l;
        cw_len = (x[cw] - x[cw - 1] + l) % l;
        next_ucw = ucw;
        next_cw = cw - 1;
    }

    return memo[ucw][cw][is_ucw] = 
        max(walk_len(true, next_ucw, next_cw, x) + ucw_len,
            walk_len(false, next_ucw, next_cw, x) + cw_len);
}


