ll dist(ll left, ll right, ll now, ll dir){

  if(right == left){
    return 0;
  }

  ll ans = 0;

  if(dir == 1){
    ll ccw = tr[left] > now ? tr[left] - now : l - now + tr[left];
    ans += ccw + dist(left+1, right, tr[left], -1);
  }else{
    ll cw = tr[right-1] > now ? now + l - tr[right-1] : now - tr[right-1];
    ans += cw + dist(left, right-1, tr[right-1], 1);
  }

  return ans;
}


