  for(ll i=0; i<n; i++){
    ans = max(ans, tr[i] + dist(i+1,n,tr[i],-1));
    ans = max(ans, l - tr[n-1-i] + dist(0,n-i-1,tr[n-1-i],1));
  }

  cout << ans << endl;
}

#include <cstdio>
