const int MAXN = 2e5 + 10;


int n, l;
int a[MAXN];
int d[MAXN];
typedef long long LL;

LL solve() {
  static LL sum[MAXN], sum1[MAXN], sum2[MAXN];
  for (int i = 1; i <= n; i++) sum[i] = sum[i - 1] + d[i];
  for (int i = 1; i <= n; i++) {
    sum1[i] = sum1[i - 1] + 2 * i * d[i];
    sum2[i] = sum2[i - 1] + 2 * (n - i) * d[i];
  }

  LL ans = 0;
  for (int i = 1; i < n; i++) {
    LL tot = i * sum[n - i];
    if (i & 1) {
      int p = n - (i >> 1);
      tot += (sum1[n] - sum1[p - 1]) - (sum[n] - sum[p - 1]) * 2 * p;
      tot += (sum2[p - 1] - sum2[n - i]) - (sum[p - 1] - sum[n - i]) * (2 * (n - p) + 1);
    } else {
      int p = n - (i >> 1) + 1;
      tot += (sum1[n] - sum1[p - 1]) - (sum[n] - sum[p - 1]) * (2 * p - 1);
      tot += (sum2[p - 1] - sum2[n - i]) -
        (sum[p - 1] - sum[n - i]) * (2 * (n - p + 1));    
    }
    //fprintf(stderr, "%lld\n", tot);
    ans = std::max(ans, tot);
  }
  return ans;
}
int main() {
  scanf("%d%d", &l, &n);
  for (int i = 1; i <= n; i++) {
    scanf("%d", a + i);
  }
  for (int i = 1; i <= n; i++) {
    d[i] = a[i] - a[i - 1];
  }
  n++;
  d[n] = l - a[n - 1];
  long long ans = solve();
  std::reverse(d + 1, d + n + 1);
  ans = std::max(ans, solve());
  printf("%lld\n", ans);


}

