int main() {
	int N; long long L;
	cin >> L >> N;
	vector<long long> X(N);
	for (int i = 0; i < N; ++i) {
		cin >> X[i];
	}
	long long ans = 0;
	for (int i = 0; i < 2; ++i) {
		for (int j = 0; j < N; ++j) {
			int l = N - 1, r = j, s = 0; long long sum = X[j];
			if (j + 1 != N) sum += L - X[N - 1] + X[j];
			while (l - r > 1) {
				if (s == 0) {
					sum += L - X[l] + X[++r];
				}
				else {
					sum += L - X[--l] + X[r];
				}
				s ^= 1;
			}
			ans = max(ans, sum);
		}
		reverse(X.begin(), X.end());
		for (int j = 0; j < N; ++j) {
			X[j] = L - X[j];
		}
	}
	cout << ans << endl;
	return 0;
}

