ll dp(int x, int y, int l){
    if(x>y)
        return 0;
    ll res=0;
    if(l){
        if(a[x]-a[x-1]>a[x-1]+L-a[y])
            res=a[x]-a[x-1]+dp(x+1, y, 1);
        else
            res=a[x-1]+L-a[y]+dp(x, y-1, 0);
    }
    else{
        if(a[x]+L-a[y+1]>a[y+1]-a[y])
            res=a[x]+L-a[y+1]+dp(x+1, y, 1);
        else
            res=a[y+1]-a[y]+dp(x, y-1, 0);
    }
    return res;
}
