		} else {
			if((x[r] - x[r - 1]) < (x[l + 1] + (L - x[r]))) ans += (x[l + 1] + (L - x[r])), l++, opt ^= 1;
			else ans += (x[r] - x[r - 1]), r--; 			
		}
		if(l + 1 == r) break;
	}
