using namespace std;
const int _=5e5+20;
ll n,L,x[_],y[_],sx[_],sy[_],ans;
ll f(int l,int r){ return sx[r]-sx[l-1];}
ll g(int l,int r){ return sy[r]-sy[l-1];}
void solve(){
	ans=max(ans,x[n]);
	for(int i=1;i<=(n>>1);++i){
		int A=i,B=i,no=n-A-B;
		ans=max(ans,x[no]+x[no+B]+(f(no+1,no+B-1)+g(no+B+1,n))*2);
		ans=max(ans,y[no+B+1]+(f(no+1,no+B)+g(no+B+2,n))*2);
		if(i*2+1<=n){
			A=i+1;B=i;no=n-A-B;
			ans=max(ans,x[no]+y[no+B+1]+(f(no+1,no+B)+g(no+B+2,n))*2);
			A=i;B=i+1;no=n-A-B;
			ans=max(ans,x[no+B]+(f(no+1,no+B-1)+g(no+B+1,n))*2);
		}
	}
}
int main(){
	ios::sync_with_stdio(false);
	cin>>L>>n;
	for(int i=1;i<=n;++i)cin>>x[i],sx[i]=x[i];
	for(int i=1;i<=n;++i)sy[i]=y[i]=L-x[i];
	for(int i=1;i<=n;++i)sx[i]+=sx[i-1],sy[i]+=sy[i-1];
	solve();reverse(x+1,x+n+1);reverse(y+1,y+n+1);swap(x,y);
	for(int i=1;i<=n;++i)sx[i]=sx[i-1]+x[i],sy[i]=sy[i-1]+y[i];
	solve();cout<<ans<<endl;
	return 0;
}

