vector<vector<vector<ll>>> memo;
ll L, N;
ll rec(int n, int s, int t, vector<ll> &X, int a) {
    //dump(s);
    //dump(t);
    //dump(n);
    if (s > t) {
        return 0;
    }
    if (memo[s][t][a] != -1) return memo[s][t][a];
    ll dnow = X[n];
    ll ds = X[s];
    ll dt = X[t];
    if (s < n) {
        ds += L;
    }
    if (t > n) {
        dt -= L;
    }
    ll ans = max(rec(s, s + 1, t, X, 0) + ds - dnow, rec(t, s, t - 1, X, 1) + dnow - dt);
