#include<iostream>
#include<cstdio>
using namespace std;

unsigned long long int L, N, *X;

int PPP(unsigned long long int p , unsigned long long int mm , bool de )
{
	if (!de)
	{
		//右
		if (p > mm)
			return p - mm;
		else
			return L - mm + p;
	}
	else
	{
		//左
		if (p < mm)
			return mm - p;
		else
			return L - mm + p;

	}
	return 0;
}

int main(void)
{
	cin >> L >> N;

	X = new unsigned long long int[N];

	for (int i = 0; i < N; i++)
		cin >> X[i];

	unsigned long long int left = 0 , right = N - 1;

	unsigned long long int mm = 0;

	unsigned long long int p = 0;

	bool flag = false;
	while(1)
	{
		if (flag)
			break;
		if (left == right)
			flag = true;

		unsigned long long int pl = PPP(p, X[left], true);
		unsigned long long int pr = PPP(p, X[right], false);
		if (pl > pr)
		{
			p = X[left];
			mm += pl;
			left++;	
		}
		else
		{
			p = X[right];
			mm += pr;
			right--;
		}
	}
	cout << mm << endl;

	return 0;
}

