const int nmax = 2e5 + 4;
long long l, n;
long long x[nmax];
long long ac[nmax];

long long solve(bool right, int s) {
  long long ans;
  if (right){
    if (!((n - s) & 1)) {
      ans = 2 * (-ac[s - 1] + ac[(s + n) / 2 - 1] + ac[(s + n) / 2] - ac[n])
      + x[(s + n) / 2] + (n - s) * l;
    } else {
      ans = 2 * (-ac[s - 1] + ac[(s + n) / 2] + ac[(s + n) / 2 + 1] - ac[n])
      - x[(s + n) / 2 + 1] + (n - s) * l;
    }
  } else {
    if (!(s & 1)) {
      ans = 2 * (ac[s / 2 - 1] + ac[s / 2] - ac[s])
      + x[s / 2] + s * l;
    } else {
      ans = 2 * (ac[s / 2] + ac[s / 2 + 1] - ac[s])
      - x[(s + 1) / 2] + s * l;
    }
  }
  return ans;
}


