int max(int a, int b)
{ return (a > b) ? a : b; }

const int MAXN = 2031;
int x[MAXN];
ll dp[MAXN][MAXN][2];
int main()
{
    ios_base::sync_with_stdio(0);
    cin.tie(0);

    ll L, n;
    cin >> L >> n;

    for (int i = 0; i < n; i++)
    {
        cin >> x[i];
    }

    for (int i = 0; i < MAXN; i++)
    for (int j = 0; j < MAXN; j++) dp[i][j][0] = -1000000000000000L, dp[i][j][1] = -1000000000000000L;
    dp[0][1][1] = x[0];
    dp[1][0][0] = L - x[n - 1];
    ll ans = -1;
    for (int i = 0; i <= n; i++)
    {
        for (int j = 0; j <= n; j++)
        {
            if (i + j > n) break;
            if (i + j <= 1) continue;
            if (i > 0) dp[i][j][0] = max(dp[i - 1][j][0] + (i >= 2 ? x[n - i + 1] : L) - x[n - i], dp[i-1][j][1] + (x[j - 1] + (L - x[n - i])));
            if (j > 0) dp[i][j][1] = max(dp[i][j - 1][1] + x[j - 1] - (j >= 2 ? x[j - 2] : 0), dp[i][j - 1][0] + (L - x[n - i]  + x[j - 1]));
            if (i + j == n) ans = max(ans, max(dp[i][j][0], dp[i][j][1]));

//            cerr << i << " " << j << " " << dp[i][j][0] << " " << dp[i][j][1] << endl;
        }

    }
    cout << ans;

    return 0;
}

