int L;
int N;
vector<int> v;
vector<vector<int> > k;

void init()
{
    cin >> L >> N;
    if (N > 2000) exit(1);
    vector<int> t;
    v.RS(N+1);
    CINV(t, N);
    v[0] = t[0];
    v[N] = L - t[N-1];
    reps(i, 1, N) {
        v[i] = t[i] - t[i-1];        
    }
}


void solve()
{
   rep(i, N) {
       vector<int> t(N+1, 0);
       int cnt = 0;
       reps(j, i+1, N+1) {
           t[j] = cnt * 2 + 1;
           if (cnt < i) cnt++;
       }
       cnt = 0;
       rrep(j, i) {
           t[j] = cnt * 2 + 2;
           if (cnt < N - i - 1) cnt++;
       }
       k.PB(t);
       reverse(all(t));
       k.PB(t);
   }
   int res = 0;
   for (auto x : k) {
       int t = 0;
       rep(j, N+1) {
           t += x[j] * v[j];
       }
       res = max(res, t);
   }
   cout << res << endl;
}

