typedef pair<ll, ll> P;
typedef pair<P, int> PPI;
typedef pair<P, P> PPII;
#define INF INT_MAX/3
#define MAX_N 1000
#define M_INF 1000000000
int n,m,v,i,L,l,r;
void solve(){
   cin.tie(0);
  ios::sync_with_stdio(false);
  cin>>L>>n;
  ll dp[n];
  rep(i,n) cin>>dp[i];
  ll ans = 0;
  ll now = 0;
  l = 0,r = n-1;
  ll l_len,r_len;
  priority_queue<PPII,vector<PPII>,greater<PPII> > que;
  que.push(PPII(P(0,n-1),P(0,0)));
  ll dpp[n];
  rep(i,n) dpp[i] = -1;
  while(!que.empty()){
    PPII p = que.top();
    que.pop();
    if(dpp[n-1-(p.fi.se-p.fi.fi)] > p.se.se) continue;
    dpp[n-1-(p.fi.se-p.fi.fi)] = p.se.se;
    // cout<<p.fi.fi<<" "<<p.fi.se<<" "<<p.se.fi<<" "<<p.se.se<<endl;
    l = p.fi.fi;
    r = p.fi.se;
    now = p.se.fi;
    if(now < dp[l]) l_len = abs(dp[l]-now);
    else l_len = abs(dp[l]+L-now);
    if(now < dp[r]) r_len = abs(now+L-dp[r]);
    else  r_len = abs(now-dp[r]);
    if(r-l==0){
      ans = MAX(ans,p.se.se+l_len);
      ans = MAX(ans,p.se.se+r_len);
    } else {
        que.push(PPII(P(l+1,r),P(dp[l],p.se.se+l_len)));
        que.push(PPII(P(l,r-1),P(dp[r],p.se.se+r_len)));
    }
  }

  cout<<ans<<endl;

}

int main(){
  solve();
  return 0;
}

