int L,N;
int circle(int now, int before ,int after,int score){
    if (before==after){
        if(now+1==before){
            return max(score+a[after]-a[now],score+a[now]+L-a[after]);
        }
        return max(score+a[now]-a[after],score-a[now]+L+a[after]);
    }
    if(now+1==before){
        int t=circle(before,before+1 ,after,score+a[before]-a[now]);
        int r=circle(after,before ,after-1,score+a[now]+L-a[after]);
        if (t>r){
            return t;
        }
        return r;
    }
    else if(now-1==after){
        int t=circle(before,before+1 ,after,score+a[before]+L-a[now]);
        int r=circle(after,before ,after-1,score+a[now]-a[after]);
       if (t>r){
            return t;
        }
        return r;
    }

}
