#include<bits/stdc++.h>
#define ll long long
#define maxn 400010
using namespace std;
int dis[maxn], l;
ll pre[maxn];
ll get_mn(int l, int r, int x)
{
	int tl = l, tr = min(r, l + x - 1);
	return 2 * (pre[tr] - pre[tl - 1]);
}
ll get_mx(int l, int r, int x)
{
	int tl = max(l, r - x + 1), tr = r;
	return 2 * (pre[tr] - pre[tl - 1]);
}
ll solve(int l1, int r1, int l2, int r2)
{
	if (l1 > r1) return dis[r2] - l;
	if (l2 > r2) return l - dis[l1];
	ll res = 0;
	for (int i = 0; i <= 1; i++)
		for (int j = 0; j <= 1; j++)
		{
			ll sum = 0;
			if (i == 0) sum = l;
			else sum = -l;
			int t1 = r1 - l1 + 1, t2 = r2 - l2 + 1;
			if (i == 0) t2++; else t1++;
			t1--; t2--;
			if (j == 0) sum = sum - dis[l1] + get_mx(l2, r2, t1) - get_mn(l1 + 1, r1, t2);
			else sum = sum + dis[r2] - get_mn(l1, r1, t2) + get_mx(l2, r2 - 1, t1);
			res = max(res, sum);
		}
	return res;
}
int main()
{
	int n;
	scanf("%d%d", &l, &n);
	for (int i = 1; i <= n; i++)
	{
		scanf("%d", &dis[i]);
		dis[i + n] = dis[i] + l;
	}
	for (int i = 1; i <= 2 * n; i++)
		pre[i] = pre[i - 1] + dis[i];
	ll res = 0;
	for (int i = 1; i <= n; i++)
	{
		int t1 = n - i + 1, t2 = n - t1;
		res = max(res, solve(i, n, n + 1, n + t2));
	}
	printf("%lld\n", res);
	return 0;
}

