using ll = long long;

ll m;

vector<ll> rev(vector<ll> a) {
    reverse(begin(a), end(a));
    for (auto &x: a) {
        x = m - x;
    }
    return a;
}

ll solve(const vector<ll> &a) {
    int n = SZ(a);
    ll d = a[n - 1];
    ll ret = d;
    // printf("%lld\n", d);
    for (int l = 1; l < n - l; l++) {
        d += a[n - l - 1] - a[n - l];
        d += 2 * (a[n - l * 2] - a[n - l - 1]);
        d += 2 * (a[n - l * 2 - 1] + m - a[n - l]);
        // printf("%lld\n", d);
        ret = max(ret, d);
    }
    // printf("\n");
    d = 2 * a[n - 2] + m - a[n - 1];
    ret = max(ret, d);
    // printf("%lld\n", d);
    for (int l = 2; l <= n - l; l++) {
        d += a[n - l + 1] - a[n - l];
        d += 2 * (a[n - l * 2] + m - a[n - l + 1]);
        d += 2 * (a[n - l * 2 + 1] - a[n - l]);
        ret = max(ret, d);
        // printf("%lld\n", d);
    }
    // printf("\n");
    return ret;
}

