			{
				if (!state[now + j - n])
				{
					//	使われていない
					temp1 = now + j - n;
					break;
				}
			}
			else
			{
				if (!state[j + now])
				{
					//	使われていない
					temp1 = j + now;
					break;
				}
			}
		}

