struct State {
  int L, R, pos;
  int64_t cost;
};

std::multiset<int> listset;
std::vector<int> list;
std::vector<State> states;
int L, N;

int rdistance(int from, int to) {
  return (from < to ? (from + L - to) : (from - to));
}

int ldistance(int from, int to) {
  return (from < to ? (to - from) : (to + L - from));
}

int main(){
  scanf("%d %d", &L, &N);
  for(int i = 0; i < N; i++) {
    int tmp;
    scanf(" %d", &tmp);
    listset.insert(tmp);
  }
  std::copy(listset.begin(), listset.end(), std::back_inserter(list));
  states.push_back({0, N - 1, 0, 0});
  int64_t max_cost = 0;
  for(int i = 0; i < states.size(); i++){
    State v = states[i];
    if(max_cost < v.cost) max_cost = v.cost;
    if(v.L > v.R) continue;
    states.push_back({v.L, v.R - 1, list[v.R], rdistance(v.pos, list[v.R]) + v.cost});
    states.push_back({v.L + 1, v.R, list[v.L], ldistance(v.pos, list[v.L]) + v.cost});
  }/*
  for(auto &v : states){
    printf("%d %d %d %lld\n", v.L, v.R, v.pos, v.cost);
  }
