//!============================================!//
//!    8888ba.88ba             oo              !//
//!    88  '8b  '8b                            !//
//!    88   88   88  .d8888b.  dP  88d888b.    !//
//!    88   88   88  88'  '88  88  88'  '88    !//
//!    88   88   88  88.  .88  88  88    88    !//
//!    dP   dP   dP  '88888P8  dP  dP    dP    !//
//!============================================!//
int main()
{
    const ll L = read<ll>();
    const int N = read<int>();
    auto X = readVec<ll>(N);
    auto d = [&](const int s, const int t, const bool cl) {
        const ll l = (t > s ? X[t] - X[s] : X[t] - X[s] + L);
        return cl ? l : L - l;
    };
    auto solve = [&]() -> ll {
        int s = 0;
        ll ans = X[s];
        int p = s;
        for (;;) {
            const bool small = 2 * p < N;
            const int nxt = (small ? N - 1 - p : N - p);
            if (p == nxt) { break; }
            if (small ^ (p < nxt)) { break; }
            ans += d(p, nxt, nxt < p), p = nxt;
        }
        int t = p;
        ll sum = ans;
        SHOW(t, ans);
        bool small = 2 * t < N;
        for (int i = 0; i < N; i++) {
            sum += d(s, t, true) - d(small ? (t + 1) % N : t, s, true);
            chmax(ans, sum);
            s = (s + 1) % N, t = (t + 1) % N;
            SHOW(s, t, sum);
        }
        return ans;
    };
    ll ans = 0;
    chmax(ans, solve());
    for (auto& e : X) { e = L - e; }
    std::reverse(X.begin(), X.end());
    chmax(ans, solve());
    std::cout << ans << std::endl;
    return 0;
}

