int L, N, x[MAXN];
int calc1() {
	int l = 1, r = N + 1, opt = 0, ans = x[1];
	while(l <= r) {
		if(opt == 0) {
			if((x[l + 1] - x[l]) < (x[l] + (L - x[r - 1]))) ans += x[l] + (L - x[r - 1]), r--, opt ^= 1;
			else ans += x[l + 1] - x[l], l++; 			
		} else {
			if((x[r] - x[r - 1]) < (x[l + 1] + (L - x[r]))) ans += (x[l + 1] + (L - x[r])), l++, opt ^= 1;
			else ans += (x[r] - x[r - 1]), r--; 			
		}

		if(l + 1 == r) break;
	}
	return ans;
}
int calc2() {
	int l = 0, r = N, opt = 1, ans = L - x[N];
	while(l <= r) {
		if(opt == 0) {
			if((x[l + 1] - x[l]) < (x[l] + (L - x[r - 1]))) ans += x[l] + (L - x[r - 1]), r--, opt ^= 1;
			else ans += x[l + 1] - x[l], l++; 			
		} else {
			if((x[r] - x[r - 1]) < (x[l + 1] + (L - x[r]))) ans += (x[l + 1] + (L - x[r])), l++, opt ^= 1;
			else ans += (x[r] - x[r - 1]), r--; 			
		}
		if(l + 1 == r) break;
	}
	return ans;	
}

