ll  L, N;
ll  X[200005];
ll XL[200005], XR[200005];

void solve() {
    cin >> L >> N;
    for (int i = 1; i <= N; ++i) {
        cin >> X[i];
    }
    for (int i = 1; i <= N; ++i) {
        XL[i] = XL[i - 1] + X[i];
    }
    for (int i = N; i >= 1; --i) {
        XR[i] = XR[i + 1] + L - X[i];
    }

    ll result = 0;
    for (int x = 0; x <= N; ++x) {
        ll sum = 0;
        int l = x, r = N - x;
        int d = min(l, r);
        sum += 2 * (XL[l] - XL[l - d]);
        sum += 2 * (XR[l + 1] - XR[l + 1 + d]);
        if (l == r) {
            sum -=  min(X[l], L - X[l + 1]);
            result =  max(result, sum);
            break;
        }
        if (l > r) {
            result =  max(result, sum + 2 * X[l - d] - X[l]);
            result =  max(result, sum - (L - X[l + 1]));
        } else if (r > l) {
            result =  max(result, sum + 2 * (L - X[l + 1 + d]) - (L - X[l + 1]));
            result =  max(result, sum - X[l]);
        }

    }
    cout << result << endl;
}

int main() {
    ios_base::sync_with_stdio(false);
    cout << setprecision(12) << fixed;

    solve();

    return 0;
}

