class Task{
	public:

	long long l, n;
	vector<int> x;
	vector<bool> burnt;

	void run(int test_case){
		cin >> l >> n;
		x.resize(n);
		burnt.resize(n);
		for (int i = 0; i < n; i++) cin >> x[i];
		long long not_burnt = n, pos = 0, ans = 0;
		while (not_burnt > 0) {
			long long rmn = INT_MAX, lmn = INT_MAX, ri = 0, li = 0;
			for (int i = 0; i < n; i++) if (!burnt[i]) {
				if (x[i] > pos) {
					long long rmnt = x[i] - pos;
					long long lmnt = l - rmnt;
					if (rmnt < rmn) {
						rmn = rmnt;
						ri = i;
					}
					if (lmnt < lmn) {
						lmn = lmnt;
						li = i;
					}
				} else {
					long long lmnt = pos - x[i];
					long long rmnt = l - lmnt;
					if (rmnt < rmn) {
						rmn = rmnt;
						ri = i;
					}
					if (lmnt < lmn) {
						lmn = lmnt;
						li = i;
					}
				}
			}
			if (rmn > lmn) {
				ans += rmn;
				pos = x[ri];
				burnt[ri] = true;
			}
			else {
				ans += lmn;
				pos = x[li];
				burnt[li] = true;
			}
			not_burnt--;
		}
		cout << ans << "\n";
	}
};

int main(){
	ios_base::sync_with_stdio(0);
	cin.tie(0);

	int T = 1;
	//cin >> T;
	for (int i = 1; i <= T; i++) {
		Task *solver = new Task();
		solver->run(i);
		delete solver;
	}
}

