int sub(vi w){
	int n=int(w.size())-1;
	vi a(n),b(n),c(n),d(n);
	for(int i=n-1;i>=0;i--){
		a[i]=b[i]=w[i+1];
		if(i+1<n){
			a[i]+=a[i+1];
			b[i]+=b[i+1];
			b[i]+=a[i+1]*2;
		}
	}
	REP(i,n){
		if(i>0){
			c[i]=c[i-1]+w[i-1];
			d[i]=d[i-1]+c[i]*2;
		}
	}
	int res=0;
	REP(i,n){
		int p=(n-i)*2-1,q=i*2;
		int v=b[i]+d[i];
		if(p>q+1){
			int j=n-(p-(q+1))/2;
			v-=a[j]+b[j];
		}else if(p+1<q){
			int j=(q-(p+1))/2;
			v-=d[j];
		}
		chmax(res,v);
	}
	return res;
}

