ll getLeftTreeIndex(ll treeNo){
    ll count = 0;
    FOR(i, 0, N){
        if(B[i] != 0 && B[i]<=x){
            count++;
            if(count==treeNo){
                return i;
            }
        }
    }
}

ll getRightTreeIndex(ll treeNo){
    ll count = 0;
    FOR(i, 0, N){
        if(A[i] != 0 && A[i]>=x){
            count++;
            if(count==treeNo){
                return i;
            }
        }
    }
}

void cutTreeByA(ll index){
    A[index] = 0;
    B[N-1-index] = 0;
}
void cutTreeByB(ll index){
    B[index] = 0;
    A[N-1-index] = 0;
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    // input
    cin >> L >> N;

    // pn(L);
