    FOR(i, 0, N){
        // p("");
        // p2(i, "回目");
        // p2("x", x);
        ll leftTreeIndex = getLeftTreeIndex(1);
        ll rightTreeIndex = getRightTreeIndex(1);
        // p2(leftTreeIndex, rightTreeIndex);
        ll dist0 = x - B[leftTreeIndex]; // 左型
        ll dist1 = A[rightTreeIndex] - x; // 右側

        // 遠い方を切りに行く
        if(dist0>dist1){
            // p2("シンプルに左に行く", dist0);
            x = B[leftTreeIndex];
            cutTreeByB(leftTreeIndex);
            // p2("+", dist0);
            move_sum += dist0;
        }
        else if(dist0<dist1){
            // p2("シンプルに右に行く", dist1);
            x = A[rightTreeIndex];
            cutTreeByA(rightTreeIndex);
            // p2("+", dist1);
            move_sum += dist1;
        }
        // 同じ距離（スキャンが必要）
        else{
            // p("scan");
            FOR(j, 2, N-i){
                ll _leftIndex = getLeftTreeIndex(j);
                ll _rightIndex = getRightTreeIndex(j);
                ll _diff0 = x - B[_leftIndex]; // 左型
                ll _diff1 = A[_rightIndex] - x; // 右側

                if(_diff0==_diff1){
                    // cout << j << "では見つからず" << B[_leftIndex] << "," << A[_rightIndex] << endl;
                    continue;
                }
                else if(_diff0 > _diff1){
                    // 左にする
