                }
                // _diff0 < _diff1
                else{
                    // 右にする
                    //cout << "サーチの結果、右に行く" << endl;
                    x = A[rightTreeIndex];
                    cutTreeByA(rightTreeIndex);
                    move_sum += dist1;
                    break;
                }
            }
        }
    }

    // p("answer");
    p(move_sum);

    return 0;
}

