			cout << max(d1(0, x[0]), d2(0, x[0])) << endl;
			return;
		}
		for (int i = 0; i < maxn; ++i) for (int j = 0; j < maxn; ++j) dp[i][j][0] = dp[i][j][1] = -oo;
