ll solve1(ll L, int N, vll& x, vll& _x) {
    vll ax(N+1), a_x(N+1);
    ax[0] = a_x[0] = 0;
    rep(i,N) {
        ax[i+1] = ax[i] + x[i];
        a_x[i+1] = a_x[i] + _x[i];
    }

    ll best = 0;
    for (int n=1; n<=N; ++n) {
        int pos = n+(N-n)/2, neg = N-pos;
        ll curr = 2*(ax[pos]-ax[n-1]) + 2*(a_x[neg]-a_x[0]);
        if ((N-n) % 2){
            curr -= _x[neg-1];
        } else {
            curr -= x[pos-1];
        }
        best = max(best, curr);
    }
    return best;
}

