unsigned int search(
  unsigned int l,
  unsigned int n,
  unsigned int* x,
  unsigned int z,
  unsigned int leng
  )
{
  unsigned int i, leng0, leng1, add;
  int j;
  for(j=0; j<=1; j++){
    for(i=0; i<n-1; i++){
      if(z < x[0] || x[n-1] < z){
        i = n-1;
        break;
      }
      if(x[i]<z && z<x[i+1]){
        break;
      }
    }
    if(j==0){ // 反時計回り
      add = z - x[i];
      z = x[i];
      for(; i<n-1; i++){
        x[i] = x[i+1];
      }
      n--;
      leng0 = leng + add;
      if(n!=0){
        leng0 = search(l, n, &x[0], z, leng0);
      }
    }
    else{// 時計回り
      if(i!=n-1){
        leng += x[i+1] - z;
        z = x[i+1];
        for(; i<n-2; i++){
          x[i+1] = x[i+2];
        }
      }else{
        leng += - z + x[0];
        if(z>x[n-1]){
          leng += l;
        }
        z = x[0];
        for(i=0; i<n-1; i++){
          x[i] = x[i+1];
        }
      }
      n--;
      if(n==0){
          leng1 = leng;
      }else{
        leng1 = search(l, n, &x[0], z, leng);
      }
    }
  }
  return max(leng0, leng1);
}

