	vector<int> X(N + 2);
	for (int i = 1; i <= N; ++i) cin >> X[i];
	X[N + 1] = L;
	function<long long(int, int, int, bool)> calc = [&](int d, int l, int r, bool isleft) {
		if (vis[d][l][isleft ? 0 : 1]) return dp[d][l][isleft ? 0 : 1];
		if (d == N) return (long long)(0);
		long long lc = calc(d + 1, l + 1, r, true);
		if (d == 0 || isleft) lc += X[l + 1] - X[l];
		else lc += L - (X[r] - X[l + 1]);
		long long rc = calc(d + 1, l, r - 1, false);
		if (d == 0 || !isleft) rc += X[r] - X[r - 1];
		else rc += L - (X[r - 1] - X[l]);
		vis[d][l][isleft ? 0 : 1] = true;
		dp[d][l][isleft ? 0 : 1] = max(lc, rc);
		return max(lc, rc);
	};
	long long ret = calc(0, 0, N + 1, true);
	cout << ret << endl;
	return 0;
}

