inline void solve(){
	LL ssuf=0,spre=0,sf=N,sp=0;
	for(LL i=1;i<=N;i++){
		ans=max(ans,ssuf+spre+suf[N-i+1]);
		LL PC1=min(sp,sf); PC1=max(PC1,0LL);
		LL PC2=min(sp,sf); PC2=max(PC2,0LL);
		++sp; pre[sp]=pre[sp-1]+a[i]-a[i-1]; --sf; 

		LL lim=sp,C=min(lim,sf); 
		if(i>1) ssuf-=2*(suf[N-i]-suf[N-i-PC1]);
		if(C>PC1)ssuf+=suf[N-i-C]*2;  

		spre+=pre[sp]*2; C=min(sp,sf);
		if(PC2>C) spre-=(pre[sp-C]+pre[sp-C-1])*2;
		if(PC2==C) spre-=pre[sp-C]*2;
	} 
}
