ll X[222222];

ll Dist(ll x, ll y, ll L) {
    if (y < x)
        return y+L-x;
    else
        return y-x;
}


ll Solve(int a, int b, ll L, bool where) {

    if (a > b) {
        return 0;
    }
    // either at X[a-1] or X[b+1]

    ll ans = 0;

    if (!where) {
        ans = max(ans, Dist(X[a-1],X[a],L)+Solve(a+1,b,L,false));
        ans = max(ans, Dist(X[b],X[a-1],L)+Solve(a,b-1,L,true));
    } else {
        ans = max(ans, Dist(X[b+1],X[a],L)+Solve(a+1,b,L,false));
        ans = max(ans, Dist(X[b],X[b+1],L)+Solve(a,b-1,L,true));
    }

    return ans;



}


ll dp[2222][2222][2];

ll Solve(int N,ll L) {

    for(int d=0;d<=N;d++) {
        for(int a=1;a+d-1<=N;a++) {
            for(int where=0;where<=1;where++) {
                int b = a+d-1;
                if (a > b) {
                    dp[a][b][where]=0;
                    continue;
                }

                ll ans = 0;

                if (!where) {
                    ans = max(ans, Dist(X[a-1],X[a],L)+dp[a+1][b][0]);
                    ans = max(ans, Dist(X[b],X[a-1],L)+dp[a][b-1][1]);
                } else {
                    ans = max(ans, Dist(X[b+1],X[a],L)+dp[a+1][b][0]);
                    ans = max(ans, Dist(X[b],X[b+1],L)+dp[a][b-1][1]);
                }

                dp[a][b][where]=ans;

            }
        }
    }

    return dp[1][N][0];
}


