/* v-v-v-v-v-v-v-v-v Main Part v-v-v-v-v-v-v-v-v */

ll L;
int N;
ll X[200010];

ll solve(int i) {
    if (i == 0) return L - X[1];
    if (i == N) return X[N];

    ll ret = 0;

    vector<ll> l, r;
    for (int j = 1; j <= i; ++j) {
        l.push_back(X[j]);
    }

    for (int j = N; j > i; --j) {
        r.push_back(L - X[j]);
    }

    ll sl = l.back(), sr = r.back();

    ll cost = 0;
    while (!l.empty() && !r.empty()) {
        cost += l.back();
        l.pop_back();
        cost += r.back();
        r.pop_back();
    }

    // 左から行った場合
    if (l.empty()) l.push_back(0);
    ret = max(ret, (cost + l.back()) * 2 - sl);

    // 右から行った場合
    if (r.empty()) r.push_back(0);
    ret = max(ret, (cost + r.back()) * 2 - sr);

    return ret;
}

int main() {
    cin >> L >> N;

    X[0] = 0;
    for (int i = 1; i <= N; ++i) {
        cin >> X[i];
    }
    X[N + 1] = L;

    set<int> s;
    if (N % 2 == 0) {
        for (int i = -1; i <= 1; ++i) {
            s.insert(N / 2 - i);
        }
    } else {
        for (int i = -1; i <= 2; ++i) {
            s.insert(N / 2 - i);
        }
    }

    ll ans = 0;
    for (int i : s) {
        if (i < 0 || i > N) continue;
        ans = max(ans, solve(i));
    }

    cout << ans << endl;
    return 0;
}

