using namespace std;
const int N = 2e5 + 100;

int Limit,n;
int a[N];
void nhap()
{
    cin >> Limit >> n;
    for (int i = 1; i <= n; i++) cin >> a[i];
}

int KC(int L,int R,int Type) { ///0: Trai; 1: Phai
    //cout << L << " " << R << " " << Type << '\n';
    if (Type == 0) {
        if (L > R) return a[L] - a[R];
        return a[L] + Limit - a[R];
    }
    if (L < R) return a[R] - a[L];
    return Limit - a[L] + a[R];
}
long long Get(int Start,int Type,int L,int R) {
    //cout << Start << " " << Type << " " << L << " " << R << '\n';
    if (L > R) return 0;
    int S1 = KC(Start,L,1 - Type);
    int S2 = KC(Start,R,Type);
    //cout << S1 << " " << S2 << '\n';
    if (S1 > S2) return Get(L,0,L + 1,R) + S1;
    return Get(R,0,L,R - 1) + S2;
}
void solve()
{
    long long S1 = a[1] + Get(1,0,2,n);
    //cout << S1 << " " << '\n';
    long long S2 = Limit - a[n] + Get(n,0,1,n - 1);
    //cout << S2 << '\n';
    cout << max(S1,S2);
}
int main()
{
    nhap();
    solve();
}

