typedef long long LL;
const int N = 2e5 + 50;

int n, a[N];
LL fix[N], L;

inline LL calc(int l) {
  if (l == n) return 0;
  if (l == n - 1) return L - (a[n] - a[n - 1]);
  if ((n - l + 1) % 2 == 0) {
    int p = (n - l + 1) / 2;
    LL res = fix[n] - fix[n - p + 1];
    res = L * (p - 1) - res;
    res += fix[l + p - 1] - fix[l];
    res *= 2;
    return res + (L - a[n - p + 1]) + a[l];
  } else {
    int p = (n - l + 1) / 2;
    LL res = fix[n] - fix[n - p];
    res = L * p - res;
    res += fix[l + p - 1] - fix[l];
    res *= 2;
    return res + a[l] + a[l + p];
  }
}

int main() {
  scanf("%lld%d", &L, &n);
  for (int i = 1; i <= n; i ++) {
    scanf("%d", &a[i]);
    fix[i] = fix[i - 1] + a[i];
  }
  fix[n + 1] = fix[n];
  LL ans = 0;
  for (int i = 1; i <= n; i ++)
    ans = max(ans, a[i] + calc(i));
  reverse(a + 1, a + n + 1);
  for (int i = 1; i <= n; i ++) {
    a[i] = L - a[i];
    fix[i] = fix[i - 1] + a[i];
  }
  for (int i = 1; i <= n; i ++)
    ans = max(ans, a[i] + calc(i));
  printf("%lld\n", ans);
  return 0;
}

