ll dist(ll left, ll right, ll now){
  if(right == left ){
    return 0;
  }else if(tr[left] - now > now + l - tr[right-1]){
    return tr[left] - now + dist(left+1, right, tr[left]);
  }else if(tr[left] - now < now + l - tr[right-1]){
    return now + l - tr[right-1] + dist(left, right-1, tr[right]);
  }else if(tr[left] - now == now + l - tr[right-1]){
    return max(tr[left] - now + dist(left+1, right, tr[left]), now + l - tr[right-1] + dist(left, right-1, tr[right-1]));
  }
}


