    X[0] = Y[0] = 0;
    for (int i = 1; i <= N; i++) {
        cin >> X[i];
    }
    sort(X, X + N);
    for (int i = N; i > 0; i--) {
        Y[N - i + 1] = L - X[i];
    }

    dp[0][0][0] = dp[0][0][1] = 0;

    for (int i = 0; i <= N; i++) {
        for (int j = 0; j <= N; j++) {
            for (int k = 0; k < 2; k++) {
                if (k == 0) {
                    dp[i + 1][j][k] = max(dp[i + 1][j][k], dp[i][j][k] + X[i + 1] - X[i]);
                    dp[i][j + 1][k + 1] = max(dp[i][j + 1][k + 1], dp[i][j][k] + X[i] + Y[j + 1]);
                }
                else {
                    dp[i + 1][j][k - 1] = max(dp[i + 1][j][k - 1], dp[i][j][k] + Y[j] + X[i + 1]);
                    dp[i][j + 1][k] = max(dp[i][j + 1][k], dp[i][j][k] + Y[j + 1] - Y[j]);
                }
            }
        }
    }

    ll ans = 0;
    for (int i = 0; i <= N; i++) {
        for (int j = 0; j < 2; j++) {
            ans = max(ans, dp[i][N - i][j]);
        }
    }
    cout << ans << endl;
    return 0;
}

