#define RIGHT true
#define LEFT false

ll solve(int L, int apos, int bpos, const vector<int>& T, bool at) {
    ll res = 0;
    while (apos != bpos) {
        if (at == RIGHT) {
            res += L - T[apos] + T[bpos];
            apos--;
        } else {
            res += L - T[apos] + T[bpos];
            bpos++;
        }
        at = !at;
    }
    return res;
}

ll go(int L, const vector<int> T) {
    int apos = sz(T) - 1;
    int bpos = 0;

    ll ans = T[0];

    return ans + max(
            T[bpos + 1] - T[bpos] + solve(L, apos, bpos + 1, T, LEFT),
            L - T[apos] + T[bpos] + solve(L, apos, bpos + 1, T, RIGHT));
}

