ll calc(ll* d)
{
    int k = 0, l = n-1;
    int nw = L;
    ll init = 0;
    int left = 1;
    while(k <= l){
        if(left){
            init += d[k++] + (L-nw);
            nw = d[k-1];
        }else{
            init += nw + (L-d[l--]);
            nw = d[l+1];
        }
        left ^= 1;
    }
    val[0] = init;
    srep(i,1,n){
        // int k = (n-1+i)/2, l = k+1;
        val[i] = val[i-1] - d[i-1] + (d[(n+i-1)/2] - d[i-1]) - (L-d[(n+i)/2]);
    }
    // sar(val, n);
    return *max_element(val, val+n);
}

