	for(i=1;i<=n;i++) scanf("%i",&a[i]);
	for(i=1;i<=n;i++) lsm[i]=lsm[i-1]+a[i]*2,rsm[i]=rsm[i-1]+(L-a[i])*2;
	ll ans=max(a[n],L-a[1]);
	for(int cen=1;cen<=n;cen++)
	{
		int l=cen-1;
		int r=n-cen;
		if(l<=r)
		{
			//Same
			ll lf=lsm[cen-1];
			ll rf=rsm[cen+l]-rsm[cen];
			ans=max(ans,lf+rf+max(a[cen],L-a[cen]));
			//MoreL
			if(l>0)
			{
				rf=rsm[cen+l-1]-rsm[cen];
				ans=max(ans,lf+rf+L-a[cen]);
			}
			//MoreR
			if(l<r)
			{
				rf=rsm[cen+l+1]-rsm[cen];
				ans=max(ans,lf+rf+a[cen]);
			}
		}
		else
		{
			//Same
			ll lf=lsm[cen-1]-lsm[cen-r-1];
			ll rf=rsm[n]-rsm[cen];
			ans=max(ans,lf+rf+max(a[cen],L-a[cen]));
			//MoreL
			if(l>r)
			{
				lf=lsm[cen-1]-lsm[cen-r-2];
				ans=max(ans,lf+rf+L-a[cen]);
			}
			//MoreR
			if(r>0)
			{
				lf=lsm[cen-1]-lsm[cen-r];
				ans=max(ans,lf+rf+a[cen]);
			}
		}
	}
	printf("%lld\n",ans);
	return 0;
}

