int n;
ll L, ans;
ll inp[N];

ll f(int pos, int nxt, int l, int r){
  ll ret = 0;
  if(pos < nxt){
    if(pos + 1 == nxt) ret = max(ret, inp[nxt] - inp[pos]);
    if(r == nxt) ret = max(ret, inp[pos] + L - inp[nxt]);
  } else {
    if(pos - 1 == nxt) ret = inp[pos] - inp[nxt];
    if(l == nxt) ret = max(ret, L - inp[pos] + inp[nxt]);
  }
  return ret;
}

void go(int pos, int l, int r, ll hand){
  //cout << pos << " " << l << " " << r << " " << hand << '\n';
  if(l > r){
    //cout << "found : " << hand << '\n';
    ans = max(ans, hand);
    return ;
  }
  ll p = f(pos, l, l, r);
  ll q = f(pos, r, l, r);
  if(p > q) go(l, l + 1, r, hand + p);
  else if(q > p) go(r, l, r - 1, hand + q);
  else {
    go(l, l + 1, r, hand + p);
    go(r, l, r - 1, hand + q);
  }
}

