ll solve1(ll perimeter, int n, vector<ll> const & x) {
    ll dist = 0;
    {
        const int start = 0;
        int l = start + 1;
        int r = n;
        dist += x[start];
        while (l != r) {
            dist += x[l - 1] + perimeter - x[r - 1];
            -- r;
            if (l == r) break;
            dist += x[l] + perimeter - x[r];
            ++ l;
        }
    }

    ll answer = dist;
    vector<ll> acc(n + 1);
    partial_sum(ALL(x), acc.begin() + 1);

    REP (start, n - 1) {
        int last = start + (n - start) / 2;
        dist -= x[start];
        dist += x[last] - x[start];
        if ((n - start) % 2 == 0) {
            dist -= perimeter - x[last];
        } else {
            if (last != n - 1) {
                dist -= perimeter - x[last + 1];
            }
        }
        chmax(answer, dist);
    }
    return answer;

