nagai stup(int l, int n, vector<int> c)
{
	if (n > 2000)
		return -1;
	nagai oo = 1e18;
	for (int i = 0; i < n; ++i)
		for (int j = 0; j < n; ++j)
			dp[i][j][0] = dp[i][j][1] = -oo;
	dp[0][0][0] = dp[0][0][1] = 0;
	nagai ans = 0;
	auto dist = [&](int a, int b)
	{
		nagai ans = c[b] - c[a];
		if (ans < 0)
			ans += l;
		return ans;
	};
	for (int len = 0; len < n; ++len)
	{
		for (int i = 0; i < n; ++i)
		{
			int j = (i + len) % n;
			int i1 = i == 0 ? n - 1 : i - 1;
			int j1 = j + 1 == n ? 0 : j + 1;
			ans = max(ans, dp[i][j][0]);
			ans = max(ans, dp[i][j][1]);
//			cerr << i << ' ' << j << ' ' << dp[i][j][0] << ' ' << dp[i][j][1] << '\n';
			if (len + 1 == n)
				continue;
			dp[i1][j][0] = max(dp[i1][j][0], dp[i][j][0] + dist(i1, i));
			dp[i][j1][1] = max(dp[i][j1][1], dp[i][j][0] + dist(i, j1));
			dp[i1][j][0] = max(dp[i1][j][0], dp[i][j][1] + dist(i1, j));
			dp[i][j1][1] = max(dp[i][j1][1], dp[i][j][1] + dist(j, j1));
		}
	}
	return ans;
}

nagai smart(int l, int n, vector<int> c)
{
	auto go = [&](int a, int b)
	{
		nagai ans = c[b] - c[a];
		if (ans < 0)
			ans += l;
		return ans;
	};
	nagai ans = 0;
	vector<nagai> pos(n), neg(n);
	for (int i = 0; i < n; ++i)
		pos[i] = go(0, i), neg[i] = go(i, 0);
	vector<nagai> prpos(n), suneg(n);
	for (int i = 1; i < n; ++i)
		prpos[i] = prpos[i - 1] + pos[i];
	suneg[n - 1] = neg[n - 1];
	for (int i = n - 2; i > 0; --i)
		suneg[i] = suneg[i + 1] + neg[i];
	assert(pos[0] == 0 && neg[0] == 0);
	for (int i = 1; i < n; ++i)
	{
		nagai ansich = 0;
		int rest = n - (i + 1);
		int last0 = (n - (rest + 1) / 2) % n;
		int lasti = i + rest / 2;
		ansich += (prpos[lasti] - prpos[i - 1]) * 2;
		ansich += suneg[last0] * 2;
		if (rest % 2 == 0)
			ansich -= pos[lasti];
		else
			ansich -= neg[last0];
		//cerr << i << ' ' << rest << ' ' << last0 << ' ' << lasti << ' ' << ansich << '\n';
		ans = max(ans, ansich);
		ansich = 0;
		rest = i - 1;
		last0 = (rest + 1) / 2;
		lasti = (i - rest / 2);
		ansich += prpos[last0] * 2;
		ansich += (suneg[lasti] - suneg[(i + 1) % n]) * 2;
		if (rest % 2 == 0)
			ansich -= neg[lasti];
		else
			ansich -= pos[last0];
//		cerr << i << ' ' << rest << ' ' << last0 << ' ' << lasti << ' ' << ansich << '\n';
		ans = max(ans, ansich);
	}
	return ans;
}

nagai solve(int l, int n, vector<int> c)
{
	c.insert(c.begin(), 0);
	++n;
	return smart(l, n, c);
	nagai a = stup(l, n, c);
	nagai b = smart(l, n, c);
	if (a != -1 && a != b)
	{
		//cerr << a << ' ' << b << '\n';
		exit(239);
	}
	return b;
}

