        for(int i = l+1; i <= N; i++) tmp += 2*(L-x[i]);
        tmp -= min(x[l], L-x[l+1]);
    }else if(l < N-l){
        for(int i = 1; i <= l; i++) tmp += 2*x[i];
        for(int i = l+1; i <= 2*l; i++) tmp += 2*(L-x[i]);
        tmp -= min(x[l], L-x[l+1]);
        long tmp2 = 0;
        for(int i = 1; i <= l; i++) tmp2 += 2*x[i];
        for(int i = l+1; i <= 2*l+1; i++) tmp2 += 2*(L-x[i]);
        tmp2 -= (L-x[l+1]);
        tmp = max(tmp, tmp2);
    }else{
        for(int i = 2*l-N+1; i <= l; i++) tmp += 2*x[i];
        for(int i = l+1; i <= N; i++) tmp += 2*(L-x[i]);
        tmp -= min(x[l], L-x[l+1]);
        long tmp2 = 0;
        for(int i = 2*l-N; i <= l; i++) tmp2 += 2*x[i];
        for(int i = l+1; i <= N; i++) tmp2 += 2*(L-x[i]);
        tmp2 -= x[l];
        tmp = max(tmp, tmp2);
    }
}

