long long solve(deque<long long> dq, long long coordinate, bool cycleLeft){
    int nCurrent = dq.size();
    if(nCurrent == 0) return 0;

    long long coordinateNext;
    deque<long long> cdq;
    long long dx;
    if(cycleLeft){
        if(dq.at(0) - coordinate > l - (dq.at(nCurrent - 1) - coordinate)){
            dx = dq.at(0) - coordinate;
            coordinateNext = dq.at(0);
            dq.pop_front();
            return dx + solve(dq, coordinateNext, true);
        }
        if(dq.at(0) - coordinate < l - (dq.at(nCurrent - 1) - coordinate)){
            dx = l - (dq.at(nCurrent - 1) - coordinate);
            coordinateNext = dq.at(nCurrent - 1);
            dq.pop_back();
            return dx + solve(dq, coordinateNext, false);
        }
        else{
            long long sumA;
            cdq = dq;
            dx = cdq.at(0) - coordinate;
            coordinateNext = cdq.at(0);
            cdq.pop_front();
            sumA = dx + solve(cdq, coordinateNext, true);

            long long sumB;
            cdq = dq;
            dx = l - (cdq.at(nCurrent - 1) - coordinate);
            coordinateNext = cdq.at(nCurrent - 1);
            cdq.pop_back();
            sumB = dx + solve(cdq, coordinateNext, false);

            return max(sumA, sumB);
        }
    }
    else{
        if(dq.at(0) + (l - coordinate) > coordinate - dq.at(nCurrent - 1)){
            dx = dq.at(0) + (l - coordinate);
            coordinateNext = dq.at(0);
            dq.pop_front();
            return dx + solve(dq, coordinateNext, true);
        }
        if(dq.at(0) + (l - coordinate) < coordinate - dq.at(nCurrent - 1)){
            dx = coordinate - dq.at(nCurrent - 1);
            coordinateNext = dq.at(nCurrent - 1);
            dq.pop_back();
            return dx + solve(dq, coordinateNext, false);
        }
        else{
            long long sumA;
            cdq = dq;
            dx = cdq.at(0) + (l - coordinate);
            coordinateNext = cdq.at(0);
            cdq.pop_front();
            sumA = dx + solve(cdq, coordinateNext, true);

            long long sumB;
            cdq = dq;
            dx = coordinate - cdq.at(nCurrent - 1);
            coordinateNext = cdq.at(nCurrent - 1);
            cdq.pop_back();
            sumB = dx + solve(cdq, coordinateNext, false);

            return max(sumA, sumB);
        }
    }
}

