using namespace output;

ll L, N; 
vll arr;

ll alternate(int cl, int cr, ll cp, bool side) {
	if (cl < cr) return 0;
	if (side) {
		// on right side
		return cp + L - arr[cl] + alternate(cl - 1, cr, arr[cl], false);
	} else {
		// on left side
		return L - cp + arr[cr] + alternate(cl, cr + 1, arr[cr], true);
	}
}

ll calcR(int r) {
	ll ans = 0;
	if (r != 0) {
		ans += arr[r-1];
		ans += alternate(N - 1, r, arr[r-1], true);
	} else {
		ans += L - arr[N-1] + alternate(N-2, 0, arr[N-1], false);
	}
	return ans;
}

ll calcL(int l) {
	ll ans = 0;
	if (l != 0) {
		ans += L - arr[N-l];
		ans += alternate(N-l-1, 0, arr[N-l], false);
	} else {
		ans += arr[0] + alternate(N-1, 1, arr[0], true);
	}
	return ans;
}

int main() {
    ios::sync_with_stdio(0), cin.tie(0), cout.tie(0);
	cin >> L >> N;
	arr.resize(N);
	F0R(i, N) cin >> arr[i];

	int lo, hi;

	lo = 0;
	hi = N-1;
	while (lo < hi) {
		int mid = lo + (hi - lo) / 2;
		if (calcR(mid) > calcR(mid+1)) {
			hi = mid;
		} else {
			lo = mid + 1;
		}
	}

	ll rBest = max(calcR(N), calcR(lo));

	lo = 0;
	hi = N-1;
	while (lo < hi) {
		int mid = lo + (hi - lo) / 2;
		if (calcL(mid) > calcL(mid+1)) {
			hi = mid;
		} else {
			lo = mid + 1;
		}
	}

	ll lBest = max(calcL(N), calcL(lo));
	print(max(rBest, lBest));
}

