int main() {
    ll L;
    int N;
    cin >> L >> N;

    if (N > 2000) terminate();

    ll X[N + 2];
    X[0] = 0;
    for (int i = 1; i <= N; ++i) {
        cin >> X[i];
    }
    X[N + 1] = L;

    ll ans = max(X[N], L - X[1]);
    for (int i = 1; i < N; ++i) {
        // X[i]とX[i + 1]の間を切る
        vector<ll> l, r;
        for (int j = 1; j <= i; ++j) {
            l.push_back(X[j]);
        }

        for (int j = N; j > i; --j) {
            r.push_back(L - X[j]);
        }

        ll sl = l.back(), sr = r.back();

        ll cost = 0;
        while (!l.empty() && !r.empty()) {
            cost += l.back();
            l.pop_back();
            cost += r.back();
            r.pop_back();
        }

        // 左から行った場合
        if (l.empty()) l.push_back(0);
        ans = max(ans, (cost + l.back()) * 2 - sl);

        // 右から行った場合
        if (r.empty()) r.push_back(0);
        ans = max(ans, (cost + r.back()) * 2 - sr);
    }

    cout << ans << endl;
    return 0;
}

