const int N = (int)2e5 + 228;

using namespace std;

int L, n, x[N];
ll ans, pref[N], suf[N];

void solve()
{
	for (int i = 0; i < n; i++)
	{
	 	pref[i] = x[i];
	 	if (i > 0)
	 		pref[i] += pref[i - 1];
	}                            
	for (int i = n - 1; i >= 0; i--)
		suf[i] = L - x[i] + suf[i + 1];
	for (int i = 0; i < n - 1; i++)
	{
		ll cur = x[i];
		if (!((n - i - 1) & 1))
		{
			int k = (n - i - 1) / 2;
			int a = n - k, b = i + k;
			cur += suf[a] + pref[b - 1] - pref[i - 1];
			cur += suf[a + 1] + pref[b - 1] - pref[i];
			cur += max(x[a] - x[b], L - x[a] + x[b]);	
		}
		else
		{
			int k = (n - i - 1) / 2;
			if (k > 0)
			{
				int a = n - k, b = i + k;
				cur += suf[a] + pref[b] - pref[i - 1];
				cur += suf[a] + pref[b - 1] - pref[i];
				cur += max(x[a - 1] - x[b], L - x[a - 1] + x[b]);
			}
			else
			{
				cur += max(x[i + 1] - x[i], L - x[i + 1] + x[i]);
			}
		}
		ans = max(ans, cur);
	}
}

