		scanf("%d", &x[i]);
	//~solve
	ans = max(L - x[0], x[n - 1]);
	solve();
	reverse(x, x + n);
	for (int i = 0; i < n; i++)
		x[i] = L - x[i];
	solve();
	cout << ans << endl;	

	return 0;
}

