typedef pair<LL, LL> pll;

deque<LL> q;

LL getindex(LL from, LL to, LL val) {
	if (from == to) {
		if (q[from] == val) return from;
		else return -1;
	}
	LL mid = (from + to) / 2;
	if (q[mid]==val) return mid;
	else if(q[mid]>val){
		return getindex(from, mid - 1, val);
	}
	else {
		return getindex(mid, to, val);
	}
}

int main(void)
{
