	while (burnt != n) {
		burnt++;
		LL ccw, cw;
		if (now > q.back()) {
			cw = now - q.back();
		}
		else {
			cw = l - q.back() + now;
		}
		if (now < q.front()) {
			ccw = abs(q.front() - now);
		}
		else {
			ccw = l - now + q.front();
		}
		if (cw > ccw) {
			now = q.back();
			q.pop_back();
		}
		else {
			now = q.front();
			q.pop_front();
		}
		walked += max(cw, ccw);
