long long ans;
void solve () {
	long long i , now , pos;
	a[n+1] = l;
	for ( i = 0 ; i <= n ; i++ ) p[i] = a[i+1] - a[i];
	for ( i = n ; i >= 0 ; i-- ) ra[i] = ra[i+1] + p[i];
	sdown[0] = a[1];
	for ( i = 1 ; i <= n ; i++ ) {
		sdown[i] = sdown[i-1] + a[i+1];
	}
	for( i = n ; i >= 0 ; i-- ) {
		sup[i] = sup[i+1] + ra[i];
	}
	now = 0;
	ans = max ( ans , a[n] );
	//for ( i = 0 ; i <= n ; i++ ) printf ( "%lld " , ra[i] );
	//printf ( "\n" );
	for ( i = 2 ; i <= n ; i++ ) {
		pos = n - i / 2;
		now = 0;
		if ( i % 2 == 0 ) {
			now += sup[pos+1] * 2;
			now -= ra[pos+1];
			now += sdown[pos-1] * 2;
			if ( pos-(n-pos)-1 >= 0 ) now -= (sdown[pos-(n-pos)-1]) * 2;
		}
		else {
			now += sup[pos+1] * 2;
			now += sdown[pos-1] * 2;
			if ( pos-(n-pos)-1-1 >= 0 ) now -= (sdown[pos-(n-pos)-1-1]) * 2;
			now -= a[pos];
			//printf ( "   %lld %lld %lld %lld \n" , sup[pos+1] , sdown[pos-1] , (sdown[pos-(n-pos)-1-1]) , a[pos-1] );
		}
		//printf ( "%lld %lld %lld %lld\n" , i , pos , pos - (n-pos) - 1 , now );
		ans = max ( ans , now );
	}
}
