	for ( i = 1 ; i <= n / 2 ; i++ ) swap ( a[i] , a[n-i+1] );
	for ( i = 1 ; i <= n ; i++ ) {
		a[i] = l - a[i];
	}
	solve ();
	printf ( "%lld\n" , ans );
}
