ll dfs(int p, int s, int e, ll val, int i, int j){
    //if(s > e) return val;
    ll left = X[s];
    ll right = X[e];
    ll rval, lval;
    if(e == s){
        if(p > right){
            return val + max(p - right, L-(p - right));
        }
        else{
            return val + max(right - p, L-(right - p));
        }
    }
    else if(p > right){
    //if(p >= L/2){
        rval = p - right;
        lval = L - (p - left);
    }
    else{
        lval = left - p;
        rval = L - (right - p);
    }
    ll ret = 0;

    if(lval > rval && s < i){
        ret = dfs(left, s+1, e, val+lval, i, j);
    }
    //else if(rval > lval && e > j){
    else if(rval > lval){
        ret = dfs(right, s, e-1, val+rval, i, j);
    }
    else{
        ll b = dfs(left, s+1, e, val+lval, i, j);
        ll a = dfs(right, s, e-1, val+rval, i, j);
        ret = max(a,b);
    }
    return ret;
}

