#define ll long long
ll l, n, x[200005];
ll y[200005];
ll dx[200005], dxprime[200005];
ll dy[200005], dyprime[200005];
int main(){
	scanf("%lld%lld", &l, &n);
	for (int i = 0; i < n; i++){
		scanf("%lld", &x[i]);
	}
	for (int i = n - 1; i >= 0; i--){
		y[n - 1 - i] = l - x[i];
	}
	for (int i = 1; i <= n; i++){
		dx[i] = dx[i - 1] + 2*x[i - 1];
		dxprime[i] = dx[i] - x[i - 1];
	}
	for (int i = 1; i <= n; i++){
		dy[i] = dy[i - 1] + 2*y[i - 1];
		dyprime[i] = dy[i] - y[i - 1];
	}
	ll answer = 0;
	for (int i = 0; i <= n; i++){
		ll gapone = i;
		ll gaptwo = (i + 1);
		//turns
		int turn = min(gapone, (n + 1) - gaptwo);
		//go left, turn on all right
		if (gapone > turn && (n + 1 - gaptwo)>=turn){
			answer = max(answer, dxprime[gapone] - dx[gapone - turn - 1] + dy[(n + 1) - gaptwo] - dy[(n + 1) - gaptwo - turn]);
		}
		//go left turn on all left
		if (gapone >= turn && (n + 1 - gaptwo) >= turn){
			answer = max(answer, dx[gapone] - dx[gapone - turn] + dyprime[(n + 1)-gaptwo] - dy[(n + 1)-gaptwo - turn]);
		}
		//go right turn on all right
		if (gapone >= turn && (n + 1 - gaptwo) >= turn){
			answer = max(answer, dxprime[gapone] - dx[gapone - turn] + dy[(n + 1) - gaptwo] - dy[(n + 1) - gaptwo - turn]);
		}
		//go right turn on all left
		if (gapone >= turn && (n + 1 - gaptwo) > turn){
			answer = max(answer, dx[gapone] - dx[gapone - turn] + dyprime[(n + 1) - gaptwo] - dy[(n + 1) - gaptwo - turn - 1]);
		}
	}
	printf("%lld\n", answer);

}

