      sum += (tmp.front() - now + L) % L;
      now = tmp.front();
      tmp.pop_front();
    }
    ans = max(ans, sum);
    tmp = X;
    now = 0; sum = 0;
    rep(j, 0, i){
      sum += (now + L - tmp.back()) % L;
      now = tmp.back();
      tmp.pop_back();
    }
    while(tmp.size() != 0){
      sum += (tmp.front() - now + L) % L;
      now = tmp.front();
      tmp.pop_front();
      if(tmp.size() == 0) break;
      sum += (now - tmp.back() + L) % L;
      now = tmp.back();
      tmp.pop_back();
    }
    ans = max(ans, sum);
  }
  cout << ans << rt;
}

