long long recurse(int idx1, int idx2, int side) {
    if (idx1 >= idx2)
        return 0;
    if (dyn[idx1][idx2][side] != -1)
        return dyn[idx1][idx2][side];

    long long ans = 0;
    // Walk to the left
    if (side == 0) {
        long long dist = a[idx1 + 1] - a[idx1];
        ans = max(ans, recurse(idx1 + 1, idx2, 0) + dist);
    } else {
        long long dist = l - a[idx2] + a[idx1];
