        ans = max(ans, recurse(idx1 + 1, idx2, 1) + dist);
    } else {
        long long dist = a[idx2] - a[idx2 - 1];
        ans = max(ans, recurse(idx1, idx2 - 1, 1) + dist);
    }

    return dyn[idx1][idx2][side] = ans;
}

