int solve(int i, int j, bool t) {
	//何番目から何番目まで使えるか、いま最初にいるか、最後にいるか
	if (i > j) {
		return 0;
	}
	if (dp[i][j][t] > 0) {
		return dp[i][j][t];
	}
	int sum = 0;
	if (!t) {
		sum = solve(i + 1, j, 0) + x[i] - x[i - 1];
		sum = max(sum, solve(i, j - 1, 1) + x[i - 1] + (l - x[j]));
	}
	else {
		sum = solve(i + 1, j, 0) + x[i] + l - x[j + 1];
		sum = max(sum, solve(i, j - 1, 1) + x[j + 1] - x[j]);
	}
	return dp[i][j][t] = sum;
}
