ll f( ll pos, std::deque<ll> deq )
{
  ll ret = 0;

  if( deq.empty() )
    return ret;

  ll d1 = (deq[0]-pos+L)%L, d2 = L-(deq[deq.size()-1]-pos+L)%L;

  if( pos && deq[0] && pos > deq[0] )
    d1 = L-pos+deq[0];
  if( pos && deq[deq.size()-1] && pos < deq[deq.size()-1] )
    d2 = pos+L-deq[deq.size()-1];

  if( d1 > d2 )
  {
    puts("CCW");
    pos = deq[0];
    ret += d1;
    deq.pop_front();
    printf( "(to %lld) +%lld\n", pos, d1 );
    ret += f( pos, deq );
  }
  else if( d1 < d2 )
  {
    puts("CW");
    pos = deq[deq.size()-1];
    ret += d2;
    deq.pop_back();
    printf( "(to %lld) +%lld\n", pos, d2 );
    ret += f( pos, deq );
  }
  else
  {
    puts("Both");
    ll ret1 = ret, ret2 = ret;

    pos = deq[0];
    ret1 += d1;
    deq.pop_front();
    printf( "(to %lld) +%lld\n", pos, d1 );
    ret1 += f( pos, deq );
    deq.push_front( pos );
    pos = deq[deq.size()-1];
    ret2 += d2;
    deq.pop_back();
    printf( "(to %lld) +%lld\n", pos, d2 );
    ret2 += f( pos, deq );
    deq.push_back( pos );

    return std::max( ret1, ret2 );
  }

  return ret;
}

