ll l, n;
vector < ll > x;
vector < ll > smpref, smsuff;

ll sm(ll l, ll r, vector < ll > &pref){
    l = max(l, (ll)0), r = min(n - 1, r);
    if(l > r)return 0;
    if(!l)return pref[r];
    return pref[r] - pref[l - 1];
}

void solve(){
    cin >> l >> n;
    x.resize(n), smpref.resize(n), smsuff.resize(n);
    for(ll i = 0; i < n; ++i)cin >> x[i];
    smpref[0] = x[0];
    for(ll i = 1; i < n; ++i){
        smpref[i] = smpref[i - 1] + x[i];
    }
    smsuff[0] = l - x[0];
    for(ll i = 1; i < n; ++i){
        smsuff[i] = smsuff[i - 1] + (l - x[i]);
    }
//    for(ll i = 0; i < n; ++i){
//        cerr << smpref[i] << " " << smsuff[i] << "\n";
//    }
    ll ans = 0;
    for(ll i = 0; i < n; ++i){
        if(i + 1 < n - i){
            ll take = i + 1;
            ll v1 = 2 * sm(0, i, smpref) - x[i] + 2 * sm(i + 1, i + 1 + take - 1, smsuff);
            ll v2 = 2 * sm(0, i - 1, smpref) + 2 * sm(i, 2 * i, smsuff) - (l - x[i]);
//            cerr << "A " << i << " " << v1 << " " << v2 << "\n";
            ans = max({ans, v1, v2});
        } else {
            ll take = n - i;
            ll v1 = 2 * sm(i, n - 1, smsuff) + 2 * sm(i - 1 - take + 1, i - 1, smpref) - (l - x[i]);
            ll v2 = 2 * sm(i + 1, n - 1, smsuff) + 2 * sm(i - take + 1, i, smpref) - x[i];
//            cerr << "B " << i << " " << v1 << " " << v2 << "\n";
            ans = max({ans, v1, v2});
        }
    }
    cout << ans << "\n";
}

