int  gcd(int a, int b) {
	if (a < b) gcd(b, a);
	int r;
	while ((r = a%b)) {
		a = b;
		b = r;
	}
	return b;
}
long long lcm(long long a, long long b) {
	return a / gcd(a, b) * b;
}
long long nibun(int t, long long bound) {
	long long lb = 1;
	long long ub = 1000000000;
	while (ub - lb > 1) {
		long long mid = (ub + lb) / 2;
		long long tmp = 1;
		for (int i = 0; i < t; i++) {
			tmp *= mid;
			if (tmp > bound)break;
		}
		if (tmp > bound)ub = mid;
		else lb = mid;
	}
	return lb;
}
long long nibun2(int t, long long bound) {
	long long lb = 1;
	long long ub = 1000000000;
	while (ub - lb > 1) {
		long long mid = (ub + lb) / 2;
		long long tmp = 1;
		for (int i = 0; i < t; i++) {
			tmp *= mid;
			if (tmp >= bound)break;
		}
		if (tmp >= bound)ub = mid;
		else lb = mid;
	}
	return lb;
}
