ll dp[2010][2010][2];

int main() {
    ll L, N; scanf("%lld%lld", &L, &N);
    if(N > 2000) return 1;

    vector<ll> X(N);
    for(int i=0; i<N; i++) scanf("%lld", &X[i]);

    X.emplace_back(0); N++;
    sort(X.begin(), X.end());
    for(int i=0; i<N; i++) X.emplace_back(L+X[i]);

    int M = 2*N;
    fill(dp[0][0], dp[M][0], -LONGINF);
    dp[0][1][0] = dp[N][N+1][0] = 0;
    for(int d=1; d<=N; d++) {
        for(int i=0; i<M; i++) {
            int j = i + d;
            if(j > M) continue;
            for(int k=0; k<2; k++) {
                if(dp[i][j][k] == -LONGINF) continue;
                // fprintf(stderr, "dp[%d][%d][%d] = %lld\n", i, j, k, dp[i][j][k]);
                int pos = (k ? X[j-1] : X[i]);
                int cl = -1, cr = -1;
                if(i-1 >= 0) cl = X[i-1];
                if(j < M) cr = X[j];
                if(cl >= 0) chmax(dp[i-1][j][0], dp[i][j][k] + pos - cl);
                if(cr >= 0) chmax(dp[i][j+1][1], dp[i][j][k] + cr - pos);
            }
        }
    }

    ll ans = -LONGINF;
    for(int i=0; i<M-N+1; i++) {
        for(int k=0; k<2; k++) {
            chmax(ans, dp[i][i+N][k]);
        }
    }
    printf("%lld\n", ans);
    return 0;
}

