        cin >> X[i];
    }

    FORq(i,1,N){
        Y[N+1-i] = L-X[i];
    }

    FORq(i,1,N){
        S1[i] = S1[i-1] + X[i];
        S2[i] = S2[i-1] + Y[i];
    }
    ll ans = 0;

    FORq(d,0,N){
        FORq(d1,0,1){
            FORq(d2,0,1){
