	if(left==N+1&&right==0) return 0;
	if(left==N+1 && lnow==1){
		return -INF;
	}
	if(right==0 && lnow==0){
		return -INF;
	}
	ll res = 0;
	if(lnow==1){
		ll cand1 = rec(left+1, right, 1) + (X[left+1] - X[left]);
		ll cand2 = rec(left+1, right, 0) + (X[N+1]-X[left]) + (X[right] - X[0]);
		res = max(cand1, cand2);
	}else{
		ll cand1 = rec(left, right-1, 1) + (X[N+1]-X[left]) + (X[right] - X[0]);
		ll cand2 = rec(left, right-1, 0) + (X[right] - X[right-1]);
		res = max(cand1, cand2);
	}
	dp[left][right][lnow] = res;
	return res;
}

int main(){
	cin >> L >> N;
	X[0] = 0;
	REP(i, N) cin >> X[i+1];
	X[N+1] = L;

	//REP(i, N+2) cout << X[i] << " ";
	//cout << endl;

	REP(i, 2002)REP(j, 2002)REP(k, 2) dp[i][j][k] = -1;

	ll res = -1;
	REP(i, N+1)REP(j, 2) res = max(rec(i+1, i, j), res);
	cout << res << endl;
    return 0;
}

