using namespace std;

struct Config {
  int L;
  deque<int> trees;
};

Config readConfig() {
  Config output;
  size_t N;
  cin >> output.L >> N;
  while (output.trees.size() < N) {
    int t;
    cin >> t;
    output.trees.push_back(t);
  }
  return output;
}

int clockwiseDistance(int next, int curr, int L) {
  if (next < curr) {
    return curr - next;
  } else {
    return curr + (L - next);
  }
}

int counterClockwiseDistance(int next, int curr, int L) {
  if (next > curr) {
    return next - curr;
  } else {
    return next + (L - curr);
  }
}

auto pingPong(const Config& config, bool clockwiseDirection) {
  auto trees = config.trees;
  auto path = 0ull;
  int currentPosition = 0;

  while (!trees.empty()) {          
    if (!clockwiseDirection) {
      auto frontDistance = counterClockwiseDistance(trees.front(), currentPosition, config.L);
      path += frontDistance;
      currentPosition = trees.front();
      trees.pop_front();
    } else {
      auto backDistance = clockwiseDistance(trees.back(), currentPosition, config.L);        
      path += backDistance;
      currentPosition = trees.back();
      trees.pop_back();
    }
    clockwiseDirection = !clockwiseDirection;
  }
  return path;
}

auto fixedTurns(const Config& originalConfig, unsigned int turns, bool clockwise) {
    auto config = originalConfig;
    auto skip = config.trees.size() - 1 - turns;
    while (skip > 0) {
        if (clockwise) {
            config.trees.pop_back();
        } else {
            config.trees.pop_front();
        }
        skip--;
    }
    return pingPong(config, clockwise);
}

auto allTurns(const Config& config) {
    auto best = 0ull;
    for (auto turns = 0u; turns < config.trees.size(); turns++) {
        best = max(best, fixedTurns(config, turns, true));
        best = max(best, fixedTurns(config, turns, false));
    }
    return best;
}

int main() {
  const auto config = readConfig();
  cout << allTurns(config) << endl;
  return 0;
}

