}
LL n,m,D,p[M],F[M],ans,pre[M],suf[M];
void solve(){
	for(int i=1;i<=n;i++) pre[i]=pre[i-1]+p[i];
	for(int i=n;i;i--) suf[i]=suf[i+1]+D-p[i];
	for(int i=1;i<=n;i++){
		LL lt,rt,now=0;
		lt=((n+i)>>1),rt=lt+1;
		now=((pre[lt]-pre[i-1]+suf[rt])<<1);
		if((n-i-1)%2==0) now-=D-p[rt];
		else now-=p[lt];
		ans=max(ans,now);
	}	
}
