const ll max_n = 2005;
ll l, n;
ll x[max_n];

ll sim(ll y, bool clock){
	// cout << "sim:" << y << " " << clock << endl;
	ll lp = 0;
	ll rp = n+1;

	ll ret = 0;
	if(clock){
		lp += y;
		ret += x[lp];
	}else{
		rp -= y;
		ret += l - x[rp];
	}

	// cout << lp << " " << rp << " " << ret << endl;
	while(rp > lp + 1){
		if(clock){
			rp--;
		}else{
			lp++;
		}
		ret += x[lp] + l - x[rp];
		clock = !clock;

		// cout << lp << " " << rp << " " << ret << endl;
	}

	return ret;
}

int main()
{
