	cin >> l >> n;
	x[0] = 0;
	rep(i, n) cin >> x[i+1];
	x[n+1] = l;

	ll ans = 0;
	rep(i, n){
		ans = max(ans, sim(i+1, true));
		ans = max(ans, sim(i+1, false));
	}

	cout << ans << endl;
}

