int L,n; 
int get(int x[],int y[])
{

   // printarray(x,n);
   // printarray(y,n);
   int px[n],py[n];
   for (int i = 0; i < n; ++i)
   {
       px[i]=2*x[i];
       if(i!=0)px[i]+=px[i-1];
   }
   for(int i=n-1;i>=0;i--)
   {
      py[i]=2*y[i];
      if(i!=n-1)py[i]+=py[i+1];
   }
   int fans=0;
   for(int i=0;i<n;i++)
   {
      int ans=0;
      int left=0,right=0;
      if(i+1>n-(i+1))
      {
        left=n-(i+1)+1;
        right=n-(i+1);

      }
      else
      {
          left=i+1;
          right=i+1;
      }
      ans+=px[i]-x[i];
      if(i-left>=0)ans-=px[i-left];
      if(right>0)
      {
         ans+=py[i+1];
         if(i+1+right<n)ans-=py[i+1+right];
      }

      fans=max(fans,ans);
   }

    //debug(fans);  

   return fans;


}


