ll L;
int N;
ll X[200010];
ll sum[200010];
ll sum_rev[200010];
ll ans = 0;

void solve()
{
  sort(X + 1, X + N + 1);
  sum[0] = 0;
  for (auto i = 1; i <= N; i++)
  {
    sum[i] = sum[i - 1] + X[i];
    // cerr << "sum[" << i << "] = " << sum[i] << endl;
  }
  sum_rev[N + 1] = 0;
  for (auto i = N; i >= 1; i--)
  {
    sum_rev[i] = sum_rev[i + 1] + L - X[i];
    // cerr << "sum_rev[" << i << "] = " << sum_rev[i] << endl;
  }
  for (auto right = 1; right <= N; right++)
  {
    int left = N - right;
    int num = min(right, left);
    // cerr << "left = " << left << ", right = " << right << endl;
    ll tans = sum[right] - sum[right - num] + sum_rev[right + 1] - sum_rev[right + 1 + num];
    tans *= 2;
    tans -= L - X[right + 1];
    // cerr << "tans = " << tans << endl;
    ans = max(tans, ans);
    num = min(right, left + 1);
    tans = sum[right] - sum[right - num] + sum_rev[right + 1] - sum_rev[right + 1 + (num - 1)];
    tans *= 2;
    tans -= X[right];
    // cerr << "tans = " << tans << endl;
    ans = max(tans, ans);
  }
}

int main()
{
  cin >> L >> N;
  X[0] = 0;
  for (auto i = 1; i <= N; i++)
  {
    cin >> X[i];
  }
  X[N + 1] = L;
  solve();
  for (auto i = 1; i <= N; i++)
  {
    X[i] = L - X[i];
  }
  solve();
  cout << ans << endl;
}

