  }

  if(dp[i][j][k] >= 0)return dp[i][j][k];
  ll res = 0;
  if(k == 0){
    res = max(res, calc(i+1, j, 0) + x[i+1]-x[i]);
    res = max(res, calc(i+1, j, 1) + x[i] + (l - x[j]));
  }else{
