ll calc(int now, vector<bool> flag){
  flag[now] = false;

  // 反時計
  int left = now;
  ll ld = 0;
  for( int i=1,id=now+1; i<N; i++ ){
    if( id == N ) id = 0;
    if( flag[id] ){
      left = id;
      ld = X[left] - X[now];
      if( ld < 0 ) ld += L;
      break;
    }
    id++;
  }

  // 時計
  int right = now;
  ll rd = 0;
  for( int i=1,id=now-1; i<N; i++ ){
    if( id == -1 ) id = N-1;
    if( flag[id] ){
      right = id;
      rd = X[now] - X[right];
      if( rd < 0 ) rd += L;
      break;
    }
    id--;
  }

  // cout << now << ", " << left << ":" << ld << ", " << right << ":" << rd << endl << endl;
  if( left == right ) return max( ld, rd );

  ll ret = 0;
  // if( ld > rd ){
  //   ret = ld + calc(left, flag);
  // } else if( ld < rd ){
  //   ret = rd + calc(right, flag);
  // } else{
    // ret = max( ld + calc(left, flag), rd + calc(right, flag) );
  // }

  ll cld = ld + calc(left, flag);
  ll crd = rd + calc(right, flag);
  ret = max( cld, crd );

  // cout << now << ", " << left << ":" << ld << ":" << cld << ", " << right << ":" << rd << ":" << crd << ", " << ret << endl;
  return ret;
}

