long L;
vector<long> X;
long calc(long now, int l, int r)
{
	long a = X[l];
	long b = X[r];

	if (l == r)
	{
		if (a < now)
		{
			return max(now - a, a + L - now);
		}
		else
		{
			return max(a - now, now + L - a);
		}
	}

	long A = (now < a) ? a - now : a + L - now;
	long B = (b < now) ? now - b : now + L - b;

	long first = A + calc(a, l + 1, r);
	long second = B + calc(b, l, r - 1);
	return max(first, second);

}
