    for(int i = 1; i < n; i++){
        long long d = 0, c = n - i, le = c / 2, ri = n - (c + 1) / 2 + 1;
        d = 2 * (x[i] + s[i + le] - s[i] + rs[ri]);
        if(c % 2 == 0)
            d -= x[i + le];
        else
            d -= l - x[ri];
        ans = max(ans, d);
    }
    for(int i = n; i > 1; i--){
        long long d = 0, c = i - 1, le = (c + 1) / 2, ri = i - c / 2;
        d = 2 * (l - x[i] + s[le] + rs[ri] - rs[i]);
        if(c % 2 == 0)
            d -= l - x[ri];
        else
            d -= x[le];
        ans = max(ans, d);
    }
    cout << ans << endl;
    return 0;
}

