ll calc(const vector<ll>& sumx, const vector<ll>& sumy, int n) {
  ll ret = 0;
  rep(d, n) {
    // skip d-th tree at first
    auto cnt = n-d;
    auto xpos = d+cnt/2;
    auto ypos = (cnt-1)/2;
    auto now = (sumx[xpos] - sumx[d])*2;
    now += sumy[ypos]*2;
    if (cnt%2 == 0) {
      now += sumy[ypos+1] - sumy[ypos];
    } else {
      now += sumx[xpos+1] - sumx[xpos];
    }
    chmax(ret, now);
  }
  return ret;
}

