ll dfs(int l, int r, ll dis, int cur) {
	if (l == r) {
		ll ldis;
		if (cur == 0) {
			ldis = dis +(ll) L - X[l];
		}
		else if(cur > l){
			ldis = dis + (ll)X[cur] - X[l];
		}
		else {
			ldis = dis + (ll)X[cur] + L - X[r];
		}
		ll rdis;
		if (cur > r) {
			rdis = dis + (ll)X[r] + L - X[cur];
		}
		else {
			rdis = dis + (ll)X[r] -  X[cur];
		}
		return max(rdis,ldis);
	}
	ll ldis, rdis;
	if (cur == 0) {
		ldis = dfs(l - 1, r, dis + (ll)L - X[l], l);
	}
	else if(cur > l){ //反時計回り
		ldis = dfs(l - 1, r, dis + (ll)(X[cur] - X[l]), l);
	}
	else {
		ldis = dfs(l - 1, r, dis + (ll)(X[cur] + L - X[l]), l);
	}
	if (cur > r) {
		rdis = dfs(l, r + 1, dis + (ll)X[r] + L - X[cur], r);
	}
	else {
		rdis = dfs(l, r + 1, dis + (ll)X[r] - X[cur], r);
	}
	return max(ldis, rdis);
}


