ll X[200002];
ll L;
int N;


template <typename T>
class BIT {
public:
	vector<T> data;
	int n;
	BIT() {}
	BIT(int n_) {
		n = n_;
		data.assign(n, T(0));
	}
	// v[a] += w
	void add(int a, T w) {
		for (int x = a; x < n; x |= x + 1) data[x] += w;
	}
	// sum of v[i] for i in [0, a)
	T sum(int a) {
		T ret = 0;
		for (int x = a - 1; x >= 0; x = (x & (x + 1)) - 1) {
			ret += data[x];
		}
		return ret;
	}
};


int main() {
	cin >> L >> N;

	BIT<ll> bit(N), bit_rev(N);
	for(int i=0;i<N;i++) {
		cin >> X[i];
		bit.add(i, X[i]);
		bit_rev.add(N - i - 1, L - X[i]);
	}

	if (N == 1) {
		cout << max(X[0], L - X[0]) << endl;
		return 0;
	}

	ll ans = 0;
	{
		// i = 0
		ans = max(ans, X[0] + 2 * (L - X[1]));
		// i = N - 1
		ans = max(ans, L - X[N - 1] + 2 * X[N - 2]);
	}

	// end i as left
	for (int i = 1; i < N - 1; i++) {
		int left_n = i;
		int right_n = N - i - 1;
		ll s;
		if (left_n >= right_n) {
			s = 2 * bit.sum(i) + 2 * bit_rev.sum(N - i - 1) + X[i];
			if (left_n > right_n) {
				s -= 2 * bit.sum(i - right_n);
			}
		}else {
			s = 2 * bit.sum(i) + 2 * bit_rev.sum(N - i - 1) + X[i];
			if (left_n + 1 < right_n) {
				s -= 2 * bit_rev.sum(N - i - 1 - (left_n + 1));
			}
		}
		ans = max(ans, s);
	}
	// end i as right
	for (int i = 1; i < N - 1; i++) {
		int left_n = i;
		int right_n = N - i - 1;
		ll s;
		if (left_n <= right_n) {
			s = 2 * bit.sum(i) + 2 * bit_rev.sum(N - i - 1) + L - X[i];
			if (left_n < right_n) {
				s -= 2 * bit_rev.sum(N - i - 1 - left_n);
			}
		} else {
			s = 2 * bit.sum(i) + 2 * bit_rev.sum(N - i - 1) + L - X[i];
			if (left_n > right_n + 1) {
				s -= 2 * bit.sum(i - (right_n + 1));
