ll solve(int i, int j, int dir){
    if(i > j){
        return 0LL;
    }

    ll &ans = dp[i][j][dir];

    if(ans != -1LL){
        return ans;
    }

    ll mn1, mn2;

    if(dir == clockwise){
        ll cur = a[i - 1];
        mn1 = a[i] - cur;
        mn2 = cur + l - a[j];

        ans = max(solve(i + 1, j, dir) + mn1, solve(i, j - 1, !dir) + mn2);
    }else{  
        ll cur = a[j + 1];

        mn1 = cur - a[j];
        mn2 = l - cur + a[i];

        ans = max(solve(i, j - 1, dir) + mn1, solve(i + 1, j, !dir) + mn2);
    }

    return ans;
}

