ll g[2][maxn];

int main()
{
    int l, n;
    cin >> l >> n;
    ll x[n + 1];
    for (int i = 1; i <= n; i++)
    {
        cin >> x[i];
    }

    //正向遍历
    for (int i = 1; i <= n; i++)
    {
        dp[0][i] = max(dp[0][i - 1], x[i]);
        g[0][i] = 2 * x[i];
    }

    //反向遍历
    for (int i = n; i >= 1; i--)
    {
        dp[1][i] = max(dp[1][i + 1], l - x[i]);
        g[1][i] = 2 * (l - x[i]);
    }

    ll ans = max(dp[0][n], dp[1][1]);

    for (int i = 1; i <= n; i++)
    {
        //顺着走到i，再逆着走到i+1
        ll tmp = g[0][i] + dp[1][i + 1];
        if(tmp > ans)
        {
            ans = tmp;
        }

        tmp = g[1][i] + dp[0][i - 1];
        //逆着走到i，再顺着走到i-1
        if(tmp > ans)
        {
            ans = tmp;
        }
    }

    cout << ans << endl;

    return 0;
}

