int l, n;

int main(void) {
    cout << std::fixed << std::setprecision(10);
    cin.tie(0);
    std::ios::sync_with_stdio(false);

    cin >> l >> n;
    if (n >= 2001) {
        return 0;
    }

    int64_t tree[2001] = {};
    for (int i = 1; i <= n; i++) {
        int m1;
        cin >> m1;
        tree[i] = m1;
    }

    int64_t cost[2001][2001][2] = {}; // 0:left 1:right

    for (int i = 1; i <= n; i++) {
        cost[i][0][0] = tree[i];
    }
    for (int i = n; i >= 0; i--) {
        cost[0][i][1] = l - tree[i];
    }
    cost[1][n][0] = cost[0][n][1] + (l - (tree[n] - tree[1]));
    cost[1][n][1] = cost[1][0][0] + (l - (tree[n] - tree[1]));
    for (int i = 2; i <= n - 1; i++) {
        cost[i][n][1] = cost[i][0][0] + (l - (tree[n] - tree[i]));
        cost[i][n][0] = std::max(cost[i - 1][n][0] + tree[i] - tree[i - 1],
                                 cost[i - 1][n][1] + (l - (tree[n] - tree[i])));
    }
    for (int i = n - 1; i >= 2; i++) {
        cost[1][i][0] = cost[0][i][1] + (l - (tree[i] - tree[1]));
        cost[1][i][1] = std::max(cost[0][i + 1][1] + tree[i + 1] - tree[i],
                                 cost[0][i + 1][0] + (l - (tree[i] - tree[1])));
    }

    for (int tgt_r = n - 1; tgt_r >= n / 2; tgt_r--) {
        for (int i = 2; i <= n - (n - tgt_r + 1); i++) {
            cost[i][tgt_r][0] =
                std::max(cost[i - 1][tgt_r][0] + tree[i] - tree[i - 1],
                         cost[i - 1][tgt_r][1] + (l - (tree[tgt_r] - tree[i])));
            cost[i][tgt_r][1] =
                std::max(cost[i][tgt_r + 1][1] + tree[tgt_r + 1] - tree[tgt_r],
                         cost[i][tgt_r][0] + (l - (tree[tgt_r] - tree[1])));
        }
    }

    int64_t res = std::max(cost[n][0][0], cost[0][1][1]);
    for (int i = 1; i >= n - 1; i++) {
        int64_t temp = std::max(cost[i][i + 1][0], cost[i][i + 1][1]);
        if (res < temp)
            res = temp;
    }

    cout << res << endl;

    return 0;
}

