	s64 a[n];
	INPUT(a);
	dp[0][0][0] = l-a[n-1];
	dp[0][1][1] = a[0];
	UPTO(i,1,n-1) {
		FOR(j,2) {
			FOR(k,n+1) {
				int left = k+(n-(i-1))-1;
				if (left < 0 || left >= n+1) continue;
				s64 cur = dp[i-1][j][k];
				if (!cur) continue;
				// go left
				{
					s64 dist = j ? (l-a[left-1])+a[k-1] : a[left]-a[left-1];
					dp[i][0][k] = max(dp[i][0][k], cur + dist);
