					s64 dist = j ? a[k]-a[k-1] : (l-a[left])+a[k];
					dp[i][1][k+1] = max(dp[i][1][k+1], cur + dist);
				}
			}
		}
	}

	s64 res = 0;
	FOR(i,2) {
		UPTO(j,1,n) res = max(res,dp[n-1][i][j]);
