ll solve2(const vector<ll>& a) {
  // cout << a << endl;
  const ll n = a.size();
  vector<ll> S(n+1, 0);
  rep(i, n) S[i+1] = S[i] + a[i];
  // cout << S << endl;
  ll left = 1, right = n-2;
  ll res = S[n-1], sum = S[n-2] * 2 + (S[n] - S[n-1]) * 2;
  ll L = S[n];
  while (true) {
    chmax(res, sum - (L - S[n-left]));
    if (right > left) {
      chmax(res, sum - S[right] + S[right-left] * 2);
    }
    if (left+1 > right-1) break;
    // 右を縮める
    sum -= S[right] * 2;
    sum += S[right-(left+0)] * 2;
    sum += S[right-(left+1)] * 2;
    --right;
    // 左を伸ばす
    sum += (S[n] - S[n-(left+1)]) * 2;
    ++left;
  }
  // cout << res << endl;
  return res;
}
ll solve(vector<ll> a) {
  if (a.size() == 2) return *max_element(all(a));
  ll res = solve2(a);
  reverse(all(a));
  chmax(res, solve2(a));
  return res;
}

