inline void solve(int s , set < int > st , int ans){

	while(!st.empty()){
		pair < int , int > s1 ,s2 ; s1 = s2 =  {18446744073709551615ull  , -1} ;
		for( set <int>::iterator it = st.begin() ; it != st.end() ; ++it){
			int x = *it;
			if(x > s){
				s1 = min(s1 , {(s + abs(l - x)) , x});
				s2 = min(s2 , {(x - s) ,x});
			}
			else{
				s1 = min(s1 , {(s - x) , x});
				s2 = min(s2 , {l - s + x , x});
			}
		} 
		if(s1 == s2){	
			if(rand() & 1){
				st.erase(s1.se);
				ans += s1.fi;
				s = s1.se;
			}
			else {
				st.erase(s2.se);
				ans += s2.fi;
				s = s2.se;
			}
		}
		else if(s1 > s2){
			st.erase(s1.se);
			ans += s1.fi;
			s = s1.se;

		}
		else {
			st.erase(s2.se);
			ans += s2.fi;
			s = s2.se;
		}
	}
	tot = max(ans , tot);
}
inline void rec(set <int> st , int d = 0 , int ans = 0 , int s = 0){
	if(st.empty()){
		tot = max(tot , ans);
		return;
	}
	if(d <= 5){
		pair < int , int > s1 ,s2 ; s1 = s2 =  {18446744073709551615ull  , -1} ;
		for( set <int>::iterator it = st.begin() ; it != st.end() ; ++it){
			int x = *it;
			if(x > s){
				s1 = min(s1 , {(s + abs(l - x)) , x});
				s2 = min(s2 , {(x - s) ,x});
			}
			else{
				s1 = min(s1 , {(s - x) , x});
				s2 = min(s2 , {l - s + x , x});
			}
		}
		st.erase(s1.se);
		rec(st , d + 1 , ans + s1.fi , s1.se);
		st.insert(s1.se);
		st.erase(s2.se);
		rec(st , d + 1 , ans + s2.fi , s2.se);
	}
	else{
		solve(s , st , ans);
	}
}
