const int N = 200010;
int pla[N], n, len, val[N];
ll ans, rec[2][N];
void prework() {
  rep (i, 1, n-1) val[i] = pla[i+1] - pla[i];
  rep (i, 1, n-1)
    rec[0][i] = rec[0][i-1] + 1ll * (n-i) * val[i];
  rep (i, 1, n-1)
    rec[1][i] = rec[1][i-1] + 1ll * (i-1) * val[i];
}
ll calc(int l,int r) {
  if (l == r) return 0;
  ll ret = 0;
  int mid = (l + r) >> 1;
  ret += (rec[0][mid-1] - rec[0][l-1]) * 2 + (pla[mid] - pla[l]) * ((r-l-1) - (2*n - 2*l));
  ret += (rec[1][r-1] - rec[1][mid]) * 2 + (pla[r] - pla[mid+1]) * ((r-l-2) - (2*r - 4));
  // for (int i = l, j = r-l-1 ; j >= 0 ; ++ i, j -= 2)
