  // for (int i = r, j = r-l-2 ; j >= 0 ; -- i, j -= 2)
  //   ret += 1ll * j * (pla[i] - pla[i-1]);
  ret += 1ll * (r - l) * (pla[l] + len - pla[r]);
  return ret;
}
int main() {
  read(len), read(n);
  rep (i, 1, n) read(pla[i]);
  prework();
  rep (i, 1, n)
    ckmx(ans, pla[i] + calc(i, n));
  rep (i, 1, n) pla[i] = len - pla[i];
  reverse(pla+1, pla+n+1);
  prework();
  rep (i, 1, n)
    ckmx(ans, pla[i] + calc(i, n));
  printf("%lld\n", ans);
  return 0;
}

