using namespace std;
int L, N;
int _X[MAX_N];

int main(void){
    int ret = 0;
    cin >> L >> N;
    int MAX_BIT = pow(2, N);
    for(int i=0; i<N; i++) cin >> _X[i];
    for(int bits=0; bits<MAX_BIT; bits++){
        vector<int> X(_X, _X+N);
        int dist = 0;
        int x = 0;
        int _bits = bits;
        for(int i=0; i<N; i++){
            auto j = lower_bound(X.begin(), X.end(), x);
            if(_bits % 2){
                // clockwise go
                j = (j != X.end()) ? j : X.begin();
                dist += (*j > x) ? *j - x : L - x + *j;
            }else{
                // counterclockwise go
                j = (j != X.begin()) ? j - 1: X.end() - 1;
                dist += (x > *j) ? x - *j : x + L - *j;
            }
            x = *j;
            X.erase(j);
            _bits /= 2;
        }
        ret = max(ret, dist);
    }
    cout << ret << endl;
    return 0;
}

