typedef long long ll;

ll l;
int n;
vector<ll> x, s;

int main() {
    cin >> l >> n;
    ll xin, sin = 0;
    x.push_back(0);
    s.push_back(0);
    for (int i = 0; i < n; i++) {
        cin >> xin;
        sin += xin;
        x.push_back(xin);
        s.push_back(sin);
    }

    sort(x.begin(), x.end());
    sort(s.begin(), s.end());
    ll ans1 = 0, ans2 = 0;
    for (int i = 1; i <= n; i++) {
        ll r = x.at(i);
        ll m1 = (n - i) / 2, m2 = (n - i - 1) / 2;
        if (n-i == 0) {
            ans1 = max(ans1, r);
            break;
        }
        if ((n - i) % 2 == 0) r += 2*(s.at(i+m1)-s.at(i-1)) - x.at(i) - x.at(i+m1) + 2*m1*l - 2*(s.at(n)-s.at(n-m1));
        else r += 2*(s.at(i+m2)-s.at(i-1)) - x.at(i) + (2*m2+1)*l - 2*(s.at(n)-s.at(n-m2-1)) + x.at(i+m2+1);
        ans1 = max(ans1, r);
    }
    for (int i = 1; i <= n; i++) {
        ll r = l - x.at(n - i + 1);
        ll m1 = (n - i) / 2, m2 = (n - i + 1) / 2;
        if (n-i == 0) {
            ans2 = max(ans2, r);
            break;
        }
        if ((n - i) % 2 == 0) r += 2 * s.at(m1) + 2*m1*l - 2 * (s.at(n-i+1) - s.at(m1)) + x.at(n-i+1) + x.at(m1+1);
        else r += (2*m2-1)*l - 2*(s.at(n-i+1) - s.at(m2)) + x.at(n-i+1) + 2 * s.at(m2) - x.at(m2);
        ans2 = max(ans2, r);
    }
    ll ans = max(ans1, ans2);

    cout << ans << endl;
}

