using namespace std;

int n;
int L;
int a[N];
long long d[2002][2002][2];

int dist(int i, int j)
{
        int res = a[j] - a[i];
        if(res < 0){
                res += L;
        }
        return res;
}

long long solve(int l, int r, int g)
{
        if(l >= r){
                return 0;
        }
        long long &res = d[l][r][g];
        if(res != -1e18){
                return res;
        }
        if(g == 0){
                res = max(res, solve(l + 1, r, 0) + dist(l, l + 1));
                res = max(res, solve(l + 1, r, 1) + dist(r, l));
        }
        else{
                res = max(res, solve(l, r - 1, 0) + dist(r, l));
                res = max(res, solve(l, r - 1, 1) + dist(r - 1, r));
        }
        return res;
}

void solve_fast()
{
        long long res = 0;
        int l = 0, r = n, g = 0;
        while(l < r){
                if(g == 0){
                        if(dist(l, l + 1) > dist(r, l)){
                                res += dist(l, l + 1);
                        }
                        else{
                                res += dist(r, l);
                                g = 1;
                        }
                        l += 1;
                }
                else{
                        if(dist(r, l) > dist(r - 1, r)){
                                res += dist(r, l);
                                g = 0;
                        }
                        else{
                                res += dist(r - 1, r);
                        }
                        r -= 1;
                }
        }
        cout << res << "\n";
}

