using namespace std;

typedef long long LL;
#define N 300000

LL n,m,ans,a[N],b[N],A[N],B[N];

void solve(){
	for (LL i=1;i<=n;++i){
		b[i]=m-a[i];
		A[i]=A[i-1]+(a[i]-a[i-1])*(n-i*2);
	}
	reverse(b+1,b+n+1);
	for (LL i=1;i<=n;++i)
		B[i]=B[i-1]+(b[i]-b[i-1])*(n-i*2);
	for (LL i=1;i<=n;++i){
		LL j=(n-i+1)/2,k=n-i-j;
		if (j>k) ans=max(ans,a[i]*(n-i+1)+B[j]-b[j]*(n-j*2-1)+(A[i+k]-A[i])-(a[i+k]-a[i])*(n-(i+k)*2-2));
		else ans=max(ans,a[i]*(n-i+1)+B[j]-b[j]*(n-j*2-2)+(A[i+k]-A[i])-(a[i+k]-a[i])*(n-(i+k)*2-1));
	}
}

int main(){
	scanf("%lld%lld",&m,&n);
	for (LL i=1;i<=n;++i) scanf("%lld",a+i);
	solve();
	for (LL i=1;i<=n;++i) a[i]=m-a[i];
	reverse(a+1,a+n+1);
	solve();
	printf("%lld\n",ans);

	return 0;
}

