int main() {
  std::cin.tie(0); std::cin.sync_with_stdio(false);
  int X, n; std::cin >> X >> n;
  std::vector<int> a(n), b(n), A(n), B(n);
  std::for_each(a.begin(), a.end(), [](auto& x){std::cin >> x;});
  std::transform(a.begin(), a.end(), b.begin(), [X](auto x){return X - x;});
  std::reverse(b.begin(), b.end());
  std::partial_sum(a.begin(), a.end(), A.begin()); A.insert(A.begin(), 0);
  std::partial_sum(b.begin(), b.end(), B.begin()); B.insert(B.begin(), 0);
  long long ret = 0;
  auto check = [&] (int l, auto& a, auto& A) mutable {
    assert(0 <= l && l < n);
    long long now = -1;
    auto range_sum = [&] (int l, int r) {return A.at(r) - A.at(l);};
    if (2 * l >= n) {
      now = - X + a.at(l) + 2 * (n - l) * X
        - 2 * range_sum(l, n) + 2 * range_sum(2 * l - n, l);
    } else {
      now = - X + a.at(l) + 2 * (l + 1) * X
        - 2 * range_sum(l, 2 * l + 1) + 2 * range_sum(0, l);
    }
    ret = std::max(ret, now);
  };
  for (int i = 0; i < n; i++) check(i, a, A);
  for (int i = 0; i < n; i++) check(i, b, B);
  std::cout << ret << std::endl;
  return 0;
}

