#include "bits/stdc++.h"
#define in std::cin
#define out std::cout
#define rep(i,N) for(LL i=0;i<N;++i)
typedef long long int LL;

LL L, N;
std::vector<LL>X(N);
std::vector<std::vector<std::vector<LL>>>memo;

LL dp(LL i, LL j, bool f)
{
	if (i == j) return 0;
	if (j - i == 1) return 0;
	if (memo[i][j][f] != -1) return memo[i][j][f];
	LL res1 = 0, res2 = 0;
	if (i + 1 <= j && i + 1 <= N) res1 = dp(i + 1, j, true) + std::abs((f ? X[i + 1] - X[i] : X[i + 1] + (L - X[j]) % L));
	if (i <= j - 1 && j - 1 > 0) res2 = dp(i, j - 1, false) + std::abs((f ? (L - X[j - 1]) + X[i] : X[j] - X[j - 1]));
	return memo[i][j][f] = std::max(res1, res2);
}

int main()
{
	in >> L >> N;
	X.resize(N + 2);
	rep(i, N) in >> X[i + 1];
	X[0] = X[N + 1] = 0;
	if (N > 2000) return 0;
	memo.resize(N + 2);
	rep(i, memo.size())
	{
		memo[i].resize(N + 2);
		rep(j, memo[i].size()) memo[i][j].resize(2, -1);
	}
	out << dp(0, N + 1, true) << std::endl;
}

