using namespace std;
map<ll, int> mp;
int n,m;
ll res=0;
void dfs(ll x,ll y,int z)
{
	//cout <<x<<" "<<y<<" "<<z<<" ##\n";
	if (z==m)
	{
		res=max(res,y);
		return;
	}
	ll t=x,tt=x;
	while (!mp[t])
	{
		t--;
		if (t==-1) t=n-1;
	}
	while (!mp[tt])
	{
		tt++;
		if (tt==n) tt=0;
	}
	ll r=x-t,rr=tt-x;
	if (r<0) r+=n;
	if (rr<0) rr+=n;
	if (r>rr)
	{
		mp[t]=0;
		dfs(t,y+r,z+1);
		mp[t]=1;
	}
	else if (rr>r)
	{
		mp[tt]=0;
		dfs(tt,y+rr,z+1);
		mp[tt]=1;
	}
	else
	{
		mp[t]=0;
		dfs(t,y+r,z+1);
		mp[t]=1;
		mp[tt]=0;
		dfs(tt,y+rr,z+1);
		mp[tt]=1;
	}
}
