using namespace std;

int main()
{
    long long l, n;
    cin >> l >> n;
    vector<long long> x(n);
    vector<bool> isBurned(n);
    for (int i = 0; i < n; ++i){
        cin >> x[i];
        isBurned[i] = false;
    }
    int burned = 0;
    int now = 0;
    int next = 0;
    long long ans = 0;
    long long d_ccw, d_cw = 0;
    int d_ccwitr, d_cwitr;
    while(burned < n){
        d_ccw = 0;
        d_cw = 0;
        if(burned == 0){
            for (int i = 0; i < n; ++i){
                if(x[i] == (l - x[n-1-i])){continue;}
                else {
                    if(x[i] > x[n-1-i]){
                        now = 0;
                        ans += x[i];
                    }
                    else {
                        now = n-1;
                        ans += l - x[n-1];
                    }
                }
                isBurned[now] = true;
                break;
            }
        }
        else {
            for (int i = 1; i < n; ++i){
                if(now + i < n){
                    if(isBurned[now + i]){continue;}
                    next = now + i;
                    d_ccw = abs(x[next] - x[now]);
                }
                else {
                    if(isBurned[now + i - n]){continue;}
                    next = now + i - n;
                    d_ccw = abs(l - x[now] + x[next]);
                }
                d_ccwitr = next;
                break;
            }
            for (int i = 1; i < n; ++i){
                if(now - i >= 0){
                    if(isBurned[now - i]){continue;}
                    next = now - i;
                    d_cw = abs(x[next] - x[now]);
                }
                else {
                    if(isBurned[now - i + n]){continue;}
                    next = now - i + n;
                    d_cw = abs(l - x[next] + x[now]);
                }
                d_cwitr = next;
                break;
            }
            // cout << "(" << d_ccw << ", " << d_cw << ")" << endl;
            if(d_cw >= d_ccw){
                ans += d_cw;
                isBurned[d_cwitr] = true;
                now = d_cwitr;
            }
            else {
                ans += d_ccw;
                now = d_ccwitr;
                isBurned[d_ccwitr] = true;
            }
        }
        // cout << burned << " : " << ans << endl;
        burned++;
    }
    cout << ans << endl;
    return 0;
}

