const int maxn = 2005;
long long dp[3][maxn][maxn];

long long f(int cur, int left, int right, const vector<long long> &v, long long l) {
  if (left == right) {
    long long d = abs(v[cur] - v[left]);
    return max(d, l - d);
  }

  int dir;
  if (cur + 1 == left) {
    dir = 0;
  } else {
    dir = 1;
  }

  long long &ret = dp[dir][left][right];

  if (ret == -1) {
    long long a = f(left, left + 1, right, v, l);
    if (cur + 1 == left) {
      a += v[left] - v[cur];
      assert((v[left] - v[cur]) > 0);
    } else {
      a += l - v[cur] + v[left];
      assert((l - v[cur] + v[left]) > 0);
    }

    long long b = f(right, left, right - 1, v, l);
    if (cur - 1 == right) {
      b += v[cur] - v[right];
      assert((v[cur] - v[right]) > 0);
    } else {
      b += l - v[right] + v[cur];
      assert((l - v[right] + v[cur]) > 0);
    }

    ret = max(a, b);
  }

  return ret;
}

