ll solve(ll l, int n, vector<ll> &x){
  ll res = 0;
  vector<ll> acc = x; FOR(i, 1, n)acc[i] += acc[i-1];
  vector<ll> iacc(n);
  rep(i, n){
    iacc[i] = l - x[i];
    if(i > 0)iacc[i] += iacc[i-1];
  }
  int mid = (n + 1) / 2;
  ll tmp = acc[mid-1] * 2 + (iacc[n-1] - iacc[mid-1]) * 2;
  if(n % 2 == 0)tmp -= (l - x[mid]);
  else tmp -= x[mid-1];
  chmax(res, tmp);
  chmax(res, x.back());

  for(int i = 1; i < n; i++){
    tmp = 0;
    mid = (n - i + 1) / 2;
    tmp += (acc[i+mid-1] - acc[i-1]) * 2;
    tmp += (iacc[n-1] - iacc[i+mid-1]) * 2;
    if((n - i) % 2 == 0)tmp -= l - x[i+mid];
    else tmp -= x[i+mid-1];
    chmax(res, tmp);
  }
  return res;
}

