    int ok = 0, ng = N + 1;
    while (ng - ok > 2000) {
        int mid1 = (ok * 2 + ng) / 3;
        int mid2 = (ok + ng * 2) / 3;
        if (count(mid1) < count(mid2)) ok = mid1;
        else                           ng = mid2;
    }
    ll ans = 0;
    FOR(i, ok, ng) ans = max(count(i), ans);
    REP(i, 100) ans = max(count(i), ans);
    FOR(i, N - 100, N + 1) ans = max(count(i), ans);
    cout << ans << endl;
    return 0;
}

