ll L;

ll CalDist(ll prev, ll next, bool dir) {
  // dir==true で反時計回り
  ll ans = 0;
  if (dir == true) {
    if (prev < next) {
      ans = next - prev;
    } else {
      ans = L - prev + next;
    }
  } else {
    if (prev < next) {
      ans = prev + L - next;
    } else {
      ans = prev - next;
    }
  }
  return ans;
}

ll questAns = 0;

void Cal(vector<ll> X, ll curPos, ll lIndex, ll rIndex, ll tempAns) {
  ll right, left;
  left = CalDist(curPos, X[lIndex], true);
  right = CalDist(curPos, X[rIndex], false);
  // cout << left << ' ' << right << endl;

  if (lIndex <= rIndex) {
    Cal(X, X[lIndex], lIndex + 1, rIndex, tempAns + left);
    Cal(X, X[rIndex], lIndex, rIndex - 1, tempAns + right);
  } else {
    questAns = max(questAns, tempAns);
    // cout << tempAns << endl;
  }
}

