	int out=0;
	rep(i,n+1){
		if(i<=n-i){
			cmax(out,2*(x[i]+y[n-i]-y[n-i-i])-in[i]);
			cmax(out,2*(x[i]+y[n-i]-y[n-i-i-1])-(l-in[i+1]));
		}else{
			cmax(out,2*(x[i]+y[n-i]-x[i-n+i])-(l-in[i+1]));
			cmax(out,2*(x[i]+y[n-i]-x[i-n+i-1])-in[i]);
		}

	}
	cout<<out<<endl;
}

