int l, n;
int xl[200001] = {};
int xr[200001] = {};

long f(int current_i, int next_il, int next_ir) {

    long ans = 0;

    if (next_il > next_ir) return ans;

    long dist_l;
    if (next_il > current_i) {
        dist_l = xl[next_il] - xl[current_i];
    } else {
        dist_l = xl[next_il] + xr[current_i];
    }

    long dist_r;
    if (next_ir > current_i) {
        dist_r = xl[current_i] + xr[next_ir];
    } else {
        dist_r = xr[next_ir] - xr[current_i];
    }

    //cout << current_i << " " << dist_l << " " << dist_r << endl;

    if (dist_l > dist_r) {
        ans += dist_l;
        ans += f(next_il, next_il + 1, next_ir);
    } else if (dist_l < dist_r) {
        ans += dist_r;
        ans += f(next_ir, next_il, next_ir - 1);
    } else {
        long a = f(next_il, next_il + 1, next_ir);
        long b = f(next_ir, next_il, next_ir - 1);

        if (a > b) {
            ans += dist_l;
            ans += f(next_il, next_il + 1, next_ir);
        } else {
            ans += dist_r;
            ans += f(next_ir, next_il, next_ir - 1);
        }
    }

    return ans;
}

