LL dp[2000][2000][2] = {};

void solve() {
    REP(i,0,2000) REP(j,0,2000) dp[i][j][0] = dp[i][j][1] = -INF;
    LL ll,n;
    cin >> ll >> n;
    if (n > 2000) return; // tmp
    VLL x(n), rx(n);
    REP(i,0,n) cin >> x[i];
    REP(i,0,n) rx[i] = ll - x[i];
    if (n == 1) {
        cout << max(x[0], rx[0]);
        return;
    }

    dp[1][n-1][0] = x[0];
    dp[0][n-2][1] = rx[n-1];
    RREP(i,1,n-1) {
        REP(j,0,n) {
            if (i + j >= n) break;
            /*
            if (i == 1) {
                dp[j][i+j-1][1] = max(dp[j][i+j-1][1], dp[j][i+j][1] + ll - (x[i+j] - x[i+j-1]));
                dp[j+1][i+j][0] = max(dp[j+1][i+j][0], dp[j][i+j][0] + ll - (x[j+1] - x[j]));
                dp[j][i+j-1][1] = max(dp[j][i+j-1][1], dp[j][i+j][0] + ll - (x[j-1] + ll - x[i+j-1]));
                dp[j+1][i+j][0] = max(dp[j+1][i+j][0], dp[j][i+j][1] + ll - (ll - x[j+1] + x[j]));
            }
            */
            if (i + j + 1 != n) dp[j][i+j-1][1] = max(dp[j][i+j-1][1], dp[j][i+j][1] + x[i+j+1] - x[i+j]);
            else dp[j][i+j-1][1] = max(dp[j][i+j-1][1], dp[j][i+j][1] + x[0] + rx[i+j]);
            if (j != 0) dp[j+1][i+j][0] = max(dp[j+1][i+j][0], dp[j][i+j][0] + x[j] - x[j-1]);
            else dp[j+1][i+j][0] = max(dp[j+1][i+j][0], dp[j][i+j][0] + x[j] - rx[n-1]);
            if (dp[j][i+j][0] != -INF) dp[j][i+j-1][1] = max(dp[j][i+j-1][1], dp[j][i+j][0] + x[j-1] + rx[i+j]);
            if (dp[j][i+j][1] != -INF) dp[j+1][i+j][0] = max(dp[j+1][i+j][0], dp[j][i+j][1] + rx[i+j+1] + x[j]);
        }
    }
    LL ans = 0;
    REP(i,0,n) {
        int j = i;
        ans = max(ans, dp[i][j][0] + max(abs(x[i] - x[(i-1+n)%n]), ll - abs(x[i] - x[(i-1+n)%n])));
        //dump(ans);
        ans = max(ans, dp[i][j][1] + max(abs(x[i] - x[(j+1)%n]), ll - abs(x[i] - x[(j+1)%n])));
        //dump(ans);
    }
    cout << ans << endl;
    /*
    REP(i,0,n) {
        REP(j,0,n) cout << dp[i][j][0] << "," << dp[i][j][1] << " ";
        cout << endl;
    }
    */
}

int main() {
    solve();

    return 0;
}

