ll dp[2001][2001][2]; // (反時計回りにどこまで訪れたか, 時計回りにどこまで訪れたか, 現在の位置) 
// pos 0: ccw, 1: cw
ll dist(int ccw, int cw, int pos) {
	//dump(ccw, cw, pos);
	if (ccw == 0 && pos == 0) return INT64_MIN;
	if (cw % N == 0 && pos == 1) return INT64_MIN;
	if (dp[ccw][cw][pos] != INT64_MIN) return dp[ccw][cw][pos];
	if (pos == 0) {
		// ccw
		dp[ccw][cw][pos] = max({
			dist(ccw - 1, cw, 0) + X[ccw] - X[ccw - 1],
			dist(ccw - 1, cw, 1) + X[ccw] + (L - X[cw])
			});
	}
	else {
		dp[ccw][cw][pos] = max({
			dist(ccw, cw == N ? 0 : cw + 1, 0) + X[ccw] + (L - X[cw]),
			dist(ccw, cw == N ? 0 : cw + 1, 1) + ((cw == N ? L : X[cw + 1]) - X[cw])
			});
	}
	//dump(ccw, cw, pos, dp[ccw][cw][pos]);
	return dp[ccw][cw][pos];
}

