ll dok(int v)
{
	//~ if (v>n)
		//~ return 0;
	ll ret=sum[n]-sum[v-1];
	return (n+1-v)*l-ret;
}

int main()
{
	scanf("%lld%d", &l, &n);
	for (int i=1; i<=n; i++)
		scanf("%lld", &tab[i]);
