typedef long long ll;

const int MAXN = 5e5+5;

ll n, l, d[MAXN], part[MAXN], up[MAXN];

ll s(int i, int j) {
	return part[j+1] - part[i];
}

ll up1(int i, int j) {
	return 2*(up[j+1] - up[i]) - (2*i+1)*s(i, j);
}

ll up2(int i, int j) {
	return up1(i, j) + s(i, j);
}

ll down1(int i, int j) {
	return (2*(j-i)+2)*s(i, j) - up1(i, j);
}

ll down2(int i, int j) {
	return down1(i, j) + s(i, j);
}

int main() {
	ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);

	cin >> l >> n;
	for (int i = 0; i < n; ++i)
		cin >> d[i];
	n++;
	d[n-1] = l - d[n-2];
	for (int i = n-2; i >= 0; --i)
		d[i] -= d[i-1];
	for (int i = n; i < 2*n; ++i)
		d[i] = d[i-n];
	part[0] = 0;
	for (int i = 1; i <= 2*n; ++i)
		part[i] = d[i-1] + part[i-1];
	up[0] = 0;
	for (int i = 1; i <= 2*n; ++i)
		up[i] = i*d[i-1] + up[i-1];
	ll ans = 0;
	// cout << s(1, 3) << endl;
	for (int i = 0; i < n; ++i) {
		if (i == n-i-1) {
			ans = max(ans, up2(i+1, n-1)+down1(0, i-1));
			ans = max(ans, up1(i+1, n-1)+down2(0, i-1));
		} if (i > n-i-1) {
			ans = max(ans, up2(i+1, n-1) + down1(2*i-n+1, i-1) + (2*(n-i-1)+1)*s(0, 2*i-n));
			ans = max(ans, up1(i+1, n-1) + down2(2*i-n+1, i-1) + (2*(n-i-1))*s(0, 2*i-n));
		} if (i < n-i-1) {
			ans = max(ans, down2(0, i-1) + up1(i+1, 2*i) + (2*i+1)*s(2*i+1, n-1));
			ans = max(ans, down1(0, i-1) + up2(i+1, 2*i) + (2*i)*s(2*i+1, n-1));
		}
		// cout << ans << endl;
	}

	cout << ans << endl;
}

