long long dp(int i, int j, int l){
  if(i+1 == j){
    return 0;
  }

  if(memo[i][j][l] != -1){
    return memo[i][j][l];
  }

  if(l == 0){
    return memo[i][j][l] = max(dp(i+1, j, 1) + x[i+1], dp(i, j-1, 2) + L-x[j-1]);
  }

  if(l == 1){
    return memo[i][j][l] = max(dp(i+1, j, 1) - x[i] + x[i+1], dp(i, j-1, 2) + x[i] + L - x[j-1]);
  }

  if(l == 2){
    return memo[i][j][l] = max(dp(i+1, j, 1) + L-x[j]+x[i+1], dp(i, j-1, 2) + x[j]-x[j-1]);
  }
}

