void work ()
{
	// main work

	lpi ( i, 1, n ) ps[i] = ps[i - 1] + a[i];

	lpi ( i, 1, n ) ra[i] = L - a[n - i + 1];
	lpi ( i, 1, n ) rps[i] = rps[i - 1] + ra[i];

	a[0] = 0, a[n + 1] = L;
	LL ans = 0, cur;
	lpi ( i, 0, n ) {
		int cl = i, cr = n - i;
		cur = 0;
		if ( cl >= cr ) cur = getans ( ra, rps, cr, cl );
		else cur = getans ( a, ps, cl, cr );
		ans = qmax ( ans, cur );
	}

	cout << ans << endl;
}



LL getans ( int a[], LL ps[], int cl, int cr )
{
	int d = cr - cl;
	LL cur1 = ( ps[cr] - ps[d] + SC ( LL, cl ) * L - ( ps[n] - ps[n - cl] ) ) * 2 - ( L - a[n - cl + 1] );
	LL cur2 = ( ps[cr] - ( d ? ps[d - 1] : 0 ) + SC ( LL, cl ) * L - ( ps[n] - ps[n - cl] ) ) * 2 - a[cr];
	return qmax ( cur1, cur2 );
}

