LL solve()
{
    LL res=0,ans=0;
    LL tmp=n,dir=1;
    int now=1;
    while (tmp--)
    {
        res+=d[now]*tmp;
        now=now+tmp*dir;
        dir=-dir;
    }
    ans=res;
    LL sum=0;for (int i=1;i<=n;i++) sum+=d[i];
    int cnt=n;
    LL offset=0;for (int i=1;i<=cnt/2;i++) offset+=d[i];
    //printf("%lld\n",res);
    for (int i=1;i<n-1;i++)
    {
        offset-=d[i];
        res=res-sum+2*offset;
        cnt--;
        if (cnt%2==0)
        {
            res+=2*d[i+cnt/2];
            offset+=d[i+cnt/2];
        }
        else res+=d[i+cnt/2+1];
        //printf("%lld\n",res);
        ans=max(ans,res);
    }
    return ans;
}

