void solve() {
    cin >> L >> N;
    for (int i = 1; i <= N; ++i) {
        cin >> X[i];
    }
    for (int i = 1; i <= N; ++i) {
        XL[i] = XL[i - 1] + X[i];
    }
    for (int i = N; i >= 1; --i) {
        XR[i] = XR[i + 1] + L - X[i];
    }

    ll result = 0;
    for (int x = 0; x <= N; ++x) {
        ll sum = 0;
