// x -> y
ll dis(int dir, int x, int y) {
  if (dir == 0) {
    // 時計回り
    if (x < y) {
      return L - (y - x);
    } else {
      return (x - y);
    }
  } else {
    if (x < y) {
      return (y - x);
    } else {
      return L - (x - y);
    }
  }
}

// leftとrightをえらべる
ll rec(int left, int right, int cur, ll dist) {
  if (left == right) {
    // X[left]にいきたい
    return dist + max(dis(0,cur,X[left]), dis(1,cur,X[left]));
  }
  ll res = rec(left + 1, right, X[left], dist + dis(1,cur,X[left]));
  chmax(res, rec(left, right - 1, X[right], dist + dis(0,cur,X[right])));
  return res;
}

