typedef long long LL;

LL counter_clockwise_start(int l, int n, const std::vector<LL>& x, int i) {
  LL walk = 0;
  int mid=(i+n)/2;

  if ((i+n)%2 != 0) {
    for (int j = i; j <= mid; ++j) walk += 2*x[j];
    for (int j = n; j > mid+1; --j) walk += 2*(l-x[j]);
    walk += l-x[mid+1];
    return walk;
  } else {
    for (int j = i; j < mid; ++j) walk += 2*x[j];
    for (int j = n; j >= mid+1; --j) walk += 2*(l-x[j]);
    walk += x[mid];
    return walk;
  }
}

LL clockwise_start(int l, int n, const std::vector<LL>& x, int i) {
  LL walk = 0;
  int mid=(i+1)/2;

  if (i%2 != 0) {
    for (int j = i; j > mid; --j) walk += 2*(l-x[j]);
    for (int j = 1; j < mid; ++j) walk += 2*x[j];
    walk += l-x[mid];
    return walk;
  } else {
    for (int j = i; j > mid; --j) walk += 2*(l-x[j]);
    for (int j = 1; j < mid; ++j) walk += 2*x[j];
    walk += x[mid];
    return walk;
  }
}

int main() {
  int l, n; std::cin >> l >> n;
  std::vector<LL> x(n+1);
  for (int i = 1; i <= n; ++i) std::cin >> x[i];

  LL ans = 0;
  for (int i = 1; i <= n; ++i) {
    ans = std::max(ans, counter_clockwise_start(l, n, x, i));
    ans = std::max(ans, clockwise_start(l, n, x, i));
  }
  std::cout << ans << std::endl;
}

