            f[t+1][j][1]=max(f[t+1][j][1],f[t][i][0]+a[i]+l-a[j]);
            f[t+1][i+1][0]=max(f[t+1][i+1][0],f[t][i][0]+a[i+1]-a[i]);
        }
        else
        {
            int j=t-n+i;
            f[t+1][j][0]=max(f[t+1][j][0],f[t][i][1]+a[j]+l-a[i]);
            f[t+1][i-1][1]=max(f[t+1][i-1][1],f[t][i][1]+a[i]-a[i-1]);
        }
    }
    for(int i=0;i<=n;++i) kq=max({kq,f[n][i][0],f[n][i][1]});
    cout<<kq;
}

