int go(int m , int l , int r , int id , int pos){
   if(id == 0){
      if(l < 0)
         return L - x[pos];
      return L - (x[pos] - x[l]) + go(m , l - 1 , r , 1 - id , l);
   }
   else{
      if(r == n)
         return x[pos];
      return L - (x[r] - x[pos]) + go(m , l , r + 1 , 1 - id , r);
   }
}

int check(int m){
   int l = m - 1 , r = m + 1;
   return max(go(m , l , r , 0 , m) , go(m , l , r , 1 , m));
}

