long long f(int now, vector<int> x) {
	int r = 1;
	for (;;r++) {
		if (now + r == n+1) r = 0 - now;
		if (x[now + r] != -1) break;
	}
	int l = 1;
	for (;;l++) {
		if (now - l == -1) l = -n + now;
		if (x[now - l] != -1) break;
	}

	if (now - l == now + r) {
		long long ans1, ans2;
		if (now < now - l) {
			ans1 = L - (x[now - l] - x[now]);
		}
		else {
			ans1 = x[now] - x[now - 1];
		}

		if (now + r > now) {
			ans2 = x[now + r] - x[now];
		}
		else {
			ans2 = L - x[now] + x[now + r];
		}

		return max(ans1, ans2);

	}

	int tmp = x[now];
	x[now] = -1;
	long long ans1 = f(now - l, x);
	long long ans2 = f(now + r, x);
	x[now] = tmp;
	if (now < now - l) {
		ans1 += L - (x[now - l] - x[now]);
	}
	else {
		ans1 += x[now] - x[now - 1];
	}

	if (now + r > now) {
		ans2 += x[now + r] - x[now];
	}
	else {
		ans2 += L - x[now] + x[now + r];
	}
	return max(ans1, ans2);

}

