long long L, n;

long long S(int l, int r){
	long long res = pre[r];
	if(l != 0) res -= pre[l - 1];
	return res;
}

long long solve(){
	long long ans = 0;
	pre[0] = arr[0];
	for(int i = 1;i < n;i++){
		pre[i] = pre[i-1] + arr[i];
	}

	for(long long cut = 0;cut < n;cut++){

		long long res = arr[cut];
		int dis = (n - cut) / 2;

		long long O = 0;
		O += 2LL * S(n - dis, n-1);
		O -= S(cut, cut + dis - 1);
		O -= S(cut + 1, cut + dis); 
		O = (n - cut - 1) * L - O;
		res += O;

		ans = max(ans, res);
		//cout << dis << " " << res << "\n";
	}


	return ans;
}
