ll memo[2020][2020][3];
ll f(int L, int R, int cur) {
    if (0 <= memo[L][R][cur]) return memo[L][R][cur];

    int x;

    if (cur == 0) x = 0;
    else if (cur == 1) x = X[L - 1];
    else x = X[R + 1];

    if (L == R) return memo[L][R][cur] = max(abs(x - X[L]), LL - abs(x - X[L]));

    ll res = -1;

    // 反時計回り
    if (x < X[L]) chmax(res, X[L] - x + f(L + 1, R, 1));
    else chmax(res, LL - x + X[L] + f(L + 1, R, 1));

    // 時計回り
    if(x < X[R]) chmax(res, x + LL - X[R] + f(L, R - 1, 2));
    else chmax(res, x - X[R] + f(L, R - 1, 2));

    return memo[L][R][cur] = res;
}
