int* GetHanToKeiList(int* Trees, const int& iN, int& iMove)
{
	int N1 = iN - 1;
	int* Tree1 = new  int[N1];
	int Cnt = 0;
	while (Cnt < N1)
	{
		Tree1[Cnt] = Trees[Cnt] + iMove;
		Cnt++;
	}
	return Tree1;
}

int* GetToKeiList(int* Trees, const int& iN)
{
	int N1 = iN - 1;
	int* Tree1 = new  int[N1];
	int Cnt = 1;
	while (Cnt < iN)
	{
		Tree1[Cnt - 1] = Trees[Cnt] - Trees[0];
		Cnt++;
	}
	return Tree1;
}

int GetMoveDistance(int* Trees,const int& iN,int& L)
{
	//時計 
	int tokei = Trees[0];
	if (iN>1)
	{ 
		int* Tree1 = GetToKeiList(Trees, iN);
		int N1 = iN - 1;
		tokei += GetMoveDistance(Tree1, N1,L);
		delete[] Tree1;
	}
	int hantokei = L - Trees[iN - 1];
	if (iN > 1)
	{
		int* Tree1 = GetHanToKeiList(Trees, iN, hantokei);
		int N1 = iN - 1;
		hantokei  += GetMoveDistance(Tree1, N1, L);
		delete[] Tree1;
	}
	return tokei > hantokei ? tokei : hantokei;
}

