	//repn(i, N) cout << c[i] <<" "<< lc[i] << endl;

	ll ans = 0;

	repn(i, N) {
		ll d = min(i - 1, N - i);
		ll v = c[i - 1] - c[i - 1 - d] + lc[i + d] - lc[i];
		v += max(X[i], L - X[i]);

		ll w = 0;
		if (i - 1 < N - i) {
			w = c[i - 1] - c[i - 1 - d] + lc[i + d + 1] - lc[i];
			w += X[i];
		}
		if (i - 1 > N - i) {
			w = c[i - 1] - c[i - 1 - d - 1] + lc[i + d] - lc[i];
			w += L - X[i];
		}

		v = max(v, w);

		//cout << i << " " << v << endl;

		ans = max(ans, v);
	}

	cout << ans;

	system("PAUSE");
}

