      val[i] = 0;
  }

  void add(int x, int y) {
    for(; x <= n; x += -x & x) {
      val[x] += y;
    }
  }

  long long Query(int x, int y) {
    x--;
    long long ans = 0;
    if(x >= y) {
      return 0;
    }
    for(; x; x -= -x & x) {
      ans -= val[x];
    }
    for(; y; y -= -y & y) {
      ans += val[y];
    }
    ans *= 2;
    return ans;
  }
