const int MAXN = 2e5 + 10;

ll L, X[MAXN], F[2][MAXN], ans = 0;
int N;

ll f(int h, int k) {
    if (F[h][k] != -1) return F[h][k];
    set<ll> T;
    FOR(i, N) {
        T.insert(X[i]);
        T.insert(L + X[i]);
        T.insert(2 * L + X[i]);
    }
    ll cur = L, tot = 0; bool isB = false;
    FOR(i, N) {
        auto it = T.upper_bound(cur);
        ll a = *it, b = *prev(it);
        if (a == b) {
            b = (b % L) + L;
            it = T.lower_bound(b);
            b = *prev(it);
        }
        if (i < k) isB = h == 1;
        if (isB) a = b;
        tot += abs(cur - a);
        a %= L;
        cur = L + a;
        T.erase(a);
        T.erase(L + a);
        T.erase(2 * L + a);
        isB = !isB;
    }
    MAX(ans, tot);
    return F[h][k] = tot;
}

int main() {
    // setInput("in.txt");
    // setOutput("out.txt");
    // setError("err.txt");
    read(L, N);
    read(X, X + N);
    FOR(h, 2) FOR(k, N + 5) F[h][k] = -1;
    FOR(h, 2) {
        int lo = 0, hi = N + 2, mid;
        while (lo < hi) {
            mid = lo + (hi - lo) / 2;
            if (f(h, mid) > f(h, mid + 1)) hi = mid;
            else lo = mid + 1;
        }
        For(k, lo - 100, lo + 100) f(h, k);
    }
    writeln(ans);
    return 0;
}

