    vector<ll> suma(n+1), sumb(n+1);
    rep(i,0,n) {
        suma[i+1]=suma[i]+a[i];
        sumb[i+1]=sumb[i]+b[i];
    }
    ll ans = 0;
    rep(i,0,n+1) {
        int k = min(i,n-i);
        ll suml = suma[i]-suma[i-k];
        ll sumr = sumb[i+k]-sumb[i];
        ll can1 = 2*(suml+sumr);
        if(i-1>=0) can1-=a[i-1];
        ll can2 = 2*(suml+sumr);
        if(i<n) can2-=b[i];
        if(i-k-1>=0) can1+=2*a[i-k-1];
        if(i+k<n) can2+=2*b[i+k];
        ans=max(ans,max(can1,can2));
        // debug(ans);
        // debug(i);
    }
    cout<<ans<<"\n";
}

#include <bits/stdc++.h>
using namespace std;

typedef long long llt;

const int MaxN = 2000 + 5;

int L, N;
llt X[MaxN];
llt dp[MaxN][MaxN][2];

void init() {
  scanf("%d %d", &L, &N);
  for (int i = 1; i <= N; ++i)
    scanf("%lld", &X[i]);
  X[N + 1] = 1ll * L;
}

inline void update(llt &x, llt v) {
  x = max(x, v);
}

void solve() {
  llt ans = 0;

  for (int i = 1; i <= N; ++i) {
    for (int j = 1; j <= i; ++j) {
      dp[i][j][0] = dp[i - 1][j - 1][0] + X[j] - X[j - 1];
      if (j != i) update(dp[i][j][0], dp[i - 1][j - 1][1] + L - X[N - i + j + 1] + X[j]);
      update(ans, dp[i][j][0]);
    }
    for (int j = 0; j < i; ++j) {
      dp[i][j][1] = dp[i - 1][j][1] + X[N - i + j + 2] - X[N - i + j + 1];
      if (j != 0) update(dp[i][j][1], dp[i - 1][j][0] + L - X[N - i + j + 1] + X[j]);
      update(ans, dp[i][j][1]);
    }
  }

  cout << ans << endl;
}

int main() {
  init();
  solve();
  return 0;
}

