ll dfs(ll l, ll r, ll pos){
    if(dp[l][r][pos] >= 0) return dp[l][r][pos];
    ll res = 0;
    if((l + 1) % N == r) {
        res = 0;
    }
    else{
        // to l 
        {
            if(pos == 0){
                res = max(res, dfs(l + 1, r, 0) + (X[l+1] - X[l]));
            }
            else if(pos == 1){
                res = max(res, dfs(l + 1, r, 0) + (X[l+1] + (L - X[r])));
            }
        }
        // to r
        {
            if(pos == 1){
                res = max(res, dfs(l, (r - 1 + N) % N, 1) + (X[r] - X[(r - 1 + N) % N]));
            }
            else if(pos == 0){
                res = max(res, dfs(l, (r - 1 + N) % N, 1) + (X[l] + (L - X[(r - 1 + N) % N])));
            }
        }
    }
    return dp[l][r][pos] = res;
}

