inline ll getpre_seg(int ql,int qr){return s2[qr]-s2[ql]-(s[qr]-s[ql])*(n-qr);}
inline ll getsuf(int x){return t2[x]-t[x]*(x-1);}
inline ll getsuf_seg(int ql,int qr){return t2[ql]-t2[qr]-(t[ql]-t[qr])*(ql-1);}
int main(){
	cin>>l>>n;
	x[0]=0;
	for(int i=1;i<=n;++i)scanf("%d",&x[i]),s[i]=s[i-1]+x[i]-x[i-1],s2[i]=s2[i-1]+1ll*(n-i+1)*(x[i]-x[i-1]);
	x[n+1]=l;
