			ans=max(ans,getpre(l)*2+getsuf_seg(l+1,l*2+2)*2-(t[l+1]-t[l*2+2])+t[l*2+2]*(l*2+1));
			ans=max(ans,getpre(l)*2-s[l]+getsuf_seg(l+1,l*2+1)*2+t[l*2+1]*l*2);
