// L <= pos and pos < 2*L
int solve(set<int> &S, int pos, int dir, int cnt=0, int sum=0) {
    if(cnt == N) {
        // fprintf(stderr, "sum = %lld\n", sum);
        return sum;
    }

    // fprintf(stderr, "cnt = %lld, pos = %lld\n", cnt, pos);
    int orig = pos;
    set<int>::iterator itr;
    if(dir == LEFT) {
        itr = S.lower_bound(pos);
    }
    if(dir == RIGHT) {
        itr = --S.lower_bound(pos);
    }

    pos = orig;
    int npos = normalize(*itr);
    int cost = -1;
    if(dir == LEFT ) {
        if(pos < npos) cost = (npos - pos) % L;
        else cost = (L - (pos - npos) % L);
    }
    if(dir == RIGHT) {
        if(npos < pos) cost = (pos - npos) % L;
        else cost = (L - (npos - pos) % L);
    }
    // fprintf(stderr, "*itr = %lld, pos = %lld, npos = %lld, cost = %lld\n", *itr, pos, npos, cost);

    S.erase(npos - L);
    S.erase(npos);
    S.erase(npos + L);
    int res = solve(S, npos, 1 - dir, cnt + 1, sum + cost);
    S.insert(npos - L);
    S.insert(npos);
    S.insert(npos + L);
    return res;
}

signed main() {
    cin >> L >> N;
    if(N >= 2010) {
        return 1;
    }

    set<int> S;
    for(int i=0; i<N; i++) {
        cin >> X[i];

        // 二周ぶん
        S.insert(X[i]);
        S.insert(X[i] + L);
        S.insert(X[i] + 2 * L);
    }
    set<int> T = S;

    int ans = max(solve(S, L, LEFT), solve(S, L, RIGHT)), tmp_sum = 0;
    for(int i=0; i<N; i++) {
        tmp_sum += (i == 0 ? X[i] : X[i] - X[i-1]);
        S.erase(X[i]);
        S.erase(X[i] + L);
        S.erase(X[i] + 2*L);
        int tmp_ans = max(solve(S, X[i] + L, LEFT, i+1), solve(S, X[i] + L, RIGHT, i+1)) + tmp_sum;
        chmax(ans, tmp_ans);
    }

    tmp_sum = 0;
    for(int i=N-1; i>=0; i--) {
        int itr = N - i;
        tmp_sum += (i == N-1 ? L - X[i] : X[i+1] - X[i]);
        T.erase(X[i]);
        T.erase(X[i] + L);
        T.erase(X[i] + 2*L);
        int tmp_ans = max(solve(T, X[i] + L, LEFT, itr), solve(T, X[i] + L, RIGHT, itr)) + tmp_sum;
        chmax(ans, tmp_ans);
    }
    cout << ans << endl;
    return 0;
}

