int N;
LL L;
LL A[200000];

LL linear(int l, int r) {
	int cnt = 0;
	LL sum = 0;
	REP(i, l, r) {
		sum += cnt * (A[i + 1] - A[i]);
		++cnt;
	}
	return sum;
}

LL constant(int l, int r) {
	return A[r] - A[l];
}

LL sub(int st) {
	int l = st;
	int r = N - 1 - st;

	LL mx = 0;
	if (l <= r) {
		int be = 0;
		int en = 2 * st;
		int h = en - be;
		LL diff = 0;
		diff += 2 * linear(be, st) + constant(be, st);
		diff += h * constant(st, en) - 2 * linear(st, en);
		LL sum = h * L - diff;
		sum += A[be];
		if (en < N - 1) sum += 2 * (L - A[en + 1]);
		mx = max(mx, sum);
	} else {
		int en = N - 1;
		int be = en - 2 * (en - st);
		int h = en - be;
		LL diff = 0;
		diff += 2 * linear(be, st) + constant(be, st);
		diff += h * constant(st, en) - 2 * linear(st, en);
		LL sum = h * L - diff;
		sum += A[be];
		mx = max(mx, sum);
	}

	return mx;
}

int main() {
	cin >> L >> N;
	if (N > 2000) {
		throw 1;
	}
	REP(i, 0, N) cin >> A[i];

	LL mx = 0;
	REP(i, 0, N) mx = max(mx, sub(i));
	reverse(A, A + N);
	REP(i, 0, N) A[i] = L - A[i];
	REP(i, 0, N) mx = max(mx, sub(i));
	cout << mx << endl;
	return 0;
}

#include <iostream>
