using lint = long long;

int main() {
    lint L;
    int N;
    std::cin >> L >> N;

    std::vector<lint> A(N);
    for (auto& a : A) std::cin >> a;

    std::vector<lint> presum(N + 1, 0);
    for (int i = 0; i < N; ++i) presum[i + 1] = presum[i] + A[i];

    // Aを左右反転させたもの
    auto B = A;
    std::reverse(B.begin(), B.end());
    for (auto& b : B) b = L - b;

    std::vector<lint> sufsum(N + 1, 0);
    for (int i = 0; i < N; ++i) sufsum[i + 1] = sufsum[i] + B[i];

    lint ans = 0;

    // 右に移動して終わるケース
    for (int r = 1; r <= N; ++r) {
        // r個の区間に右から入る
        int l = N - r;
        int step = std::min(l, r);  // 「階段」の段数

        lint left = (sufsum[l] - sufsum[l - step]) * 2;
        lint right = (presum[r] - presum[r - step]) * 2 - A[r - 1];
        if (r > l) right += (presum[r - step] - presum[r - step - 1]) * 2;
        // 右側の階段が1段増える

        ans = std::max(ans, left + right);
    }

    // 左から終わるケース
    // さっきのを全体を左右反転させてやるだけ
    for (int r = 1; r <= N; ++r) {
        int l = N - r;
        int step = std::min(l, r);

        lint left = (presum[l] - presum[l - step]) * 2;
        lint right = (sufsum[r] - sufsum[r - step]) * 2 - B[r - 1];
        if (r > l) right += (sufsum[r - step] - sufsum[r - step - 1]) * 2;

        ans = std::max(ans, left + right);
    }

    std::cout << ans << std::endl;
    return 0;
}

