#include <bits/stdc++.h>

using namespace std;

using ite_t = vector<int64_t>::iterator;

static int64_t l;
static int64_t n;
static std::vector<int64_t> xs;

int64_t solve_one(const ite_t& low, const ite_t& high, const ite_t& current) {
  if (low == xs.begin() && high == xs.end() - 1) {
    if (current == low) {
      return *low;
    }
    return l - *high;
  }

  if (low == xs.begin() && current == low) {
    ite_t const nextHigh = high + 1;
    return solve_one(low, nextHigh, nextHigh) + (*low + (l - *nextHigh));
  }

  if (low == xs.begin() && current == high) {
    return l - *high;
  }

  if (high == xs.end() - 1 && current == high) {
    ite_t const nextLow = low - 1;
    return solve_one(nextLow, high, nextLow) + (*nextLow + (l - *high));
  }

  if (high == xs.end() - 1 && current == low) {
    return *low;
  }

  int64_t ret1;
  int64_t ret2;
  if (current == low) {
    ite_t const nextLow = low - 1;
    ret1 = solve_one(nextLow, high, nextLow) + (*low - *nextLow);
    ite_t const nextHigh = high + 1;
    ret2 = solve_one(low, nextHigh, nextHigh) + (*low + (l - *nextHigh));
  } else {
    ite_t const nextLow = low - 1;
    ret1 = solve_one(nextLow, high, nextLow) + (*nextLow + (l - *high));
    ite_t const nextHigh = high + 1;
    ret2 = solve_one(low, nextHigh, nextHigh) + (*nextHigh - *high);
  }

  return std::max(ret1, ret2);
}

int64_t solve() {
  int64_t ret = 0;
  for (ite_t low = xs.begin(); low != xs.end() - 1; ++low) {
    ite_t const high = low + 1;
    int64_t const diff = std::max(*high - *low, *low - *high + l);
    auto const ret1 = solve_one(low, high, low) + diff;
    ret = std::max(ret1, ret);
    auto const ret2 = solve_one(low, high, high) + diff;
    ret = std::max(ret2, ret);
  }
  return ret;
}

int main() {
  std::cin.tie(nullptr);
  std::ios::sync_with_stdio(false);
  std::cin >> l >> n;
  xs.resize(n);
  for (auto& x : xs) {
    std::cin >> x;
  }
  std::cout << solve() << std::endl;
  return 0;
}

