const int INF = 1 << 29;

auto solve() {
    ll L, N;
    cin >> L >> N;
    vi x(N);
    for (auto &&e: x) cin >> e;

    sort(all(x));

    auto calc_r_dist = [&](ll c, ll goal) -> ll {
        return (c - goal + L) % L;
    };
    auto calc_l_dist = [&](ll c, ll goal) -> ll {
        return (goal - c + L) % L;
    };

    ll mres = 0;
    for (int _t = 0; _t < N; ++_t) {
        deque<ll> deq;
        for (auto &&e: x) deq.push_back(e);

        int rem = _t * 2;
        int cut_l = 0, cut_r = 0;
        if (rem >= N) {
            cut_l = rem - N;
        } else {
            cut_r = N - rem;
        }

        ll c = 0;
        ll res = 0;
        for (int i = 0; i < cut_l; ++i) {
            ll fr = deq.front();
            res += calc_l_dist(c, fr);
            c = fr;
            deq.pop_front();
        }
        for (int i = 0; i < cut_r; ++i) {
            ll fr = deq.back();
            res += calc_r_dist(c, fr);
            c = fr;
            deq.pop_back();
        }

        bool go_l = false;
        if(!deq.empty()){
            ll f = deq.front();
            ll b = deq.back();
            ll f_l = calc_l_dist(c, f);
            ll b_r = calc_r_dist(c, b);

            go_l = f_l >= b_r;
        }

        while (!deq.empty()) {
            if (go_l) {
                ll fr = deq.front();
                res += calc_l_dist(c, fr);
                c = fr;
                deq.pop_front();
            } else {
                ll fr = deq.back();
                res += calc_r_dist(c, fr);
                c = fr;
                deq.pop_back();
            }

            go_l = !go_l;
        }

        mres = max(mres, res);
    }


    return mres;
}


int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    cout << solve() << endl;
//    solve();
    return 0;
}

