ll L, N;

ll Sub(vll &X)
{
	vll accX(N+1);
	accX[0] = 0;
	REP(i, N) accX[i+1] = accX[i]+X[i];

	auto sumX = [&](ll i, ll j){
		return accX[j+1] - accX[i];
	};

	ll len;
	ll maxLen = 0;

	REPS(i, 0, N-3){
		ll m = (N-1+i)/2;
		if ((N-i)%2 == 1){
			len = L*(N-1-i) + 2*sumX(i, m-1) - 2*sumX(m+1, N-1) + X[m];
		} else{
			len = L*(N-1-i) + 2*sumX(i, m)   - 2*sumX(m+2, N-1) - X[m+1];
		}
		chmax(maxLen, len);
	}
	//i==N-2
	if (N >= 2){
		len = X[N-2] + L-(X[N-1]-X[N-2]);
		chmax(maxLen, len);
	}
	//i==N-1
	len = X[N-1];
	chmax(maxLen, len);

	return maxLen;
}

void solve()
{
	cin >> L >> N;
	vll X = cinv(N);
	vll Y = X;
	std::reverse(Y.begin(), Y.end());
	EACH(e, Y) e = L-e;
	ll ans = Sub(X);
	chmax(ans, Sub(Y));
	cout << ans << '\n';
}

int main(){
	solve();
	return 0;
}

