class BTreeBurning {
public:



    void solve(istream& cin, ostream& cout) {
        int L, N;
        cin >> L >> N;
        vector<int> X(N);
        cin >> X;
        vector<ll> P(N+1, 0);
        for (int i = 0; i < N; ++i) {
            P[i+1] = P[i] + X[i];
        }

        ll ans = 0;
        for (int i = 1; i <= N; ++i) {
            ll cur = 0;
            int left = (N-i)/2;
            int right = (N-i)-left;
            cur += 2 * (P[i+left] - P[i]);
            cur += 2 * ((ll(right) * L) - (P[N] - P[N-right]));
            cur -= L-X[i+left];
            ans = max(ans, cur);

            cur = 0;
            right = (N-i)/2;
            left = (N-i)-right;

            cur += 2 * (P[i+left] - P[i]);
            cur += 2 * ((ll(right) * L) - (P[N] - P[N-right]));
            cur -= L-X[i+left];
            ans = max(ans, cur);
        }

        for (int i = 1; i <= N; ++i) {
            ll cur = 0;
            int right = (N-i)/2;
            int left = (N-i)-right;
            cur += 2 * P[left];
            cur += 2 * ((ll(right) * L) - (P[N-i] - P[N-i-right]));
            cur -= X[left-1];
            ans = max(ans, cur);

            cur = 0;
            left = (N-i)/2;
            right = (N-i)-left;
            cur += 2 * P[left];
            cur += 2 * ((ll(right) * L) - (P[N-i] - P[N-i-right]));
            cur -= L - X[left];
            ans = max(ans, cur);
        }


        cout << ans << endl;
    }
};


int main() {
	ios_base::sync_with_stdio(false); cin.tie(nullptr); cout.tie(nullptr);
	BTreeBurning solver;
	std::istream& in(std::cin);
	std::ostream& out(std::cout);
	solver.solve(in, out);
    return 0;
}

