int recurse(int l, int r, int x)
{
	if(l<0 || r<0 || r>n || l>n) return 0;
	if(dp[l][r][x]!=-1) return dp[l][r][x];
	if(x==0)
	{
		dp[l][r][x]=recurse(l+1, r, 0)+arr[l]-arr[l-1];
		dp[l][r][x]=max(dp[l][r][x], recurse(l, r-1, 1)+arr[l-1]+L-arr[r]);
	//	cout << l << " " << r << " " << x << " - " << dp[l][r][x]/dv << endl;
		return dp[l][r][x];
	}
	dp[l][r][x]=recurse(l, r-1, 1)+arr[r+1]-arr[r];
	dp[l][r][x]=max(dp[l][r][x], recurse(l+1, r, 0)+L-arr[r+1]+arr[l]);
	//cout << l << " " << r << " " << x << " - " << dp[l][r][x]/dv << endl;
	return dp[l][r][x];
}
