using namespace std;

long max_route(long x[], long l, long n) {
    long b[n];
    b[n - 1] = x[n - 1];
    for (int i = n - 2; i >= 0; i--) {
        b[i] = b[i + 1] - x[n - 1 - ((n - 1 - i) >> 1)] + l - x[n - 1 - ((n - 2 - i) >> 1)] + (x[i] << 1);
    }
    return b[max_element(b, b + n) - b];
}

