#include <iostream>
#include <vector>
typedef long long LL;

LL counter_clockwise_start(int l, int n, const std::vector<LL>& x,
                           const std::vector<LL>& sums1, const std::vector<LL>& sums2,
                           int i) {
  int mid=(i+n)/2;
  LL walk = 2*(sums1[mid]-sums1[i-1]) + 2*sums2[mid+1];

  if ((i+n)%2 != 0) {
    walk -= l-x[mid+1];
  } else {
    walk -= x[mid];
  }

  return walk;
}

LL clockwise_start(int l, int n, const std::vector<LL>& x,
                   const std::vector<LL>& sums1, const std::vector<LL>& sums2,
                   int i) {
  int mid=(i+1)/2;
  LL walk = 2*(sums2[mid+1]-sums2[i+1]) + 2*sums1[mid-1];

  if (i%2 != 0) {
    walk += l-x[mid];
  } else {
    walk += x[mid];
  }

  return walk;
}

int main() {
  int l, n; std::cin >> l >> n;
  std::vector<LL> x(n+1);
  for (int i = 1; i <= n; ++i) std::cin >> x[i];

  std::vector<LL> sums1(n+1);
  std::vector<LL> sums2(n+2);
  for (int i = 1; i <= n; ++i) sums1[i] = sums1[i-1] + x[i];
  for (int i = n; i >= 1; --i) sums2[i] = sums2[i+1] + (l-x[i]);

  LL ans = 0;
  for (int i = 1; i <= n; ++i) {
    ans = std::max(ans, counter_clockwise_start(l, n, x, sums1, sums2, i));
    ans = std::max(ans, clockwise_start(l, n, x, sums1, sums2, i));
  }
  std::cout << ans << std::endl;
}

