					x.erase(x.begin(), x.begin() + 1);
					pos = x[0];
					n--;
				} else {
					ans += abs(pos + l - x[n - 1]) % l;
					x.erase(x.end() - 1, x.end());
					pos = x[n - 1];
					n--;
				}
			} else if (abs(x[0] + l - pos) % l > abs(pos + l - x[n - 1]) % l) {
				cout << "reverse" << endl;
				ans += abs(x[0] + l - pos) % l;
				pos = x[0];
				x.erase(x.begin(), x.begin() + 1);
				n--;
			} else {
				cout << "forward" << endl;
				ans += abs(pos + l - x[n - 1]) % l;
				pos = x[n - 1];
				x.erase(x.end() - 1, x.end());
				n--;
			}
			cout << pos << endl;
			cout << ans << endl;
			cout << x[0] << " " << x[n - 1] << endl;
			cout << "*****" << endl;
		}
	}

	cout << ans << endl;

	return 0;
}

