int N;
ll L;
vector<ll>X;

ll solve(int l, int r, bool which)
{
	if (l == 0 && r == N - 1)
	{
		if(which)return X[l];
		else return L-X[r];
	}

	if (which)
	{
		int index = (r + 1) % N;
		if (X[index] < X[l])return X[l];
		return solve(l, r + 1, !which) + L - (X[index] - X[l]);
	}
	else
	{
		int index = (l - 1 + N) % N;
		if (X[index] > X[r])return L - X[r];
		return solve(l - 1, r, !which) + L - (X[r] - X[index]);
	}
}

