using namespace std;

long long solve(long long L, long long N, vector<long long> &X) {
    vector<long long> ac(N+1);
    ac[0] = 0;
    for (int i=0; i<N; ++i) {
        ac[i+1] = ac[i] + X[i];
    }

    long long ans = max(X[N-1], L-X[0]);

    for (int i=0; i<N-1; ++i) {
        int rest = N - i;
        int l = rest / 2 + rest % 2;
        int r = rest - l;
        long long d = (ac[i+l] - ac[i]) * 2LL + (L * r - (ac[i+l+r] - ac[i+l])) * 2LL;
        if (rest % 2 == 0) {
            d -= (L - X[i+l]);
        } else {
            d -= X[i+l-1];
        }
        ans = max(ans, d);
    }

    return ans;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);

    long long L, N;
    cin >> L >> N;

    vector<long long> X(N);
    for (int i=0; i<N; ++i) {
        cin >> X[i];
    }

    vector<long long> Xrev(N);
    for (int i=0; i<N; ++i) {
        Xrev[i] = L - X[N-1-i];
    }

    cout << max(solve(L, N, X), solve(L, N, Xrev)) << endl;

    return 0;
}

