ll keisan(int A, int B, int D) {
	if (memo[A][B][D]) return memo[A][B][D];
	if (A == 1 && B == N) {
		if (D) memo[A][B][D] = X[A] * 2 + L - X[B];
		else memo[A][B][D] = X[A] + (L - X[B]) * 2;
	}
	else if (B == N) {
		if (D) memo[A][B][D] = X[A] * 2 + L - X[B];
		else memo[A][B][D] = max(keisan(A - 1, B, 1) + X[A] + L - X[B], keisan(A - 1, B, 0) + X[A] - X[A - 1]);
	}
	else if (A == 1) {
		if (D) memo[A][B][D] = max(keisan(A, B + 1, 0) + X[A] + L - X[B], keisan(A, B + 1, 1) + X[B + 1] - X[B]);
		else memo[A][B][D] = X[A] + (L - X[B]) * 2;
	}
	else {
		if (D) memo[A][B][D] = max(keisan(A, B + 1, 0) + X[A] + L - X[B], keisan(A, B + 1, 1) + X[B + 1] - X[B]);
