using ll = long long;

int L, n, x[200005], x2[200005];

ll solve() {
    ll ans = 0;
    ll sum = x[n];
    for (int i = n - 1; i > 0; --i) {
        int cntr = n - i;  // 2*n-2i+1<=n+1
        int cntl = i;
        if (cntr <= cntl) {
            sum += 2LL * (L - x[i + 1]);
            sum -= 2LL * (x[i] - x[i - cntr + 1]);
            sum -= x[i + 1] - x[i];
            sum += 2LL * x[i - cntr];
            // printf("+ %lld - %lld - %lld + %lld\n", 2LL * (L - x[n + 1]), 2LL * (x[i] - x[i - cnt + 1]), x[i + 1] - x[i], 2LL * x[i - cnt]);
            // printf("Round 1.1 i = %d, sum = %lld\n", i, sum);
        } else {
            sum -= 2LL * x[i];
            sum -= x[i + 1] - x[i];
            sum += 2LL * (x[i + 1 + cntl] - x[i + 1]);
            // if cntr > cntl, n-i > i, i+i < n, i+i+1 <= n
            sum -= 2LL * (L - x[i + cntl + 2]);
            // printf("Round 1.2 i = %d, sum = %lld\n", i, sum);
        }
        ans = max(ans, sum);
    }
    return ans;
}

