long long dp[2005][2005][2]; bool vis[2005][2005][2];
int main() {
	int L, N;
	cin >> L >> N;
	assert(N <= 2000);
	vector<int> X(N + 2);
	for (int i = 1; i <= N; ++i) cin >> X[i];
	X[N + 1] = L;
	function<long long(int, int, int, bool)> calc = [&](int d, int l, int r, bool isleft) {
		if (vis[d][l][isleft ? 0 : 1]) return dp[d][l][isleft ? 0 : 1];
		if (d == N) return (long long)(0);
		long long lc = calc(d + 1, l + 1, r, true);
		if (d == 0 || isleft) lc += X[l + 1] - X[l];
		else lc += L - (X[r] - X[l + 1]);
		long long rc = calc(d + 1, l, r - 1, true);
		if (d == 0 || !isleft) rc += X[r] - X[r - 1];
		else rc += L - (X[r - 1] - X[l]);
		vis[d][l][isleft ? 0 : 1] = true;
		dp[d][l][isleft ? 0 : 1] = max(lc, rc);
		return max(lc, rc);
	};
	long long ret = calc(0, 0, N + 1, true);
	cout << ret << endl;
	return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

const int MX = 2005;

ll ans = 0;

int XX[MX];
int L, n;

void solve()
{
	/*
	for (int i = 0; i <= n; i++) {
		cout << XX[i] << " ";
	} cout << endl << "--------" << endl;
	*/
	for (int len = 1; len <= n; len++) {
		ll tmp = 0;

		int l, r = n - len / 2;
		l = r;
		int dir;
		if (len % 2 == 0) {
			dir = -1;
			r++;
		}
		else {
			dir = 1;
			l--;
		}

		ll mult = 0;
		while (true) {
			if (dir == -1) {
				tmp += mult * XX[l];
				l--;
			}
			else {
				if (r > n) {
					mult--;
					break;
				}

				tmp += mult * XX[r];
				r++;
			}

			mult++;

			dir *= -1;
		}

		while (l >= 0) {
			tmp += mult * XX[l];
			l--;
		}

		ans = max(ans, tmp);
	}
}

