{
	ios::sync_with_stdio(false);
	cin.tie(0);

	cin >> L >> n;

	for (int i = 1; i <= n; i++) {
		cin >> X[i];
	}

	for (int i = 0; i < n; i++) {
		XX[i] = X[i + 1] - X[i];
	} XX[n] = L - X[n];

	solve();

	for (int i = 1; i <= n; i++) {
		X[i] = L - X[i];
	}
	for (int i = 1, j = n; i < j; i++, j--) swap(X[i], X[j]);

	for (int i = 0; i < n; i++) {
		XX[i] = X[i + 1] - X[i];
	} XX[n] = L - X[n];
	solve();

	cout << ans << "\n";
}

