void solve(){
    ll l, n;
    ll ans = 0;
    cin >> l >> n;
    vector < ll > x(n);
    for(ll i = 0; i < n; ++i)cin >> x[i];
    vector < vector < vector < ll > > > dp(n + 1, vector < vector < ll > > (n + 1, vector < ll > (2)));
    dp[1][0][0] = x[0];
    dp[0][1][1] = (l - x[n - 1]);
    for(ll i = 0; i <= n; ++i){
        for(ll j = 0; j <= n; ++j){
            for(ll p = 0; p < 2; ++p){
                if(i + j > n){
                    dp[i][j][p] = -inf;
                    continue;
                }
                ll v1 = 0;
                ll v2 = 0;
                if(i >= 1 && j >= 1){
                    if(p == 1){
                        v1 = dp[i][j - 1][0] + x[i - 1] + (l - x[n - j]);
                    } else {
                        v1 = dp[i - 1][j][1] + (l - x[n - j]) + x[i - 1];
                    }
                }
                if(i >= 2 && p == 0){
                    v2 = dp[i - 1][j][0] + (x[i - 1] - x[i - 2]);
                }
                if(j >= 2 && p == 1){
                    v2 = dp[i][j - 1][1] + (x[n - (j - 1)] - x[n - j]);
                }
                dp[i][j][p] = max({dp[i][j][p], v1, v2});
                if(i + j == n){
                    ans = max(ans, dp[i][j][p]);
                }
            }
        }
    }
    cout << ans << "\n";
}

