pair<long, long> h(long long x, long long y, long long z) {
	auto t1 = z - y;
	auto t2 = y - x;
	if (t1 < 0) t1 += L;
	if (t2 < 0) t2 += L;
	return {t1, t2};
}

vector<vector<map<long long, long long>>> memo;

long long f(int p, int q, long long x) {
	if (memo[p][q].count(x)) return memo[p][q][x];
	auto t = h(X[q], x, X[p]);
	if (p == q) {
		return memo[p][q][x] = max(t.first, t.second);
	} else {
		return memo[p][q][x] = max(
			f(p+1, q, X[p]) + t.first,
			f(p, q-1, X[q]) + t.second
		);
	}
}

