inline int get(int *s, int l, int r) {
  if (l > r) return 0;
  return s[r] - s[l - 1];
}

inline int doit() {
  int ans = 0;
  rep (i, n) sum[i] = sum[i - 1] + pos[i], sub[i] = sub[i - 1] + L - pos[i];
  for (int cut = 1; cut <= n; cut ++) {
    int now = 2 * pos[cut - 1];
    int res_num = n - cut + 1;
    int id = res_num & 1 ? res_num / 2 + 1 : res_num / 2;
    id += cut - 1;
    // cout << id << " " << now << " " << (get(sum, cut, id - 1) + get(sub, id, n)) * 2 << " " << res_num << "\n";
    if (res_num & 1) {
      now += get(sum, cut, id - 1) * 2
        + get(sub, id, n) * 2 - (L - pos[id]);
    } else {
      now += get(sum, cut, id) * 2
        + get(sub, id + 1, n) * 2 - pos[id];
    }
    // cout << cut << " " << now << "\n";
    ans = max(ans, now);
  }
  return ans;
}

