int N;
ll L;
vector<ll>X;

ll solve(vector<ll>&X)
{
	vector<ll>Sum(N + 2);
	for (int i = 0; i < N; i++)
	{
		Sum[i + 1] += Sum[i] + X[i];
	}
	Sum[N + 1] += Sum[N] + L;

	ll ans = 0;

	for (int i = 0; i < N; i++)
	{
		ll tmp = 0;
		int x = N - i - 1;
		int l = i + 1 + x / 2;
		tmp = 2 * (Sum[l] - Sum[i]) + 2 * ((N - l)*L - (Sum[N] - Sum[l]));
		if (x % 2)tmp -= L - X[l];
		else tmp -= X[l - 1];

		ans = max(ans, tmp);
	}

	return ans;
}

