void solve() {
  int l, n; cin >> l >> n;
  vi xs(n); cin >> xs;

  vi rev;
  rrep(i,n) rev.emplace_back(l - xs[i]);

  vl sumXs(n+1), sumRev(n+1);
  sumXs[0] = sumRev[0] = 0;
  rep(i,n) {
    sumXs[i+1] = sumXs[i] + xs[i];
    sumRev[i+1] = sumRev[i] + rev[i];
  }

  ll ans = 0;

  rep(i,n) {
    int cnt = n - (i+1);
    int a = cnt / 2, b = cnt - a;
    ll tmp = (sumXs[a + (i+1)] - sumXs[i] + sumRev[b]) * 2;
    if (cnt & 1) tmp -= rev[b-1];
    else tmp -= xs[a + i];
    chmax(ans, tmp);
    tmp = (sumRev[a + (i+1)] - sumRev[i] + sumXs[b]) * 2;
    if (cnt & 1) tmp -= xs[b-1];
    else tmp -= rev[a + i];
    chmax(ans, tmp);
  }

  cout << ans << endl;
}


