int solve(vector<int> &v, int l){
    deque<int> kek;
    int n = v.size();
    int ind = n-1, here=0;
    while (2*kek.size() < n){
        kek.push_back((l-v[ind])-here);
        here = l - v[ind];
        ind--;
    }
    deque<int> sas;
    here = 0;
    for (int i=0;i<=ind; i++){
        sas.push_back(v[i]-here);
        here = v[i];
    }
    int mv = 0;
    if (kek.size() > sas.size()){
        mv += kek[0];
        sas[0] += kek[0];
        kek.pop_front();
    }
    int aa = 0, bb=0, s1=0, s2=0;
    int mn = 2*kek.size();
    for (int i=0; i < kek.size(); i++){
        s1 += kek[i], s2 += sas[i];
        aa += mn*kek[i], bb += mn*sas[i];
        mn-=2;
    }
    int res = mv + aa+bb - min(s1, s2);
    int sz = kek.size();
//    for (int i=0; i < kek.size(); i++) cout << kek[i] << " ";
//    cout << endl;
//    for (int i=0; i <sas.size(); i++) cout << sas[i] << " ";
//    cout << endl;
//    cout << endl;
    for (int i=0; i < sz-1; i++){
        int V = kek.front();
        kek.pop_front();
        int P = kek.front();
        kek.pop_front();
        mv += V+P;
        s1 -= V+P;
        aa -= 2*((sz-i)*V + (sz-i-1)*P);
        bb += 2*(sz-i)*(V+P);
        s2 += V+P;
        sas[0] += V+P;
        int hh = sas.back();
        sas.pop_back();
        int index = sz-i-1;
        int rl = v[index+1] - v[index];
        bb -= 2*hh;
        s2 -= hh;
        bb -= 2*s2;
        aa += 2*s1;
        s1 += rl;
        aa += 2*rl;
        kek.push_back(rl);
        res = max(res, mv + aa+bb - min(s1, s2));
//        for (int i=0; i < kek.size(); i++) cout << kek[i] << " ";
//        cout << endl;
//        for (int i=0; i <sas.size(); i++) cout << sas[i] << " ";
//        cout << endl;
//        cout << endl;
//        cout << mv << " " << aa << " " << bb << " " << s1 << " " << s2 << endl;
    }
    return res;
}
