int rec(int l, int r, int side, int prev){
	int& ret = dp[l][r][side];
	if(ret != -1) return ret;
	if(l == r){
		return ret = max(abs(prev-a[l]), L	 - abs(prev - a[l]));
	}
	//either attack l or r
	//attacking l here
	if(side == 0){
		return ret = max(a[l]-prev + rec(l+1, r, 0, a[l]), prev + L-a[r] + rec(l, r-1, 1, a[r]));
	}else{
		return ret = max(prev-a[r] + rec(l, r-1, 1, a[r]), L-prev + a[l] + rec(l+1, r, 0, a[l]));
	}
}

