class Timer {
	chrono::high_resolution_clock::time_point start, end;
	double limit;

public:
	Timer() {
		start = chrono::high_resolution_clock::now();
	}
	Timer(double l) {
		start = chrono::high_resolution_clock::now();
		limit = l;
	}

	double getTime() {
		end = chrono::high_resolution_clock::now();
		return chrono::duration<double>(end - start).count();
	}

	bool Over() {
		if (getTime() > limit) {
			return true;
		}
		return false;
	}

	void setLimit(double l) {
		limit = l;
	}
	void setStart() { start = chrono::high_resolution_clock::now(); }
	double getLimit() { return limit; }
};

typedef long long ll;



int N;
ll L;
vector<ll>X;

ll solve(int l, int r, bool which)
{
	if (l == 0 && r == N - 1)
	{
		if(which)return X[l];
		else return L-X[r];
	}

	if (which)
	{
		int index = (r + 1) % N;
		if (X[index] < X[l])return X[l];
		return solve(l, r + 1, !which) + L - (X[index] - X[l]);
	}
	else
	{
		int index = (l - 1 + N) % N;
		if (X[index] > X[r])return L - X[r];
		return solve(l - 1, r, !which) + L - (X[r] - X[index]);
	}
}

