	Timer tmr(1.8);

	ll ans = 0;
	int pos = N/2;
	int t=0;
	while(!tmr.Over())
	{
		pos += (t%2?1:-1)*t;
		if(pos <0 || pos >=N)break;

		ans = max(ans, solve(pos, pos, true));
		ans = max(ans, solve(pos, pos, false));

		t++;
	}
	cout << ans << endl;

	return 0;
}

