ll dp[2222][2222][2];
ll calc(int lft, int rgt, int w, ll L, vector<ll>& P, int n) {
	if(lft+1 == rgt) {
		return 0;
	}
	ll& ans = dp[lft+1][rgt][w];
	if(ans == -1) {
		ll last = w == 0 ? P[lft] : P[rgt];
		ll d1 = (L+(P[lft+1]-last)%L)%L; 
		ll d2 = ((L+last-P[rgt-1])%L+L)%L;
		ans = max(d1+calc(lft+1, rgt, 0, L, P, n), d2+calc(lft, rgt-1, 1, L, P, n));
	}
	return ans;
}
ll solve(vector<ll> P, int n, ll L) {
	memset(dp, -1, sizeof(dp));
	return max(calc(0, n, 0, L, P, n)+P[0], calc(-1, n-1, 1, L, P, n)+(-P[n-1]+L)%L);
}

ll solvebt(vector<ll> P, int n, ll L) {
	ll ans = 0;
	REP(i, 1<<n) {
		ll cdist = 0;
		int lft = 0, rgt = n-1;
		ll pos = 0;
		REP(j, n) {
			if(i&(1<<j)) {
				cdist += (L+(P[lft]-pos)%L)%L; 
				pos = P[lft];
				lft++;
			} else {
				cdist += ((L+pos-P[rgt])%L+L)%L;
				pos = P[rgt];
				rgt--;
			}
		}
		ans = max(cdist, ans);
	}
	return ans;
}

