using namespace std;

long long calc(vector<long long> &x, long long l, long long n) {
    vector<long long> y(n);
    for (int i = 0; i < n; i++)
        y[i] = l - x[n - i - 1];

    vector<long long> ll(n + 1), rr(n + 1);
    for (int i = 1; i <= n; i++) {
        rr[i] = rr[i - 1] + x[i - 1];
        ll[i] = ll[i - 1] + y[i - 1];
    }

    long long maxx = 0;
    for (int i = 1; i <= n; i++) {
        // left
        long long res = 0;
        int num_left = i + (n - i) / 2;
        int num_right = (n - i + 1) / 2;
        if ((n - i) % 2 == 0) {
            res = 2 * (ll[num_left - 1] - ll[i - 1]) + y[num_left - 1] +
                  2 * rr[num_right];

        } else {

            res = 2 * (ll[num_left] - ll[i - 1]) + 2 * rr[num_right - 1] +
                  x[num_right - 1];
        }
        maxx = max(maxx, res);
    }

    return maxx;
}
int main() {
    long long l, n;
    cin >> l >> n;
    vector<long long> x(n);
    for (int i = 0; i < n; i++) {
        cin >> x[i];
    }

    long long maxx = 0;
    maxx = max(maxx, calc(x, l, n));

    vector<long long> rev(n);
    for (int i = 0; i < n; i++) {
        rev[i] = l - x[n - i - 1];
    }
    maxx = max(maxx, calc(rev, l, n));

    cout << maxx << endl;

    return 0;
}

