    for (int i = n; i >= 1; i--)
    {
        dp[1][i] = max(dp[1][i + 1], l - x[i]);
        g[1][i] = 2 * (l - x[i]);
    }

    ll ans = max(dp[0][n], dp[1][1]);

    for (int i = 1; i <= n; i++)
    {
        //顺着走到i，再逆着走到i+1
        ll tmp = g[0][i] + dp[1][i + 1];
        if(i == n)
        {
            tmp /= 2;
        }
        if(tmp > ans)
        {
            ans = tmp;
        }

        tmp = g[1][i] + dp[0][i - 1];
        if(1 == i)
        {
            tmp /= 2;
        }
        //逆着走到i，再顺着走到i-1
        if(tmp > ans)
        {
            ans = tmp;
        }
    }

    cout << ans;

    return 0;
}

