int N;
LL L;
LL A[200000];
LL P[200000];

void pre() {
	LL sum = 0;
	REP(i, 0, N - 1) {
		sum += i * (A[i + 1] - A[i]);
		P[i + 1] = sum;
	}
}

LL constant(int l, int r) {
	return A[r] - A[l];
}

LL linear(int l, int r) {
	return (P[r] - P[l]) - l * constant(l, r);
}

LL sub(int st) {
	int l = st;
	int r = N - 1 - st;

	LL mx = 0;
	if (l <= r) {
		int be = 0;
		int en = 2 * st;
		int h = en - be;
		LL diff = 0;
		diff += 2 * linear(be, st) + constant(be, st);
		diff += h * constant(st, en) - 2 * linear(st, en);
		LL sum = h * L - diff;
		sum += A[be];
		if (en < N - 1) sum += 2 * (L - A[en + 1]);
		mx = max(mx, sum);
	} else {
		int en = N - 1;
		int be = en - 2 * (en - st);
		int h = en - be;
		LL diff = 0;
		diff += 2 * linear(be, st) + constant(be, st);
		diff += h * constant(st, en) - 2 * linear(st, en);
		LL sum = h * L - diff;
		sum += A[be];
		mx = max(mx, sum);
	}

	return mx;
}

int main() {
	cin >> L >> N;
	REP(i, 0, N) cin >> A[i];

	LL mx = 0;
	pre();
	REP(i, 0, N) mx = max(mx, sub(i));
	reverse(A, A + N);
	REP(i, 0, N) A[i] = L - A[i];

	pre();
	REP(i, 0, N) mx = max(mx, sub(i));
	cout << mx << endl;
	return 0;
}

