int main()
{
    ull l;
    int n;
    cin >> l >> n;
    VEC(ull, n + 2, x, -1);
    x[0] = 0;
    x[n + 1] = l;
    REP(i, n) cin >> x[i + 1];

    VEC(ull, n + 2, sum0, 0);
    VEC(ull, n + 2, sumN, 0);
    REP( i, n + 1 ) sum0[i+1] = sum0[i] + x[i+1];
    REP( i, n + 1 ) sumN[n-i] = sumN[n-i+1] + x[n+1] - x[n-i];

    ull ans = 0;
    REP(i, n + 1)
    {
        if (i == 0)
        {
            ans = max(ans, x[n+1] - x[1]);
            continue;
        }
        if( i == n )
        {
            ans = max(ans, x[n]);
            continue;
        }

        int start = i;
        int end = i + 1;
        ull sum;
        if( i * 2 == n )
        {
            sum = sumN[end] + sum0[start];
            sum *= 2;
            ans = max(ans, sum - x[start]);
            ans = max(ans, sum - x[end]);
        }
        else if( i * 2 < n )
        {
            sum = sumN[end] - sumN[end + i] + sum0[start];
            sum *= 2;
            ans = max(ans, sum - x[start]);
            sum = sumN[end] - sumN[end + i + 1] + sum0[start];
            sum *= 2;
            ans = max(ans, sum -( x[n+1] - x[end] ) );
        }
        else
        {
            int j = n + 1 - end;
            sum = sumN[end] + sum0[start] - sum0[start-j];
            sum *= 2;
            ans = max(ans, sum - (x[n + 1] - x[end]));
            sum = sumN[end] + sum0[start] - sum0[start-j-1];
            sum *= 2;
            ans = max(ans, sum - x[start]);
        }
    }

    cout << ans << endl;
    return 0;
}

