int PPP(unsigned long long int p , unsigned long long int mm , bool de )
{
	if (de)
	{
		//左
		if (p < mm)
			return mm - p;
		else
			return L - p + mm;
	}
	else
	{
		//
		//右
		if (p < mm)
			return p + L - mm;
		else
			return p - mm;

	}
	return 0;
}

int main(void)
{
	cin >> L >> N;

	X = new unsigned long long int[N];

	for (int i = 0; i < N; i++)
		cin >> X[i];

	unsigned long long int left = 0 , right = N - 1;

	unsigned long long int mm1 , mm2;

	unsigned long long int p = 0;

	bool flag = false;
	unsigned long long int cnt = 0;

	mm1 = 0;
	left = 0;
	right = N - 1;
	cnt = 0;
	p = 0;
	flag = false;
	while(1)
	{

		if (left == right)
			break;

		unsigned long long int pl = PPP(p, X[left], true);
		unsigned long long int pr = PPP(p, X[right], false);
		if (!(cnt%2))
		{
			p = X[left];
			mm1 += pl;
			left++;	
		}
