#include<cassert>
using namespace std;
typedef long long int ll;
static const int MAX_N = 2000;

int L, N;
int X[MAX_N + 2];
ll memo[2][MAX_N + 1][MAX_N + 1];

ll memoize(int k, int i, int j){
	if(memo[k][i][j] != 0) return memo[k][i][j];
	if(i == 0 && j == 0) return 0;
	if(i != 0 && i <= j) return 0;
	if(k == 0){
		if(j == 0) return 0;
		else if(i == 0) return X[j];
		else return max({memoize(1, i, j - 1) + L - X[i] + X[j], memoize(1, i, j - 1) + 2 * (X[j] - X[j - 1]), memoize(0, i, j - 1) + X[j] - X[j - 1]});
	}else{
		if(i == 0) return 0;
		else if(j == 0) return L - X[i];
		else return max({memoize(0, (i + 1) % (N + 1), j) + X[j] + L - X[i], memoize(0, (i + 1) % (N + 1), j) + 2 * (X[i] - X[i + 1]), memoize(1, (i + 1) % (N + 1), j) + X[i + 1] - X[i]});
	}
}

int main(){
	scanf("%d %d", &L, &N);
	assert(N <= 2000);
	for(int i = 0; i < N; i++) scanf("%d", &X[i + 1]);
	X[N + 1] = L;
	for(int i = N; i >= 0; i--){
		for(int j = 0; j < N + 1; j++){
			for(int k = 0; k < 2; k++){
				memo[k][i][j] = memoize(k, i, j);
			}
		}
	}
	ll res = 0;
	for(int i = 0; i < N + 1; i++){
		for(int j = 0; j < 2; j++){
			res = max(res, memo[j][(i + 1) % (N + 1)][i]);
		}
	}
	printf("%lld\n", res);
	return 0;
}

