        vector<ll> sx(n+1,0),srx(n+1,0);
        for(int i=0;i<n;i++) sx[i+1] = sx[i] + x[i];        // sx[i] = x[0] + ... + x[i-1]
        for(int i=0;i<n;i++) srx[i+1] = srx[i] + rx[i];     // srx[i] = rx[0] + ... + rx[i-1]

        //cout << "x  " << x << endl;
