using namespace std;

vector<vector<vector<long long>>> memo;
vector<int> X;
int L, N;

long long solve(int l, int r, int p)
{
    if (r<=l)
        return 0LL;
    if (memo[l][r][p] != -1)
        return memo[l][r][p];

    long long ans;
    if (p == 0)
        ans = max(
            X[l+1]-X[l] + solve(l+1, r, 0),
            X[l]+L-X[r] + solve(l+1, r, 1));
    else
        ans = max(
            X[r]-X[r-1] + solve(l, r-1, 1),
            X[l]+L-X[r] + solve(l, r-1, 0));
    return memo[l][r][p] = ans;
}

