            {
                dp[i][e][0] = dp[i][e + 1][1] + (l - a[e + 1]) + a[i];
                dp[i][e][1] = dp[i][e + 1][1] + a[e + 1] - a[e];
            }
            else if (e == n - 1)
            {
                dp[i][e][0] = dp[i - 1][e][0] + a[i] - a[i - 1];
                dp[i][e][1] = dp[i - 1][e][0] + a[i - 1] + (l - a[e]);
            }
            else
