using lint = long long;

int main() {
    lint L;
    int N;
    std::cin >> L >> N;

    std::vector<lint> A(N);
    for (auto& a : A) std::cin >> a;

    std::vector<lint> rsum(N + 1, 0);
    for (int i = 0; i < N; ++i) rsum[i + 1] = rsum[i] + A[i];

    // Aを左右反転させたもの
    auto B = A;
    std::reverse(B.begin(), B.end());
    for (auto& b : B) b = L - b;

    std::vector<lint> lsum(N + 1, 0);
    for (int i = 0; i < N; ++i) lsum[i + 1] = lsum[i] + B[i];

    A.insert(A.begin(), 0);
    B.insert(B.begin(), 0);  // index合わせ(なくてもいい)

    lint ans = 0; 

    // 右に移動して終わるケース
    for (int r = 1; r <= N; ++r) {
        // r個の区間に右から入る
        int l = N - r;
        int step = std::min(l, r);  // 「階段」の段数

        lint left = (lsum[l] - lsum[l - step]) * 2;
        lint right = (rsum[r] - rsum[r - step]) * 2 - A[r];
        if (r > l) right += A[r - step] * 2;
        // 右側の階段が1段増える

        ans = std::max(ans, left + right);
    }

    // 左から終わるケース
    // さっきのを全体を左右反転させてやるだけ
    for (int l = 1; l <= N; ++l) {
        int r = N - l;
        int step = std::min(l, r);

        lint left = (rsum[l] - rsum[l - step]) * 2 - B[l];
        lint right = (lsum[r] - lsum[r - step]) * 2;
        if (l > r) left += B[l - step] * 2;

        ans = std::max(ans, left + right);
    }

    std::cout << ans << std::endl;
    return 0;
}

