struct summator {
    vll pref;

    explicit summator(const vll& a) {
        pref.resize(sz(a) + 1);
        forn(i, sz(a)) {
            pref[i + 1] = pref[i] + a[i];
        }
    }

    ll get(int l, int r) {
        ++r;
        if (l >= r) {
            return 0;
        }
        return pref.at(r) - pref.at(l);
    }
};

void solve() {
    vll a;
    forn(i, n) {
        a.pb(xs[i]);
    }

    vll b;
    ford(i, n) {
        b.pb(L - xs[i]);
    }

    summator A(a);
    summator B(b);

    ll ans = 0;
    for (int len_a = 0; len_a <= n; ++len_a) {
        const int len_b = n - len_a;

        const auto upd = [&](int cnt_a, int cnt_b) {
            assert(cnt_a <= len_a);
            assert(cnt_b <= len_b);
            assert(abs(cnt_a - cnt_b) <= 1);
            assert(cnt_a + cnt_b > 0);

            ll cur = A.get(len_a - cnt_a, len_a - 1) * 2;
            cur += B.get(len_b - cnt_b, len_b - 1) * 2;

            if (cnt_b > cnt_a) {
                cur -= b.at(len_b - 1);
            } else if (cnt_a > cnt_b) {
                cur -= a.at(len_a - 1);
            } else {
                cur -= min(b.at(len_b - 1), a.at(len_a - 1));
            }

            remax(ans, cur);
        };

        int min_len = min(len_a, len_b);
        if (min_len > 0) {
            upd(min_len, min_len);
        }
        if (min_len + 1 <= len_a) {
            upd(min_len + 1, min_len);
        }
        if (min_len + 1 <= len_b) {
            upd(min_len, min_len + 1);
        }
    }

    cout << ans << endl;
}

