    for(int i=1;i<=n;++i)X[i]=L-X[i];
    for(int i=1;i<=n/2;++i)swap(X[i],X[n-i+1]);
    solve();
    cout<<ans<<endl;
}

#include <bits/stdc++.h>

using namespace std;

using int64 = long long;


int N, L;

int64 solve(vector< int > X) {
  int N = (int) X.size();
  X.push_back(L);

  int64 ret = 0;
  for(int i = N - 2; i >= 0; i--) { // 右端を固定
    int64 sub = 0;

    {
      for(int j = 0; j < i; j++) {
        int64 rightRest = (i - j - 1);
        int64 leftLeft = (N - i - 1);
        sub += 1LL * (X[j + 1] - X[j]) * min(rightRest, leftLeft);
      }
    }

    for(int j = N - 1; j > i; j--) {
      int64 rightRest = i;
      int64 leftLeft = j - i;
      sub += 1LL * (X[j + 1] - X[j]) * min(rightRest, leftLeft);
    }

    sub *= 2;

    for(int j = 0; j < i; j++) {
      sub += 1LL * (X[j + 1] - X[j]);
    }


    ret = max(ret, sub);
  }

  return ret;
}

int main() {
  cin >> L >> N;
  if(N > 2000) throw 0;
  vector< int > X(N + 1);
  X[0] = 0;
  for(int i = 1; i <= N; i++) cin >> X[i];
  int64 ret = solve(X);
  for(auto &p : X) p = (L - p) % L;
  sort(begin(X), end(X));
  cout << max(ret, solve(X)) << endl;
}

