const int N = 2e5 + 5;
ll d1[N], d2[N];
ll pre_d1[N], pre_d2[N];

void solve() {
	int L, n;
	cin >> L >> n;
	for(int i = 1; i <= n; i++) {
		cin >> d1[i];
		d2[i] = L - d1[i];
	}
	reverse(d2 + 1, d2 + n + 1);
	for(int i = 1; i <= n; i++) {
		pre_d1[i] = pre_d1[i - 1] + d1[i];
	}
	for(int i = 1; i <= n; i++) {
		pre_d2[i] = pre_d2[i - 1] + d2[i];
	}
	ll ans = 0;
	for(int c1 = 0; c1 <= n; c1++) {
		int c2 = n - c1;
		if(c1 == 0 || c1 == n) {
			ans = max(ans, d1[c1] + d2[c2]);
			continue;
		}
		for(int i = 0; i < 2; i++) {
			int cc1 = c1, cc2 = n - c1;
			ll val = 0;
			if(i == 0 && !cc1) continue;
			if(i == 1 && !cc2) continue;
			if(i == 0) val += d1[cc1--];
			else val += d2[cc2--];
			int cnt1 = cc1, cnt2 = cc2;
			if(i == 0) {
				cnt2 = min(cnt2, cnt1 + 1);
				cnt1 = min(cnt1, cnt2);
			}
			else {
				cnt1 = min(cnt1, cnt2 + 1);
				cnt2 = min(cnt2, cnt1);
			}
			val += 2 * (pre_d1[cc1] - pre_d1[cc1 - cnt1] + pre_d2[cc2] - pre_d2[cc2 - cnt2]);
			ans = max(ans, val);
		}
	}
	// print(pre_d1 + 1, pre_d1 + n + 1);
	// print(pre_d2 + 1, pre_d2 + n + 1);
	cout << ans;
}

