ll go(vector<int> const &v){
	ll an = 0, sml = v[0], smr = 0, csm, smr2 = 0;
	f(i, 1, v.size())smr += v[i];
	smr2 = smr;
	csm = smr;
	an = csm;
	f(i, 1, v.size() - 1){
		int nv = (i + 1 << 1) - 1;
		if (nv > (int)v.size())break;
		csm += sml << 1;
		sml += v[i];
		csm -= v[i];
		smr -= v[i];
		if (nv > 1)smr2 -= v[nv - 2];
		csm -= smr - smr2 << 1;
		smr2 -= v[nv - 1];
		csm += smr2 << 1;
		an = max(an, csm);
	}
	sml = v[0], smr = 0;
	f(i, 1, v.size())smr += v[i];
	smr2 = smr - v[1];
	csm = sml + (smr - v[1] << 1);
	an = max(an, csm);
	f(i, 1, v.size() - 1){
		int nv = i + 1 << 1;
		if (nv > (int)v.size())break;
		csm += sml << 1;
		sml += v[i];
		csm += v[i];
		smr -= v[i];
		if (nv > 1)smr2 -= v[nv - 2];
		csm -= smr - smr2 << 1;
		smr2 -= v[nv - 1];
		csm += smr2 << 1;
		an = max(an, csm);
	}
	return an;
}

