int main() {
	ll L, N;
	cin >> L >> N;
	vector<ll> x(N + 1);
	x[0] = 0;
	for (int i = 1; i <= N; ++i) { cin >> x[i]; }

	vector<ll> dr(N + 1, 0);
	vector<ll> dl(N + 1, 0);
	for (int i = N; i >= 1; --i) {
		dl[i] = L - x[N - i + 1];
		dr[N - i + 1] = x[N - i + 1];
	}

	if (N > 2000) {
		cout << 0 << endl;
		return 0;
	}

	vector<vector<vector<ll>>> dp(N + 1, vector<vector<ll>>(N + 1, vector<ll>(2, 0)));
	for (int r = 0; r <= N; ++r) {
		for (int l = 0; l <= N; ++l) {
			if (r + l == N) { continue; }

			ll t0 = dp[l][r][0];
			ll t1 = dp[l][r][1];

			if (r < N) {
				dp[l][r + 1][1] = max(dp[l][r + 1][1], t0 + (dl[l] + dr[r + 1]));
				dp[l][r + 1][1] = max(dp[l][r + 1][1], t1 + (dr[r + 1] - dr[r]));
			}
			if (l < N) {
				dp[l + 1][r][0] = max(dp[l + 1][r][0], t0 + (dl[l + 1] - dl[l]));
				dp[l + 1][r][0] = max(dp[l + 1][r][0], t1 + (dr[r] + dl[l + 1]));
			}
		}
	}

	ll res = 0;
	for (int r = 0; r <= N; ++r) {
		int l = N - r;
		res = max(res, dp[l][r][0]);
		res = max(res, dp[l][r][1]);
	}

	cout << res << endl;

	return 0;
}

