int main()
{
	int l, n;
	cin >> l >> n;

	vector<int>	x;
	x.resize(n);

	int i, j;
	long	r = 0;
	vector<bool> state;
	state.resize(n);

	for (i = 0; i < n; i++)
	{
		cin >> x[i];
		state[i] = false;
	}

	int now;

	if (x[0] > (l - x[n - 1]))
	{
		now = 0;
		r = x[0];
		state[0] = true;
	}
	else
	{
		now = n - 1;
		r = (l - x[n - 1]);
		state[n - 1] = true;
	}

	int temp1, temp2;

	for (i = 1; i < n; i++)
	{
		temp1 = temp2 = -1;

		for (j = 1; j < n; j++)
		{
			if (now + j >= n)
			{
				if (!state[now + j - n])
				{
					//	使われていない
					temp1 = now + j - n;
					break;
				}
			}
			else
			{
				if (!state[j + now])
				{
					//	使われていない
					temp1 = j + now;
					break;
				}
			}
		}

		for (j = 1; j < n; j++)
		{
			if (now - j < 0)
			{
				if (!state[now - j + n])
				{
					//	使われていない
					temp1 = now - j + n;
					break;
				}
			}
			else
			{
				if (!state[now - j])
				{
					//	使われていない
					temp1 = now - j;
					break;
				}
			}
		}

		if (temp1 == -1 || temp2 == -1)
		{
			break;
		}

		int r1, r2;

		r1 = x[temp1] > x[now] ? x[temp1] - x[now] : x[temp1] - (l - x[now]);
		r2 = x[temp2] < x[now] ? x[now] - x[temp2] : x[now] + (l - x[temp2]);

		if (r1 > r2)
		{
			r += r1;
			now = temp1;

		}
		else
		{
			r += r2;
			now = temp2;
		}

		state[now] = true;
	}

	printf("%ld", r);

	return 0;
}

