        dp[i+1] = max(dp[i]+a[k],dp[i+1]);
        dp[i+1] = max(dp[i]+l-b[p],dp[i+1]);
        if(a[k] > l-b[p]) k++;
        if(a[k] < l-b[p]) p++;
        if(a[k] == l-b[p]) k++;
        if(k+p == n) break;
    }
    cout << dp[n] << endl;
    return 0;
}

