ll l, n, x[200005];

ll rec(ll lhs, ll rhs, bool turn_right) {
    if (lhs == -1) {
        if (turn_right) {
            return l - x[rhs];
        } else {
            return x[rhs];
        }
    } else if (rhs == n) {
        if (turn_right) {
            return l - x[lhs];
        } else {
            return x[lhs];
        }
    }

    if (turn_right) {
        return (l - x[rhs] + x[lhs]) + rec(lhs, rhs + 1, false);
    } else {
        return (l - x[rhs] + x[lhs]) + rec(lhs - 1, rhs, true);
    }
}

