ll res = 0;
ll L;

void dfs(vector<ll>& x, vector<bool>& used,int now, int n, ll dist) {
	if (n == used.size()) {
		res = max(res, dist);
		return ;
	}
	int N = used.size();

	int r = now;
	for (int i = 1; i < N; ++i) {
		r = (now + i) % N;
		if (!used[r]) { break; }
	}
	int l = now;
	for (int i = 1; i < N; ++i) {
		l = (now - i + N) % N;
		if (!used[l]) { break; }
	}

	ll dr = x[r] - x[now];
	if (now > r) {
		dr = (L - x[now]) + x[r];
	}
	ll dl = x[now] - x[l];
	if (now < l) {
		dl = (L - x[l]) + x[now];
	}

	used[r] = true;
	dfs(x, used, r, n + 1, dist + dr);
	used[r] = false; 
	used[l] = true;
	dfs(x, used, l, n + 1, dist + dl);
	used[l] = false;
}

