using namespace std;

long L, N, xs[MAX_N];
long dp[MAX_N][MAX_N][2];

long max_distance(long l, long r, long pos) {
  if (r < l) {
    return 0;
  }
  if (dp[l][r][pos] < 0) {
    long go_anti_clock, go_clock;
    if (pos == 0) {
      go_anti_clock = max_distance(l + 1, r, 0) + xs[l] - xs[l - 1];
      go_clock = max_distance(l, r - 1, 1) + L - (xs[r] - xs[l - 1]);
    } else {
      go_anti_clock = max_distance(l + 1, r, 0) + L - (xs[r + 1] - xs[l]);
      go_clock = max_distance(l, r - 1, 1) + xs[r + 1] - xs[r];
    }
    dp[l][r][pos] = max(go_clock, go_anti_clock);
    // printf("l = %ld, r = %ld, pos = %ld, go_anti_clock = %ld, go_clock = %ld\n",
    //        l, r, pos, go_anti_clock, go_clock);
  }
  return dp[l][r][pos];
}

int main(int argc, char *argv[]) {
  // read inputs
  scanf("%ld %ld", &L, &N);
  for (long i = 0; i < N; i++) {
    scanf("%ld", &xs[i]);
  }

  // solve dp
  // corner case
  if (N == 1) {
    printf("%ld\n", max(xs[0], L - xs[0]));
    return 0;
  }
  // initialize
  for (long i = 0; i < N; i++) {
    for (long j = 0; j < N; j++) {
      dp[i][j][0] = -1;
      dp[i][j][1] = -1;
    }
  }
  // print ans
  printf("%ld\n", max(max_distance(1, N - 1, 0) + xs[0],
                      max_distance(0, N - 2, 1) + L - xs[N - 1]));

  return 0;
}

