const int N = 5e5;
const ll  I = 1e18;
int l, n, x[N];
ll pref[N];

ll sum(int l, int r) {
	return pref[r] - pref[l];
}

ll solvep(int cp, int cm) {
	assert(cp >= 1 && cm >= 0);
	int p = min(cp, cm + 1);
	int m = min(cm, cp);
	assert(p <= m + 1);
	assert(m <= p);
	ll s = 2 * sum(cp - p, cp) + 2LL * l * m - 2 * sum(n - cm, n - cm + m);
	s -= x[cp - 1];
	return s;
}

ll solvem(int cp, int cm) {
	assert(cp >= 0 && cm >= 1);
	int p = min(cp, cm);
	int m = min(cm, cp + 1);
	assert(p <= m);
	assert(m <= p + 1);
	ll s = 2 * sum(cp - p, cp) + 2LL * l * m - 2 * sum(n - cm, n - cm + m);
	s -= l - x[n - 1 - (cm - 1)];
	return s;
}

