long long dfs( int l, int r )
{
	int ll = l;
	int flag = 0;
	if( l < 0 ) {
		flag = 1;
		l = -l;
	}
	l--;
	if( l > r ) {
		return 0;
	}
	if( memo[ll + N][r] >= 0 ) {
		return memo[ll + N][r];
	}
	long long d1;
	long long d2;
	if( l == 0 && r == N - 1 ) {
		d1 = X[l];
		d2 = L - X[r];
		long long res1 = dfs( l + 1 + 1, r ) + d1;
		long long res2 = dfs( -(l + 1), r - 1 ) + d2;
		memo[ll + N][r] = max( res1, res2 );
		return memo[ll + N][r];
	}
	else {
		int c = l - 1;
		if( flag ) {
			c = r + 1;
		}
		d1 = X[l] - X[c];
		if( d1 < 0 || L <= d1 ) {
			d1 = L - X[c] + X[l];
		}
		d2 = L - X[r] + X[c];
		if( d2 < 0 || L <= d2 ) {
			d2 = X[c] - X[r];
		}
		long long res1 = dfs( l + 1 + 1, r ) + d1;
		long long res2 = dfs( -(l + 1), r - 1 ) + d2;
		memo[ll + N][r] = max( res1, res2 );
		return memo[ll + N][r];
	}
}

int main() {
	cin >> L >> N;
	if( N > MAX ) {
		cout << 0 << endl;
		return 0;
	}
	for( int i = 0; i < N; i++ ) {
		cin >> X[i];
	}

	memset( memo, -1, sizeof( memo ) );
	long long ans = dfs( 1, N - 1 );

	cout << ans << endl;

	return 0;
}

