typedef long long int lld;
typedef pair<int, int> pii;

const int MAXN = 200002;

int n;
lld M, arr[MAXN], L[MAXN], R[MAXN];

lld _L(int i, int j) {
  if (i > j) return 0;
  if (j >= n) j = n-1;
  if (i <= 0) return L[j];
  return L[j] - L[i-1];
}

lld _R(int i, int j) {
  if (i > j) return 0;
  if (i < 0) i = 0;
  if (j >= n-1) return R[i];
  return R[i] - R[j+1];
}

int main() {
  ios_base::sync_with_stdio(0);
  cin.tie(0);
  cin >> M >> n;
  for (int i = 0; i < n; ++i) 
    cin >> arr[i];

  L[0] = arr[0];
  for(int i = 1; i < n; ++i) 
    L[i] = L[i-1] + (lld) arr[i];

  R[n-1] = M-arr[n-1];
  for (int i = n-2; i >= 0; --i)
    R[i] = R[i+1] + (lld) (M - arr[i]);

  lld ans = 0;
  for (int i = 0; i < n; ++i) {
    int mid; lld costo;

    // Try to start moving right til ith tree
    mid = (n-1+i) / 2;
    if ((n-i) & 1) {
      costo = _L(i, mid-1) + _L(i, mid) + 2ll*_R(mid+1, n-1);
    } else {
      costo = 2ll*_L(i, mid) + _R(mid+1, n-1) + _R(mid+2, n-1);
    }
    ans = max(ans, costo);

    // Try to start moving left til ith tree
    mid = (i+1) / 2;
    if ((i + 1) & 1) {
      costo = 2ll*_L(0, mid-1) + _R(mid, i) + _R(mid + 1, i);
    } else {
      costo = 2ll*_R(mid, i) + _L(0, mid-2) + _L(0, mid-1);
    }
    ans = max(ans, costo);
  }
  cout << ans << "\n";
  return 0;
}

