ll xs[200000+10];

ll memo[2010][2010][2];
ll solve(int bg, int ed, bool isBg) {
  ll &res = memo[bg][ed][isBg];
  if(res < 0) {
    if(bg == ed) {
      res = 0;
    } else {
      ll pos = isBg ? xs[bg-1] : xs[ed];
      if(bg+1 == ed) {
        ll goal = xs[bg];
        ll res1 = pos < goal ? goal-pos : L-pos+goal; // 反時計回り
        ll res2 = pos > goal ? pos-goal : pos+L-goal; // 時計回り
        res = max(res1, res2);
      } else {
        ll goal = xs[bg]; // 反時計回り
        ll res1 = (pos < goal ? goal-pos : L-pos+goal) + solve(bg+1, ed, true);
        goal = xs[ed-1]; // 時計回り
        ll res2 = (pos > goal ? pos-goal : pos+L-goal) + solve(bg, ed-1, false);
        res = max(res1, res2);
      }
    }
    // cerr << bg << " " << ed << " " << isBg << " = " << res << endl;
  }
  return res;
}

