using namespace std;
const int N=200005;
int a[N],b[N],sum1[N],sum2[N];
int l,n,ans;
int gs1(int l,int r){return r<l?0:(sum1[r]-sum1[l-1]);}
int gs2(int l,int r){return r<l?0:(sum2[r]-sum2[l-1]);}
void solve()
{
	for(int i=1;i<=n;i++) 
		sum1[i]=sum1[i-1]+a[i];
	for(int i=1;i<=n;i++) 
		sum2[i]=sum2[i-1]+l-a[i];
	for(int i=1;i<=n/2;i++)
	{
		int y=n-i*2;
		ans=max(ans,gs1(y,y+i-1)*2+a[y+i]+gs2(y+i+1,n)*2);
		ans=max(ans,gs1(y+1,y+i)*2+gs2(y+i+2,n)*2+l-a[y+i+1]);
	}
}
main()
{
	ios::sync_with_stdio(false);
	cin>>l>>n;
	for(int i=1;i<=n;i++) 
		cin>>a[i];
	ans=max(a[n],l-a[1]);
	solve();
	for(int i=1;i<=n;i++) 
		b[i]=l-a[n-i+1];
	for(int i=1;i<=n;i++) 
		a[i]=b[i];
	solve();
	cout<<ans<<endl;
	return 0;
}

