        ll ans = X[s];
        int p = s;
        for (;;) {
            const bool small = 2 * p < N;
            const int nxt = (small ? N - 1 - p : N - p);
            if (p == nxt) { break; }
            if (small ^ (p < nxt)) { break; }
            ans += d(p, nxt, nxt < p), p = nxt;
        }
        int t = p;
        ll sum = ans;
        SHOW(t, ans);
        for (int i = 0; i < N - 1; i++) {
            sum += d(s, t, true) - d((i + N) % 2 == 1 ? (t + 1) % N : t, s, true);
            chmax(ans, sum);
            s = (s + 1) % N, t = (i % N) % 2 == 1 ? (t + 1) % N : t;
            SHOW(s, t, sum);
        }
        return ans;
    };
    ll ans = std::max(L - X.front(), X.back());
    chmax(ans, solve());
    for (auto& e : X) { e = L - e; }
    std::reverse(X.begin(), X.end());
    chmax(ans, solve());
    std::cout << ans << std::endl;
    return 0;
}

