        }
    } else if (k == j) {
        /*ret = max(
            x[j] - x[j - 1] + dfs(i, j - 1, j - 1),
            l - x[j] + x[i + 1] + dfs(i + 1, j, i + 1)
        );*/
        auto r1 = dfs(i, j - 1, j - 1);
        auto r2 = dfs(i + 1, j, i + 1);

        i64 c1 = r1.first + x[j] - x[j - 1];
        i64 c2 = r2.first + l - x[j] + x[i + 1];

        if (c1 > c2) {
            ret.first = c1;
            ret.second = r1.second;
            ret.second.push_back(j - 1);
        } else {
            ret.first = c2;
