int main() {
    in(l, n);

    x = vin<i64>(n);

    vector<i64> y(n);

    for (int i = 0; i < n; i++) {
        y[i] = l - x[i];
    }

    i64 ans = 0;

    vector<i64> cumsum1(n), cumsum2(n);

    cumsum1[0] = x[0];
    for (int i = 1; i < n; i++) {
        cumsum1[i] = cumsum1[i - 1] + x[i];
    }

    cumsum2[n - 1] = y[n - 1];
    for (int i = n - 2; i >= 0; i--) {
        cumsum2[i] = cumsum2[i + 1] + y[i];
    }

    for (int i = 0; i < n; i++) {
        // x[i] が最後に訪れる場所

        if (i == 0) {
            ans = max(ans, y[i + 1] + max(x[i + 1] - x[i], y[i + 1] + x[i]));
        } else if (i == n - 1) {
            ans = max(ans, x[i - 1] + max(x[i] - x[i - 1], x[i - 1] + y[i]));
        } else {
            {
                // x[i - 1] が最後から2番目に訪れる場所

                i64 s = 0;

                int j1 = i - 1;
                int j2 = i + 1;

                vector<int> v1, v2;

                s += x[j1--];

                int k1 = j1 + 1;
                int k2 = n - j2;

                if (j1 >= 0) {
                    s += 2 * cumsum1[j1];
                }

                s += 2 * cumsum2[j2];

                if (k2 <= k1) {
                    if (j1 - k2 >= 0) {
                        s -= 2 * cumsum1[j1 - k2];
                    }
                } else {
                    if (j2 + k1 + 1 < n) {
                        s -= 2 * cumsum2[j2 + k1 + 1];
                    }
                }

                ans = max(ans, s + max(x[i] - x[i - 1], x[i - 1] + y[i]));
            }

            {
                // x[i + 1] が最後から2番目に訪れる場所

                i64 s = 0;

                int j1 = i - 1;
                int j2 = i + 1;

                vector<int> v1, v2;

                s += y[j2++];

                int k1 = j1 + 1;
                int k2 = n - j2;

                if (j2 < n) {
                    s += 2 * cumsum2[j2];
                }

                s += 2 * cumsum1[j1];

                if (k1 <= k2) {
                    if (j2 + k1 < n) {
                        s -= 2 * cumsum2[j2 + k1];
                    }
                } else {
                    if (j1 - k2 - 1 >= 0) {
                        s -= 2 * cumsum1[j1 - k2 - 1];
                    }
                }

                ans = max(ans, s + max(x[i + 1] - x[i], y[i + 1] + x[i]));
            }
        }
    }

    out(ans);
}

