LL calc(int *a)
{
    LL ans=0;
    for (int i=1;i<=n;++i)  sum[i]=sum[i-1]+a[i];
    // for (int i=1;i<=n;++i)  cout<<a[i]<<" "; cout<<endl;
    for (int i=1;i<=n;++i)
    {
        if (i+(i-1)<=n) // LL
            ans=max(ans,-2LL*(sum[2*i-1]-sum[i])+2LL*sum[i]-a[i]+2LL*(i-1)*m);
        if (i+i<=n) //LR
            ans=max(ans,-2LL*(sum[2*i]-sum[i])+a[i+1]+2LL*sum[i]+(2LL*i-1)*m);
        if (i+i<=n) //RL
            ans=max(ans,-2LL*(sum[2*i]-sum[i])+2LL*sum[i]-a[i]+2LL*i*m);
        if (i+i+1<=n)
            ans=max(ans,-2LL*(sum[2*i+1]-sum[i])+a[i+1]+2LL*sum[i]+(2LL*i+1)*m);
