                    last[l][r-1] = trees[r-1];
                }
            }
            if(l < n) {
                ll diff_l = trees[l] - last[l][r];
                while(diff_l < 0LL) diff_l += L;
                if(dp[l+1][r] < dp[l][r] + diff_l) {
                    dp[l+1][r] = dp[l][r] + diff_l;
                    last[l+1][r] = trees[l];
                }
            }
        }
    }

    ll ans = 0LL;
    for(int l=0;l<=n;++l) ans = max(ans, dp[l][l]);
