template<class T> inline bool UpdateMin(T& a, T b) {
  if (a > b) { a = b; return 1; } return 0;
}
template<class T> inline bool UpdateMax(T& a, T b) {
  if (a < b) { a = b; return 1; } return 0;
}

constexpr int DEBUG = 0;

int64 SolvePartial(int64 l, int n, vector<int64>& xs) {
  int64 solution = 0;

  vector<int64> cum1(n);
  cum1[0] = xs[0];
  for (int i = 1; i < n; i++) {
    cum1[i] = cum1[i - 1] + xs[i];
  }

  auto r_range_sum = [&](int i, int j) -> int64 {
    if (i > j) return 0;
    int64 sum = cum1[j];
    if (i >= 1) sum -= cum1[i - 1];
    return sum;
  };

  vector<int64> cum2(n);
  cum2[n - 1] = l - xs[n - 1];
  for (int i = n - 2; i >= 0; i--) {
    cum2[i] = cum2[i + 1] + (l - xs[i]);
  }

  for (int k = 1; k <= n; k++) {
    int remaining = n - k;
    if (remaining % 2 == 1) {
      int left_count = remaining / 2 + 1;
      int right_count = remaining / 2;
      int64 right_cost = 0;
      right_cost += 2 * cum1[k + right_count - 1];
      if (k >= 2) right_cost -= 2 * cum1[k - 2];
      int64 left_cost = 0;
      if (left_count > 0) left_cost += l - xs[n - left_count];
      if (left_count >= 2) left_cost += 2 * cum2[n - (left_count - 1)];
      int64 cost = right_cost + left_cost;
      if (DEBUG) {
        cout << "k: " << k << " cost: " << cost
            << " right_cost: " << right_cost
            << " left_cost: " << left_cost << endl;
      }
      UpdateMax(solution, cost);
    } else {
      int left_count = remaining / 2;
      int right_count = remaining / 2;
      int64 right_cost = 0;
      right_cost += xs[k + right_count - 1];
      right_cost += 2 * r_range_sum(k - 1, k + right_count - 2);
      // if (k + right_count >= 2) right_cost += 2 * cum1[k + right_count - 2];
      // if (k >= 2) right_cost -= 2 * cum1[k - 2];
      int64 left_cost = 0;
      if (left_count > 0) left_cost += 2 * cum2[n - left_count];
      int64 cost = right_cost + left_cost;
      if (DEBUG) {
        cout << "k: " << k << " cost: " << cost
            << " right_cost: " << right_cost
            << " left_cost: " << left_cost << endl;
      }
      UpdateMax(solution, cost);
    }
  }

  return solution;
}

