    //if(p >= L/2){
        rval = p - right;
        lval = L - (p - left);
    }
    else{
        lval = left - p;
        rval = L - (right - p);
    }
    ll ret = 0;

    if(rval > lval && e > i){
        ret = dfsr(right, s, e-1, val+rval, i);
    }
    else if(lval > rval){
        ret = dfsr(left, s+1, e, val+lval, i);
    }
    else{
        ll b = dfsr(left, s+1, e, val+lval, i);
        ll a = dfsr(right, s, e-1, val+rval, i);
        ret = max(a,b);
    }
    return ret;
}

