ll dfs(ll l,ll p,ll r){
	ll tl = x[l]-x[p]; if(tl<0) tl+=L;
	ll tr = x[p]-x[r]; if(tr<0) tr+=L;

	if(l==r) return max(tl,tr);

	if(tl>tr){
		return dfs(l+1,l,r)+tl;
	}
	else if(tl<tr){
		return dfs(l,r,r-1)+tr;
	}
	else{
		return max(dfs(l+1,l,r)+tl,dfs(l,r,r-1)+tr);
	}
}


