signed main() {
	INIT;

	VAR(int, L, n);
	VEC(int, x, n);
	x.insert(x.begin(), 0);
	x.emplace_back(L);

	FILL(dp, -INFLL);
	dp[0][n][0] = dp[0][n][1] = 0;

	RFOR(d, 1, n + 1) REP(l, n) {
		int r = l + d;
		if (r > n) break;
		CHMAX(dp[l + 1][r + 0][0], dp[l][r][0] + (x[l + 1] - x[l]));
		CHMAX(dp[l + 1][r + 0][0], dp[l][r][1] + x[l + 1] + (L - x[r + 1]));
		CHMAX(dp[l + 0][r - 1][1], dp[l][r][0] + x[l] + (L - x[r]));
		CHMAX(dp[l + 0][r - 1][1], dp[l][r][1] + (x[r + 1] - x[r]));
	}

	int ans = 0;
	REP(i, n) REP(f, 2) CHMAX(ans, dp[i][i][f]);
	OUT(ans)BR;

	return 0;
}

