{
    cin >> l >> n;

    for(int i = 1; i <= n; i ++)
    {
        cin >> v[i];

        st[i] = st[i  - 1] + v[i];
    }

    for(int i = n; i >= 1; i --)
        dr[i] = dr[i + 1] + (l - v[i]);

//    calc(0, 1);
   // calc(1, -1);

  //  cout << "\n";

    calc2(0, 1);
    calc2(1, -1);

    cout << rez << "\n";

    return 0;
}

