int max_dist(int a, int b, int L){
    int d = abs(a - b);
    return max(d, L - d);
}
int main(){
    scanf("%d %d", &L, &n);
    for(int i = 1; i <= n; i++) scanf("%d", &x[i]);
    if(n == 1){
        printf("%lld\n", max_dist(0, x[1], L));
        return 0;
    }
    for(int i = 0; i < MAXN; i++){
        for(int j = 0; j < MAXN; j++){
            for(int k = 0; k < 2; k++){
                dp[i][j][k] = -INF;
            }
        }
    }
    dp[0][1][1] = x[1];
    dp[1][0][0] = L - x[n];
    for(int l = 0; l <= n; l++){
        for(int r = max(0, 2 - l); l + r <= n - 1; r++){
            if(l > 0) dp[l][r][0] = max(dp[l][r][0], dp[l - 1][r][0] + x[n - l + 2] - x[n - l + 1]);
            if(l > 0) dp[l][r][0] = max(dp[l][r][0], dp[l - 1][r][1] + x[r] + (L - x[n - l + 1]));
            if(r > 0) dp[l][r][1] = max(dp[l][r][1], dp[l][r - 1][0] + (L - x[n - l + 1]) + x[r]);
            if(r > 0) dp[l][r][1] = max(dp[l][r][1], dp[l][r - 1][1] + x[r] - x[r - 1]);
        }
    }
    long long ans = 0;
    for(int l = 0; l <= n - 1; l++){
        int r = n - 1 - l;
        if(l > 0) ans = max(ans, dp[l][r][0] + max_dist(x[n + 1 - l], x[r + 1], L));
        if(r > 0) ans = max(ans, dp[l][r][1] + max_dist(x[r], x[r + 1], L));
    }
    printf("%lld\n", ans);
    return 0;
}

