	if(way == 0){
		ret = max(dp(left+1, right, 0) + rui[left][0] - rui[left-1][0],
			dp(left, right-1, 1) + rui[left-1][0] + rui[right][1]);
	}else{
		ret = max(dp(left+1, right, 0) + rui[right+1][1] + rui[left][0],
			dp(left, right-1, 1) + rui[right][1] - rui[right+1][1]);
	}


	return memo[left][right][way] = ret;
}

