//!    8888ba.88ba             oo              !//
//!    88  '8b  '8b                            !//
//!    88   88   88  .d8888b.  dP  88d888b.    !//
//!    88   88   88  88'  '88  88  88'  '88    !//
//!    88   88   88  88.  .88  88  88    88    !//
//!    dP   dP   dP  '88888P8  dP  dP    dP    !//
//!============================================!//
int main()
{
    const ll L = read<ll>();
    const int N = read<int>();
    auto X = readVec<ll>(N);
    auto cwd = [&](const int s, const int t) { return (X[t] - X[s] + L) % L; };
    auto naive = [&](const int s) {
        bool clock = false;
        ll sum = X[s];
        std::set<int> res;
        for (int i = s + 1; i < N; i++) { res.insert(i); }
        for (int p = s; not res.empty(); clock = not clock) {
            if (clock) {
                const int nxt = *res.begin();
                sum += cwd(p, nxt), res.erase(nxt), p = nxt;
            } else {
                const int nxt = *res.rbegin();
                sum += cwd(nxt, p), res.erase(nxt), p = nxt;
            }
        }
        return sum;
    };
    auto tle = [&]() {
        ll ans = 0;
        for (int i = 0; i < N; i++) { chmax(ans, naive(i)); }
        for (auto& e : X) { e = L - e; }
        std::reverse(X.begin(), X.end());
        for (int i = 0; i < N; i++) { chmax(ans, naive(i)); }
        std::cout << ans << std::endl;
    };
    auto fast = [&]() {
        ll ans = X.back(), sum = ans;
        for (int s = N - 1, t = N - 1; s >= 1;) {
            bool hoge = (N - 1 - s) % 2 == 0;
            s--, t = hoge ? t : t - 1;
            sum += -cwd(s, t) + cwd(hoge ? t : (t + 1) % N, s);
            chmax(ans, sum);
            SHOW(s, t, sum);
        }
        return ans;
    };
    auto ac = [&]() {
        ll ans = fast();
        for (auto& e : X) { e = L - e; }
        std::reverse(X.begin(), X.end());
        chmax(ans, fast());
        std::cout << ans << std::endl;
    };
    ac();
    //    tle();
    return 0;
}

