long long pref[maxn], suff[maxn];

void solve() {
  pref[0] = 0;
  for (int i = 0; i < n; i++) {
    pref[i + 1] = pref[i] + x[i];
  }
  suff[n] = 0;
  for (int i = n - 1; i >= 0; i--) {
    suff[i] = suff[i + 1] + (l - x[i]);
  }
  long long res = max(l - x[0], x[n - 1]);
  for (int i = 0; i + 1 < n; i++) {
    int k = min(i + 1, n - i - 1);
    {
      long long cur = pref[i + 1] - pref[i + 1 - k];
      cur += suff[i + 1] - suff[i + 1 + k];
      cur *= 2;
      cur -= min(x[i], l - x[i + 1]);
      res = max(res, cur);
    }
    if (i + 1 > k) {
      long long cur = pref[i + 1] - pref[i + 1 - k - 1];
      cur += suff[i + 1] - suff[i + 1 + k];
      cur *= 2;
      cur -= x[i];
      res = max(res, cur);
    }
    if (n - i - 1 > k) {
      long long cur = pref[i + 1] - pref[i + 1 - k];
      cur += suff[i + 1] - suff[i + 1 + k + 1];
      cur *= 2;
      cur -= l - x[i + 1];
      res = max(res, cur);
    }
  }
  printf("%lld\n", res);
}

