    FOR(h, 2) {
        FOR(i, N) {
            T.insert(X[i]);
            T.insert(L + X[i]);
            T.insert(2 * L + X[i]);
        }
        ll cur = L, tot = 0; bool first = true, isB = false;
        FOR(i, N) {
            auto it = T.upper_bound(cur);
            ll a = *it, b = *prev(it);
            if (a == b) {
                b = (b % L) + L;
                it = T.lower_bound(b);
                b = *prev(it);
            }
            if (i == 0) {
                if (h == 1) {
                    a = b;
                    isB = true;
                }
            } else if (first) {
                if (h == 0 && abs(cur - b) > abs(cur - a)) {
                    first = false;
                    isB = true;
                } else if (h == 1 && abs(cur - a) > abs(cur - b)) {
                    first = false;
                    isB = false;
                } else {
                    isB = h == 1;
                }
            }
            if (isB) a = b;
            tot += abs(cur - a);
            a %= L;
            cur = L + a;
            T.erase(T.lower_bound(a));
            T.erase(T.lower_bound(L + a));
            T.erase(T.lower_bound(2 * L + a));
            isB = !isB;
        }
        MAX(best, tot);
    }
