using namespace std;
vector<long int> X;
map<pair<long int, pair<int, int>>, long int> mp;

int walk(long int L, long int start, int low, int high){
	if(low == high){
		int val;
		if(X[low] == start) val =  0;
		if(X[low] < start) val = max(start - X[low], L - start + X[low]);
		else val =  max(X[low] - start, L- X[low] + start);
		return val;
	}
	pair<int, int> now1;
	now1.first = low;
	now1.second = high;
	pair<long int, pair<int, int>> now;
	now.first = start;
	now.second = now1;
	if(mp.find(now) != mp.end()) {
		return mp[now]; 
	}
	int first, second;
	if(start > X[low]) first = L - start + X[low];
	else first = X[low] - start;
	if(start > X[high]) second = start - X[high];
	else second = L - X[high] + start;
	int val = max(first + walk(L, X[low], low+1, high), second + walk(L, X[high], low, high-1));
	mp[now] = val;
	return val;
}

