struct Node
{
	int prevDiff;
	int nextDiff;
	int prevIndex;
	int nextIndex;
};

/**
 * 湖の周長: L <= 1e+9
 * 湖の周上にある木の本数: N　<= 2e+5
 * i本目の木の座標: 1 <= X[1] < ... < X[N] <= L-1
 * 
 * - 湖の周上には所有者の家がある．
 * - 周上は反時計回りに，家からの距離で実数の座標が定められている．
 * - 家のある座標 0 には木は生えていない．
 * 
 * 行動:
 * 	- すべての木を燃やし終えている場合，終了
 * 	- 時計回り(-)か反時計回り(+)かを指定
 * 	- 燃やしていない木がある座標まで指定した方向に歩き続ける
 * 	- 木があれば即ち燃やす
 * 
 * Q: 歩く距離の合計の最大値
 */
int main ()
{
	/**
	 * 各ステップで，現在地点から最も遠い木を目指す．
	 */

	int L, N;
	cin >> L >> N;

	vector<int> X(N + 2);
	// 家（処理簡略のため初めと最後に一つずつ）
	X[0] = 0;
	X[N+1] = L;
	// 木
	for (int i=0; i<N; ++i)
	{
		cin >> X[i+1];
	}

	// 循環リストで隣接間の差で位置を表現
	vector<Node> circle;
	// 家
	Node house;
	{
		house.prevDiff = L - X[N];
		house.nextDiff = X[1];
		house.prevIndex = N;
		house.nextIndex = 1;
	}
	circle.push_back(house);
	// 木
	for (int i=0; i<N; ++i)
	{
		Node tree;
		tree.prevDiff = X[i+1] - X[i];
		tree.nextDiff = X[i+2] - X[i+1];
		tree.prevIndex = i;
		tree.nextIndex = i + 2;
		circle.push_back(tree);
	}

	// 湖の大炎上
	// 初期地点は家
	int cursor = 0;

	long long total = 0LL;

	while (cursor != circle[cursor].prevIndex)
	{
		// 炎上（自ノード連結解除）
		circle[circle[cursor].prevIndex].nextIndex = circle[cursor].nextIndex;
		circle[circle[cursor].prevIndex].nextDiff = circle[cursor].prevDiff + circle[cursor].nextDiff;
		circle[circle[cursor].nextIndex].prevIndex = circle[cursor].prevIndex;
		circle[circle[cursor].nextIndex].prevDiff = circle[cursor].prevDiff + circle[cursor].nextDiff;

		// 次の木を決定
		if (circle[cursor].prevDiff >= circle[cursor].nextDiff)
		{
			total += circle[cursor].prevDiff;
			cursor = circle[cursor].prevIndex;
		}
		else
		{
			total += circle[cursor].nextDiff;
			cursor = circle[cursor].nextIndex;
		}
	}

	cout << total << endl;

	return 0;
}

