#define max_N 2018

//ここから編集する
class Solve {
public:
    ll Loop;
    int N;
    ll dp[max_N][max_N][2];
    vector<ll> X;

    void input() {

    }

    ll dfs(int L, int R, int d) {
        if (L < 0 || R > N + 1) return -INFl;
        if (dp[L][R][d] != -1) return dp[L][R][d];
        if (L >= R) return dp[L][R][d] = 0ll;

        ll ret;
        if (d == 0) {
            ll left = dfs(L - 1, R, 0) + X[L] - X[L - 1];
            ll right = dfs(L - 1, R, 1) + Loop - (X[R] - X[L]);
            ret = max(left, right);
        } else {
            ll right = dfs(L, R + 1, 1) + X[R + 1] - X[R];
            ll left = dfs(L, R + 1, 0) + Loop - (X[R] - X[L]);
            ret = max(left, right);
        }

//        cout << "(L,R,d) = " << L << "," << R << "," << d << ",ret :" << ret << endl;
        return dp[L][R][d] = ret;
    }

    void solve() {
        input();

        cin >> Loop;

        cin >> N;

        X = vector<ll>(N + 2, 0ll);

        rep(i, 1, N + 1) cin >> X[i];
        X[N + 1] = Loop;

        for (int i = 0; i < max_N; ++i) {
            for (int j = 0; j < max_N; ++j) {
                dp[i][j][0] = dp[i][j][1] = -1ll;
            }
        }

        dp[0][N + 1][0] = dp[0][N + 1][1] = 0ll;

        ll ans = 0ll;
        for (int L = 0; L <= N; ++L) {
            ll tmpl = dfs(L, L + 1, 0);
            ll tmpr = dfs(L, L + 1, 1);
            ll tmp = max(tmpl, tmpr);
            chmax(ans, tmp);
        }
//        ans = dfs(0,3,0);

        cout << ans << endl;

    }
};


int main() {
//    cin.tie(0);
