ll dfs(int li, int ri, int isleft) {

    if (li == ri) {
        return 0;
    }

    if (dp[li][ri][isleft] > 0) return dp[li][ri][isleft];

    if (isleft == 1) {
        // LEFT
        ll a1 = dfs(li + 1, ri, 1) + X[li + 1] - X[li];
        // RIGHT
        ll a2 = dfs(li + 1, ri, 0) + X[li] + (L - X[ri]);
        return dp[li][ri][isleft] = max(a1, a2);
    }
    else {
        // LEFT
        ll a1 = dfs(li, ri - 1, 1) + (L - X[ri]) + X[li];
        // RIGHT
        ll a2 = dfs(li, ri - 1, 0) + X[ri] - X[ri - 1];
        return dp[li][ri][isleft] = max(a1, a2);
    }
}

