ll go(ll s, ll e, int f) {
	if (s > e) return 0;
	ll &ret = dp[s][e][f];
	if (ret != -1) return ret;

	ll cur = 0;
	if (f == 1) cur = arr[s - 1];
	else if (f == 2) cur = arr[e + 1];

	ret = max(ret, go(s + 1, e, 1) + (cur > arr[s] ? L - cur + arr[s] : arr[s] - cur));
	ret = max(ret, go(s, e - 1, 2) + (cur > arr[e] ? cur - arr[e] : L - arr[e] + cur));

	return ret;
}
