const int MAXN = 2e5 + 5;

ll L, X[MAXN], F[2][MAXN], ans = 0;
int N;

ll f(int h, int k) {
    if (F[h][k] != -1) return F[h][k];
    set<ll> T;
    FOR(i, N) {
        T.insert(X[i]);
        T.insert(L + X[i]);
        T.insert(2 * L + X[i]);
    }
    ll cur = L, tot = 0; bool isB = false;
    FOR(i, N) {
        auto it = T.upper_bound(cur);
        ll a = *it, b = *prev(it);
        if (a == b) {
            b = (b % L) + L;
            it = T.lower_bound(b);
            b = *prev(it);
        }
        if (i <= k) isB = h == 1;
        if (isB) a = b;
        tot += abs(cur - a);
        a %= L;
        cur = L + a;
        T.erase(T.lower_bound(a));
        T.erase(T.lower_bound(L + a));
        T.erase(T.lower_bound(2 * L + a));
        isB = !isB;
    }
    MAX(ans, tot);
    return F[h][k] = tot;
}

template <class T, class F> ternary_search(F f, T lo, T hi) {
    static_assert(is_integral<T>::value, "T must be an integral type"); T mid;
    while (lo < hi) {
        mid = lo + (hi - lo) / 2;
        if (f(mid) < f(mid + 1)) hi = mid; // f(mid) < f(mid + 1) for minimum, f(mid) > f(mid + 1) for maximum
        else lo = mid + 1;
    }
    return lo;
}


