LL leftPart(LL b, LL e, vector<LL>& left1, vector<LL>& left2){
    LL score = (left2[e] - left2[b]) * 2;
    score -= (left1[e] - left1[b]) * (b * 2 + 1);
    return score;
}


LL rightPart(LL b, LL e, vector<LL>& right1, vector<LL>& right2){
    LL score = (right2[e] - right2[b]) * 2;
    score -= (right1[e] - right1[b]) * (b * 2 + 2);
    return score;
}


LL kougo(LL total, LL n, LL b, LL e, vector<LL>& left1, vector<LL>& left2, vector<LL>& right1, vector<LL>& right2){
    if(e - b < 1) return 0;
    LL last = (e + b) / 2;
    LL score = total * (e - b - 1);
    score -= leftPart(b, last, left1, left2);
    score -= rightPart(n+1 - e, n+1 - last, right1, right2);
    return score;
}


LL solve(LL l, LL n, vector<LL>& x){
    vector<LL> left1(x.size());
    vector<LL> left2(x.size());
    vector<LL> right1(x.size());
    vector<LL> right2(x.size());
    for(LL i = 1; i < n+2; ++i){
        left1[i] = left1[i-1] + (x[i] - x[i-1]);
        left2[i] = left2[i-1] + (x[i] - x[i-1]) * i;
        right1[i] = right1[i-1] + (x[n+1-(i-1)] - x[n+1-i]);
        right2[i] = right2[i-1] + (x[n+1-(i-1)] - x[n+1-i]) * i;
    }

    LL ans = 0;
    for(LL i = 0; i < n+1; ++i){
        LL cand = x[i] + kougo(l, n, i, n+1, left1, left2, right1, right2);
        ans = max<LL>(ans, cand);
    }
    return ans;
}


