ll Solve(deque <int> D, bool beg)
{
    int cur = 0;
    ll res = 0;
    while (!D.empty()) {
        if (beg) { res += Dist(cur, D.front()); cur = D.front(); D.pop_front(); }
        else { res += Dist(D.back(), cur); cur = D.back(); D.pop_back(); }
        beg = !beg;
    }
