        ans = max(ans, cost * 2 - min(X[l], L - X[l + 1] - (L - X[l * 2 + 1]) * 2));
    }

    for (int i = 0; i <= N + 1; ++i) {
        X[i] = L - X[i];
    }

    reverse(X, X + N + 2);

    cost = 0;
    ans = max(ans, L - X[N]);

    for (int l = 1; l <= N - l; ++l) {
        // X[1] ~ X[l]までのl個
        // X[l+1] ~ X[2l]までのl個

        cost += X[l];
        cost -= L - X[l];
        cost += (L - X[l * 2 - 1]) + (L - X[l * 2]);

        ans = max(ans, cost * 2 - min(X[l], L - X[l + 1] - (L - X[l * 2 + 1]) * 2));
    }

    cout << ans << endl;

    return 0;
}

