ll solve(const V<ll> &dlist, ll n, ll total_len)
{
    ll left_len = 0LL;
    ll left_step = 0LL;
    ll center_len = total_len - dlist[0];
    ll right_len = 0LL;
    ll right_step = 0LL;

    ll ret = 0LL;

    rep (i, n/2LL) {
        ll sum1 = center_len * (i * 2LL) + (left_step - left_len) + right_step;
        ll sum2 = center_len * (i * 2LL + 1LL) + left_step + (right_step - right_len);

        ret = max({ret, sum1, sum2});

        center_len -= dlist[(i*2LL+1LL)%n];
        center_len -= dlist[(i*2LL+2LL)%n];

        left_len += dlist[i];
        left_step += left_len * 2LL;

        right_step -= right_len * 2LL;
        right_len -= dlist[(i+1LL)%n];
        right_len += dlist[(i*2LL+1LL)%n];
        right_len += dlist[(i*2LL+2LL)%n];
        right_step += dlist[(i*2LL+1LL)%n] * (i * 2LL);
        right_step += dlist[(i*2LL+2LL)%n] * ((i + 1LL) * 2LL);
    }

    return ret;
}

