    rep (i, n) dlist.pb(xlist[i+1] - xlist[i]);
    ll ans = 0LL;

    ans = max(ans, solve(dlist, n, total_len));
    reverse(ALL(dlist));
    ans = max(ans, solve(dlist, n, total_len));

