        ll sum1 = 0LL;
        ll sum2 = 0LL;
        ll sum3 = 0LL;
        ll sum4 = 0LL;
        rep (i, n/2LL) {
            sum1 += dlist[i] * (n - i * 2LL - 2LL);
            sum2 += dlist[i] * (n - i * 2LL - 1LL);
            sum3 += dlist[n-i-1] * (n - i * 2LL - 2LL);
            sum4 += dlist[n-i-1] * (n - i * 2LL - 1LL);
        }

        ans = max(ans, sum1 + sum4);
