         return x[pos];
      return L - (x[r] - x[pos]) + go(m , l , r + 1 , 1 - id , r);
   }
}

int check(int m){
   int l = m - 1 , r = m + 1;
   return max(go(m , l , r , 0 , m) , go(m , l , r , 1 , m));
}

