	memset(dyn, -1, sizeof(dyn));
	long long ans = 0;
	ans = max(ans, recurse(0, n - 1, 0) + a[0]);
	ans = max(ans, recurse(0, n - 1, 1) + l - a[n - 1]);
	fprintf(out, "%lld\n", ans);

	return 0;
}

