long long N;
long long L;
long long X[3001];
long long mem[3001][3001][2];

long long rec(long long S, long long E, long long V){
	long long res = 0;
	if (mem[S][E][V] != -1) return mem[S][E][V];
	if (E-S == 0) {
		res = 0;
	} else if (E-S == 1) {
		res = max(X[E]-X[S], L-(X[E]-X[S]));
	} else if (V == 0) {
		res = max(rec(S+1,E,0)+(X[S+1]-X[S]),rec(S+1,E,1)+(L-(X[E]-X[S])));
	} else if (V == 1) {
		res = max(rec(S,E-1,0)+(L-(X[E]-X[S])),rec(S,E-1,1)+(X[E]-X[E-1]));
	}
	return mem[S][E][V] = res;
}

void solve(long long L, long long N, long long X[]){
	for (long long i = 0; i < 3001; i++) {
		for (long long j = 0; j < 3001; j++) {
			for (long long k = 0; k < 2; k++) {
				mem[i][j][k] = -1;
			}
		}
	}
	printf("%lld\n", max(X[0]+rec(0,N-1,0), L-X[N-1]+rec(0,N-1,1)));
}

