long long ret = 0;

long long range_sum(int id1, int id2) {
    assert(1 <= id1);
    assert(id1 <= id2);
    return ac[id2] - ac[id1-1];
}

void solve() {
    for (int i = 1; i <= N; i++) {
        ac[i] = ac[i-1] + X[i];
    }

    ret = std::max(ret, X[N]);

    for (int i = 1; i <= N; i++) {
        int num = std::min(i-1, N-i);
        if (1 <= num) {
            ret = std::max(ret, range_sum(i-num, i-1) * 2 + X[i] - range_sum(i+1, i+num) * 2 + L * 2 * num);
        }
        std::cout << i << " " << ret << std::endl;
    }

    for (int i = 1; i <= N; i++) {
        int num = std::min(i-1, N-i+1);
        if (1 <= num) {
            ret = std::max(ret, range_sum(i-num, i-1) * 2 + L * 2 * num - range_sum(i, i+num-1) * 2 - (L - X[i]));
        }
        std::cout << i << " " << ret << std::endl;
    }
}

