    for (int i = 1; i <= N; i++) {
        tmp[i] = L - X[N-i+1];
    }

    for (int i = 1; i <= N; i++) {
        X[i] = tmp[i];
    }

    solve();

    std::cout << ret << std::endl;

    return 0;
}

