long long f(int cur, int left, int right, const vector<long long> &v, long long l) {
  if (left == right) {
    long long d = abs(v[cur] - v[left]);
    return max(d, l - d);
  }

  long long a = 0;
  if (cur + 1 == left) {
    a += v[left] - v[cur];
  } else {
    a += l - v[cur] + v[left];
  }

  long long b = 0;
  if (cur - 1 == right) {
    b += v[cur] - v[right];
  } else {
    b += l - v[right] + v[cur];
  }

  if (a > b) {
    return a + f(left, left + 1, right, v, l);
  } else {
    return b + f(right, left, right - 1, v, l);
  }
}

int main() { IO;
