    long long ans = max(v[0], l - v[0]);
    cout << ans << endl;
    return 0;
  }

  long long a = v[0] + f(0, 1, n - 1, v, l);
  long long b = (l - v[n - 1]) + f(n - 1, 0, n - 2, v, l);
  long long ans = max(a, b);
  cout << ans << endl;

  return 0;
}

