#define REP(i, n) for (int i = 0; i < (n); i++)
#define RREP(i, n) for (int i = (n) - 1; i >= 0; i--)
#define FOR(i, a, b) for (int i = (a); i < (b); i++)
#define RFOR(i, a, b) for (int i = (a); i > (b); i--)
#define ALL(a) (a).begin(), (a).end()

int L, N, X[200002];

ll count(int di) {
    vector<ll> l, r;
    REP(i, di) r.push_back(X[i + 1] - X[i]);
    FOR(i, di + 1, N + 1) l.push_back(X[i + 1] - X[i]);
    reverse(ALL(l));
    if (l.size() < r.size()) swap(l, r);
    ll ls = l.size(), rs = r.size();

    ll ret = 0;
    if (ls != rs) {
        REP(i, ls - rs - 1) l[ls - rs - 1] += l[i];
        l.erase(l.begin(), l.begin() + ls - rs - 1);
        ls = l.size();

        REP(i, ls) ret += l[i] * ((ls - i) * 2 - 1);
        REP(i, rs) ret += r[i] * ((rs - i) * 2);

        l[1] += l[0];
        l.erase(l.begin());
        ls--;
    }

    ll tmp1 = 0, tmp2 = 0;
    REP(i, ls) tmp1 += l[i] * ((ls - i) * 2);
    REP(i, rs) tmp1 += r[i] * ((rs - i) * 2 - 1);
    REP(i, ls) tmp2 += l[i] * ((ls - i) * 2 - 1);
    REP(i, rs) tmp2 += r[i] * ((rs - i) * 2);
    ret = max(ret, max(tmp1, tmp2));
    return ret;
}

