    int ok = 0, ng = N + 1;
    while (ng - ok > 2000) {
        int mid1 = (ok * 2 + ng) / 3;
        int mid2 = (ok + ng * 2) / 3;
        if (count(mid1) < count(mid2)) ok = mid1;
        else                           ng = mid2;
    }
    ll ans = 0;
    FOR(i, ok, ng) ans = max(count(i), ans);
    cout << ans << endl;
    return 0;
}

#include <bits/stdc++.h>

using namespace std;

using int64 = long long;

template< class T >
struct BinaryIndexedTree {
  vector< T > data;

  BinaryIndexedTree(int sz) {
    data.assign(++sz, 0);
  }

  T sum(int k) {
    T ret = 0;
    for(++k; k > 0; k -= k & -k) ret += data[k];
    return (ret);
  }

  void add(int k, T x) {
    for(++k; k < data.size(); k += k & -k) data[k] += x;
  }
};

int N, L;

int64 solve(vector< int > X) {
  int N = (int) X.size();
  X.push_back(L);
  BinaryIndexedTree< int64 > uku(X.size());
  for(int i = 0; i + 1 < X.size(); i++) uku.add(i, X[i + 1] - X[i]);

  BinaryIndexedTree< int64 > beet(X.size());
  for(int i = 0; i + 1 < X.size(); i++) beet.add(i, (X[i + 1] - X[i]) * i);


  int64 ret = 0;
  for(int i = N - 1; i >= 0; i--) { // 右端を固定
    int64 sub = 0;

    {
      for(int j = 0; j < i; j++) {
        int64 rightRest = (i - j - 1);
        int64 leftLeft = (N - i - 1);
        sub += 1LL * (X[j + 1] - X[j]) * min(rightRest, leftLeft);
      }
    }

    {

      int ok = i, ng = N;
      while(ng - ok > 1) {
        int j = (ok + ng) / 2;

        int64 rightRest = i;
        int64 leftLeft = j - i; // jが大きいほど大きくなる

        if(leftLeft < rightRest) ok = j;
        else ng = j;
      }

      // こっちはleftLeftです
      sub -= 1LL * (uku.sum(ok) - uku.sum(i)) * i;
      sub += 1LL * (beet.sum(ok) - beet.sum(i));

      sub += 1LL * (uku.sum(N - 1) - uku.sum(ok)) * i;

    }

    sub *= 2;
    ret = max(ret, sub + X[i]);
  }

  return ret;
}

int main() {
  cin >> L >> N;
  vector< int > X(N + 1);
  X[0] = 0;
  for(int i = 1; i <= N; i++) cin >> X[i];
  int64 ret = solve(X);
  for(auto &p : X) p = (L - p) % L;
  sort(begin(X), end(X));
  cout << max(ret, solve(X)) << endl;
}

