#define MAX_N 2010

ll L, N;
vector<ll> V;

ll dp[MAX_N][MAX_N][3];

enum Direction { House = 0, Clock = 1, AntiClock = 2 };

// from から to に dir 方向で燃やしにいったときの距離
ll get_dist(ll from, ll to, ll dir) {
    if(dir == AntiClock) {
        if(from < to) { return V[to] - V[from]; }
        return (L - V[from]) + V[to];
    }
    else {
        if(to < from) { return abs(V[to] - V[from]); }
        return (L - V[to]) + V[from];
    }
}

// 反時計で j, 時計 で i がまだ燃えておらず、前回燃やしたのが prev
// のときの最大
ll dfs(ll i, ll j, ll prev) {
    if(i > j) { return 0; }

    ll& ret = dp[i][j][prev];
    if(~ret) { return ret; }

    ll pos = 0;
    if(prev == Clock) { pos = j + 1; }
    else if(prev == AntiClock) { pos = i - 1; }

    // 反時計で燃やす
    ret = dfs(i+1, j, AntiClock) + get_dist(pos, i, AntiClock);
    // 時計で燃やす
    ret = max(ret, dfs(i, j-1, Clock) + get_dist(pos, j, Clock));

    return ret;
}

ll solve() {
    MINUS(dp);
    return dfs(1, N, House);
}

