int main()
{

	int L, n;
	cin >> L >> n;
	vector<int> v(n);
	for (int i = 0; i < n; i++) {
		scanf("%d", &v[i]);
	}
	int f = 0, b = n-1, p = 0;
	LL d = 0;

	for (int i = 0; i < n; i++) {
		// walk to the next furthest tree from current position
		int df = p < v[f] ? v[f]-p : L-p+v[f];
		int db = p < v[b] ? p+L-v[b] : p-v[b];
		if (df > db) {
			d += df;
			p = v[f];
			f = (f+1)%n;
		}
		else {
			d += db;
			p = v[b];
			b = ((b-1)%n+n)%n;
		}
	}
	cout << d << endl;
	exit(0);
}

