int main()
{
    //freopen("data.in","r",stdin);
    cin>>L>>n;
    for(i=1;i<=n;i++)
        cin>>x[i];
        //1-in j
        //0-in i
    x[0]=0;x[n+1]=L;
    for(i=1;i<=n;i++)
        for(j=1;j<=n;j++)
            for(k=0;k<2;k++)
              dp[i][j][k]=-1LL*1e15;
    dp[1][n][0]=dp[1][n][1]=0;
    for(i=1;i<=n;i++)
        for(j=n;j>=i-1;j--)
    {
        dp[i][j-1][1]=max(dp[i][j-1][1],dp[i][j][0]+L-x[j]+x[i-1]);
        dp[i+1][j][0]=max(dp[i+1][j][0],dp[i][j][0]+x[i]-x[i-1]);
        dp[i][j-1][1]=max(dp[i][j-1][1],dp[i][j][1]+x[j+1]-x[j]);
        dp[i+1][j][0]=max(dp[i+1][j][0],dp[i][j][1]+L-x[j+1]+x[i]);
        ans=max(ans,dp[i][j][0]);
        ans=max(ans,dp[i][j][1]);
    }
    cout<<ans;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

const int MX = 200005;

ll ans = 0;

int X[MX];
int L, n;

ll S[MX];
ll SR[MX];

void solve()
{
	/*
	for (int i = 0; i <= n; i++) {
		cout << XX[i] << " ";
	} cout << endl << "--------" << endl;
	*/

	S[0] = 0;
	for (int i = 1; i <= n; i++) {
		S[i] = S[i - 1] + X[i];
	}

	SR[n] = L - X[n];
	for (int i = n - 1; i >= 0; i--) {
		SR[i] = SR[i + 1] + (L - X[i]);
	}

	for (int len = 1; len <= n; len++) {
		ll tmp = 0;

		int i = n - len / 2;

		if (len % 2 == 0) {
			tmp += SR[i+1]*2 - (L-X[i+1]);

			tmp += 2 * S[i];			
			tmp -= 2 * S[n - len];
		}
		else {
			tmp += SR[i+1]*2;

			tmp += 2 * S[i] - X[i];
			tmp -= 2 * S[n - len];
		}

		ans = max(ans, tmp);
	}
}

int main()
{
	ios::sync_with_stdio(false);
	cin.tie(0);

	cin >> L >> n;

	for (int i = 1; i <= n; i++) {
		cin >> X[i];
	}


	solve();

	for (int i = 1; i <= n; i++) {
		X[i] = L - X[i];
	}
	for (int i = 1, j = n; i < j; i++, j--) swap(X[i], X[j]);

	solve();

	cout << ans << "\n";
}

