typedef long long ll;

int main() {
    ll L, N;
    cin >> L >> N;
    vector<ll> X(N);
    for(ll i=0; i<N; i++) cin >> X[i];

    vector<bool> f(N,false);
    ll ans=0;

    ll z=0,i=0;
    while(1){
        ll j,k,d1,d2;
        if(z==0){
            if((L-X[N-1]) > X[0]){
                i = N-1;
                ans += L-X[N-1];
                f[N-1]=true;
            } else {
                i = 0;
                ans += X[0];
                f[0]=true;
            }
            z++;
        }
        else {
            j=i+1; k=i-1;
            while(1){
                if(j==N) j=0;
                if(!f[j]){
                    if(X[i]>X[j]){
                        d1 = L-X[i]+X[j];
                    } else {
                        d1 = X[j]-X[i];
                    }
                    break;
                }
                j++;
            }
            while(1){
                if(k==-1) k=N-1;
                if(!f[k]){
                    if(X[i]<X[k]){
                        d2 = X[i]+L-X[k];
                    } else {
                        d2 = X[i]-X[k];
                    }
                    break;
                }
                k--;
            }
            if(d1>d2){
                ans += d1;
                i = j;
                f[j]=true;
            } else {
                ans += d2;
                i = k;
                f[k]=true;
            }
        }


        bool F=true;
        for(ll i=0; i<N; i++){
            if(!f[i]) F=false;
        }
        if(F) break;
    }

    cout << ans << endl;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long LL;
LL read(){
	LL x=0,f=0;
	char ch=getchar();
	while (!isdigit(ch))
		f|=ch=='-',ch=getchar();
	while (isdigit(ch))
		x=(x<<1)+(x<<3)+(ch^48),ch=getchar();
	return f?-x:x;
}
const int N=200005;
int n,L;
int x[N];
LL tl[N],tr[N];
LL sv(){
	LL ans=0;
	for (int i=1;i<=n;i++)
		tl[i]=tl[i-1]+x[i];
	for (int i=n;i>=1;i--)
		tr[i]=tr[i+1]+L-x[i];
	for (int i=1;i<n;i++){
		int las=max(x[i+1]-x[i],x[i]+L-x[i+1]);
		if (i==n-1){
			ans=max(ans,(LL)x[i]+las);
			continue;
		}
		LL tmp=x[i]+las;
		int d=i-1-(n-i-1);
		if (d>=0){
			tmp+=tl[i-1]*2-tl[d]*2;
			tmp+=tr[i+2]*2;
		}
		else {
//			if (i==2){
//				cout << tl[i-1] << endl;
//				cout << tr[i+2] << endl;
//				cout << tr[n+d+1] << endl;
//				cout << tmp << endl;
//				cout << d << endl;
//			}
			d=-d;
			tmp+=tl[i-1]*2;
			tmp+=tr[i+2]*2-tr[n-d+2]*2;
		}
		ans=max(ans,tmp);
	}
	return ans;
}
int main(){
	L=read(),n=read();
	for (int i=1;i<=n;i++)
		x[i]=read();
	LL ans=sv();
	for (int i=1;i<=n;i++)
		x[i]=L-x[i];
	reverse(x+1,x+n+1);
	ans=max(ans,sv());
	cout << ans;
	return 0;
}

