template <class T>
vector<T> sumup(const vector<T>& a) {
  int N = a.size();
  vector<T> res(N + 1);
  for (int i = 0; i < N; i++) res[i + 1] = res[i] + a[i];
  return res;
}

int main() {
  ll L;
  int N;
  while (cin >> L >> N) {
    vector<ll> X(N);
    for (int i = 0; i < N; i++) cin >> X[i];
    vector<ll> Y(N);
    for (int i = 0; i < N; i++) Y[i] = L - X[i];
    reverse(Y.begin(), Y.end());
    auto Xsum = sumup(X);
    auto Ysum = sumup(Y);
    auto f = [](const vector<ll>& Xsum, const vector<ll>& Ysum, int R, int L) {
      int wR, wL;
      if (R < L) {
        wR = R;
        wL = R + 1;
      } else {
        wR = wL = L;
      }
      return 2 * ((Xsum[R] - Xsum[R - wR]) + (Ysum[L] - Ysum[L - wL]));
    };
    ll res = 0;
    chmax(res, X.back());
    chmax(res, Y.back());
    for (int R = 1; R < N; R++) {
      int L = N - R;
      chmax(res, f(Xsum, Ysum, R - 1, L) + X[R - 1]);
      chmax(res, f(Ysum, Xsum, L - 1, R) + Y[L - 1]);
    }
    cout << res << endl;
  }
  return 0;
}

