using namespace std;
ll L, N;

ll clock_wise(ll current_position, ll target)
{
    if(current_position <= target)
    {
        return target - current_position;
    }
    else if(current_position > target)
    {
        return L - (current_position - target);
    }
    return 0;
}

ll anti_clock_wise(ll current_position, ll target)
{
    if(current_position >= target)
    {
        return current_position - target;
    }
    else if(current_position < target)
    {
        return L - (target - current_position);
    }
    return 0;
}

int main(void)
{
    cin.tie(NULL); ios_base::sync_with_stdio(false);
    cin >> L >> N;

    deque<ll> vec(N, 0);
    for(int i = 0; i < N; i++) { cin >> vec[i]; }


    sort(vec.begin(), vec.end());
    ll ret1 = 0;
    ll current_position = 0;

    while(!vec.empty())
    {
        auto clock_target = vec[0];
        auto anti_clock_target = vec.back();
        if(vec.front() <= current_position && current_position <= vec.back())
        {
            swap(clock_target, anti_clock_target);
        }


        auto clock = clock_wise(current_position, clock_target);
        auto anti_clock = anti_clock_wise(current_position, anti_clock_target);

        if(clock > anti_clock)
        {
            vec.pop_front();
            current_position = clock_target;
            ret1 += clock;
        }
        else
        {
            vec.pop_back();
            current_position = anti_clock_target;
            ret1 += anti_clock;
        }
    }


    cout << ret1 << endl;
    return 0;
}

