  ll ans = 0;
  REP(i, N) {
    cin >> X[i];
    XR[N - 1 - i] = L - X[i];
  }
  REP(i, N) {
    DP[i + 1] = DP[i] + X[i];
    DPR[i + 1] = DPR[i] + XR[i];
  }
  FOR(i, 1, N + 1) {
    ll score = 2 * (DPR[((N - i) / 2) + i] - DPR[i - 1]);
    score += 2 * (DP[((N - i) / 2) + ((N - i) % 2)]);
    if ((N - i) % 2 == 1)
