    else
      score -= XR[((N - i) / 2) + i - 1];
    ans = max(ans, score);
  }
  swap(X, XR);
  swap(DP, DPR);
  FOR(i, 1, N + 1) {
    ll score = 2 * (DPR[((N - i) / 2) + i] - DPR[i - 1]);
    score += 2 * (DP[((N - i) / 2) + ((N - i) % 2)]);
