ll gcd(ll a,ll b) { return b==0?a:gcd(b,a%b); }

const int MAXN=200000;

int len,n;
int x[MAXN];


int a[MAXN];
int b[MAXN];

ll asum[MAXN+1],axsum[MAXN+1];
ll bsum[MAXN+1],bxsum[MAXN+1];


ll calc(int *z,ll *zsum,ll *zxsum,int cnt,int lim) {
	ll ret=0;
	// 2*(cnt-1-j)<=lim -> j>=cnt-1-lim/2
	int upto=max(0,cnt-1-lim/2);
	ret+=zsum[upto]*lim;
	ret-=zsum[upto]*2*(cnt-1)-zxsum[upto]*2;
	ret+=zsum[cnt]*2*(cnt-1)-zxsum[cnt]*2;
	return ret;
}

ll solve1dir() { // last is on the right
	//printf("a:"); REP(i,n) printf(" %d",a[i]); puts("");
	//printf("b:"); REP(i,n) printf(" %d",b[i]); puts("");
	asum[0]=0; REP(i,n) asum[i+1]=asum[i]+a[i];
	bsum[0]=0; REP(i,n) bsum[i+1]=bsum[i]+b[i];
	axsum[0]=0; REP(i,n) axsum[i+1]=axsum[i]+(ll)i*a[i];
	bxsum[0]=0; REP(i,n) bxsum[i+1]=bxsum[i]+(ll)i*b[i];

	ll ret=LLONG_MIN;
	REP(i,n) {
		int na=i+1,nb=n-na;
		// last on a side gets 1, one before 3, one before 6, etc. up to 2*min(na,nb)-1
		// last on b side gets 2, one before 4, one before 6, etc. up to 2*min(na,nb)
		ll cur=0; int alim=na>nb?2*nb+1:2*na+1,blim=2*min(na,nb);
		cur+=asum[na];
		cur+=calc(a,asum,axsum,na,alim-1);
		cur+=2*bsum[nb];
		if(nb>0) cur+=calc(b,bsum,bxsum,nb,blim-2);
		//REP(j,na) cur+=(ll)a[na-1-j]*min(2*j+1,alim);
		//REP(j,nb) cur+=(ll)b[nb-1-j]*min(2*j+2,blim);
		ret=max(ret,cur);
		//printf("na=%d nb=%d -> %lld (alim=%d,blim=%d)\n",na,nb,cur,alim,blim);
	}

	return ret;
}

ll solve() {
	REP(i,n) a[i]=x[i]; for(int i=n-1;i>=1;--i) a[i]-=a[i-1];
	REP(i,n) b[i]=len-x[n-i-1]; for(int i=n-1;i>=1;--i) b[i]-=b[i-1];
	ll opt1=solve1dir();
	REP(i,n) swap(a[i],b[i]);
	ll opt2=solve1dir();
	return max(opt1,opt2);
}

void run() {
	scanf("%d%d",&len,&n);
	REP(i,n) scanf("%d",&x[i]);
	printf("%lld\n",solve());
}

int main() {
	run();
	return 0;
}

