ll gett(int l, int r)
{
    if (l > r) return 0;
    //if (l < 0) cerr << "BAD!!\n";
    return (pref[r + 1] - pref[l]);
}

ll solve()
{
    //for (int i = 0; i < n; i++)
    //    cerr << a[i] << " ";
    //cerr << "\n";
    pref[0] = 0;
