    for(int i=1;i<=N;i++) r[i] = L - l[N-i+1];

    for(int i=0;i<N;i++) sl[i+1] = sl[i] + l[i+1], sr[i+1] = sr[i] + r[i+1];

    lint ans = -1;
    for(int i=1;i<=N;i++){
        lint cur;
        // 反時計回り
        cur = 2 * (sl[i+(N-i)/2]-sl[i-1]+sr[(N-i+1)/2]);
        if((N-i)%2) cur -= r[(N-i+1)/2];
