template<typename tp> inline void read(tp &x) {
  x = 0; char c = getchar(); int f = 0;
  for (; c < '0' || c > '9'; f |= c == '-', c = getchar());
  for (; c >= '0' && c <= '9'; x = (x << 3) + (x << 1) + c - '0', c = getchar());
  if (f) x = -x;
}
#define int long long
const int N = 3e5 + 2334;
int sum[N], sub[N], pos[N];
int ans, n, L;

inline int get(int *s, int l, int r) {
  if (l > r) return 0;
  return s[r] - s[l - 1];
}

inline int doit() {
  int ans = 0;
  rep (i, n) sum[i] = sum[i - 1] + pos[i], sub[i] = sub[i - 1] + L - pos[i];
  for (int cut = 1; cut <= n; cut ++) {
    int now = 2 * pos[cut - 1];
    int res_num = n - cut + 1;
    int id = res_num & 1 ? res_num / 2 + 1 : res_num / 2;
    id += cut - 1;
    // cout << id << " " << now << " " << (get(sum, cut, id - 1) + get(sub, id, n)) * 2 << " " << res_num << "\n";
    if (res_num & 1) {
      now += get(sum, cut, id - 1) * 2
        + get(sub, id, n) * 2 - (L - pos[id]);
    } else {
      now += get(sum, cut, id) * 2
        + get(sub, id + 1, n) * 2 - pos[id];
    }
    // cout << cut << " " << now << "\n";
    ans = max(ans, now);
  }
  return ans;
}

signed main(void) {
  read(L); read(n);
  rep (i, n) read(pos[i]);
  ans = max(ans, doit());
  rep (i, n) pos[i] = L - pos[i];
  reverse(pos + 1, pos + n + 1);
  ans = max(ans, doit());
  cout << ans << "\n";
}

