		return 0;
	}
	if (was[f][t].find(make_pair(l, r))!= was[f][t].end()) {
		return was[f][t][make_pair(l, r)];
	}	
	long long ans = 0;
	if (f == 1) {
		chkmax(ans, get(l, r - 1, 1, t + 1) + x[r] - x[r - 1]);
		chkmax(ans, get(l, r - 1, 0, t) + L - x[r] + x[l]);
	} else {
		chkmax(ans, get(l + 1, r, 0, t + 1) + x[l + 1] - x[l]);
		chkmax(ans, get(l + 1, r, 1, t) + x[l] + L - x[r]);
	}
	was[f][t][make_pair(l, r)] = ans;
	return ans;
}	


