    lld l,n,i,j,x[200000],left,right,indexl,indexr,c;
    cin>>l>>n;
    for(i=0;i<n;++i){
        cin>>x[i];
    }

    sort(x,x+n);

    indexl = 0;
    indexr = n-1;
    left = x[0];
    right = l - x[n-1];
    lld ans = 0;
    lld flag = 2;
    c = 0;
    while(c < n){
        if(left > right || flag == 1){
            c++;
//            cout<<"LEFT\n";
            ans += left;
//            cout<<"Adding left: "<<left<<endl;
            right += left;
            indexl++;
            left = x[indexl] - x[indexl-1];
            flag = 2;
//            cout<<"RIGHT: "<<right<<"  ,LEFT:"<<left<<endl;
        }else if(left < right || flag == 0){
            c++;
//            cout<<"RIGHT\n";
//            cout<<"Adding right: "<<right<<endl;
            ans += right;
            left += right;
            right = x[indexr] - x[indexr-1];
            indexr--;
            flag = 2;
//            cout<<"RIGHT: "<<right<<"  ,LEFT:"<<left<<endl;
        }else{
            flag = 0;
            for(i=0;i<(n-c);++i){
                lld newl = (x[indexl+1+i] - x[indexl]);
                lld newr = (x[indexr] - x[indexr-1-i]);
                if(newl > newr){
                    flag = 1;
                    break;
                }else if(newl < newr){
                    flag = 0;
                    break;
                }
            }
        }
    }

    cout<<ans;

    return 0;
}

