void dfs(int cur, long long dist, vector<bool> vis) {
	bool all = true;
	vector<bool> v = vis;
	for(int i = 0; i < n + 1; i++) {
		if(!vis[i]) all = false;
			//cerr << vis[i] << " ";
	}
		//cerr << endl;
	if(all) {
		ans.push_back(dist);
			//cerr << "dist" << dist << endl;
		return;
	}
	bool f = false;
	for(int i = cur; i < n + 1; i++) {
		if(!vis[i]) {
			v[i] = true;
				//cerr << t[i] << endl;
			dfs(i, dist + t[i] - t[cur], v);
			v[i] = false;
			f = true;
			break;
		}
	}
	if(!f) {
		for(int i = 0; i < n + 1; i++) {
			if(!vis[i]) {
			  v[i] = true;
				  //cerr << t[i] << endl;
			  dfs(i, dist + t[i] + l - t[cur], v);\
				v[i] = false;
				break;
			}
		}
	}
	for(int i = cur; i >= 0; i--) {
		if(!vis[i]) {
			v[i] = true;
				//cerr << t[i] << endl;
			dfs(i, dist + t[cur] - t[i], v);
			return;
			v[i] = false;
		}
	}
	for(int i = n; i >= cur; i--) {
		if(!vis[i]) {
			v[i] = true;
			   //cerr << t[i] << endl;
			dfs(i, dist + t[cur] + l - t[i], v);
			return;
		}
	}
}


