signed main() {
    int L, N;

    cin >> L >> N;

    int X[N];
    for (int i = 0; i < N; i++) cin >> X[i];

    int dp[2][N+1][N+1];
    for (int i = 0; i < 2; i++) {
        for (int j = 0; j <= N; j++) {
            for (int k = 0; k <= N; k++) {
                dp[i][j][k] = -1;
            }
        }
    }

    dp[0][1][0] = X[0];
    dp[1][0][1] = L - X[N-1];

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            if (i == 0 && j == 0) continue;
            if (i + j >= N) continue;

            if (i > 0) {
                dp[0][i+1][j] = max(dp[0][i+1][j], dp[0][i][j] + X[i] - X[i-1]);
                dp[1][i][j+1] = max(dp[1][i][j+1], dp[0][i][j] + X[i-1] + (L - X[N - 1 - j]));
            }

            if (j > 0) {
                dp[0][i+1][j] = max(dp[0][i+1][j], dp[1][i][j] + (L - X[N - 1 - (j - 1)] + X[i]));
                dp[1][i][j+1] = max(dp[1][i][j+1], dp[1][i][j] + X[N - 1 - (j - 1)] - X[N - 1 - j]);
            }
        }
    }

    int ret = -777;

    for (int i = 0; i <= N; i++) {
        for (int j = 0; j <= N; j++) {
            if (!(i + j == N)) continue;

            ret = max(ret, dp[0][i][j]);
            ret = max(ret, dp[1][i][j]);
        }
    }

    cout << ret << endl;

    return 0;
}

