	REP(i, n) c[i + 1] = c[i] + d[i];

	int ans = 0;
	int now = 0;
	int r = n;
	REP(i, n) {
		int l = n - 1 - i;
		now += c[l] - c[0];
		now -= c[r] - c[l];
		if (i % 2 == 0) --r;
		now += c[n] - c[r];
		CHMAX(ans, now);
	}
	return ans;
}

