void init() {
	ps.resize(v.size() + 1);
	for (int i = 0; i < (int)v.size(); i++) {
		ps[i + 1] = ps[i] + v[i];
	}
}

int sm(int l, int r) {
	r++;
	if (l >= r) return 0;
	return ps[r] - ps[l];
}

int proc(int l, int r, int dir) {
	//0-l
	//1-r
	int c = (r - l);
	int t = n - c;
	if (t == 0) return 0;
	int ans = 0;
	if (!dir) {
		dir ^= (t % 2);
		int rl = (l - (t + 1) / 2);
		int rr = (r + t / 2);
		ans = sm(rl, l - 1) + sm(r + 1, rr);
		ans *= 2;
		if (!dir) ans -= v[rr];
		else ans -= v[rl];
		ans += v[r];
	} else {
		dir ^= (t % 2);
		int rl = (l - t / 2);
		int rr = (r + (t + 1) / 2);
		ans = sm(rl, l - 1) + sm(r + 1, rr);
		ans *= 2;
		if (!dir) ans -= v[rr];
		else ans -= v[rl];
		ans += v[l];
	}
	return ans;
}

int sr() {
	int l = n;
	int r = n;
	int c = 0;
	int ans = 0;
	for (int i = 0; i <= n; i++) {
		c = v[i + n];
		ans = max(ans, c + proc(l, r, 0));
		r++;
	}
	return ans;
}

int sl() {
	int l = n;
	int r = n;
	int c = 0;
	int ans = 0;
	for (int i = 0; i <= n; i++) {
		c = v[n - i];
		ans = max(ans, c + proc(l, r, 1));
		l--;
	}
	return ans; 
}


