int64_t solve_greedy(const vector<int64_t>& x, int64_t l, int first, int last, int64_t pos) {
    if (first > last) {
        return 0;
    }

    int64_t dist_first = x[first] - pos;
    if (dist_first < 0) {
        dist_first += l;
    }

    int64_t dist_last = pos - x[last];
    if (dist_last < 0) {
        dist_last += l;
    }

#if 0
    if (dist_first < dist_last) {
        return dist_last + solve_greedy(x, l, first, last - 1, x[last]);
    } else if (dist_first > dist_last) {
        return dist_first + solve_greedy(x, l, first + 1, last, x[first]);
    } else {
        auto left_dist = solve_greedy(x, l, first + 1, last, x[first]);
        auto right_dist = solve_greedy(x, l, first, last - 1, x[last]);

        return dist_first + max(left_dist, right_dist);
    }
#else
    if (dist_first <= dist_last) {
        return dist_last + solve_greedy(x, l, first, last - 1, x[last]);
    } else {
        return dist_first + solve_greedy(x, l, first + 1, last, x[first]);
    }
#endif
}

struct Key {
    int64_t first;
    int64_t last;
    int64_t prev_dir;

    bool operator==(const Key& other) const {
        return first == other.first && last == other.last && prev_dir == other.prev_dir;
    }
};

struct KeyHasher {
    size_t operator()(const Key& key) const {
        auto h = (key.first << 32);
        h += key.prev_dir * key.last;
        return h;
    }
};

int64_t solve(const vector<int64_t>& x, int64_t l, int64_t dist, int first, int last, int prev) {
    static unordered_map<Key, int64_t, KeyHasher> memo;
    static int64_t lower = solve_greedy(x, l, first, last, 0);

    if (first > last) {
        return 0;
    }

    Key key{first, last, (prev < first ? -1 : 1)};

    if (dist + (last - first + 1) * l < lower) {
        // cerr << "pruned: " << first << " " << last << " " << prev << " " << key.prev_dir << " " << lower << " " << dist << " " << (last - first + 1) * l << endl;
        return -1;
    }

    if (memo.count(key) > 0) {
        // cerr << "memo: " << first << " " << last << " " << prev << " " << key.prev_dir << " " << memo[key] << endl;
        return memo[key];
    }

    auto pos = (prev == -1 ? 0 : x[prev]);
    auto dist_first = x[first] - pos;
    if (dist_first < 0) {
        dist_first += l;
    }
    auto tmp_f = solve(x, l, dist + dist_first, first + 1, last, first);
    dist_first += tmp_f;

    auto dist_last = pos - x[last];
    if (dist_last < 0) {
        dist_last += l;
    }
    auto tmp_l = solve(x, l, dist + dist_last, first, last - 1, last);
    dist_last += tmp_l;

    if (tmp_f == -1 && tmp_l == -1) {
        // not record to memo
        return -1;
    }

    auto ret = max(dist_first, dist_last);
    memo[key] = ret;

    // cerr << first << " " << last << " " << prev << " " << key.prev_dir << " " << dist_first << " " << dist_last << endl;

    if (dist + ret < lower) {
        // cerr << "pruned2: " << first << " " << last << " " << prev << " " << key.prev_dir << " " << lower << " " << dist << " " << (last - first + 1) * l << endl;
        return -1;
    }

    lower = dist + ret;

    return ret;
}

main() {
    int64_t l, n;
    cin >> l >> n;

    vector<int64_t> x(n);
    for (auto&& xx : x) {
        cin >> xx;
    }

    cout << solve(x, l, 0, 0, n - 1, -1) << endl;
}

