long keisan(long x[], int z[]){
    long y[N + 1];
    y[0] = x[0];
    for(int i = 1; i < N; i++){
        y[i] = x[i] - x[i-1];
    }
    y[N] = L - x[N-1];

    long len1 = 0;
    for(int i = 0; i < N + 1; i++){
        len1 += y[i] * z[i];
    }

    long ans = len1;
    for(int i = 1; i < N / 2 + 1; i++){
        len1 += myfunc(i, x);
        if(len1 > ans)
            ans = len1;
    }
    return ans;
}

