ll N, L;

ll calc_d(ll a, ll b, bool rcloc){
    if(a > b) return calc_d(b, a, !rcloc);
    ll ans;
    if(rcloc){
        ans = ((b - a) + L) % L;
    }
    else{
        ans = ((a - b) + L) % L;
    }

    return ans;
}

void solve(istream &cin) {
    L = 0; N = 0;
    cin >> L >>  N;
    if(!cin) return;
    vector<ll> X(N);
    cin >> X;
    X.push_back(0);
    vector<vector<ll>> dp1(N+1, vector<ll>(N+1, -1));
    dp1[0][0] = 0;
    auto dp2 = dp1;
    sort(X.begin(), X.end());

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N - i; ++j) {
            ll ds = dp1[i][j];
            if(ds != -1){
                ll now = X[i];
                ll d = calc_d(now, X[i+1], true);
                dp1[i+1][j] = max(dp1[i+1][j], d + ds);
                d = calc_d(now, X[N - j], false);
                dp2[i][j+1] = max(dp2[i+1][j], d + ds);
            }

            ds = dp2[i][j];
            if(ds != -1){
                ll now = j == 0 ? 0 : X[N - j + 1];
                ll d = calc_d(now, X[i+1], true);
                dp1[i+1][j] = max(dp1[i+1][j], d + ds);
                d = calc_d(now,  X[N - j], false);
                dp2[i][j+1] = max(dp2[i][j+1], d + ds);
            }
        } // end j

    } // end i
    ll ans = 0;
    for (int i = 0; i <= N; ++i) {
        ans = max({ans, dp1[i][N-i], dp2[i][N-i]});
    } // end i
    cout << ans << endl;

}

