class Solve {
public:
    void input() {

    }

    ll calc(vector<ll> X, ll L) {


        //L = 1 => n
        int n = X.size();
        ll val = L - X[0];
        ll ret = val;
        for (int i = 1; i < n; ++i) {
            val += L;
            val -= 2 * X[i];
            if (i % 2) {
                val += 2 * X[i / 2];
            } else {
                val += X[i / 2 - 1];
                val += X[i / 2];
            }

            chmax(ret, val);
        }

        val = X[n - 1];
        int state = 1;   //pt1かpt2か
        int pt1 = n - 1; //ひとつを-2
        int pt2 = n - 1; //ふたつを-1
        for (int i = n - 2; i >= 0; --i) {
            val += L;
            val += 2 * X[i];
            if (state == 1) {
                state = 2;
                val -= 2 * X[pt1];
                pt1--;
            } else {
                state = 1;
                val -= X[pt2];
                val -= X[pt2 - 1];
                pt2--;
            }

            chmax(ret, val);
        }

        return ret;
    }

    void solve() {
        input();
        ll L;
        int N;
        cin >> L >> N;

        vector<ll> X(N);
        rep(i, 0, N) cin >> X[i];

        ll ans = calc(X, L);
        cout << ans << endl;
    }
};


