constexpr size_t SIZE = 200000;
int x[SIZE];
i64 dc[SIZE], da[SIZE];

int main() {
    i64 l, n;
    cin >> l >> n;

    if (n == 1) {
        i64 x;
        cin >> x;
        cout << max(x, l-x) << endl;
        return 0;
    }

    for (int i = 0; i < n; ++i) {
        cin >> x[i];
    }

    for (int i = 0; i < n-1; ++i) {
        i64 d = x[i+1] - x[i];
        d = max(d, l-d);
        dc[i] = da[i+1] = d;
    }

    for (int len = 2; len <= n-1; ++len) {
        i64 da_t = da[len-1];
        for (int i = 0; i+len < n; ++i) {
            i64 c = x[i+1] - x[i] + dc[i+1];
            i64 a = l + x[i] - x[i+len] + da[i+len];
            i64 dc_t = max(c, a);

            c = l + x[i] - x[i+len] + dc[i];
            a = x[i+len] - x[i+len-1] + da[i+len-1];
            da[i+len-1] = da_t;
            da_t = max(c, a);
            dc[i] = dc_t;
        }
        da[n-1] = da_t;
    }

    i64 c = x[0] + dc[0];
    i64 a = l - x[n-1] + da[n-1];
    cout << max(c, a) << endl;

    return 0;
}

