void readx(inp_t& x)
{
	x=0; int k=1; char ch=0;
	while (ch<'0' || ch>'9') { ch=getchar(); if (ch=='-') k=-1; }
	while (ch>='0' && ch<='9') { x=x*10+ch-'0'; ch=getchar(); }
	x*=k;
}

int GetDist(ll nx,ll tx,ll dir)
{
	ll ret=0;
	if (dir==1) 
	{
		ret=tx-nx;
		if (ret<0) ret+=L;
	}
	else
	{
		ret=nx-tx;
		if (ret<0) ret+=L;
	}
	return ret;
}

int main()
{
	readx(L); readx(n); 
	for (int i=1;i<=n;i++) readx(pos[i]);

	for (int i=1;i<=n;i++) // len
	{
		for (int j=1;j<=i+1;j++) // left offset
		{
			int l=j,r=n-(i-j+1);
			dp[l][r][0]=max(dp[l-1][r][0]+GetDist(pos[l-1],pos[l],1),
							  dp[l][r+1][1]+GetDist(pos[r+1],pos[l],1)); // in positive position
			dp[l][r][1]=max(dp[l-1][r][0]+GetDist(pos[l-1],pos[r],-1),
							  dp[l][r+1][1]+GetDist(pos[r+1],pos[r],-1)); // in negetive position
		}
	}

	for (int i=1;i<=n;i++) ans=max({ans,dp[i][i][0],dp[i][i][1]});
	printf("%lld\n",ans);
}

