	rep(i, n) {
		if (i <= (n - 1) / 2)sum += x[i];
		else sum += l - x[i];
	}
	sum *= 2;
	if (n & 1) {//ki
		sum -= x[n / 2];
		res = max(res,sum);
		rep(i, n-2) {
			sum -= 2 * x[i];
			if (i & 1) {
				sum -= l - x[n / 2 + i/2+1];
				sum += x[n / 2 + i / 2+1];
				res = max(res, sum);
			}
			else {
				sum += x[n / 2 + i / 2];
				sum -= l-x[n / 2 + i / 2+1];
				res = max(res, sum);
			}
		}
	}

	else {
		sum -= l - x[n / 2];
		res = max(res,sum);
		rep(i, n-2) {
			sum -= x[i] * 2;
			if (i & 1) {
				sum += x[n / 2 + i / 2+1];
				sum -= x[n / 2 + i/ 2];
				res = max(res, sum);
			}
			else {
				sum -= l - x[n / 2 + i/2];
				sum += x[n / 2 + i/2];
				res = max(res, sum);
			}
		}
	}
