int n,L,a[N],pre[N],suf[N]; 
signed main(){
	scanf("%lld%lld",&L,&n);
	for (int i=1;i<=n;i++) scanf("%lld",&a[i]);
	for (int i=1;i<=n;i++) {
		pre[i]=pre[i-1]+a[i];
		suf[i]=suf[i-1]+L-a[i];
	}
	int ans=max(a[n],L-a[1]);
	for (int i=1;i<=n;i++){
		int l=i+1,r=n,len=(r-l+1)/2;
		if (l<=r){
			int tmp=2*a[i];
			tmp+=2*(pre[l+len-1]-pre[l-1]);
			tmp+=2*(suf[r]-suf[r-len]);
			if(len*2==r-l+1) tmp-=a[l+len-1];
			else tmp+=L-a[l+len];
			ans=max(ans,tmp);
		}
		l=1,r=i-1,len=(r-l+1)/2;
		if (l<=r){
			int tmp=2*(L-a[i]);
			tmp+=2*(pre[l+len-1]-pre[l-1]);
			tmp+=2*(suf[r]-suf[r-len]);
			if (len*2==r-l+1) tmp-=L-a[l+len];
			else tmp+=a[l+len];
			ans=max(ans,tmp);
		}
	}
	printf("%lld\n",ans);
	return 0;
}

