	x.resize(N);
	long long a_x = 0;
	long long b_x = N - 1;
	REP(i, N) {
		cin >> x[i];
	}

	while (1) {
		if (nowX < x[a_x]) {
			l = x[a_x] - nowX;
		}
		else {
			l = x[a_x] + L - nowX;
		}

		if (nowX > x[b_x]) {
			l_inv = nowX - x[b_x];
		}
		else {
			l_inv = nowX + L - x[b_x];
		}
		if (l > l_inv) {
			sum += l;
			nowX = x[a_x];
			++a_x;
		}
		else {
			sum += l_inv;
			nowX = x[b_x];
			--b_x;
		}
		if (b_x < a_x)break;
	}

	cout << sum << endl;

