LL rec(LL i, LL j) {
    if (i == j) return 0;
    if (dp[i][j] >= 0) return dp[i][j];

    if (i < j) {
	amax(dp[i][j], rec(i+1, j) + A[i+1] - A[i]);
	amax(dp[i][j], rec(j, i+1) + A[i] + (L - A[j]));
    } else {
	amax(dp[i][j], rec(i-1, j) + A[i] - A[i-1]);
	amax(dp[i][j], rec(j, i-1) + (L - A[i]) + A[j]);
    }

    return dp[i][j];
}

