int dfs(int i, int j, bool l) {
    if (dp[i][j][l] >= 0)return dp[i][j][l];
    int now;
    if (l)now = A[i - 1];
    else now = A[j + 1];

    if (i == j) {
        int va = abs(A[i] - now);
        int kota = max(L - (va), va);
        return kota;
    }
    int res = -1;
    //反時計回りに移動
    //自分の近くにあるなら
    int dis = 0;
    //原点の反対
    if (A[i] < now)dis = A[i] + L - now;
    else dis = A[i] - now;
    chmax(res, dfs(i + 1, j, 1) + dis);

    //時計回り
    dis = 0;
    //原点の反対
    if (A[i] > now)dis = now + L - A[j];
    else dis = now - A[j];
    chmax(res, dfs(i, j - 1, 0) + dis);
    return dp[i][j][l] = res;
}
