using namespace std;
long long int L; 
int N; 
long long int solve(long long int A[200010]){
	long long int Dir[200010] = {}; // 1を出発・iをindexが減る向きにゴールするときの最小値
	Dir[2] = L - A[2] + A[1]; 
	for(int i = 3; i <= N/2+1; i++){
		Dir[i] = Dir[i-1] + L*2 - 3 * (A[i]-A[i-1]) - 2 * (A[i*2-2]-A[i*2-3]) - 4 * (A[i*2-3]-A[i]);
	}
	Dir[N] = L - A[1] - A[N] + 2*A[N-1]; 
	for(int i = N-1; i > N/2+1; i--){
		Dir[i] = Dir[i+1] + L*2 - (A[i+1]-A[i]) - 2 * (A[i*2-N]-A[i*2-N-1]) - 4 * (A[i]-A[i*2-N]);
	}
	long long int ans = 0; 
	for(int i = 2; i <= N; i++){
		ans = max(ans, Dir[i]); 
	}
	return ans;  
}
int main(){
	cin >> L >> N; 
	long long int X[200010] = {}; 
	for(int i = 1; i <= N; i++){
		cin >> X[i];
	}
	long long int Y[200010] = {}; 
	long long int Z[200010] = {}; 
	long long int W[200010] = {}; 
	for(int i = 2; i <= N; i++){
		Y[i] = X[1] + L - X[N+2-i]; 
		Z[i] = X[N] - X[N+1-i];
		W[i] = X[i-1] + L - X[N]; 
	}
	X[N+1] = L+X[1]; Y[N+1] = L+Y[1];
	Z[N+1] = L+Z[1]; W[N+1] = L+W[1];
	long long int a = X[1] + solve(X); 
	long long int b = X[1] + solve(Y); 
	long long int c = L - X[N] + solve(Z); 
	long long int d = L - X[N] + solve(W); 
	cout << max({a,b,c,d}) << endl; 
}

