        pref[i] = pref[i - 1] + d[i];
    }
    d[n + 1] = L - x[n];
    pref[n + 1] = pref[n] + d[n];
    suf[0] = 0;
    for (int i = 1; i <= n + 1; i++) {
        suf[i] = suf[i - 1] + d[n + 2 - i];
    }
    ll ans = 0;
    for (int l = 0; l <= n; l++) {
        for (int r = 0; l + r <= n; r++) {
            for (int flag = 0; flag < 2; flag++) {
                if (l + r == n) {
                    ans = max(ans, dp[l][r][flag]);
                    //cout << l << " " << r << " " << dp[l][r][flag] << endl;
                    continue;
                }
                if (flag == 0) {
                    dp[l + 1][r][0] = max(dp[l + 1][r][0], dp[l][r][0] + d[l + 1]);
                    dp[l][r + 1][1] = max(dp[l][r + 1][1], dp[l][r][0] + suf[r + 1] + pref[l]);
                }
