                    dp[l][r + 1][1] = max(dp[l][r + 1][1], dp[l][r][1] + d[n + 1 - r]);
                    dp[l + 1][r][0] = max(dp[l + 1][r][0], dp[l][r][1] + suf[r] + pref[l + 1]);
