template <class T> using reversed_priority_queue = priority_queue<T, vector<T>, greater<T> >;
typedef long long ll;

ll L,N;
ll X[200010];

int main ()
{
    cin >> L >> N;
    REP(i,N) cin >> X[i];

    deque < ll > que_t;
    REP(i,N) que_t.push_back (X[i]);
    reversed_priority_queue < pair < pair < ll,ll >, deque < ll > > > beam;
    beam.push(make_pair(make_pair(0, 0), que_t));

    REP(i,N) {
        reversed_priority_queue < pair < pair < ll,ll >, deque < ll > > > beam_nxt;
        while (beam.size() > 0) {
            ll ans = beam.top().first.first;
            ll cur = beam.top().first.second;
            deque < ll > que = beam.top().second;
            beam.pop();
            if (ans == 0) {
                ll diff_f = que.front();
                ll diff_b = L - que.back();
                if (diff_f >= diff_b) {
                    ans += diff_f;
                    cur = que.front();
                    que.pop_front();
                } else {
                    ans += diff_b;
                    cur = que.back();
                    que.pop_back();
                }
                beam_nxt.push(make_pair(make_pair(ans, cur), que));
            } else {
                ll diff_f = 0;
                ll diff_b = 0;

                if (que.front() > cur) diff_f = que.front() - cur;
                else diff_f = L - cur + que.front();

                if (que.back() < cur) diff_b = cur - que.back();
                else diff_b = cur + L - que.back();

                ll ans1 = ans;
                ll cur1 = cur;
                deque < ll > que1 = que;

                ans += diff_f;
                cur = que.front();
                que.pop_front();
                beam_nxt.push(make_pair(make_pair(ans, cur), que));

                ans1 += diff_b;
                cur1 = que1.back();
                que1.pop_back();
                beam_nxt.push(make_pair(make_pair(ans1, cur1), que1));
            }

            while (beam_nxt.size() > 10000) {
                beam_nxt.pop();
            }
        }
        beam = beam_nxt;
    }

    ll ans = 0;
    while (beam.size() > 0) {
        ans = max(ans, beam.top().first.first);
        beam.pop();
    }

    cout << ans << endl;

    return 0;
}

