ll get_left(int s,int t)
{
	s=max(s,0);
	t=min(t,n-1);
	if(s>t) return 0;
	return  rt[t]-(s==0?0:rt[s-1]);
}
ll get_right(int s,int t)
{
	s=max(s,0);
	t=min(t,n-1);
	if(s>t) return 0;
	ll sum=get_left(s,t);
	return (ll) L*(ll) (t-s+1)-sum;
}
