    L = 10, N = 6;
    X = vector<ll>{1, 2, 3, 6, 7, 9};
}

ll solve() {
    ll ans = 0;
    for (ll i = 0; i < N * 2; i++) {
        ll k = i % N;
        bool fleft = i < N;
        ll cans = fleft ? X[k] : L - X[k];
        ll left = fleft ? k + 1 : 0;
        ll right = fleft ? N - 1 : k - 1;
        ll pos = k;
        bool toleft = !fleft;
        while (left <= right) {
            if (toleft) {
                cans += (L + X[left] - X[pos]) % L;
                pos = left;
                left++;
            } else {
                cans += (L + X[pos] - X[right]) % L;
                pos = right;
                right--;
            }
            toleft = !toleft;
        }
        ans = max(ans, cans);
    }
    return ans;
}


