ll dp[2010][2010];

using Cost = ll;
struct Edge{
    Cost cost;
    int last, far;
    bool operator>(const Edge &right)const{
        return cost > right.cost;
    }
    bool operator<(const Edge &right)const{
        return cost < right.cost;
    }
};

// priority_queue<Edge,vector<Edge>,greater<Edge>> qu;
priority_queue<Edge,vector<Edge>> qu;

void update(int last, int far, ll cost) {
    if (dp[last][far] < cost) {
        dp[last][far] = cost;
        qu.push({cost, last, far});
    }
}

int main(void){
    cin >> L >> n;
    x.resize(n+2);
    rep1(i,n) cin >> x[i];
    x[0] = 0, x[n+1] = L;
    if (n > 2000) return 0;

    dp[0][n+1] = dp[n+1][0] = 0;

    qu.push({0,0,n+1});
    qu.push({0,n+1,0});
    while(qu.size()){
        Edge cur = qu.top(); qu.pop();
        int last = cur.last;
        int far = cur.far;
        if (dp[last][far] > cur.cost) continue;
        if (abs(last - far) == 1) continue;

        // 反時計
        if (last < far) {
            update(last+1, far, dp[last][far] + x[last+1]-x[last]);
            update(far-1, last, dp[last][far] + L - (x[far-1]-x[last]));
        }
        // 時計
        else {
            update(last-1, far, dp[last][far] + x[last]-x[last-1]);
            update(far+1, last, dp[last][far] + L - (x[last]-x[far+1]));
        }
    }
    ll res = 0;
    rep(i,n+1){
        res = max({res, dp[i][i+1], dp[i+1][i]});
    }
    cout << res << endl;

    return 0;
}

