const int N = 2e5+7;
int x[N];
deque<int> q;
ll check(int s, int l, int n)
{
	int p = 0;
	ll res = 0;
	for(int i = 1; i <= n; i++)
	{
		q.push_back(x[i]);
	}
	for(int i = 0; i < min(5, n); i++)
	{
		if(s&(1<<i))
		{
			int qb = q.back();
			res += p > qb ? p-qb : p+l-qb;
			q.pop_back();
			p = qb;
		}
		else
		{
			int qf = q.front();
			res += p < qf ? qf-p : l-p+qf;
			q.pop_front();
			p = qf;
		}
	}
	while(q.size())
    {
		int qf = q.front(), qb = q.back();
		int disb = p < qf ? qf-p : l-p+qf;
		int dise = p > qb ? p-qb : p+l-qb;
		if(disb>dise)
		{
		    p = qf;
			res += disb;
			q.pop_front();
		}
		else
		{
			p = qb;
			res += dise;
		    q.pop_back();
		}
	}
	return res;
}
