long long L, N;
vector<long long> X;

long long solve0(long long N, long long L, vector<long long> &X){
    vector<long long> Y(N+2, 0);
    for(long long i=1; i<=N; i++)
        Y[i] = Y[i-1] + X[i];

    long long ret = 0;
    for(long long i=1; i<N; i++){
        long long k = min(i, N-i);
        long long left = 2*(Y[i] - Y[i-k]);
        long long mid = L-X[i+1];
        long long right = 2*(-Y[i+k]+Y[i+1])+2*(k-1)*L;
        ret = max(ret, left+mid+right);
    }
    return ret;
}

long long solve1(long long N, long long L, vector<long long> &X){
    vector<long long> Y(N+2, 0);
    for(long long i=1; i<=N; i++)
        Y[i] = Y[i-1] + X[i];

    long long ret = 0;
    for(long long i=1; i<N; i++){
        long long k = min(i, N-i+1);
        long long left = X[i] + 2*(Y[i-1] - Y[i-k]);
        long long right = 2*(-Y[i+k-1]+Y[i])+2*(k-1)*L;
        ret = max(ret, left+right);
    }
    return ret;
}

int main(){
    cin >> L >> N;
    X.resize(N+2, 0);
    for(long long i=1; i<=N; i++)
        cin >> X[i];

    long long ans = 0;
    ans = max(ans, solve0(N, L, X));
    ans = max(ans, solve1(N, L, X));
    for(int i=1; i<=N; i++)
        X[i] = L - X[i];
    reverse(X.begin(), X.end());
    ans = max(ans, solve0(N, L, X));
    ans = max(ans, solve1(N, L, X));
    cout << ans << endl;
    return 0;
}

