/*----------------------------------------*/

int main() {
  cin.tie(0); ios::sync_with_stdio(false);
  // freopen("input.txt", "r", stdin);

  int l, n; cin >> l >> n;
  vector<int> x(n+1, 0), rev_x(n+1, 0); // 1-index
  FOR(i, 1, n+1) cin >> x[i];
  FOR(i, 1, n+1) rev_x[i] = l - x[n+1-i];
  vector<long long> anticlockwise(n+1, 0), clockwise(n+1, 0);
  REP(i, n) {
    anticlockwise[i+1] = anticlockwise[i] + x[i+1];
    clockwise[i+1] = clockwise[i] + rev_x[i+1];
  }
  long long ans = 0;
  REP(i, n-1) {
    long long tmp = -anticlockwise[i] * 2;
    if ((n-i) % 2 == 1) tmp += (anticlockwise[i+(n-i)/2] + clockwise[(n-i)/2]) * 2 + x[i+(n-i)/2+1];
    else tmp += (anticlockwise[i+(n-i)/2] + clockwise[(n-i)/2-1]) * 2 + rev_x[(n-i)/2];
    ans = max(ans, tmp);
  }
  ans = max(ans, (long long)x[n]);
  REP(i, n) {
    anticlockwise[i+1] = anticlockwise[i] + rev_x[i+1];
    clockwise[i+1] = clockwise[i] + x[i+1];
  }
  REP(i, n-1) {
    long long tmp = -anticlockwise[i] * 2;
    if ((n-i) % 2 == 1) tmp += (anticlockwise[i+(n-i)/2] + clockwise[(n-i)/2]) * 2 + rev_x[i+(n-i)/2+1];
    else tmp += (anticlockwise[i+(n-i)/2] + clockwise[(n-i)/2-1]) * 2 + x[(n-i)/2];
