LL solve(LL L, int N, vector<LL> X) {
    X.push_back(L);
    vector<LL> D(N);
    for (int i = 0; i < N; i++) {
        if (i != N-1) D[i] = X[i+1]-X[i];
        else D[i] = L-X[i];
    }
    vector<LL> pref(N+1);
    pref[0] = 0;
    for (int i = 0; i < N; i++) pref[i+1] = pref[i] + i*D[i];
    LL res = 0;
    for (int i = 0; i < N; i++) { // FIXME
        int a = (N+i-2)/2;
        int b = (N+i)/2;
        LL ris = (N-i)*X[i];
        // dbg(ris);
        if (i == N-1) {
            res = max(ris, res);
            // dbg(ris);
            continue;
        } else if (i == N-2) {
            res = max(ris + D[N-1], res);
            // dbg(ris+ D[N-1]);
            continue;
        }
        // dbg(a);
        // dbg(ris);
        // dbg(a);
        ris += (N+i-2)*(X[a+1]-X[i]);
        ris -= 2 * (pref[a+1] - pref[i]);
        // dbg(ris);

        ris -= (N+i-1) * (L-X[b]);
        ris += 2 * (pref[N] - pref[b]);
        // dbg(b);
        // dbg(ris);
        // cout << ris << "\n";
        res = max(res, ris);
    }
    return res;
}

