typedef long long ll;
ll l,n;
ll x[200001];
ll dfs(ll nl,ll nr,ll s,ll ko){
  if(ko==n)return s;
  ll ret=0;
  if(x[nl]>l-x[nr]){
    for(ll j=nl+1;j<=nr;j++)x[j]-=x[nl];
    ret+=dfs(nl+1,nr,s+x[nl],ko+1);
  }
  else if(x[nl]<l-x[nr]){
     for(ll j=nl;j<nr;j++)x[j]+=l-x[nr];
    ret+=dfs(nl,nr-1,s+l-x[nr],ko+1);
  }
  else{
    ll y[n];
    for(ll j=0;j<n;j++)y[j]=x[j];
    for(ll j=nl+1;j<=nr;j++)x[j]-=x[nl];
    ll u=dfs(nl+1,nr,s+x[nl],ko+1);
    for(ll j=0;j<n;j++)x[j]=y[j];
    for(ll j=nl;j<nr;j++)x[j]+=l-x[nr];
    ll d=dfs(nl,nr-1,s+l-x[nr],ko+1);
    ret+=max(u,d);
  }
  return ret;
}
