typedef long long ll;
using namespace std;

int L, N, X[200000];
ll ans;

void anticlockwise(int l, int r, int now, ll len);
void clockwise(int l, int r, int now, ll len);

void anticlockwise(int l, int r, int now, ll len) {
    int dist = abs(now - X[l]);
    if (now > X[l]) dist = L - now + X[l];
    len += dist;
    now = X[l];
    l++;
    if (l > r) {
        ans = max(ans, len);
        return;
    }
    clockwise(l, r, now, len);
}

void clockwise(int l, int r, int now, ll len) {
    int dist = abs(now - X[r]);
    if (now < X[r]) dist = now + L - X[r];
    len += dist;
    now = X[r];
    r--;
    if (l > r) {
        ans = max(ans, len);
        return;
    }
    anticlockwise(l, r, now, len);
}

int main() {
    cin >> L >> N;
    rep(i, N) scanf(" %d", &X[i]);
    int now = 0;
    ll len = 0;
    rep(i, N) {
        // LLLLRLR...
        clockwise(i, N - 1, now, len);
        int dist = abs(now - X[i]);
        if (now > X[i]) dist = L - now + X[i];
        len += dist;
        now = X[i];
    }
    now = 0; len = 0;
    for (int i = N - 1; i >= 0; i--) {
        // RRRLRLR...
        anticlockwise(0, i, now, len);
        int dist = abs(now - X[i]);
        if (now < X[i]) dist = now + L - X[i];
        len += dist;
        now = X[i];
    }
