// template

int solve(const vector<int>& X) {
	int N = X.size() - 2;
	vector<int> L(N);
	vector<int> R(N);
	vector<int> Lsum(N);
	vector<int> Rsum(N);

	REP(i, N) {
		R[i] = X[i + 1];
		L[i] = X.back() - X[N - i];
		Lsum[i] = L[i];
		Rsum[i] = R[i];
	}

	FOR(i, 1, N) {
		Lsum[i] += Lsum[i - 1];
		Rsum[i] += Rsum[i - 1];
	}

	int res = L.back();
	FOR(i, 1, N) {
		int lcnt = (i > 0 ? (i - 1) / 2 + 1 : 0);
		int rcnt = i / 2 + 1;
		int lmax = lcnt - 1;
		int lmin = 0;
		int rmax = N - lcnt - 1;
		int rmin = rmax - rcnt + 1;

		//cerr << lcnt << " " << lmin << " " << lmax << " | " << rcnt << " " << rmin << " " << rmax << endl;
		int temp = Lsum[lmax];
		if(lmin - 1 >= 0) temp -= Lsum[lmin - 1];
		temp += Rsum[rmax];
		if(rmin - 1 >= 0) temp -= Rsum[rmin - 1];
		temp *= 2;
		if (i % 2 == 1) {
			temp -= L[lmax];
		}
		else {
			temp -= R[rmax];
		}
		res = max(res, temp);
	}
	return res;

	return 0;
}

void solve() {
	int L, N; cin >> L >> N;
	vector<int> X(N + 2);

	X[0] = 0;
	REP(i, N) {
		cin >> X[i + 1];
	}
	X[N + 1] = L;

	int res = solve(X);

	REP(i, X.size()) {
		X[i] = L - X[i];
	}
	reverse(ALL(X));

	res = max(solve(X), res);
	cout << res << endl;
}

