ll dp(int l, int r, bool flag)
{
	if(l == r)
		return 0;
	if(l + 1 == r)
		return max(a[r] - a[l], L - (a[r] - a[l]));
	if(~f[l][r][flag])
		return f[l][r][flag];
	int nl = l + (!flag), nr = r - flag, now = flag ? r : l;
	f[l][r][flag] = max(dp(nl, nr, 0) + (a[nl] - a[now] + L) % L, dp(nl, nr, 1) + (a[now] - a[nr] + L) % L);
	return f[l][r][flag];
}	
