long long doSearchL(int lPos, int rPos)
{
	if (lPos == rPos)
		return 0;

	if (L[lPos][rPos] > 0)
		return L[lPos][rPos];

	long long leftDist = doSearchL(lPos + 1, rPos) + x[lPos + 1] - x[lPos];
	long long rightDist = doSearchR(lPos + 1, rPos) + x[lPos] + l - x[rPos];

	if (leftDist > rightDist)
		L[lPos][rPos] = leftDist;
	else
		L[lPos][rPos] = rightDist;

	return L[lPos][rPos];
}

long long doSearchR(int lPos, int rPos)
{
	if (lPos == rPos)
		return 0;

	if (R[lPos][rPos] > 0)
		return R[lPos][rPos];

	long long leftDist = doSearchL(lPos, rPos - 1) + x[lPos] + l - x[rPos];
	long long rightDist = doSearchR(lPos, rPos - 1) + x[rPos] - x[rPos - 1];

	if (leftDist > rightDist)
		R[lPos][rPos] = leftDist;
	else
		R[lPos][rPos] = rightDist;

	return R[lPos][rPos];
}

