const int N = 2001;
long long dp[N][N][2];
long long x[N];

long long longestRoute(int l, int r, long long L, bool clockwise) {
	if (dp[l][r][clockwise]) {
		return dp[l][r][clockwise];
	}
	if (l == r) {
		return 0;
	}
	if (clockwise) {
		dp[l][r][clockwise] = max(x[l + 1] - x[l] + longestRoute(l + 1, r, L, clockwise),
															 x[l] + L - x[r] + longestRoute(r, l + 1, L, !clockwise));
	} else {
		dp[l][r][clockwise] = max(x[l] - x[l - 1] + longestRoute(l - 1, r, L, clockwise),
															 L - x[l] + x[r] + longestRoute(r, l - 1, L, !clockwise));
	}
	return dp[l][r][clockwise];
}

void solve() {
