		for (int i = 0; i < 2; ++i) {
			LL left = s, right = s, last = s, t = 0;
			bool f = true;
			while (left > 1 || right < n) {
				LL a = 0, b = 0;
				if (left > 1) {
					if (last == right) {
						a = l - pos[last] + pos[left - 1];
					} else {
						a = pos[left] - pos[left - 1];
					}
				}
				if (right < n) {
					if (last == left) {
						b = pos[left] + l - pos[right + 1];
					} else {
						b = pos[right + 1] - pos[right];
					}
				}
				if (f) {
					if (i && a > 0) {
						t += a;
						--left;
						last = left;
					} else {
						t += b;
						++right;
						last = right;
					}
					f = false;
				} else {
