#include<bits/stdc++.h>
using namespace std;
typedef long long LL;
LL L;

LL dist1(LL x, LL y)
{
    if (x <= y) return y-x;
    return L-x+y;
}

LL dist2(LL x, LL y)
{
    if (y <= x) return x-y;
    return x+L-y;
}

LL solve(deque<LL>&dq, LL now)
{
    LL ans = 0;

    while (!dq.empty()) {
        LL x = dq.front();
        LL xd = dist1(now, x);
        LL y = dq.back();
        LL yd = dist2(now, y);

        if (xd > yd) {
            ans += xd;
            now = x;
            dq.pop_front();
        } else {
            ans += yd;
            now = y;
            dq.pop_back();
        }
    }

    return ans;
}

