        dq.push_back(g);
    }

    deque<LL>dq1(dq);

    LL now = dq.front();
    dq.pop_front();
    LL ans = now+solve(dq, now);

    now = dq1.back();
    dq1.pop_back();
    LL ans1 = L-now+solve(dq1, now);

//    cout << ans << " " << ans1 << endl;

    cout << max(ans, ans1) << "\n";

    return 0;
}

