    for(int i = 1; i <= n; i++){
        // ccw
        auto it1 = s.upper_bound(now);
        ll dist1;
        if(it1 != s.end()) dist1 = *it1 - now;
        else{
            it1 = s.begin();
            dist1 = l - (now - *it1);
        }

        // cw
        auto it2 = s.lower_bound(now);
        ll dist2;
        if(it2 != s.begin()){
            it2--;
            dist2 = now - *it2; 
        }
        else{
            it2 = --s.end();
            dist2 = l - (*it2 - now);
        }

        if(dist1 > dist2){
            ans += dist1;
            now = *it1;
            s.erase(it1);            
        }
        else{
            ans += dist2;
            now = *it2;
            s.erase(it2);
        }
    }
    printf("%lld\n", ans);
    return 0;
}

