				dfs(left+1, right, pos, pre+l[left]-l[left-1]);
				dfs(left, right+1, false, pre+l[left-1]+r[right]);
			}
			else{
				dfs(left, right+1, false, pre+l[left-1]+r[right]);
			}
		}
		else{
			if(r[right]-r[right-1] > l[left]+r[right-1]){
				dfs(left, right+1, pos, pre+r[right]-r[right-1]);
			}
