lint rob() {
	lint ans = 0;
	lint lans = 0;
	int zjed = -1;
	int zmin = -1;
	FOR(i,0,n) {
		if (i+i < n - 1) lans += 2LL * v[i];
		if (i+i == n - 1) {
			lans += v[i];
			zjed = i;
		}
		if (i+i == n) {
			lans -= v[i];
			zmin = i;
		}
		if (i+i > n) lans -= 2LL * v[i];
	}
	lans += (n-1)*1LL*L;
	ans = lans;
	int mam = n;
	int ind = 0;
	while (mam > 1) {
		lans -= L;
		lans -= 2LL * v[ind];
		if (zjed != -1) {
			lans += v[zjed];
			lans += v[zjed+1];
			zjed = -1;
			zmin = zjed+1;
		} else {
			lans += 2LL*v[zmin];
			zjed = zmin;
			zmin = -1;
		}
		mam--;
		ans = max(ans, lans);
		ind++;
	}
	return ans;
}

