    int dp[N+2][N+2][2] = {}; // [left][right][last==right]
    for (int i = 1; i <= N; i++) {
        dp[i][0][0] = dp[i-1][0][0] + X[i] - X[i-1];
    }
    for (int i = N; i >= 1; i--) {
        dp[0][i][1] = dp[0][i+1][1] + X[i+1] - X[i];
    }
    for (int i = 1; i <= N; i++) {
        for (int j = N; j > i; j--) {
            dp[i][j][0] = max({
                dp[i-1][j][0] + X[i] - X[i-1],
                dp[i-1][j][1] + L - X[j] + X[i],
            });
            dp[i][j][1] = max({
                dp[i][j==N?0:j+1][0] + X[i] + L - X[j],
                dp[i][j==N?0:j+1][1] + X[j+1] - X[j],
            });
        }
    }
    int ans = 0;
    for (int i = 0; i < N; i++) {
        for (int j = 0; j <= 1; j++) {
            ans = max(ans, dp[i][i+1][j]);
        }
    }
    cout << ans << endl;
    return 0;
}

