template<class T> void inputVector(vector<T>& v, int n) {
    v.resize(n);
    for (int i = 0; i < v.size(); i++) cin >> v[i];
}

int L, N;
int solve(vector<int> &X, vector<int> &rX) {
    deque<int> leftQ, rightQ;
    leftQ.push_back(X[0]);
    rightQ.push_back(rX[1]);
    int leftNum = 1;
    int rightNum = N - 1;
    int leftCost = X[0];
    int rightCost = rX[1] * 2;
    int rightPt = 2;
    int ret = leftCost + rightCost;

    REP(now, 1, N - 2) {
        leftNum++;
        rightNum--;
        int leftActNum = min(leftNum, rightNum + 1);
        int rightActNum = min(leftNum, rightNum);

        leftCost += X[now] + X[now - 1];
        leftQ.push_front(X[now]);

        while (leftQ.size() > leftActNum) {
            leftCost -= 2 * leftQ.back();
            leftQ.pop_back();
        }

        rightCost -= 2 * rightQ.front();
        rightQ.pop_front();

        while (rightQ.size() < rightActNum) {
            rightCost += 2 * rX[rightPt];
            rightQ.push_back(rX[rightPt]);
            rightPt++;
        }

        //cerr << "now:" << now << endl;
        //cerr << " leftQ : ";
        //for (int num : leftQ) cerr << num << " ";
        //cerr << endl;
        //cerr << " rightQ: ";
        //for (int num : rightQ) cerr << num << " ";
        //cerr << endl;
        //cerr << " leftCost : " << leftCost << endl;
        //cerr << " rightCost: " << rightCost << endl;
        //cerr << " leftActNum : " << leftActNum << endl;
        //cerr << " rightActNum: " << rightActNum << endl;

        ret = max(ret, leftCost + rightCost);
    }

    return ret;
}

signed main() {
    cin >> L >> N;
    vector<int> X, rX;

    inputVector(X, N);

    if (N == 1) {
        cout << max(X[0], L - X[0]) << endl;
        return 0;
    }

    rX.resize(N);
    rep(i, N) {
        rX[i] = L - X[i];
    }

    int ret = solve(X, rX);

    reverse(all(X));
    reverse(all(rX));

    swap(X, rX);

    ret = max(ret, solve(X, rX));

    cout << ret << endl;

    return 0;
}

