      }
    }
    for(ll j=n-1;dp[j][i][0]!=0||dp[j][i][1]!=0;j--){
      if(dp[j][i][0]!=0){
        dp[(j+n-1)%n][i+1][0]=max(dp[(j+n-1)%n][i+1][0],dp[j][i][0]+((x[j]-x[(j+n-1)%n])<0?(x[j]-x[(j+n-1)%n]+l):(x[j]-x[(j+n-1)%n])));
