int calc(V<int> d) {
	int n = d.size();
	using S = MonoidOfValue::MONOID::S;
	V<S> a(n);
	REP(i, n) a[i] = S{ 0, d[i] };
	LazySegmentTree<MonoidOfValue::MONOID, MonoidOfOperator::add<int>, ApplyOperator::AGC030> lst(a);

	int ans = 0;
	int r = n;
	REP(i, n) {
		int l = n - 1 - i;
		lst.update(0, l, 1);
		lst.update(l, r, -1);
		if (i % 2 == 0) --r;
		lst.update(r, n, 1);

		CHMAX(ans, lst.query(0, n).a);
	}
	return ans;
}

