llint calc(llint l, llint r, llint p)
{
	if(l > r) return 0;
	if(memo[l][r][p] != -1) return memo[l][r][p];

	llint ans = 0;
	if(p == 0){
		ans = max(ans, x[l]-x[l-1] + calc(l+1, r, 0));
		ans = max(ans, L-(x[r]-x[l-1]) + calc(l, r-1, 1));
