int L = 0;

int calc_left_distance(int pos, int x)
{
    if (pos <= x) {
        return x - pos;
    } else {
        return (L - pos + x);
    }
}

int calc_right_distance(int pos, int x)
{
    return L - calc_left_distance(pos, x);
}

int main()
{
    int N;
    std::cin >> L >> N;

    int X[N];
    for (int i = 0; i < N; ++i) {
        std::cin >> X[i];
    }

    int pos = 0;
    int left = 0;
    int right= N - 1;

    uint64_t total = 0;

    bool complete = false;
    while (true) {
        if (left == right) {
            complete = true;
        }

        int dist_left = calc_left_distance(pos, X[left]);
        int dist_right = calc_right_distance(pos, X[right]);
        if (dist_left <= dist_right) {
            pos = X[right];
            total += dist_right;
            std::cout << "right," << dist_right << "," << dist_left << std::endl;
            --right;
        } else {
            pos = X[left];
            total += dist_left;
            std::cout << "left," << dist_left << "," << dist_right << std::endl;
            ++left;
        }

        if (complete) {
            break;
        }
    }

    std::cout << total << std::endl;

    return 0;
}

