				ans += X[i];
				goLeft = !goLeft;
			}
			else { //一度折り返したあと
				if (goLeft) {
					if (il > in) ans += X[il] - X[in];
					else ans += (L - X[in]) + X[il];
					in = il;
					il++;
				}
				else {
					if (ir > in) ans += (L - X[ir]) + X[in];
					else ans += X[in] - X[ir];
					in = ir;
					ir--;
				}
				goLeft = !goLeft;
			}
		}
	}
	else {
		int il = 1, ir = 0, in = 0;
		int rep = N + 1;
