lint calc(lint i, lint j, vector<lint> X) {
  if(dp[i][j] != -1) return dp[i][j];
  lint val;
  if(i == j) val = 0;

  if(i < j) {
    val = max(calc(i+1, j,X) + X[i+1]-X[i], calc(j, i+1,X) + X[i] - X[j] + L);
