typedef long long ll;
using namespace std;

pair<int, bool> farther_neighbor(int iprev, ll l, vector<ll> &x, vector<bool> &burnt) {

    int n = x.size();

    int lb = iprev;
    ll candl = lb;
    ll candr = lb;
    while (true) {
        candl = (candl + n - 1) % n;
        if (candl == lb || !burnt[candl]) break;
    }
    while (true) {
        candr = (candr + 1) % n;
        if (candr == lb || !burnt[candr]) break;
    }

    ll dl = (x[iprev] - x[candl] + l) % l;
    ll dr = (x[candr] - x[iprev] + l) % l;

    // cerr << dl << ", " << dr << endl;

    if (candl != lb && candr != lb) {
        return dl < dr ? make_pair(candr, true) : make_pair(candl, false);
    } else if (candl != lb) {
        return make_pair(candl, false);
    } else if (candr != lb) {
        return make_pair(candr, true);
    } else {
        return make_pair(-1, false);
    }

}

int main() {

    ll l, n;
    cin >> l >> n;
    vector<ll> x(n+1, 0);
    vector<bool> burnt(n+1, false);
    int remainder = n;
    REP(i, n) cin >> x[i+1];

    ll ans = 0;
    x[0] = 0;
    burnt[0] = true;


    int p = 0;
    for (;;) {
        ll dans = 0;
        ll xnow = x[p];
        auto fn = farther_neighbor(p, l, x, burnt);
        if (fn.first == -1) break;
        ll dst = x[fn.first];
        bool toplus = fn.second;
        if (remainder == 1) {
            ll d = abs(dst - xnow);
            dans = max(d, l - d);
        } else if (toplus) {
            dans = (dst - xnow + l) % l;
        } else {
            dans = (xnow - dst + l) % l;
        }
        // cerr << "Takahashi-kun has burnt the tree " << fn.first << "(+" << dans << ", " << xnow << "->" << dst << ")" << endl;
        ans += dans;
        burnt[fn.first] = true;
        remainder--;
        p = fn.first;
    }

    cout << ans << endl;

}

#include <iostream>
#include <vector>
#include <map>

using INT = long long;

struct Solver {
  size_t const L;
  size_t const N;
  std::vector<INT> const& X;

  std::vector<std::vector<INT>> cache_L;
  std::vector<std::vector<INT>> cache_R;

  Solver(size_t L, size_t N, std::vector<INT> const& X)
    : L(L)
    , N(N)
    , X(X)
    , cache_L(N+1, std::vector<INT>(N+1, -1))
    , cache_R(N+1, std::vector<INT>(N+1, -1)) {}

  INT from_left(size_t burned_left, size_t burned_right) {
    if (cache_L[burned_left][burned_right] >= 0)
      return cache_L[burned_left][burned_right];

    INT dist_to_left = (L + X[burned_left+1] - X[burned_left]) % L;
    INT dist_to_right = (L + X[burned_left] - X[N-burned_right]) % L;

    INT ans;

    if (burned_left + burned_right < N) {
      INT ans_to_left = dist_to_left + from_left(burned_left+1, burned_right);
      INT ans_to_right = dist_to_right + from_right(burned_left, burned_right+1);
      ans = std::max(ans_to_left, ans_to_right);
    } else {
      ans = 0;
    }

    return cache_L[burned_left][burned_right] = ans;
  }

  INT from_right(size_t burned_left, size_t burned_right) {
    if (cache_R[burned_left][burned_right] >= 0)
      return cache_R[burned_left][burned_right];

    INT dist_to_left = (L + X[burned_left+1] - X[N-burned_right+1]) % L;
    INT dist_to_right = (L + X[N-burned_right+1] - X[N-burned_right]) % L;

    INT ans;

    if (burned_left + burned_right < N) {
      INT ans_to_left = dist_to_left + from_left(burned_left+1, burned_right);
      INT ans_to_right = dist_to_right + from_right(burned_left, burned_right+1);
      ans = std::max(ans_to_left, ans_to_right);
    } else {
      ans = 0;
    }

    return cache_R[burned_left][burned_right] = ans;
  }

  INT solv() {
    return std::max(X[1] + from_left(1, 0), X[N+1]-X[N] + from_right(0, 1));
  }
};

int main() {
  size_t L, N;

  std::cin >> L >> N;

  std::vector<INT> X;
  X.reserve(N+2);

  X.push_back(0);
  for (size_t i=0; i<N; i++) {
    INT x;
    std::cin >> x;
    X.push_back(x);
  }
  X.push_back(L);

  std::cout << Solver(L, N, X).solv() << std::endl;

  return 0;
}

