long long table[MAX_N][MAX_N][2] = {};

long long dfs(int max_index, int min_index = 0, long long pos = 0);

int main(){

	std::cin >> L >> N;

	for(int i = 0; i < N; ++i){
		std::cin >> X[i];
	}

	std::cout << dfs(N - 1) << std::endl;

