int arr[N];

int dp(int l, int r, int lst) {
  if (l == r) {
    if (lst == 0) {
      return max(arr[l] - arr[l - 1], n - arr[l] + arr[l - 1]);
    } else {
      return max(arr[r + 1] - arr[r], n - arr[r + 1] + arr[r]);
    }
  }
  if (memo[l][r][lst] != -1) return memo[l][r][lst];
  int ans = 0;
  if (lst == 0) {
    ans = max(ans, (arr[l] - arr[l - 1]) + dp(l + 1, r, 0));
    ans = max(ans, arr[l - 1] + n - arr[r] + dp(l, r - 1, 1));
  } else {
    ans = max(ans, arr[r + 1] - arr[r] + dp(l, r - 1, 1));
    ans = max(ans, n - arr[r + 1] + arr[l] + dp(l + 1, r, 0));
  }
  return memo[l][r][lst] = ans;
}

