#include <bits/stdc++.h>
#define LL long long
#define MEM(x,y) memset(x,y,sizeof(x))
using namespace std;
const int maxn = 1e5+7;
LL x[maxn],d[maxn];
LL L;
int n;
LL solve()
{
    LL res=0,ans=0;
    int tmp=n,now=1,dir=1;
    while (tmp--)
    {
        res+=d[now]*tmp;
        now=now+tmp*dir;
        dir=-dir;
    }
    ans=res;
    LL sum=0;
    int cnt=(n-1)/2;
    LL down=0;for (int i=n;i>n-cnt;i--) down+=d[i];
    LL up=0;for (int i=1;i<1+cnt;i++) up+=d[i];
    for (int i=1;i<n;i++)
    {
        sum+=d[i];
        up=up-d[i]+d[i+cnt];
        res=res-sum+up-down;
        //printf("%lld\n",res);
        ans=max(ans,res);
    }
    return ans;
}

int main()
{
    scanf("%lld%d",&L,&n);
    x[0]=0;
    for (int i=1;i<=n;i++)
    {
        scanf("%d",&x[i]);
        d[i]=x[i]-x[i-1];
    }
    n++;d[n]=L-x[n-1];
    LL ans=solve();
    for (int i=1;i<=n/2;i++) swap(d[i],d[n-i+1]);
    ans=max(ans,solve());
    printf("%lld\n",ans);
    return 0;
}

