			ll offset = 0;
			ll dif = (rend - rstart) - (lend - lstart) + 1; // -1 if we ending on the right
			if (k)dif -= 2;
			if (dif > 0){
				rend -= dif;
				offset = R[rend+1];
			}else if (dif < 0){
				lstart -= dif;
				offset = L[lstart-1];
			}
