			if (dif > 0 && k == 0)tot = tot + offset*2;
			if (dif < 0 && k == 1)tot = tot + offset*2;

			ans = max(ans,tot);
		}
	}
	ans = max({ans, L[N], R[1]});
	cout<<ans;
}

