// ps[0][i] = X[0] + ... + X[i]
// ps[1][i] = X[0] * 0 + X[1] * 1 + ... + X[i] * i
// ps[2][i] = X[0] * n + X[1] * (n-1) + ... + X[i] * (n-i)

// start of L to end of R

ll sum0(ll l, ll r) {
    return ps[0][r] - ps[0][l];
}

ll sum1(ll l, ll r) {
    return ps[1][r] - ps[1][l] - (ps[0][r] - ps[0][l]) * l;
}

ll sum2(ll l, ll r) {
    return ps[2][r] - ps[2][l] - (ps[0][r] - ps[0][l]) * (n - r);
}

ll calc() {
    fori (i, n) {
        ps[0][i + 1] = ps[0][i] + X[i + 1];
        ps[1][i + 1] = ps[1][i] + X[i + 1] * (i + 1);
        ps[2][i + 1] = ps[2][i] + X[i + 1] * (n - i);
    }
    ll mx = 0;
    fori (i, n - 1) {
        ll val;
        if (i % 2) {
            val = sum1(n - i / 2, n) * 2 + sum0(0, n - 1 - i) * (i + 1) + sum2(n - 1 - i, n - 2 - i / 2) * 2 + sum0(n - 1 - i / 2, n);
        } else {
            val = sum1(n - i / 2, n) * 2 + sum0(0, n - 1 - i) * (i + 1) + sum2(n - 1 - i, n - 1 - i / 2) * 2 - sum0(n - 1 - i, n - 1 - i / 2);
        }
        smax(mx, val);
    }
    return mx;
}

