int right(int p) {
//	cout << "right start " << p << endl;
	int ans = -1;
	int s;
	if(p < N)	s = p + 1;
	else		s = 1;
	REP(i, s, N+1) {
		if(X[i] != -1 && i != p) {
			ans = i;
			break;
		}
	}
	if(ans == -1 && s != 1) {
		REP(i, 1, (s - 1)) {
			if(X[i] != -1 && i != p) {
				ans = i;
				break;
			}
		}
	}
//	cout << "right ans = " << ans << endl;
	return ans;
}

int left(int p) {
//	cout << "left start " << p << endl;
	int ans = -1;
	int s;
	if(p == 1)	s = N;
	else		s = p - 1;
	for(int i = s; i >= 1; i--) {
		if(X[i] != -1 && i != p) {
			ans = i;
			break;
		}
	}
	if(ans == -1 && s != N) {
		for(int i = N ; i > s; i--) {
			if(X[i] != -1 && i != p) {
				ans = i;
				break;
			}
		}
	}
//	cout << "left ans = " << ans << endl;
	return ans;
}

int64 check(int p, int64 sum) {
//    cout << "check  start  p = " << p << "  sum = " << sum << endl;
	int rp = right(p);
	if(rp == -1)	return sum;

	int saveP;
	int64 rsum = sum;
	if(rp > p)	rsum += (X[rp] - X[p]);
	else		rsum += (X[rp] + L - X[p]);
	saveP = X[p];
	X[p] = -1;
	int64 rans = check(rp, rsum);
	X[p] = saveP;

	int lp = left(p);
	int64 lsum = sum;
	if(lp < p)	lsum += (X[p] - X[lp]);
	else		lsum += (X[p] + L - X[lp]);
	saveP = X[p];
	X[p] = -1;
	int64 lans = check(lp, lsum);
	X[p] = saveP;

	if(rans > lans)		return rans;
	else				return lans;
}


