ll xsum[N];
ll revxsum[N];

ll rangeX(int le, int ri) {
  ri = min(ri, n-1);
  if(le > ri) return 0;
  ll res = xsum[ri];
  if(le - 1 >= 0) res -= xsum[le - 1];
  return res;
}

ll rangeXRev(int le, int ri) {
  ri = min(ri, n-1);
  if(le > ri) return 0;
  ll res = revxsum[ri];
  if(le - 1 >= 0) res -= revxsum[le - 1];
  return res;
}

int goal[N];
