ll revval[N];

template<class A, class B, class C, class D, class E>
void calc(A &ans, B &rangeX, C &rangeXRev, D &x, E &revx) {
  for(int i = 0; i < n; i++) {
    ll res = x[i] * 2;
    int f = n - 1 - i;
    int k = f / 2;
    int l = f - k;
    res += rangeX(i + 1, i + 1 + k - 1) * 2;
    res += rangeXRev(0, l - 1) * 2;
    if(f & 1) {
      res -= revx[l - 1];
    } else {
      res -= x[i + 1 + k - 1];
    }
    dump(i, res);
    ans = max(ans, res);
  }
}

