// bf=1:ri, bf=0:lef
long long solve(long long lef, long long ri, bool bf) {
  if(dp[lef][ri][bf] != -1) return dp[lef][ri][bf];
  long long ans = 0, now = 0;
  if(lef == ri) {
    if(bf)
      now = x[ri + 1];
    else
      now = x[lef - 1];
    ans = max(x[ri] - now, now - x[ri]);
    ans = max(ans, l - ans);
  }
  else if(lef != 0 || ri != n - 1) {
    if(bf) {
      now = x[ri + 1];
      ans = solve(lef, ri - 1, 1) + now - x[ri];
      ans = max(ans,
                solve(lef + 1, ri, 0) + x[lef] + (l - now));
    }
    else {
      now = x[lef - 1];
      ans = solve(lef, ri - 1, 1) + now + (l - x[ri]);
      ans = max(ans, solve(lef + 1, ri, 0) + x[lef] - now);
    }
  }
  else {
    ans = solve(lef, ri - 1, 1) + (l - x[ri]);
    ans = max(ans, solve(lef + 1, ri, 0) + x[lef]);
  }
  return dp[lef][ri][bf] = ans;
}

#include <stdio.h>
