#include <math.h>

enum Dir {
	d_head,
	d_tail
};

long move(long l,enum Dir dir,long x[],int num,long now)
{
	if (dir == d_head) {
		if (x[num] > now) return x[num] - now;
		else              return x[num] + l - now;
	} else if (dir == d_tail) {
		if (x[num] < now) return now - x[num];
		else              return l - x[num] + now;
	}
}

int main(void)
{
	int n,num,head,tail,counter;
	long i,j,res,l,*x,now,dist,dist_max;
	enum Dir dir;
	char ret;

	ret = scanf("%ld %d",&l,&n);

	x = (long *)malloc(sizeof(long) * n);

	for (i=0;i<n;i++) {
		ret = scanf("%ld",&x[i]);
	}

	dist_max = 0;

	for (i=0;i<pow(2,n);i++) {
		now = 0;
		head = 0;
		tail = n-1;
		dist = 0;
		for (counter=0,j=1;counter<n;counter++,j*=2) {
			res = i & j;
			if (res == 0) {
				// to head
				dir = d_head;
				num = head;
				head += 1;
			} else {
				// to tail
				dir = d_tail;
				num = tail;
				tail -= 1;
			}
			dist += move(l,dir,x,num,now);
			now = x[num];
		}
		if (dist_max < dist) dist_max = dist;
	}

	printf("%ld\n",dist_max);

	return 0;
}

