using namespace std;
using ll = long long;

ll foo(int l, int n, vector<int>& x) {
    ll r = 0;
    for (int h = 0; h < 2; h++) {
        ll t = x[0];
        int p = x[0];
        for (int j = 0; j < n - 1; j++) {
            int k = j / 2;
            int q, y, z;

            if ((j + h) % 2 == 0) {
                y = x[k + 1];
                q = p;
                if (q > y) q -= l;
                z = y - q;
                if (j == n - 2) {
                    z = max(z, l - z);
                }
                t += z;
            } else {
                y = x[n - 1 - k];
                q = y;
                if (q > p) q -= l;
                z = p - q;
                if (j == n - 2) {
                    z = max(z, l - z);
                }
                t += z;
            }
            p = y;
        }
        r = max(r, t);
    }
    return r;
}

