		r2 = x[temp2] < x[now] ? x[now] - x[temp2] : x[now] + (l - x[temp2]);

		if (r1 > r2)
		{
			r += r1;
			now = temp1;

		}
		else
		{
			r += r2;
			now = temp2;
		}

		state[now] = true;
	}

	printf("%d", r);

	return 0;
}

