        }
    }else if(rLen > lLen){
        long long newCurrent = X[first];
        int newFirst = first+1;
        return rLen + inspectMaxLen(newCurrent, newFirst, end);
    }else{
        long long newCurrent = X[end];
        int newEnd = end-1;
        return lLen + inspectMaxLen(newCurrent, first, newEnd);
    }
}

