template<typename T> void chmin(T &a, T b) { if (a > b) a = b; }
template<typename T> void chmax(T &a, T b) { if (a < b) a = b; }

int in() { int x; scanf("%d", &x); return x; }
ll lin() { ll x; scanf("%lld", &x); return x; }

ll calc(ll c, VL x){
    ll n = x.size();
    x.push_back(c);
    VL s(n + 1);
    REP(i,n) s[i+1] = s[i] + x[i];
    ll ans = 0;
    REP(i,n){
        ll r = n - 1 - i;
        ll r1 = r / 2, r2 = r - r1;
        ll d = x[i] + 2 * (s[i + 1 + r1] - s[i + 1] - r1 * x[i]) + 2 * (r2 * x[i] + r2 * c - (s[n] - s[n - r2]));
        // cout << (s[i + r1] - s[i] - r1 * x[i]) << endl;
        if (r % 2 == 0){
            d -= x[i + r1] - x[i];
        }else{
            d -= x[i] + c - x[n - r2];
        }
        // cout << i << " " << d << endl;
        chmax(ans, d);
    }
    // cout << ans << endl;
    return ans;
}

