#define ll long long
const int N = 200002;
int l, n, X[N], A[N], sm[N], AA[N];
ll S[N];
ll sumof(int s, int e) {//A[s]+...+A[e], sm[e]-sm[s-1]이 원래
	return sm[e + 1] - sm[s];
}
ll func() {
	int i, j, z;
	ll calc = (ll)0, ans=(ll)0;
	for (i = 1, sm[0] = (ll)0; i <= n + 1; i++) {
		sm[i] = sm[i - 1] + A[i - 1];
	}
	//sm[i]=A[0]+...+A[i-1]
	for (i = 0, j = n, calc = (ll)0, z = 0, S[1] = (ll)0; z < n; z++, S[1] += calc) {
		if (z % 2 == 0) {
			calc += A[i];
			i++;
		}
		else {
			calc += A[j];
			j--;
		}
	}
	ans = S[1];
	for (i = 2; i <= n; i++) {
		S[i] = S[i - 1] - sumof(0, i - 2) + sumof(i - 1, (i + n - 1) / 2) - sumof((i + n) / 2, n);
		ans = ans > S[i] ? ans : S[i];
	}
	return ans;
}
int main() {
	int i;
	ll ans1, ans2;
	scanf("%d%d", &l, &n);
	for (i = 1; i <= n; i++) {
		scanf("%d", &X[i]);
	}
	X[n + 1] = l;
	for (i = 0; i <= n; i++) {
		AA[i] = X[i + 1] - X[i];
	}
	for (i = 0; i <= n; i++) {
		A[i] = AA[i];
	}
	ans1 = func();
	for (i = 0; i <= n; i++) {
		A[i] = AA[n - i];
	}
	ans2 = func();
	printf("%lld", ans1 > ans2 ? ans1 : ans2);
}

