#include <bits/stdc++.h>

using namespace std;

using step_t = int64_t;

struct pos_t {
  constexpr pos_t() : value(0) {}

  constexpr explicit pos_t(int64_t pos) : value(pos) {
    assert(0 <= pos);
    assert(pos < pos_t::l.value);
  }

  int64_t value;

  step_t CCW_step_from_beginning() const { return this->value; }

  step_t CW_step_from_beginning() const { return pos_t::l.value - this->value; }

  step_t CCW_step_from(const pos_t &other) const {
    if (other.value < this->value) {
      return this->CCW_step_from_beginning() - other.CCW_step_from_beginning();
    }
    return this->CCW_step_from_beginning() + other.CW_step_from_beginning();
  }

  step_t CW_step_from(const pos_t &other) const {
    if (other.value < this->value) {
      return other.CCW_step_from_beginning() + this->CW_step_from_beginning();
    }
    return other.CCW_step_from_beginning() - this->CCW_step_from_beginning();
  }

  step_t step_from_beginning() const {
    return std::max(this->CW_step_from_beginning(),
                    this->CCW_step_from_beginning());
  }

  step_t step_from(const pos_t &other) const {
    return std::max(this->CW_step_from(other), this->CCW_step_from(other));
  }

  static pos_t l;
};
pos_t pos_t::l;
constexpr step_t stepZero{0};

using index_t = int32_t;

static index_t n;
static std::array<pos_t, 200000> xs;

enum class current_t { low, high };

step_t solve_one(index_t const lowIdx, index_t const highIdx,
                 current_t const current, step_t threshold) {
  bool const lowest = lowIdx == 0;
  bool const highest = highIdx == n - 1;
  if (lowest && highest) {
    return current == current_t::low ? xs[lowIdx].CCW_step_from_beginning()
                                     : xs[highIdx].CW_step_from_beginning();
  }

  step_t ret = 0;
  index_t const lowerIdx = lowIdx - 1;
  index_t const higherIdx = highIdx + 1;
  if (current == current_t::low) {
    if (!lowest) {
      step_t const currentStep = xs[lowIdx].CCW_step_from(xs[lowerIdx]);
      step_t const nextThreshold = std::max(threshold - currentStep, stepZero);
      step_t const step =
          solve_one(lowerIdx, highIdx, current_t::low, nextThreshold) +
          currentStep;
      ret = std::max(step, ret);
    }
    if (!highest) {
      step_t const currentStep = xs[lowIdx].CCW_step_from(xs[higherIdx]);
      step_t const nextThreshold = std::max(threshold - currentStep, stepZero);
      step_t const step =
          solve_one(lowIdx, higherIdx, current_t::high, nextThreshold) +
          currentStep;
      ret = std::max(step, ret);
    }
  } else {
    if (!lowest) {
      step_t const currentStep = xs[highIdx].CW_step_from(xs[lowerIdx]);
      step_t const nextThreshold = std::max(threshold - currentStep, stepZero);
      step_t const step =
          solve_one(lowerIdx, highIdx, current_t::low, nextThreshold) +
          currentStep;
      ret = std::max(step, ret);
    }
    if (!highest) {
      step_t const currentStep = xs[highIdx].CW_step_from(xs[higherIdx]);
      step_t const nextThreshold = std::max(threshold - currentStep, stepZero);
      step_t const step =
          solve_one(lowIdx, higherIdx, current_t::high, nextThreshold) +
          currentStep;
      ret = std::max(step, ret);
    }
  }
  return ret;
}

step_t solve() {
  step_t ret = 0;
  for (index_t lowIdx = 0; lowIdx < n - 1; ++lowIdx) {
    index_t const highIdx = lowIdx + 1;
    step_t const currentStep = xs[highIdx].step_from(xs[lowIdx]);
    if (lowIdx != 0) {
      auto const currentThreshold = std::max(ret - currentStep, stepZero);
      auto const step =
          solve_one(lowIdx, highIdx, current_t::low, currentThreshold) +
          currentStep;
      ret = std::max(step, ret);
    }
    if (highIdx != n - 1) {
      auto const currentThreshold = std::max(ret - currentStep, stepZero);
      auto const step =
          solve_one(lowIdx, highIdx, current_t::high, currentThreshold) +
          currentStep;
      ret = std::max(step, ret);
    }
  }
  return ret;
}

int main() {
  pos_t::l.value = 10;
  assert(pos_t(2).CCW_step_from_beginning() == 2);
  assert(pos_t(2).CW_step_from_beginning() == 8);
  assert(pos_t(2).step_from_beginning() == 8);
  assert(pos_t(5).step_from_beginning() == 5);
  assert(pos_t(3).CCW_step_from(pos_t(1)) == 2);
  assert(pos_t(3).CW_step_from(pos_t(1)) == 8);
  assert(pos_t(1).CCW_step_from(pos_t(4)) == 7);
  assert(pos_t(1).CW_step_from(pos_t(4)) == 3);
  assert(pos_t(2).step_from(pos_t(5)) == 7);
  assert(pos_t(6).step_from(pos_t(2)) == 6);

  std::cin.tie(nullptr);
  std::ios::sync_with_stdio(false);
  std::cin >> pos_t::l.value >> n;
  for (int i = 0; i < n; ++i) {
    std::cin >> xs[i].value;
  }
  std::cout << solve() << std::endl;
  return 0;
}

