typedef long long ll;

const int MOD = 1000000007;  // 1 000 000 007


int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    // input
    ll L, N;
    cin >> L >> N;
    vector<ll> vec(N);
    REP(i, N) cin >> vec[i];

    // calculation
    if (N == 1) {
        cout << vec[0] << "\n";
    } else {
        ll front, back, sum = 0, now = 0;
        size_t idx = 0, idx_back = (size_t)N - 1;
        REP(i, N) {
            front = vec[idx] - now;
            back = now + (L - vec[idx_back]);
            sum += max(front, back);
            if (idx == idx_back) {
                break;
            } else if (front <= back) {
                idx_back--;
                now -= back;
            } else {
                idx++;
                now += front;
            }
        }
        cout << sum << "\n";
    }

    return 0;
}

