void solve() {
  int N, L; cin >> L >> N;
  vector<long long> X(N + 1, 0);
  vector<long long> Y(N + 1, 0);
  for (int i = 1; i <= N; i++) {
    cin >> X[i];
  }
  for (int i = 1; i <= N; i++) {
    Y[i] = L - X[N - i + 1];
  }
  for (int i = 1; i <= N; i++) {
    X[i] += X[i - 1];
    Y[i] += Y[i - 1];
  }
  long long ans = 0;
  for (int i = 1; i <= N; i++) {
    long long sum = 0;
    if ((N - i) % 2 == 0) {
      sum = 2ll * Y[(N - i) / 2] + 2ll * (X[(N + i) / 2] - X[i - 1]) - (X[(N + i) / 2] - X[(N + i) / 2 - 1]);
    } else {
      sum = 2ll * (X[(N + i - 1) / 2] - X[i - 1]) + 2ll * Y[(N - i + 1) / 2] - (Y[(N - i + 1) / 2] - Y[(N - i + 1) / 2 - 1]);
    }
    ans = max(ans, sum);
  }
  for (int i = 1; i <= N; i++) {
    long long sum = 0;
    if ((N - i) % 2 == 0) {
      sum = 2ll * X[(N - i) / 2] + 2ll * (Y[(N + i) / 2] - Y[i - 1]) - (Y[(N + i) / 2] - Y[(N + i) / 2 - 1]);
    } else {
      sum = 2ll * (Y[(N + i - 1) / 2] - Y[i - 1]) + 2ll * X[(N - i + 1) / 2] - (X[(N - i + 1) / 2] - X[(N - i + 1) / 2 - 1]);
    }
    ans = max(ans, sum);
  }
  cout << ans << '\n';
}

