i64 solve(int l, int r, bool f) {
	if(dp[l][r][f]) return dp[l][r][f];
	if(l == r) return 0;

	i64 ret = 0;
	if(f) {
		ret = std::max(ret, (x[l + 1] - x[l]) + solve(l + 1, r, true));
		ret = std::max(ret, x[l] + (L - x[r]) + solve(l + 1, r, false)); 
	} else {
		ret = std::max(ret, x[l] + (L - x[r]) + solve(l, r - 1, true));
		ret = std::max(ret, x[r] - x[r - 1] + solve(l, r - 1, false));
	}
	return dp[l][r][f] = ret;
}

