long long M[1 << 20];

long long solve(long long L, long long N, vector<long long>X) {
	for (int i = 1; i <= N; i++) M[i] = X[i - 1];
	for (int i = N + 1; i < 3 * (N + 1); i++) M[i] = L + M[i - (N + 1)];

	long long S = X[N - 1], maxn = S;
	long long P1 = N + 1, P2 = N * 2 + 1, S1 = N * 2 + 2, S2 = N * 2 + 1;
	for (int i = 1; i <= N - 1; i++) {
		P1 -= 1; P2 -= 2; S1 -= 2; S2 -= 1;
		long long v1 = M[P2] - M[P1];
		long long v2 = M[S2] - M[S1];
		long long v3 = M[S2 + 1] - M[S2];
		S += v1 * 2;
		S -= v2 * 2;
		S -= v3 * 1;
		maxn = max(maxn, S);
	}
	return maxn;
}

