int GetMoveDistance3(int*&  iTreesHaba, const int& iFirst, const int& iLast, int& L)
{
	if (iFirst == iLast)
	{
		return 0;
	}
	int hantokei = iTreesHaba[iFirst] + GetMoveDistance3(iTreesHaba, iFirst + 1, iLast, L);
	int tokei = iTreesHaba[iLast] +  GetMoveDistance3(iTreesHaba, iFirst, iLast - 1, L);

	return tokei > hantokei ? tokei : hantokei;
}

