int dfs(int l, int r, int n) {  
  if ( abs(l-r) <= 1 ) return 0;  
  if ( dp[l][r][n] >= 0 ) return dp[l][r][n];  

  int ret = -1;
  if ( !n ) {
    ret = max(abs(X[l]-X[l-1])+dfs(l-1, r, 0),
	      abs(L-X[l]+X[r+1])+dfs(l, r+1, 1));    
  } else {
    ret = max(abs(X[r]+L-X[l-1])+dfs(l-1, r, 0),
	      abs(X[r]-X[r+1])+dfs(l, r+1, 1));   
  }

  return dp[l][r][n] = ret;  
}

