#include <bits/stdc++.h>

using namespace std;

using int64 = long long;


int N, L;

int64 solve(vector< int > X) {
  int N = (int) X.size();
  X.push_back(L);
  int64 uku = 0;
  auto Z = [&](int i) {
    int64 ret = 0;
    int64 sub = 0;

    {
      vector< int > add(N);
      for(int j = 0; j < i; j++) {
        int64 rightRest = (i - j - 1);
        int64 leftLeft = (N - i - 1);

        add[j + 1] += min(rightRest, leftLeft);
        add[j] -= min(rightRest, leftLeft);
        sub += 1LL * (X[j + 1] - X[j]) * min(rightRest, leftLeft);
      }

    }

    for(int j = N - 1; j > i; j--) {
      int64 rightRest = i;
      int64 leftLeft = j - i;
      sub += 1LL * (X[j + 1] - X[j]) * min(rightRest, leftLeft);
    }

    sub *= 2;

    sub += X[i];
    ret = max(ret, sub);
    uku = max(uku, ret);
    return ret;
  };

  int from = 0;
  int to = N;
  while(to - from > 20) {
    int mid = (from + to) / 2;
    (Z(mid) - Z(mid - 1) > 0 ? from : to) = mid;
  }
  while(from < to) {
    Z(from++);
  }
  return uku;
}


int main() {
  cin >> L >> N;
  vector< int > X(N + 1);
  X[0] = 0;
  for(int i = 1; i <= N; i++) cin >> X[i];
  int64 ret = solve(X);
  for(auto &p : X) p = (L - p) % L;
  sort(begin(X), end(X));
  cout << max(ret, solve(X)) << endl;
}

