    return spin(i, j-1, j, ans+dl, L);
  } else if(dr > dl) {
    return spin(i+1, j, i, ans+dr, L);
  } else {
    // cout << "branch" << endl;
    return max(spin(i, j-1, j, ans+dl, L), spin(i+1, j, i, ans+dr, L));
  }
  // return max(spin(i, j-1, j, ans+dl, L), spin(i+1, j, i, ans+dr, L));
}

