ll dist(int x, int y, bool isClock)
{
  if (isClock) {
    if (x > y) return (x - y);
    else return (L - (y - x));
  } else {
    if (x < y) return (y - x);
    else return (L - (x - y));
  }
}

void init() {
  REP(i, 3000)REP(j, 3000) dp[i][j][0] = dp[i][j][1] = -1;
}

ll dfs(int i, int j, int now)
{
  if (dp[i][j][now] > 0) {
    return dp[i][j][now];
  }
  if (i == j) return 0;

  if (now == 0) {
    // i地点のものは既にとっている
    // i+1をとるか,jをとるか
    ll tmp1 = dfs(i+1,j,0) + dist(X[i],X[i+1],false);
    ll tmp2 = dfs(i+1,j,1) + dist(X[i],X[j],true);
    return dp[i][j][0] = max(tmp1, tmp2);
  } else {
    // j地点のものは既にとっている
    // iをとるか,j-1をとるか
    ll tmp1 = dfs(i,j-1,0) + dist(X[j],X[i],false);
    ll tmp2 = dfs(i,j-1,1) + dist(X[j],X[j-1],true);
    return dp[i][j][1] = max(tmp1, tmp2);
  }
