#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

const int MAXN = 200055;

int B[MAXN*2];
int A[MAXN];

ll Ans;
int N, L;

void goRight(int s, int e) {
	int lc = N-s+1, rc = e-N-1;
	ll t = 0;
	if(lc+1 <= rc) {
		for(int i = e, c = 1; N+1 < i; i--, c += 2)
			t += ll(B[i] - B[i-1]) * min(c, lc*2+1);
		for(int i = s, c = 2; i < N+1; i++, c += 2)
			t += ll(B[i+1] - B[i]) * c;
	} else {
		for(int i = e, c = 1; N+1 < i; i--, c += 2)
			t += ll(B[i] - B[i-1]) * c;
		for(int i = s, c = 2; i < N+1; i++, c += 2)
			t += ll(B[i+1] - B[i]) * min(c, rc*2);
	}
	if(Ans < t) Ans = t;
}

void solve() {
	for(int i = 1; i <= N; i++) {
		B[N+i+1] = A[i];
		B[i] = A[i]-L;
	}

	for(int s = 2, e = N+2; e <= N*2+1; s++, e++)
		goRight(s, e);
}

