	for(int i = 1; i <= N; i++) cin >> A[i];

	solve();
	reverse(A+1, A+N+1);
	for(int i = 1; i <= N; i++) A[i] = L-A[i];
	solve();

	cout << Ans << endl;
	return 0;
}

