	x[n + 1] = l;

	n++;
	inc(i, n) { d[i] = x[i + 1] - x[i]; }
	inc(i, n) { s[i + 1] = s[i] + d[i]; }


	LL ans = 0, sum = 0;
	inc(i, n) {
		if(i == 0) {
			sum = 0;
		} else {
			if(2 * i - 1 < n) {
				int x = i - 1, y = 2 * i - 1;
				sum +=  2 * ID(0, x);
				sum += -2 * CD(x, y);
				sum +=  2 * CD(y, n);
				sum +=  d[x];
			} else {
				int x = 2 * i - 1 - n, y = i - 1;
				sum += -2 * ID(0, x);
				sum +=  2 * CD(x, y);
				sum += -2 * CD(y, n);
				sum +=  d[y];
			}
		}
