ll solve1(ll a) {
  ll ret = 0, le = n - 1, ri = a;
  ll num = le - ri - 1;

  ret = rsum[ri + (num + 1) / 2];
  if (ri) ret -= rsum[ri - 1];
  if (num % 2) ret -= x[ri + (num + 1) / 2];

  ret += lsum[le - num / 2];
  if (num % 2 == 0) ret -= m - x[le - num / 2];

  return ret;
}

ll solve2(ll a) {
  ll ret = 0, le = a, ri = 0;
  ll num = le - ri - 1;

  ret = lsum[le - (num + 1) / 2];
  if (le != n - 1) ret -= lsum[le + 1];
  if (num % 2) ret -= m - x[le - (num + 1) / 2];

  ret += rsum[ri + num / 2];
  if (num % 2 == 0) ret -= x[ri + num / 2];

  return ret;
}

