  lsum[n - 1] = (m - x[n - 1]) * 2;
  RFOR(i, 0, n - 1) lsum[i] = lsum[i + 1] + (m - x[i]) * 2;

  ans = max(x[n - 1] / 2, (m - x[0]) / 2);
  rep(i, n - 1) ans = max(ans, solve1(i));
