    }
    for(int i = N - 1; i >= 0; i--){
        int res = 0;
        if(N - i <= i){
            res = sum1l[i] + sum2r[i - 1];
            if(i - 1 - (N - i) >= 0){
                res -= sum2r[i - 1 - (N - i)];
            }
            m = 3;
        }
        else {
            res = sum1l[i];
            if(i - 1 >= 0) res += sum2r[i - 1];
            res -= sum2l[N - (N - i - i - 1)];
            m = 4;
        }
        //printf("i:%lld m:%lld res:%lld\n", i, m, res);
        ans = max(ans, res);
    }
    cout << ans << endl;


    return 0;
}

