using namespace std;
typedef long long LL;

LL L;
LL ans1(vector<LL> a){
	sort(a.begin(), a.end());
	int n = a.size();
	vector<LL> psums(n+1);
	psums[0] = 0;
	for(int i = 1; i <= n; i++){
		psums[i] = psums[i-1] + a[i-1];
	}
	LL best = 0;
	for(int q = 0; q < 2; q++){
		for(int cut = 0; cut <= n; cut++){
			int n1 = cut + 1;
			if(q == 0){
				n1 = min(n1, (n - (cut+1) ));
			} else {
				n1 = min(n1, 1 + (n - (cut+1) ));				
			}
			int n2 = n1;
			if(q) n2--;
			if(n1 <= 0) continue;
			//cout << cut << " " << q << " " << n1 << " " << n2 << endl;
			LL z = 0;
			z += (psums[cut+1] - psums[cut + 1 - n1]) * 2;
			z += (L * n2 - (psums[cut+1+n2] - psums[cut+1]) )* 2;
			if(n1 == n2){
				z -= (L - a[cut+1]);
				best = max(best, z);
			} else {
				z -= a[cut];
				best = max(best, z);
			}
			//cout << best << endl;
		}
	}
	return best;
}

