            b = *prev(it);
        }
        if (i <= k) isB = h == 1;
        if (isB) a = b;
        tot += abs(cur - a);
        a %= L;
        cur = L + a;
        T.erase(a);
        T.erase(L + a);
        T.erase(2 * L + a);
        isB = !isB;
    }
    MAX(ans, tot);
    return F[h][k] = tot;
}

