    // setError("err.txt");
    read(L, N);
    read(X, X + N);
    FOR(h, 2) FOR(k, N + 3) F[h][k] = -1;
    FOR(h, 2) {
        int lo = 0, hi = N, mid;
        while (lo < hi) {
            mid = lo + (hi - lo) / 2;
            if (f(h, mid) > f(h, mid + 1)) hi = mid;
            else lo = mid + 1;
        }
        For(k, lo - 2, lo + 3) f(h, k);
    }
    writeln(ans);
    return 0;
}

