			ll tmp2 = (L - X[back]) + X[front];
			if (tmp >= tmp2) {
				ans += tmp;
				back--;
				dir = false;
			}
			else {
				ans += tmp2;
				front++;
				dir = true;
			}
		}
		num--;
	}

