typedef long long int LL;
typedef std::pair<std::pair<LL, LL>, std::pair<LL, LL>> P;
struct edge { LL to, cost; };

const LL inf = 11234567890123456;
LL L, N;
std::vector<LL>X, dist;

void dijkstra(LL s)
{
	std::priority_queue<P, std::vector<P>, std::greater<P>>que;
	std::fill(dist.begin(), dist.end(), inf);
	dist[s] = 0;
	que.push(std::make_pair(std::make_pair(0, s), std::make_pair(0, N + 1)));
	while (!que.empty())
	{
		P p = que.top(); que.pop();
		LL d = p.first.first, v = p.first.second, left = p.second.first, right = p.second.second;
		if (dist[v] < d || left + 1 == right) continue;
		if (left == v)
		{
			if (dist[v + 1] > dist[v] + -(X[v + 1] - X[v]))
			{
				dist[v + 1] = dist[v] + -(X[v + 1] - X[v]);
				que.push(std::make_pair(std::make_pair(dist[v + 1], v + 1), std::make_pair(left + 1, right)));
			}
			if (dist[right - 1] > dist[v] + -(X[v] + (L - X[right - 1])))
			{
				dist[right - 1] = dist[v] + -(X[v] + (L - X[right - 1]));
				que.push(std::make_pair(std::make_pair(dist[right - 1], right - 1), std::make_pair(left, right - 1)));
			}
		}
		else
		{
			if (dist[v - 1] > dist[v] + -(X[v] - X[v - 1]))
			{
				dist[v - 1] = dist[v] + -(X[v] - X[v - 1]);
				que.push(std::make_pair(std::make_pair(dist[v - 1], v - 1), std::make_pair(left, right - 1)));
			}
			if (dist[left + 1] > dist[v] + -((L - X[v]) + X[left + 1]))
			{
				dist[left + 1] = dist[v] + -((L - X[v]) + X[left + 1]);
				que.push(std::make_pair(std::make_pair(dist[left + 1], left + 1), std::make_pair(left + 1, right)));
			}
		}
	}
}

