{
	in >> L >> N;
	X.resize(N + 1);
	rep(i, N) in >> X[i + 1];

	X[0] = 0;
	dist.resize(N + 1);
	dijkstra(0);

	LL ans = 0;
	for (LL i = 1; i <= N; ++i) ans = std::max(ans, -dist[i]);
	out << ans << std::endl;
}

