lint linsum(int s, int e){
	return s2[e] - s2[s];
}

lint solve(){
	sort(a, a + n);
	a[n] = l;
	for(int i=0; i<n; i++){
		d[i] = a[i+1] - a[i];
	}
	d[n] = a[0];
	for(int i=0; i<n-1; i++) d[i+n+1] = d[i];
	for(int i=0; i<2*n; i++){
		s1[i+1] = s1[i] + d[i];
		s2[i+1] = s2[i] + 1ll * d[i] * i;
	}
	lint dap = 0;
	for(int i=0; i<=n; i++){
		int min_len = min(n - i, i);
		lint ret = 0;
		ret += linsum(i, i + min_len) * 2 + (1 - 2 * i) * gsum(i, i + min_len);
		ret += (2 * n + 2 * i) * gsum(n + i - min_len, n + i) - 2 * linsum(n + i - min_len, n + i);
		/*
		for(int j=i; j<i+min_len; j++){
			ret += ((j - i) * 2 + 1) * d[j];
		}
		for(int j=n+i-min_len; j<n+i; j++){
			ret += ((n + i - j) * 2) * d[j];
		}*/
		lint tmp = gsum(i + min_len, n + i - min_len);
		if(i + min_len != n){
			ret += tmp * (2 * min_len + 1);
		}
		else{
			ret += tmp * (2 * min_len);
		}
		dap = max(dap, ret);
	}
	return dap;
}

