ll solve(int n, int cut, VI seq) {
    ll best = 0;
    FOR(right,0,1) {
        if (right) {
            reverse(seq.begin(), seq.end());
            cut = n - cut;
        }

        if (cut == 0) continue;

        ll ans = 0;

        FOR(i,0,cut-1) {
            ans += (ll) seq[i] * (2 * min(i, n - cut) + 1);
        }

        FOR(i,cut,n-1) {
