int GetMoveDistance2(int*&  iTrees, const int& iFirst, const int& iLast, int& L)
{
	if (iFirst == iLast)
	{
		return 0;
	}
	int hantokei = iTrees[iFirst+1] - iTrees[iFirst];
	hantokei +=  GetMoveDistance2(iTrees, iFirst + 1, iLast, L);

	int tokei = iTrees[iFirst] + L - iTrees[iLast];
	tokei += GetMoveDistance2(iTrees, iFirst, iLast-1, L);

	return tokei > hantokei ? tokei : hantokei;
}

