int main(void){
	int L,N,i,current,right,left,dr,dl,ans=0;
	scanf("%d %d",&L,&N);
	int X[N],C[L];
	for(i=0;i<L;i++) C[i]=0;
	for(i=0;i<N;i++) scanf("%d",&X[i]);

	for(i=0;i<N;i++) C[X[i]]=1;//状態
	current=0;//現在の位置

	for(i=0;i<N;i++){
		dr=0;
		right=current;
		while(1){//右側を探す
			if(C[right]==1) break;
			else{
				right=(right+1)%L;
				dr++;
			}
		}
		dl=0;
		left=current;
		while(1){//左側を探す
			if(C[left]==1) break;
			else{
				left=(left-1+L)%L;
				dl++;
			}
		}

		if(dr>dl){
			C[right]=0;
			ans+=dr;
			current=right;
		}
		else{
			C[left]=0;
			ans+=dl;
			current=left;
		}
	}
	printf("%d",ans);
}

