unsigned long long int calc1(unsigned int l_length, unsigned int n_numoftree, unsigned int *x_pos)
{
	unsigned int forward = 0;
	unsigned int reverse = 0;
	unsigned int dist_r = 0;
	unsigned int dist_f = 0;
	unsigned int currentr = 0;
	unsigned int currentf = 0;
	unsigned long long int walking_len = 0;
    int cur_pos = 0;

    forward = n_numoftree - 1;
    while(1) {
    	switch(cur_pos) {
    	case 2: // 時計回り
    		dist_r = x_pos[reverse] + (l_length - currentf);
    		dist_f = currentf - x_pos[forward];
    		break;
    	case 1: // 反時計回り
    		dist_r = x_pos[reverse] - currentr;
    		dist_f = currentr + (l_length - x_pos[forward]);
    		break;
    	case 0: // 一番最初
    	default:
    		dist_r = x_pos[reverse];
    		dist_f = l_length - x_pos[forward];
        	cur_pos = 1;
        	walking_len += dist_r;
        	currentr = x_pos[reverse];
        	x_pos[reverse] = 0;
        	reverse++;
        	continue;
    		break;
    	}

        if(dist_r >= dist_f) {
//            printf("r %d %12d %12d %12d %12d\n",reverse, dist_r, dist_f, x_pos[reverse], x_pos[forward]);
        	cur_pos = 1;
        	walking_len += dist_r;
        	currentr = x_pos[reverse];
        	x_pos[reverse] = 0;
        	reverse++;
        } else {
//            printf("f %d %12d %12d %12d %12d\n", forward, dist_r, dist_f, x_pos[reverse], x_pos[forward]);
        	cur_pos = 2;
        	walking_len += dist_f;
        	currentf = x_pos[forward];
        	x_pos[forward] = 0;
        	forward--;
        }

        if ((x_pos[reverse] == 0) || (x_pos[forward] == 0)) {
//            printf("break %d %d %d %d\n",reverse, forward, x_pos[reverse], x_pos[forward]);
        	break;
        }
    }

	return walking_len;
}

