#define MAX(a,b) ((a)>(b)?(a):(b))

int64 calc(const int *x,const int n,const int l){
  int64 ans=0;
  int i,j;
  for(i=0;i<n;i++){
    int64 local=x[i];
    for(j=0;i+j+1<n-1-j;j++){
      local+=x[i+j]+l-x[n-1-j];
      local+=l-x[n-1-j]+x[i+j+1];
    }
    if(i+j<n-1-j) local+=x[i+j]+l-x[n-1-j];
    ans=MAX(ans,local);
  }
  return ans;
}

