long long solve(long long a[],long long n,long long l){
  long long i,res,r,w,c,g;
  r=a[n];c=1;g=n;
  res=r;
  for(i=n-1;i>=1;i--){
    c++;
    r+=l;
    if(c%2==0){
      g--;
      r-=2*a[g+1];
      r+=2*a[i];
    }
    else{
      r-=2*a[g+1];
      r+=(a[g+1]-a[g]);
      r+=2*a[i];
    }
    res=llmax(r,res);
  }
  return res;
}

