	int x[N];
	for (int i = 0; i < N; ++i)
	{
		scanf("%d",&x[i]);
	}
	int me = 0;
	int begin = 0;
	int end = N-1;
	int ans = 0;
	int count = 0;
	int direction =1;
	int hoge,poyo;
	while(count < N){
		if(direction==0){
			hoge=me-x[end];
			poyo=(L-me)+x[begin];
		}if(direction==1){
			hoge=(L-x[end])+me;
			poyo=x[begin]-me;
		}
		if(poyo >= hoge){
			ans += poyo;
			me = x[begin];
			begin++;
			direction = 1;
		}else{
			ans += hoge;
			me = x[end];
			end--;
			direction = 0;
		}
		count++;
	}
	printf("%d",ans);
	return 0;
}

