int main(){
	int L,N;
	scanf("%d %d",&L,&N);
	int x[N+1];
	int i,d_right,d_left;
	for(i=1;i<=N;i++){
		scanf("%d",&x[i]);
	}
	int d = 0;//移動距離
	int r,l;//まだ燃えていない木の，高橋君から左右にあるものを表すラベル
	r = 1;
	l = N;
	int t=0;//高橋君の座標を表す

	while(r != l){
		if(t < x[r]){//高橋君が家より右にいるとき
			d_right = x[r]-t;
		}else{
			d_right = x[r]+(L-t);
		}
		if(t < x[l]){//高橋君が家より右にいるとき
			d_left = (L-x[l])+t;
		}else{
			d_left = t - x[l];
		}

		if(d_right < d_left){//左のほうが遠いので左を燃やす
			t = x[l];
			d += d_left;
			l -= 1;
		}else{
			t = x[r];
			d += d_right;
			r += 1;
		}
	}

	if(t < x[r]){//高橋君が家より右にいるとき
		d += Mymax(x[r]-t,L-(x[r]-t));
	}else{
		d += Mymax(t-x[r],L-(t-x[r]));
	}

	printf("%d\n",d);
	return 0;
}

int Mymax(int a,int b){
	int r;
	if(a > b){
		r = a;
	}else{
		r = b;
	}
	return r;
}

int Mymin(int a,int b){
	int r;
	if(a < b){
		r = a;
	}else{
		r = b;
	}
	return r;
}

