long long walk(int a[], int n, int l, int now, int p, int q)
{
    int i;
    long long c = 0;
    long long cw, ccw;

    for (i = 0; i < n; i++) {
        ccw = ((long long) a[p] - now + l) % l;
        cw = ((long long) now + l - a[q]) % l;

        if (ccw == cw) {
            //printf("fork.\n");
            ccw += walk(a, n - i - 1, l, a[p], p + 1, q);
            cw  += walk(a, n - i - 1, l, a[q], p, q - 1);
            if (ccw > cw) {
                c += ccw;
            } else {
                c += cw;
            }
            break;
        } else if (ccw > cw) {
            //printf("ccw: %d to %d , dist=%d > %d\n", now, a[p], ccw, cw);
            //反時計
            c += ccw;
            now = a[p];
            p++;
        } else {
            //printf("cw : %d to %d , dist=%d > %d\n", now, a[q], cw, ccw);
            //時計
            c += cw;
            now = a[q];
            q--;
        }
    }

    return c;
}

