    long int x[200010], y[200010];
    long int ans = 0;
    scanf("%ld%d", &l, &n);
    for (int i = 0; i < n; i++)
    {
        scanf("%ld", &x[i]);
        y[i] = x[i] - l;
    }
    int m = n - 1, p = 0;
    long int t = 0;
    while (m >= p)
    {
        if (x[p] - t > t - y[m])
        {
            ans += x[p] - t;
            t = x[p];
            p++;
        }
        else if (x[p] - t < t - y[m])
        {
            ans += t - y[m];
            t = y[m];
            m--;
        }
        else
        {
            int j = 0;
            while (x[p + j] - t == t - y[m - j])
                j++;
            if (x[p + j] - t > t - y[m - j])
            {
                ans += x[p] - t;
                t = x[p];
                p++;
            }
            else if (x[p + j] - t < t - y[m - j])
            {
                ans += t - y[m];
                t = y[m];
                m--;
            }
        }
    }
    printf("%ld", ans);
    return 0;
}

