/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskB solver = new TaskB();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskB {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            long len = in.nextInt();
            int n = in.nextInt();
            long[] x = new long[n];
            for (int i = 0; i < n; ++i) {
                x[i] = in.nextInt();
            }
            long[][][] best = new long[2][n + 1][n + 1];
            for (int first = 0; first < n; ++first) {
                for (int last = 0; first + last < n; ++last) {
                    long pleft = first == 0 ? 0 : (x[n - first] - len);
                    long pright = last == 0 ? 0 : x[last - 1];
                    for (int old = 0; old < 2; ++old) {
                        long at = old == 0 ? pleft : pright;
                        best[0][first + 1][last] = Math.max(best[0][first + 1][last], best[old][first][last] + at - (x[n - first - 1] - len));
                        best[1][first][last + 1] = Math.max(best[1][first][last + 1], best[old][first][last] + x[last] - at);
                    }
                }
            }
            long res = 0;
            for (long[][] a : best) for (long[] b : a) for (long c : b) res = Math.max(res, c);
            out.println(res);
        }

    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

import java.util.*;
import java.util.concurrent.LinkedBlockingDeque;

public class Main {
	long L;
	int N;
	List<Long> X;
	long result = 0;

	Main() {
		Scanner in = new Scanner(System.in);
		L = in.nextLong();
		N = in.nextInt();
		X = new ArrayList<>(N);
		for (int i = 0; i < N; ++i) {
			X.add(in.nextLong());
		}
		in.close();
	}

	void calc() {
		for (int i = 0; i < N; ++i) {
			Deque<Long> queue = new LinkedBlockingDeque<>();
			queue.addAll(X);
			result = Math.max(result, calc(queue, true, i));
		}
		for (int i = 0; i < N; ++i) {
			Deque<Long> queue = new LinkedBlockingDeque<>();
			queue.addAll(X);
			result = Math.max(result, calc(queue, false, i));
		}
	}

	long calc(Deque<Long> X, boolean direction, int firstChangeDirIndex) {
		long result = 0;
		long position = 0L;
		int index = 0;
		while (!X.isEmpty()) {
			long dist = 0;
			if (direction) {
				long x = X.pollFirst();
				dist = (x - position + L) % L;
				position = x;
			} else {
				long x = X.pollLast();
				dist = (position - x + L) % L;
				position = x;
			}
			result += dist;
			if (index >= firstChangeDirIndex) {
				direction = !direction;
			}
			index++;
		}
		return result;
	}

	public static void main(String[] args) {
		Main ins = new Main();
		ins.calc();
		System.out.println(ins.result);
	}
}

