public class Main {

	public static void main(String[] args) {
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		MyInput in = new MyInput(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		TaskX solver = new TaskX();
		solver.solve(1, in, out);
		out.close();
	}

	static int INF = 1 << 30;
	static long LINF = 1L << 55;
	static int MOD = 1000000007;
	static int[] mh4 = { 0, -1, 1, 0 };
	static int[] mw4 = { -1, 0, 0, 1 };
	static int[] mh8 = { -1, -1, -1, 0, 0, 1, 1, 1 };
	static int[] mw8 = { -1, 0, 1, -1, 1, -1, 0, 1 };

	static class TaskX {

		int L, n;
		public void solve(int testNumber, MyInput in, PrintWriter out) {

			L = in.nextInt(); n = in.nextInt();
			long[] x = new long[n+2], s = new long[n+2];

			for (int i = 1; i < n+1; i++) {
				x[i] = in.nextLong();
				s[i] = s[i-1] + x[i];
			}
			x[n+1] = L;

			long ans = 0;

			// 右 左 右 ...
			for (int i = 1; i <= n; i++) {
				ans = Math.max(ans, calc(i, x, s));
			}

			// 左 右 左...
			long[] rx = new long[n+2];
			for (int i = 0; i < n+2; i++) {
				rx[i] = L - x[n+1-i];
			}
			long[] rs = rx.clone();
			Arrays.parallelPrefix(rs, Math::addExact);
			for (int i = 1; i <= n; i++) {
				ans = Math.max(ans, calc(i, rx, rs));
			}

			out.println(ans);
		}

		long calc(int i, long[] x, long[] s) {
			long tmp = 0;
			if ((n + i) % 2 == 0) {
				int m = (n + i) / 2;
				tmp = 2 * (s[m-1] - s[i-1]) + x[m] - 2 * (s[n] - s[m]) + (n-i) * L;
			} else {
				int m = (n + i + 1) / 2;
				tmp = 2 * (s[m-1] - s[i-1]) - x[m] - 2 * (s[n] - s[m]) + (n-i) * L;
			}
			return tmp;
		}
	}

	static class MyInput {
		private final BufferedReader in;
		private static int pos;
		private static int readLen;
		private static final char[] buffer = new char[1024 * 8];
		private static char[] str = new char[500 * 8 * 2];
