		int n = sc.nextInt();
		ArrayList<Long> x = new ArrayList<>();
		for(int i = 1; i <= n; i++){
		    x.add(sc.nextLong());
		}
		Collections.sort(x);

    		// 出力
		System.out.println(burn(x, l, 0, n-1, 0));
    	}

	private static long burn(ArrayList<Long> x1, long l1, int imin, int imax, long now){
	    if(imin == imax){
		long a = Math.abs(x1.get(imin) - now);
		if(a > l1 /2){
		    return a;
		}else{
		    return l1 - a;
		}
	    }else{
		long a = x1.get(imin) - now;
		if(a < 0){
		    a += l1;
		}
		long right = a + burn(x1, l1, imin+1, imax, x1.get(imin));

		a = now - x1.get(imax);
		if(a < 0){
		    a += l1;
		}
		long left = a + burn(x1, l1, imin, imax-1, x1.get(imax));

		if(right > left){
		    return right;
		}else{
		    return left;
		}
	    }
	}
    }

import java.util.*;
import java.util.concurrent.LinkedBlockingDeque;

public class Main {
	long L;
	int N;
	List<Long> X;
	long result = 0;

	Main() {
		Scanner in = new Scanner(System.in);
		L = in.nextLong();
		N = in.nextInt();
		X = new ArrayList<>(N);
		for (int i = 0; i < N; ++i) {
			X.add(in.nextLong());
		}
		in.close();
	}

	void calc() {
		Deque<Long> queue = new LinkedBlockingDeque<>();
		queue.addAll(X);
		result = Math.max(result, calc(queue));
		queue = new LinkedBlockingDeque<>();
		queue.addAll(X);
		queue.pollFirst();
		result = Math.max(result, calc(queue));
		queue = new LinkedBlockingDeque<>();
		queue.addAll(X);
		queue.pollLast();
		result = Math.max(result, calc(queue));		
	}

	long calc(Deque<Long> X) {
		long result = 0;
		long position = 0L;
		while (!X.isEmpty()) {
			long rightDist = (X.getFirst() - position + L) % L;
			long leftDist = (position - X.getLast() + L) % L;
			if (rightDist >= leftDist) {
				result += rightDist;
				position = X.pollFirst();
			} else {
				result += leftDist;
				position = X.pollLast();
			}
		}
		return result;
	}

	public static void main(String[] args) {
		Main ins = new Main();
		ins.calc();
		System.out.println(ins.result);
	}
}

import java.util.*;
public class Main{
  public static Map<String, Long> map = new HashMap<>();
  public static void main(String[] args){
    Scanner sc = new Scanner(System.in);
    long L = sc.nextLong();
    int N = sc.nextInt();
    long[] X = new long[N+1];
    X[0] = 0;
    for(int i = 1; i <= N; i++){
      X[i] = sc.nextLong();
    }
    System.out.println(solve(N, X, L));
  }

  public static long solve(int N, long[] X, long L){
    return reve(N, X, 0, L);
  }

  public static long func(int N, long[] array, boolean der, int index, long L){
    if(N == 0){
      return 0;
    }
    if(map.containsKey(Arrays.toString(array)) && N == array.length){
      return map.get(Arrays.toString(array));
    }
    long[] arrayCopy = Arrays.copyOf(array, array.length);
    int lastIndex = index;
    boolean flag = false;
    if(der){
      do{
        index++;
        if(index == array.length){
          index = 0;
          flag = true;
        }
      }while(arrayCopy[index] == 0);
    }else{
      do{
        index--;
        if(index == -1){
          index = array.length-1;
          flag = true;
        }
      }while(arrayCopy[index] == 0);
    }
    long tmp;
    if(!flag){
      tmp = Math.abs(arrayCopy[index]-arrayCopy[lastIndex]);
    }else if(der){
      tmp = Math.abs(L - arrayCopy[lastIndex] + arrayCopy[index]);
    }else{
      tmp = Math.abs(L - arrayCopy[index] + arrayCopy[lastIndex]);
    }
    arrayCopy[lastIndex] = 0;
    long ans = tmp + func(N-1, arrayCopy, !der, index, L);
    map.put(Arrays.toString(array), ans);
    return ans;
  }

  public static long reve(int N, long[] array, int index, long L){
    return Math.max(func(N, array, true, index, L), func(N, array, false, index, L));
  }
}

