public class Main {

	public static void main(String[] args) throws IOException {
		FastScanner sc = new FastScanner(System.in);

		int L = sc.nextInt();
		int N = sc.nextInt();
		int[] X = new int[N+2];
		for(int i = 1; i <= N; i++) X[i] = sc.nextInt();
		X[N+1] = L;

		long[][][] dp = new long[N+1][N+1][2];
		for(int i = 0; i <= N - 1; i++){
			for(int j = 0; j <= N - i - 1; j++){
				dp[i+1][j][0] = Math.max(dp[i][j][0] + X[i+1] - X[i], dp[i][j][1] + X[i+1] + L - X[N-j+1]);
				dp[i][j+1][1] = Math.max(dp[i][j][1] + X[N-j+1] - X[N-j], dp[i][j][0] + X[i] + L - X[N-j]);				
			}
		}

		long ans = 0;
		for(int i = 0; i <= N; i++){
			ans = Math.max(ans, dp[i][N-i][0]);
			ans = Math.max(ans, dp[i][N-i][1]);
		}
		System.out.println(ans);
	}
}

