      int cwToLast = currPos >= x[last] ? currPos - x[last] : currPos + l - x[last];
      if (ccwToFirstDist > cwToLast) {
        dist += ccwToFirstDist;
        currPos = x[first];
        first++;
      } else {
        dist += cwToLast;
        currPos = x[last];
        last--;
      }
    }
    System.out.println(dist);
  }
}

