	static class TaskX {

		public void solve(int testNumber, MyInput in, PrintWriter out) {

			long L = in.nextLong();
			int n = in.nextInt();

			if (n > 2000) return;

			long[] x = new long[n+2];
			for (int i = 1; i < n+1; i++) {
				x[i] = in.nextLong();
			}
			x[n+1] = L;

			long ans = 0;
			// 右にi本進んであとはジグザグに動く
			for (int i = 1; i < n+1; i++) {
				long tmp = 0;
				int l = i, r = n, c = 0;
				tmp += abs(x[l] - x[0]);
				while (r - l >= 1) {
					if (c % 2 == 0) {
						tmp += abs(x[l] - x[0]) + abs(x[n+1] - x[r]);
						l++;
					} else {
						tmp += abs(x[l] - x[0]) + abs(x[n+1] - x[r]);
						r--;
					}
					c++;
				}
				ans = max(ans, tmp);
			}

			// 左にi本進んであとはジグザグに動く
			for (int i = n; i >= 1; i--) {
				long tmp = 0;
				int l = 1, r = i, c = 1;
				tmp += abs(x[n+1] - x[r]);
				while (r - l >= 1) {
					if (c % 2 == 0) {
