	static class TaskX {

		long L;
		int n;
		public void solve(int testNumber, MyInput in, PrintWriter out) {

			L = in.nextLong();
			n = in.nextInt();

			if (n > 2000) return;

			long[] x = new long[n+2];
			for (int i = 1; i < n+1; i++) {
				x[i] = in.nextLong();
			}
			x[n+1] = L;

			long ans = 0;
			// 右にi本進んであとはジグザグに動く
			for (int i = 1; i < n+1; i++) {
				ans = max(ans, calc(i, x));
			}

			// 左にi本進んであとはジグザグに動く
			long[] rx = new long[n+2];
			for (int i = 0; i < n+2; i++) {
				rx[i] = L - x[n+1-i];
			}
			for (int i = n; i >= 1; i--) {
				ans = max(ans, calc(i, rx));
			}

			out.println(ans);
		}

		long calc(int i, long[] x) {
			long tmp = 0;
			int l = i, r = n, c = 0;
			tmp += abs(x[l] - x[0]);
			while (r - l >= 1) {
				if (c % 2 == 0) {
					tmp += abs(x[l] - x[0]) + abs(x[n+1] - x[r]);
					l++;
				} else {
					tmp += abs(x[l] - x[0]) + abs(x[n+1] - x[r]);
					r--;
				}
				c++;
			}
			return tmp;
		}
	}

	static class MyInput {
		private final BufferedReader in;
		private static int pos;
		private static int readLen;
		private static final char[] buffer = new char[1024 * 8];
		private static char[] str = new char[500 * 8 * 2];
		private static boolean[] isDigit = new boolean[256];
		private static boolean[] isSpace = new boolean[256];
		private static boolean[] isLineSep = new boolean[256];

		static {
			for (int i = 0; i < 10; i++) {
				isDigit['0' + i] = true;
			}
			isDigit['-'] = true;
			isSpace[' '] = isSpace['\r'] = isSpace['\n'] = isSpace['\t'] = true;
			isLineSep['\r'] = isLineSep['\n'] = true;
		}

		public MyInput(InputStream is) {
			in = new BufferedReader(new InputStreamReader(is));
		}

		public int read() {
			if (pos >= readLen) {
				pos = 0;
				try {
					readLen = in.read(buffer);
				} catch (IOException e) {
					throw new RuntimeException();
				}
				if (readLen <= 0) {
					throw new MyInput.EndOfFileRuntimeException();
				}
			}
			return buffer[pos++];
		}

		public int nextInt() {
			int len = 0;
			str[len++] = nextChar();
			len = reads(len, isSpace);
			int i = 0;
			int ret = 0;
			if (str[0] == '-') {
				i = 1;
			}
			for (; i < len; i++)
				ret = ret * 10 + str[i] - '0';
			if (str[0] == '-') {
				ret = -ret;
			}
			return ret;
		}

		public long nextLong() {
			int len = 0;
			str[len++] = nextChar();
			len = reads(len, isSpace);
			int i = 0;
			long ret = 0;
			if (str[0] == '-') {
				i = 1;
			}
			for (; i < len; i++)
				ret = ret * 10 + str[i] - '0';
			if (str[0] == '-') {
				ret = -ret;
			}
			return ret;
		}

		public char nextChar() {
			while (true) {
				final int c = read();
				if (!isSpace[c]) {
					return (char) c;
				}
			}
		}

		public String nextString() {
			return new String(nextChars());
		}

		public char[] nextChars() {
			int len = 0;
			str[len++] = nextChar();
			len = reads(len, isSpace);
			return Arrays.copyOf(str, len);
		}

		int reads(int len, boolean[] accept) {
			try {
				while (true) {
					final int c = read();
					if (accept[c]) {
						break;
					}
					if (str.length == len) {
						char[] rep = new char[str.length * 3 / 2];
						System.arraycopy(str, 0, rep, 0, str.length);
						str = rep;
					}
					str[len++] = (char) c;
				}
			} catch (MyInput.EndOfFileRuntimeException e) {
			}
			return len;
		}

		public int[] nextIntArray(final int n) {
			final int[] res = new int[n];
			for (int i = 0; i < n; i++) {
				res[i] = nextInt();
			}
			return res;
		}

		public int[] nextIntArray1Index(final int n) {
			final int[] res = new int[n + 1];
			for (int i = 1; i < n + 1; i++) {
				res[i] = nextInt();
			}
			return res;
		}

		public int[] nextIntArrayDec(final int n) {
			final int[] res = new int[n];
			for (int i = 0; i < n; i++) {
				res[i] = nextInt() - 1;
			}
			return res;
		}

		public long[] nextLongArray(final int n) {
			final long[] res = new long[n];
			for (int i = 0; i < n; i++) {
				res[i] = nextLong();
			}
			return res;
		}

		public long[] nextLongArray1Index(final int n) {
			final long[] res = new long[n + 1];
			for (int i = 1; i < n + 1; i++) {
				res[i] = nextLong();
			}
			return res;
		}

		public long[] nextLongArrayDec(final int n) {
			final long[] res = new long[n];
			for (int i = 0; i < n; i++) {
				res[i] = nextLong() - 1;
			}
			return res;
		}

		public double nextDouble() {
			return Double.parseDouble(nextString());
		}

		public double[] nextDoubleArray(int n) {
			double[] res = new double[n];
			for (int i = 0; i < n; i++) {
				res[i] = nextDouble();
			}
			return res;
		}

		static class EndOfFileRuntimeException extends RuntimeException {
		}

	}

}

import static java.lang.Integer.parseInt;
import static java.lang.Long.parseLong;
import static java.lang.Math.max;
import static java.lang.Math.min;
import static java.lang.System.exit;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {

	static void solve() throws Exception {
		long l = scanInt();
		int n = scanInt();
		long x[] = new long[n];
		for (int i = 0; i < n; i++) {
			x[i] = scanInt();
		}
		long ans = 0;
		for (int it = 0;; it++) {
			for (int i = 0; i < n; i++) {
				long cans = x[n - i - 1];
				for (int j = n - i; j < min(n, 2 * n - 2 * i); j++) {
					cans += (l - x[j]) * 2;
				}
				for (int j = max(0, n - 2 * i - 1); j < n - i - 1; j++) {
					cans += x[j] * 2;
				}
				ans = max(ans, cans);
			}
			if (it == 0) {
				for (int i = 0, j = n - 1; i <= j; i++, j--) {
					long t = x[i];
					x[i] = l - x[j];
					x[j] = l - t;
				}
			} else {
				break;
			}
		}
		out.print(ans);
	}

	static int scanInt() throws IOException {
		return parseInt(scanString());
	}

	static long scanLong() throws IOException {
		return parseLong(scanString());
	}

	static String scanString() throws IOException {
		while (tok == null || !tok.hasMoreTokens()) {
			tok = new StringTokenizer(in.readLine());
		}
		return tok.nextToken();
	}

	static BufferedReader in;
	static PrintWriter out;
	static StringTokenizer tok;

	public static void main(String[] args) {
		try {
			in = new BufferedReader(new InputStreamReader(System.in));
			out = new PrintWriter(System.out);
			solve();
			in.close();
			out.close();
		} catch (Throwable e) {
			e.printStackTrace();
			exit(1);
		}
	}
}

import java.io.PrintStream;
import java.util.Scanner;
public class Main {
    private static final PrintStream so = System.out;
    private static final Scanner     sc = new Scanner(System.in);

    public static void main(String[] args) {
        int L = sc.nextInt();
        int N = sc.nextInt();
        int[] trees = new int[N];
        for (int i = 0; i < N; i++) {
            trees[i] = sc.nextInt();
        }
        if (N == 1)  {
            so.println(Math.max(d(0, trees[0], true, L), d(0, trees[0], false, L)));
            return;
        }
        long max = 0;
        for (int i = 1; i < N; i++) {

            int temp = d(0, trees[i], CLOCKWISE, L);
            long sum = calcMax(trees, i, i-1, 0, L);
            max = Math.max(max, sum+temp);
        }

        for (int i = 0; i < N-1; i++) {
            int temp = d(0, trees[i], COUNTER_CLOCKWISE, L);
            long sum = calcMax(trees, i, N-1, i+1, L);
            max = Math.max(max, sum+temp);
        }
        so.println(max);
    }

    static boolean CLOCKWISE = true;
    static boolean COUNTER_CLOCKWISE = false;
    public static long calcMax(int[] trees, int startI, int maxI, int minI, int L) {
        long sum_clockwise_start = 0;
        int current = startI;
        int next_max = maxI;
        int next_min = minI;
        while (true) {
            // 時計回りから
            sum_clockwise_start += d(trees[current], trees[next_max], CLOCKWISE, L);
//            so.println("sum = " + sum_clockwise_start);
            current = next_max;
            next_max--;
            if (next_max < next_min) break;

            sum_clockwise_start += d(trees[current], trees[next_min], COUNTER_CLOCKWISE, L);
//            so.println("sum = " + sum_clockwise_start);
            current = next_min;
            next_min++;
            if (next_max < next_min) break;
        }

        long sum_counterclockwise_start = 0;
        current = startI;
        next_max = maxI;
        next_min = minI;
        while (true) {
//            so.println("current = " + current + ", n_max = " + next_max + ", n_min = " + next_min);
            // 反時計周りから
            sum_counterclockwise_start += d(trees[current], trees[next_min], COUNTER_CLOCKWISE, L);
//            so.println("sum2 = " + sum_counterclockwise_start);
            current = next_min;
            next_min++;
            if (next_max < next_min) break;

//            so.println("current = " + current + ", n_max = " + next_max + ", n_min = " + next_min);
            sum_counterclockwise_start += d(trees[current], trees[next_max], CLOCKWISE, L);
//            so.println("sum2 = " + sum_counterclockwise_start);
            current = next_max;
            next_max--;
            if (next_max < next_min) break;
        }

        return Math.max(sum_clockwise_start, sum_counterclockwise_start);
    }

    public static int d(int from, int to, boolean clockwise, int L) {
        if (clockwise) {
            int temp = from - to;
            if (temp < 0) temp += L;
            return temp;
        } else {
            return d(to, from, CLOCKWISE, L);
        }
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.Scanner;

class Main{
	static int[] memo;
	static int[] dp;
	static long ans = 0;
	static int l;
	static int n;
	static ArrayList<Integer> data;
	static ArrayList<Integer> re;



	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);			//文字の入力
		l = sc.nextInt();
		n = sc.nextInt();
		ArrayList<Integer> data = new ArrayList<Integer>();
		for(int i = 0;i < n;i++){
			int x = sc.nextInt();
			data.add(x);
		}
		Collections.sort(data);
		ArrayList<Integer>	re = new ArrayList<Integer>();
		for(int i= 0;i < n;i++){
			int x = data.get(n-1-i);
			re.add(x);
		}

		dfs(data,re,0,0,0l);
		System.out.println(ans);
	}

	static void dfs(ArrayList<Integer> data, ArrayList<Integer> re,int p, int count,long sum){
		int tokeidis = 0;
		int hantokeidis = 0;


		if(count == n){
			ans = Math.max(ans, sum);
			return;
		}


		tokeidis = data.get(0) - p;
		if(tokeidis < 0){
			tokeidis = l - p + data.get(0);
		}
		hantokeidis = p + l- re.get(0);

		if(p > re.get(0)){
			hantokeidis = p-re.get(0);
		}

		if(tokeidis > hantokeidis ){
			p = data.get(0);
			data.remove(0);
			re.remove(re.size()-1);
			sum += tokeidis;
			dfs(data, re, p, count+1, sum);
		}else if(tokeidis < hantokeidis){
			p =re.get(0);
			re.remove(0);
			data.remove(data.size()-1);
			sum += hantokeidis;
			dfs(data, re, p, count+1, sum);

		}else{

			ArrayList<Integer> subdata = (ArrayList<Integer>) data.clone();
			ArrayList<Integer> subre = (ArrayList<Integer>) re.clone();


			p = data.get(0);
			data.remove(0);
			re.remove(re.size()-1);
			sum += tokeidis;
			dfs(data,re,p,count+1,sum);
			data.add(0, p);			//修復
			re.add(p);
			sum -= tokeidis;



			p =subre.get(0);
			subre.remove(0);
			subdata.remove(subdata.size()-1);
			sum += hantokeidis;

			dfs(subdata, subre, p, count+1, sum);



		}




	}





}







