	static class TaskX {

		long L;
		int n;
		public void solve(int testNumber, MyInput in, PrintWriter out) {

			L = in.nextInt(); n = in.nextInt();
			long[] x = new long[n+2], s = new long[n+2];

			for (int i = 1; i < n+1; i++) {
				x[i] = in.nextLong();
				s[i] = s[i-1] + x[i];
			}
			x[n+1] = L;

			long ans = 0;

			// 右 左 右 ...
			for (int i = 1; i <= n; i++) {
				ans = Math.max(ans, calc(i, x, s));
			}

			// 左 右 左...
			long[] rx = new long[n+2];
			for (int i = 0; i < n+2; i++) {
				rx[i] = L - x[n+1-i];
			}
			long[] rs = rx.clone();
			Arrays.parallelPrefix(rs, Math::addExact);
			for (int i = 1; i <= n; i++) {
				ans = Math.max(ans, calc(i, rx, rs));
			}

			out.println(ans);
		}

		long calc(int i, long[] x, long[] s) {
			long tmp = 0;
			if ((n + i) % 2 == 0) {
				int m = (n+i) / 2;
				tmp = 2 * (s[m-1] - s[i-1]) + x[m] - 2 * (s[n] - s[m]) + (long)(n-i) * L;
			} else {
				int m = (n+i+1) / 2;
				tmp = 2 * (s[m-1] - s[i-1]) - x[m] - 2 * (s[n] - s[m]) + (long)(n-i) * L;
			}
			return tmp;
		}
	}

