	static class TaskX {

		public void solve(int testNumber, MyInput in, PrintWriter out) {

			long L = in.nextLong();
			int N = in.nextInt();
			long[] r = new long[N+2];
			for (int i = 1; i < N+1; i++) {
				r[i] = in.nextLong();
			}
			r[N+1] = L;
			long[] l = new long[N+2];
			for (int i = 0; i < N+2; i++) {
				l[i] = L - r[N+1-i];
			}

			long[][][] dp = new long[N+1][N+1][2];
			for (int i = 0; i < N; i++) {
				for (int j = 0; j < N; j++) {
					dp[i+1][j][0] = max(dp[i+1][j][0], dp[i][j][0] + l[i+1] - l[i], dp[i][j][1] + l[i+1] + r[j]);
					dp[i][j+1][1] = max(dp[i][j+1][1], dp[i][j][0] + l[i] + r[j+1], dp[i][j][1] + r[j+1] - r[j]);
				}
			}

			long ans = 0;
			for (int i = 0; i <= N; i++) {
				ans = max(ans, dp[i][N-i][0], dp[i][N-i][1]);
			}

			out.println(ans);

		}
	}

	static long max(long... n) {
		long ret = n[0];
		for (int i = 0; i < n.length; i++) {
			ret = Math.max(ret, n[i]);
		}
		return ret;
	}

