import java.io.*;
import java.util.*;

public class Main {

  static FastScanner sc = new FastScanner();
  static Output out = new Output(System.out);

  static final int[] dx = {0, 1, 0, -1};
  static final int[] dy = {-1, 0, 1, 0};

  static final long MOD = (long) (1e9 + 7);
  static final long INF = Long.MAX_VALUE / 2;

  public static class Solver {

    long L;
    int N;
    long[] X;

    public Solver() {

      L = sc.nextLong();
      N = sc.nextInt()+1;

      X = new long[N];
      for (int i=1; i<N; i++) {
        X[i] = sc.nextLong();
      }

      Arrays.sort(X);

      long[][][] dp = new long[N+1][N+1][2];

      for (int len=1; len<N; len++) {
        for (int i=0; i<=N-len; i++) {
          int j = i + len;

          int left = (i-1+N)%N;
          int right = j%N;

          dp[i][j][0] = Math.max(dist(left, 1) + dp[i+1][j][0], dist(left, j-1, 0) + dp[i][j-1][1]);
          dp[i][j][1] = Math.max(dist(right, 0) + dp[i][j-1][1], dist(right, i,1) + dp[i+1][j][0]);

        }
      }

      out.println(Math.max(dp[1][N][0], dp[1][N][1]));

    }

    public long dist(int i, int dir) {
      if (dir == 0) {
        if (i == 0) return X[0] + (L - X[N-1]);
        else return X[i] - X[i-1];
      } else if (dir == 1) {
        if (i == N-1) return X[0] + (L - X[N-1]);
        else return X[i+1] - X[i];
      }
      return -INF;
    }

    public long dist(int from, int to, int dir) {
      if (from == to) return 0;
      if (dir == 1) {
        if (from < to) return X[to] - X[from];
        else return L-X[from] + X[to];
      } else if (dir == 0) {
        if (to < from) return X[from] - X[to];
        else return L-X[to] + X[from];
      }
      return -INF;
    }

  }

  public static void main(String[] args) {
    new Solver();
    out.flush();
  }

  static class FastScanner {
    private final InputStream in = System.in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;

    private boolean hasNextByte() {
      if (ptr < buflen) {
        return true;
      } else {
        ptr = 0;
        try {
          buflen = in.read(buffer);
        } catch (IOException e) {
          e.printStackTrace();
        }
        if (buflen <= 0) {
          return false;
        }
      }
      return true;
    }

    private int readByte() {
      if (hasNextByte()) return buffer[ptr++];
      else return -1;
    }

    private static boolean isPrintableChar(int c) {
      return 33 <= c && c <= 126;
    }

    private void skipUnprintable() {
      while (hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;
    }

    public boolean hasNext() {
      skipUnprintable();
      return hasNextByte();
    }

    public String next() {
      if (!hasNext()) throw new NoSuchElementException();
      StringBuilder sb = new StringBuilder();
      int b = readByte();
      while (isPrintableChar(b)) {
        sb.appendCodePoint(b);
        b = readByte();
      }
      return sb.toString();
    }

    public long nextLong() {
      if (!hasNext()) throw new NoSuchElementException();
      long n = 0;
      boolean minus = false;
      int b = readByte();
      if (b == '-') {
        minus = true;
        b = readByte();
      }
      if (b < '0' || '9' < b) {
        throw new NumberFormatException();
      }
      while (true) {
        if ('0' <= b && b <= '9') {
          n *= 10;
          n += b - '0';
        } else if (b == -1 || !isPrintableChar(b)) {
          return minus ? -n : n;
        } else {
          throw new NumberFormatException();
        }
        b = readByte();
      }
    }

    public int nextInt() {
      return (int) nextLong();
    }

    public int[] nextIntArray(int N, boolean oneBased) {
      if (oneBased) {
        int[] array = new int[N + 1];
        for (int i = 1; i <= N; i++) {
          array[i] = sc.nextInt();
        }
        return array;
      } else {
        int[] array = new int[N];
        for (int i = 0; i < N; i++) {
          array[i] = sc.nextInt();
        }
        return array;
      }
    }

    public long[] nextLongArray(int N, boolean oneBased) {
      if (oneBased) {
        long[] array = new long[N + 1];
        for (int i = 1; i <= N; i++) {
          array[i] = sc.nextLong();
        }
        return array;
      } else {
        long[] array = new long[N];
        for (int i = 0; i < N; i++) {
          array[i] = sc.nextLong();
        }
        return array;
      }
    }
  }

  static class Output extends PrintWriter {

    public Output(PrintStream ps) {
      super(ps);
    }

    public void print(int[] a, String separator) {
      for (int i = 0; i < a.length; i++) {
        if (i == 0) print(a[i]);
        else print(separator + a[i]);
      }
