        int N = in.nextInt();
        int[] a = new int[N + 5];
        for (int i = 1; i <= N; i++) {
            a[i] = in.nextInt();
        }
        long ans = 0;
        ans = Math.max(ans, solve(N, a, L));
        int[] aa = new int[N + 5];
        for (int i = 1; i <= N; i++) {
            aa[i] = L - a[N + 1 - i];
        }
        ans = Math.max(ans, solve(N, aa, L));
