public class Main {
	int m, n;
	int[] a;

	void run() {
		m = in.nextInt();
		n = in.nextInt();
		a = new int[n];
		for (int i = 0; i < n; i++) {
			a[i] = in.nextInt();
		}
		long ans = 0;
		for (int i = 1; i <= n; i++) {
			long cur = a[i - 1] + solve(a[i - 1], i, n, true);
			ans = Math.max(ans, cur);
//			System.out.println(i + " " + cur);
			cur = m - a[n - i] + solve(a[n - i], 0, n - i, false);
//			System.out.println(i + " " + cur);
			ans = Math.max(ans, cur);
		}
		out.println(ans);
	}

//	long solve(int pos, int from, int to) {
//		return Math.max(solve(pos, from, to, false), solve(pos, from, to, true));
//	}

	long solve(int pos, int from, int to, boolean right) {
		if (from == to) {
			return 0;
		}
		if (right) {
			int walk = (pos - a[to - 1] + m) % m;
			return walk + solve(a[to - 1], from, to - 1, !right);
		} else {
			int walk = (a[from] - pos + m) % m;
			return walk + solve(a[from], from + 1, to, !right);
		}
	}

