/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskB solver = new TaskB();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskB {
        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            int l = in.nextInt();
            int n = in.nextInt();

            List<Long> a = new LinkedList<>();
            for (int i = 0; i < n; i++)
                a.add(in.nextLong());

            long ans = 0;
            long pos = 0;
            while (a.size() >= 2) {
                // out.println(pos);
                long ln = a.get(0);
                long left = pos < ln ? (ln - pos) : (l - pos + ln);
                long rn = a.get(a.size() - 1);
                long right = pos > rn ? (pos - rn) : (l - rn + pos);

                long rrn = a.get(a.size() - 2);
                right += rn > rrn ? (rn - rrn) : (l - rrn + rn);
                right += rn < ln ? (ln - rn) : (l - rn + ln);

                long lln = a.get(1);
                left += ln < lln ? (lln - ln) : (l - ln + lln);
                left += ln > rn ? (ln - rn) : (l - rn + ln);

                if (right >= left) {
                    ans += pos > rn ? (pos - rn) : (l - rn + pos);
                    pos = rn;
                    a.remove(a.size() - 1);
                } else {
                    ans += pos < ln ? (ln - pos) : (l - pos + ln);
                    pos = ln;
                    a.remove(0);
                }
            }

            long cn = a.get(0);
            cn = cn > pos ? cn - pos : cn - pos + l;
            ans += Math.max(l - cn, cn);

            out.println(ans);
        }

    }

    static class FastScanner {
        private InputStream in;
        private byte[] buffer = new byte[1024];
        private int bufPointer;
        private int bufLength;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private int readByte() {
            if (bufPointer >= bufLength) {
                if (bufLength == -1)
                    throw new InputMismatchException();

                bufPointer = 0;
                try {
                    bufLength = in.read(buffer);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }

                if (bufLength <= 0)
                    return -1;
            }
            return buffer[bufPointer++];
        }

        private static boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public long nextLong() {
            long n = 0;

            int b = readByte();
            while (isSpaceChar(b))
                b = readByte();

            boolean minus = (b == '-');
            if (minus)
                b = readByte();

            while (b >= '0' && b <= '9') {
                n *= 10;
                n += b - '0';
                b = readByte();
            }

            if (!isSpaceChar(b))
                throw new NumberFormatException();

            return minus ? -n : n;
        }

        public int nextInt() {
            long n = nextLong();

            if (n < Integer.MIN_VALUE || n > Integer.MAX_VALUE)
                throw new NumberFormatException();

            return (int) n;
        }

    }
}

import java.util.*;
import java.util.ArrayList;

public class Main {
	public static void main(String[] args){
      Scanner sc = new Scanner(System.in);
      long L = sc.nextLong();
      long N = sc.nextLong();
      long currentPos = 0;
      long totalDistance = 0;
      ArrayList<Long> X = new ArrayList<>();
      for(long i=0;i<N;i++){
        X.add(sc.nextLong());
      }

      while(X.size() > 0){
        long lastX = X.get(X.size()-1);
        long firstX = X.get(0);
        //System.out.println("l"+lastX+"f"+firstX);
        long leftTurn = lastX > currentPos ? currentPos + (L - lastX) : currentPos - lastX;
        long rightTurn = firstX > currentPos ? firstX - currentPos : L - currentPos + firstX;
        //System.out.println("L"+leftTurn+"R"+rightTurn);

        if(leftTurn >= rightTurn){
          totalDistance +=  leftTurn;
          currentPos = lastX;
          //System.out.println("Re"+(X.size()-1)+"pos"+currentPos);
          X.remove(X.size()-1);      
        } else {
          totalDistance +=  rightTurn;
          currentPos = firstX;
          //System.out.println("Re"+0+"pos"+currentPos);
           X.remove(0);
        }

      }


      System.out.print(totalDistance);

	}
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.InputMismatchException;
import java.util.NoSuchElementException;

public class Main {

	static PrintWriter out;
	static InputReader ir;
	static boolean debug = false;

	static void solve() {
		long l = ir.nextLong();
		int n = ir.nextInt();
		long[] x = ir.nextLongArray(n);
		long[] sum = new long[n + 1];
		for (int i = 1; i <= n; i++) {
			sum[i] = x[i - 1];
			sum[i] += sum[i - 1];
		}
		long res = Math.max(l - x[0], x[n - 1]);
		long t = 0;
		for (int i = n - 1; i > n / 2; i--) {
			t += (l - x[i]) * 2;
			res = Math.max(res, t + 2 * (sum[i] - sum[2 * i - n]) - Math.min(l - x[i], x[i - 1]));
			res = Math.max(res, t + 2 * (sum[i] - sum[2 * i - n - 1]) - x[i - 1]);
			res = Math.max(res, t + 2 * (sum[i] - sum[2 * i - n + 1]) - (l - x[i]));
		}
		if (n % 2 == 0) {
			res = Math.max(res, t + 2 * sum[n / 2] - Math.min(l - x[n / 2], x[n / 2 - 1]));
		}
		long[] y = new long[n];
		for (int i = 0; i < n; i++) {
			y[i] = l - x[n - 1 - i];
		}
		for (int i = 1; i <= n; i++) {
			sum[i] = y[i - 1];
			sum[i] += sum[i - 1];
		}
		t = 0;
		for (int i = n - 1; i > n / 2; i--) {
			t += (l - y[i]) * 2;
			res = Math.max(res, t + 2 * (sum[i] - sum[2 * i - n]) - Math.min(l - y[i], y[i - 1]));
			res = Math.max(res, t + 2 * (sum[i] - sum[2 * i - n - 1]) - y[i - 1]);
			res = Math.max(res, t + 2 * (sum[i] - sum[2 * i - n + 1]) - (l - y[i]));
		}
		out.println(res);
	}

	public static void main(String[] args) {
		ir = new InputReader(System.in);
		out = new PrintWriter(System.out);
		solve();
		out.flush();
	}

	static class InputReader {

		private InputStream in;
		private byte[] buffer = new byte[1024];
		private int curbuf;
		private int lenbuf;

		public InputReader(InputStream in) {
			this.in = in;
			this.curbuf = this.lenbuf = 0;
		}

		public boolean hasNextByte() {
			if (curbuf >= lenbuf) {
				curbuf = 0;
				try {
					lenbuf = in.read(buffer);
				} catch (IOException e) {
					throw new InputMismatchException();
				}
				if (lenbuf <= 0)
					return false;
			}
			return true;
		}

		private int readByte() {
			if (hasNextByte())
				return buffer[curbuf++];
			else
				return -1;
		}

		private boolean isSpaceChar(int c) {
			return !(c >= 33 && c <= 126);
		}

		private void skip() {
			while (hasNextByte() && isSpaceChar(buffer[curbuf]))
				curbuf++;
		}

		public boolean hasNext() {
			skip();
			return hasNextByte();
		}

		public String next() {
			if (!hasNext())
				throw new NoSuchElementException();
			StringBuilder sb = new StringBuilder();
			int b = readByte();
			while (!isSpaceChar(b)) {
				sb.appendCodePoint(b);
				b = readByte();
			}
			return sb.toString();
		}

		public int nextInt() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			int res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = readByte();
			} while (!isSpaceChar(c));
			return (minus) ? -res : res;
		}

		public long nextLong() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			long res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = readByte();
			} while (!isSpaceChar(c));
			return (minus) ? -res : res;
		}

		public double nextDouble() {
			return Double.parseDouble(next());
		}

		public int[] nextIntArray(int n) {
			int[] a = new int[n];
			for (int i = 0; i < n; i++)
				a[i] = nextInt();
			return a;
		}

		public long[] nextLongArray(int n) {
			long[] a = new long[n];
			for (int i = 0; i < n; i++)
				a[i] = nextLong();
			return a;
		}

		public char[][] nextCharMap(int n, int m) {
			char[][] map = new char[n][m];
			for (int i = 0; i < n; i++)
				map[i] = next().toCharArray();
			return map;
		}
	}

	static void tr(Object... o) {
		if (debug)
			out.println(Arrays.deepToString(o));
	}
}

import java.io.PrintStream;
import java.util.Scanner;

public class Main {
    private static final PrintStream so = System.out;
    private static final Scanner     sc = new Scanner(System.in);

    public static void main(String[] args) {
        int L = sc.nextInt();
        int N = sc.nextInt();
        int[] trees = new int[N];
        for (int i = 0; i < N; i++) {
            trees[i] = sc.nextInt();
        }
        if (N == 1)  {
            so.println(Math.max(d(0, trees[0], true, L), d(0, trees[0], false, L)));
            return;
        }
        long max = 0;
        for (int i = 1; i < N; i++) {

            int temp = d(0, trees[i], CLOCKWISE, L);
            long sum = calcMax(trees, i, i-1, 0, L);
            max = Math.max(max, sum+temp);
        }

        for (int i = 1; i < N; i++) {
            int temp = d(0, trees[i], COUNTER_CLOCKWISE, L);
            long sum = calcMax(trees, i, N-1, i+1, L);
            max = Math.max(max, sum+temp);
        }
        so.println(max);
    }

    static boolean CLOCKWISE = true;
    static boolean COUNTER_CLOCKWISE = false;
    public static long calcMax(int[] trees, int startI, int maxI, int minI, int L) {
        long sum_clockwise_start = 0;
        int current = startI;
        int next_max = maxI;
        int next_min = minI;
        while (true) {
            // 時計回りから
            sum_clockwise_start += d(trees[current], trees[next_max], CLOCKWISE, L);
//            so.println("sum = " + sum_clockwise_start);
            current = next_max;
            next_max--;
            if (next_max < next_min) break;

            sum_clockwise_start += d(trees[current], trees[next_min], COUNTER_CLOCKWISE, L);
//            so.println("sum = " + sum_clockwise_start);
            current = next_min;
            next_min++;
            if (next_max < next_min) break;
        }

        long sum_counterclockwise_start = 0;
        current = startI;
        next_max = maxI;
        next_min = minI;
        while (true) {
//            so.println("current = " + current + ", n_max = " + next_max + ", n_min = " + next_min);
            // 反時計周りから
            sum_counterclockwise_start += d(trees[current], trees[next_min], COUNTER_CLOCKWISE, L);
//            so.println("sum2 = " + sum_counterclockwise_start);
            current = next_min;
            next_min++;
            if (next_max < next_min) break;

//            so.println("current = " + current + ", n_max = " + next_max + ", n_min = " + next_min);
            sum_counterclockwise_start += d(trees[current], trees[next_max], CLOCKWISE, L);
//            so.println("sum2 = " + sum_counterclockwise_start);
            current = next_max;
            next_max--;
            if (next_max < next_min) break;
        }

        return Math.max(sum_clockwise_start, sum_counterclockwise_start);
    }

    public static int d(int from, int to, boolean clockwise, int L) {
        if (clockwise) {
            int temp = from - to;
            if (temp < 0) temp += L;
            return temp;
        } else {
            return d(to, from, CLOCKWISE, L);
        }
    }
}

