class Program {
    static Scanner cin = new Scanner();
    static void Main() {
        long L = cin.Long();
        int N = cin.Int();
        var X = new long[N];

        var list = new List<long>();
        list.Add(0);
        for (int i = 0; i < N; i++) {
            X[i] = cin.Long();
            list.Add(X[i]);
        }

        long ans = 0, position = 0;
        while(list.Count != 1) {
            long hidari = list[0] - position > 0 ? list[0] - position : L - position + list[0];
            long migi = position - list[list.Count - 1] > 0 ? position - list[list.Count - 1] : L + position - list[list.Count - 1];
            long tmp = Math.Max(hidari, migi);
            ans += tmp;
            if(hidari >= migi) {
                position = list[0];
                list.RemoveAt(0);
            }
            else {
                position = list[list.Count - 1];
                list.RemoveAt(list.Count - 1);
            }
        }

        if(position - list[0] > 0) {
            ans += Math.Max(position - list[0], L - position + list[0]);
        }
        else {
            ans += Math.Max(list[0] - position, position + L - list[0]);
        }
        Console.WriteLine(ans);
        Console.ReadLine();
    }
}

