        static int CountCheck(List<int> pointList, int len, bool leftStartFlg)
        {

            int moveCnt = 0;
            int nowPoint = 0;

            while (0 < pointList.Count)
            {
                int p1 = 0;
                if (nowPoint <= pointList[0])
                {
                    p1 = pointList[0] - nowPoint;
                }
                else
                {
                    p1 = len - nowPoint + pointList[0];
                }

                int p2 = 0;
                if (nowPoint <= pointList[pointList.Count - 1])
                {
                    p2 = len - pointList[pointList.Count - 1] + nowPoint;
                }
                else
                {
                    p2 = nowPoint - pointList[pointList.Count - 1];
                }

                if (leftStartFlg)
                {
                    if (p1 <= p2)
                    {
                        moveCnt += p2;
                        nowPoint = pointList[pointList.Count - 1];
                        pointList.RemoveAt(pointList.Count - 1);
                    }
                    else
                    {
                        moveCnt += p1;
                        nowPoint = pointList[0];
                        pointList.RemoveAt(0);
                    }
                }
                else
                {
                    if (p1 < p2)
                    {
                        moveCnt += p2;
                        nowPoint = pointList[pointList.Count - 1];
                        pointList.RemoveAt(pointList.Count - 1);
                    }
                    else
                    {
                        moveCnt += p1;
                        nowPoint = pointList[0];
                        pointList.RemoveAt(0);
                    }
                }
            }

