using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using System.Diagnostics;

public class Program
{
    // public static readonly int Mod = 1000000007;

    public static void Main(string[] args)
    {
        long L = Scanner.Int;
        int N = Scanner.Int;

        List<long> x = new List<long>(N);
        List<long> y = new List<long>(N);

        foreach (long i in Enumerable.Range(0, N).Select(i => Scanner.Long))
        {
            x.Add(i);
            y.Add(i);
        }

        long left = solve(L, x.Count - 1, L - x[x.Count - 1], x);
        long right = solve(L, 0, y[0], y);

        Console.WriteLine(Math.Max(left, right));
        Console.ReadLine();
    }

    static long solve(long L, int now, long ans, List<long> x)
    {
        Func<int, int, bool, long> distance = (before, after, left) =>
        {
            long d = Math.Abs(x[before] - x[after]);
            if (left)
            {
                d = x[after] - x[before];

                if (d < 0)
                {
                    d = (L - x[before]) + x[after];
                }
            }
            else
            {
                d = x[before] - x[after];

                if (d < 0)
                {
                    d = x[before] + (L - x[after]);
                }
            }

            return d;
        };

        while (x.Count > 1)
        {
            int left = (now <= 0) ? x.Count - 1 : now - 1;
            int right = (now >= x.Count - 1) ? 0 : now + 1;

            long dl = distance(now, left, false);
            long dr = distance(now, right, true);

            if (dl >= dr)
            {
                ans += dl;

                x.RemoveAt(now);
                now = left - ((now < left) ? 1 : 0);
            }
            else
            {
                ans += dr;

                x.RemoveAt(now);
                now = right - ((now < right) ? 1 : 0);
            }
        }

        return ans;
    }
}

