namespace AGC030
{
    class B
    {
        static Dictionary<long, long> dis = new Dictionary<long, long>();

        static long getway(int[] X, int s, int t, int current, int L)
        {
            long key = ((long)s * 1000000 + (long)t) * 1000000000 + (long)current;
            if (dis.ContainsKey(key)) return dis[key];
            if (s == t)
            {
                long d = Math.Abs(current - X[s]);
                return Math.Max(d, L - d);
            }
            else
            {
                long d1, d2;
                if (current < X[s])
                {
                    d1 = getway(X, s + 1, t, X[s], L) + X[s] - current;
                    d2 = getway(X, s, t - 1, X[t], L) + (L - X[t] + current);
                }
                else
                {
                    d1= getway(X, s + 1, t, X[s], L) + X[s] +(L- current);
                    d2 = getway(X, s, t - 1, X[t], L) + (current - X[t]);
                }
                dis[key]= Math.Max(d1, d2);
                return dis[key];
            }
        }

        static void Main(string[] args)
        {
