            long r = x[0]; int n = x[1];
            long[,,] dp = new long[n + 1, n + 1, 2];//pluscount minuscount plus->0
            long[] tree = new long[n + 2];
            for (int i = 1; i <= n; i++) tree[i] = long.Parse(Console.ReadLine());
