            {
                for (int p = 0; p <= sum; p++)
                {
                    int m = sum - p;
                    if (p > 0)
                        dp[p, m, 0] = Math.Max(dp[p, m, 0], Math.Max(
                        dp[p - 1, m, 0] + (tree[p] - tree[p - 1]),
                        dp[p - 1, m, 1] + (tree[p] + r - tree[n - m + 1])
                        ));
                    if (m > 0)
                        dp[p, m, 1] = Math.Max(dp[p, m, 1], Math.Max(
                        dp[p, m - 1, 0] + ((r - tree[n - m + 1]) + tree[p]),
                        dp[p, m - 1, 1] + ((r - tree[n - m + 1]) - (r - tree[n - m + 2]))
                        ));
                }
            }
            long ret = 0;
            for (int p = 0; p <= n; p++)
            {
                ret = Math.Max(ret, Math.Max(dp[p, n - p, 0], dp[p, n - p, 1]));
