        static public void Solve()
        {
            var L = NN;
            var N = NN;
            var XList = NNList(N);
            var ans1 = 0L;
            var ans2 = 0L;
            {
                var leftTree = new PQ<long>();
                var rightTree = new PQ<long>();
                foreach (var item in XList)
                {
                    leftTree.Push(item);
                    rightTree.Push(L - item);
                }
                var now = 0L;
                for (var i = 0; i < N; i++)
                {
                    var lp = leftTree.Peek;
                    var rp = rightTree.Peek;
                    if (lp - now > now + rp)
                    {
                        ans1 += lp - now;
                        now = leftTree.Pop();
                    }
                    else
                    {
                        ans1 += now + rp;
                        now = -rightTree.Pop();
                    }
                }
            }
            {
                var leftTree = new PQ<long>();
                var rightTree = new PQ<long>();
                var leftSum = 0L;
                var rightSum = 0L;
                foreach (var item in XList)
                {
                    leftTree.Push(item);
                    rightTree.Push(L - item);
                    leftSum += item;
                    rightSum += L - item;
                }
                var now = 0L;
                for (var i = 0; i < N; i++)
                {
                    if (leftSum > rightSum)
                    {
                        var dif = leftTree.Peek - now;
                        now = leftTree.Pop();
                        ans2 += dif;
                        leftSum -= (N - i) * dif;
                        rightSum += (N - i) * dif;
                    }
                    else
                    {
                        var dif = now + rightTree.Peek;
                        now = -rightTree.Pop();
                        ans2 += dif;
                        leftSum += (N - i) * dif;
                        rightSum -= (N - i) * dif;
                    }
                }
            }
            Console.WriteLine(Max(ans1, ans2));
        }

