using System;
using System.Collections.Generic;
using System.Linq;
class Program{
	static int[] s;
	static int[] h;
	static int[] arr;
	static long ans=0;
	static Dictionary<string,long[]> hs=new Dictionary<string,long[]>();
	static void Main(){
		s=Array.ConvertAll(Console.ReadLine().Split(),int.Parse);
		arr=new int[s[0]+1];
		for(int i=1;i<=s[1];i++){arr[i]=int.Parse(Console.ReadLine());}
		h=new int[s[1]+1];
		//fu(0,1,s[1],1,0);
		Console.WriteLine("{0}",fu(0,1,s[1],1,0));
	}
	static long fu(int n,int a,int b,int o,long c){
		long q=0;
		string sh=n+" "+a+" "+b+" "+o;

		if(hs.ContainsKey(sh)){
			if(hs[sh][0]>=c){return hs[sh][1];}
			else{
				hs[sh][1]+=c-hs[sh][0];
				hs[sh][0]=c;
				return hs[sh][1];
			}
		}
		if(o==s[1]+1){
			ans=Math.Max(ans,c);
			return c;
		}
		h[o]=a;
		q=fu(a,a+1,b,o+1,c+(((arr[a]+s[0])-arr[n])%s[0]));
		h[o]=b;
		q=Math.Max(q,fu(b,a,b-1,o+1,c+(s[0]-(((arr[b]+s[0])-arr[n])%s[0]))));
		hs.Add(sh,new long[]{c,q});
		return q;
	}
}

