            {
                ys[i] = l - xs[n + 1 - i];
                ySums[i] = ySums[i - 1] + ys[i];
            }

            long res = 0;
            for (int i = 0; i <= n; i++)
            {
                int r = n - i;
                long cnt = 0;
                long ll = 0;
                if (i > 0)
                {
                    cnt = Math.Min(i - 1, r);
                    ll += (xSums[i - 1] - xSums[i - 1 - cnt]) * 2;
                    ll += (ySums[r] - ySums[r - cnt]) * 2;
                    ll += xs[i];
                }

                long lr = 0;
                cnt = Math.Min(i, r);
                lr += (xSums[i] - xSums[i - cnt]) * 2;
                lr += (ySums[r] - ySums[r - cnt]) * 2;
                lr -= xs[i];

                long rl = 0;
                cnt = Math.Min(i, r);
                rl += (xSums[i] - xSums[i - cnt]) * 2;
