using System;
using System.Collections.Generic;
using System.Linq;
class Program{
    static long l;
    static int n;
    static List<long> x;
    static void Main(){
        //入力の受け取り
        string[] s = Console.ReadLine().Split();
        l = long.Parse(s[0]);
        n = int.Parse(s[1]);
        x = new List<long>();
        for (int i = 0;i < n;i++)
            x.Add(long.Parse(Console.ReadLine()));
        //解
        long c = 0; //現在位置(座標)
        long wd = 0; //移動距離
        while(x.Count > 0){
            if (D(0,c) > D(x.Count - 1,c)){
                wd += D(0,c);
                c = x[0];
                x.RemoveAt(0);
            }
            else{
                wd += D(x.Count - 1,c);
                c = x[x.Count - 1];
                x.RemoveAt(x.Count - 1);
            }
#if TEST
            Console.WriteLine("c = {0}, wd = {1}",c,wd);
#endif
        }
        Console.WriteLine(wd);
    }
    static long D(int i, long c){
        int n = x.Count;
        if (n == 1){
            long d = Math.Abs(x[i] - c);
            return Math.Max(d,l - d);
        }
        if (i == 0){
            if (c < x[0])
                return x[0] - c;
            return l - c + x[0];
        }
        if (c > x[x.Count - 1])
            return c - x[x.Count - 1];
        return l - x[x.Count - 1] + c;
    }
}

using System;
using System.Collections.Generic;

namespace atbc_030
{
    class Program
    {
        static void Main(string[] args)
        {
            string[] dataArr = Console.ReadLine().Split(' ');
            int len = int.Parse(dataArr[0]);
            int cnt = int.Parse(dataArr[1]);

            List<int> pointList = new List<int>();

            for (int i = 0; i < cnt; i++)
            {
                pointList.Add(int.Parse(Console.ReadLine()));
            }

            int retCnt = 0;
            CountCheck(new List<int>(pointList), len, 0, 0, ref retCnt);

            Console.WriteLine(retCnt);
        }

        static void CountCheck(List<int> pointList, int len, int nowPoint, int moveCnt, ref int retCnt)
        {

            if(0 == pointList.Count)
            {
                if (retCnt < moveCnt)
                {
                    retCnt = moveCnt;
                }
                return;
            }

            int p1 = 0;
            if (nowPoint <= pointList[0])
            {
                p1 = pointList[0] - nowPoint;
            }
            else
            {
                p1 = len - nowPoint + pointList[0];
            }

            int p2 = 0;
            if (nowPoint <= pointList[pointList.Count - 1])
            {
                p2 = len - pointList[pointList.Count - 1] + nowPoint;
            }
            else
            {
                p2 = nowPoint - pointList[pointList.Count - 1];
            }

            List<int> tmpList1 = new List<int>(pointList);
            tmpList1.RemoveAt(0);
            List<int> tmpList2 = new List<int>(pointList);
            tmpList2.RemoveAt(pointList.Count - 1);

            bool f1 = false;
            bool f2 = false;

            if (p2 < p1)
            {
                f1 = true;
            }
            else if (p1 < p2)
            {
                f2 = true;
            }
            else
            {
                f1 = true;
                f2 = true;
            }

            if(f1) CountCheck(tmpList1, len, pointList[0], moveCnt + p1, ref retCnt);
            if (f2) CountCheck(tmpList2, len, pointList[pointList.Count - 1], moveCnt + p2, ref retCnt);
        }
    }
}

