public class Hello
{
    public static void Main()
    {
        string[] line = Console.ReadLine().Trim().Split(' ');
        var L = int.Parse(line[0]);
        var n = int.Parse(line[1]);
        var a = new int[n];
        for (int i = 0; i < n; i++) a[i] = int.Parse(Console.ReadLine().Trim());
        var ans = getAns(a,  L, n);
        var ans2 = getAns2(a, L, n);
        Console.WriteLine(Max(ans,ans2));

    }
    static long getAns2(int[] a, int L, int n)
    {
        var p = 0; var q = n - 1;
        var ans =  L - a[q];
        while (true)
        {
            var w =   L - a[q] + a[p];
            var t = a[q] - a[q - 1];
            if (t >= w) { ans += t; q--; }
            else { ans += w; break; }
            if (p == q) return ans;
        }
        if (p == q) return ans;
        while (true)
        {
            q--;
            if (p == q) return ans;
            ans += L - a[q] + a[p];
            p++;
            if (p == q) return ans;
            ans += a[p] + L - a[q];
        }
    }

    static long getAns (int[] a ,  int L,  int n)
    {
        var ans = a[0];
        var p = 0;   var q = n - 1;
        while (true)
        {
            var t = a[p + 1] - a[p];
            var w =  a[p] +    L - a[q];
            if (t >= w ) { ans += t;   p++; }
            else { ans += w;   break; }
            if (p == q) return ans;
        }
        if (p == q) return ans;
        while (true)
        {
            p++;
            if (p == q) return ans;
            ans += a[p] + L - a[q];
            q--;
            if (p == q) return ans;
            ans += L - a[q] + a[p];
        }
    }
}

