    {
        static private int nowTakahant;
        static private int nowTakatok;
        static private int[] Xhant;
        static private int[] Xtok;
        static private int[] Xf;
        static private int Z;
        static private int N;
        static private int G;

        static void Main(string[] args)
        {
            string[] input = Console.ReadLine().Split(' ');
            int L = int.Parse(input[0]);
            N = int.Parse(input[1]);
            Z = 0;
            Xhant = new int[N];
            Xtok = new int[N];
            Xf = new int[N];
            G = 0;

            nowTakahant = 0;
            nowTakatok = 0;

            for (int i = 0; i < N; i++)
            {
                int xn = int.Parse(Console.ReadLine());
                Xhant[i] = xn;
                Xtok[i] = L - xn;
                Xf[i] = 0;
            }

            while (true)
            {
                idou();

                if (Z == N)
                {
                    break;
                }
            }

            Console.WriteLine(G);


        }

        static void idou()
        {
            int hantP =0;
            int hantPi = 0;
            int tokP = 0;
            int tokPi = 0;

            for (int i = 0; i < N; i++)
            {
                if(Xf[i] == 0)
                {
                    hantP = Xhant[i];
                    hantPi = i;
                    break;
                }
            }

            for (int i = N-1; i >= 0; i--)
            {
                if (Xf[i] == 0)
                {
                    tokP = Xtok[i];
                    tokPi = i;
                    break;
                }
            }

            if(hantP - nowTakahant > tokP - nowTakatok)
            {
                G += hantP - nowTakahant;
                Xf[hantPi] = 1;
