namespace Practice
{
    class Program
    {
        static void Main(string[] args)
        {
            Solve();
        }
        private const int MOD = 1000000007;
        static void Solve()
        {
            var ln = ReadAndParseIntArr();
            var l = ln[0];
            int n = ln[1];
            var x = new int[n];
            for(int i=0;i<n;++i)
            {
                x[i] = ReadAndParseInt();
            }
            var llen = new int[n];
            var rlen = new int[n];
            for(int i=0;i<n;++i)
            {
                llen[i] = x[i];
                rlen[i] = l - (x[n - 1 - i]);
            }
            long ans = 0;
            for(int i=0;i<n;++i)
            {
                ans = Math.Max(ans, SolveImpl(i, llen, rlen));
                ans = Math.Max(ans, SolveImpl(i, rlen, llen));
            }
            Console.WriteLine(ans);
        }
        private static long SolveImpl(int toIdx, int[] llen, int[] rlen)
        {
            long ans = 0;
            // 左
            ans += llen[toIdx];
            if( toIdx == llen.Length - 1)
            {
                // 全部まわしちゃった
                return ans;
            }
            ans += llen[toIdx];
            int n = llen.Length - 1 - toIdx;
            for(int i=0;i<n;++i)
            {
                if (i % 2 == 0)
                {
                    // 右
                    ans += rlen[i / 2];
                    if (i != n - 1)
                    {
                        ans += rlen[i / 2];
                    }
                }
                else
                {
                    // 左
                    int offset = (i + 1) / 2;
                    ans += llen[toIdx + offset];
                    if (i != n - 1)
                    {
                        ans += llen[toIdx + offset];
                    }
                }
            }
            return ans;
        }

        #region よく使う便利関数
        private static bool isPrime(long x)
        {
            if (x == 2) { return true; }
            if (x < 2 || x % 2 == 0) { return false; }
            long i = 3;
            while (i * i <= x)
            {
                if (x % i == 0) { return false; }
                i = i + 2;
            }
            return true;
        }
        private static long lcm(long x, long y)
        {
            return x / gcd(x, y) * y;
        }
        private static long gcd(long x, long y)
        {
            return y > 0 ? gcd(y, x % y) : x;
        }
        private static long pow(long x, long n)
        {
            if (n == 0) { return 1; }
            long res = pow(x * x % MOD, n / 2);
            if (n % 2 == 1)
            {
                res = res * x % MOD;
            }
            return res;
        }
        private static int ReadAndParseInt()
        {
            return int.Parse(Console.ReadLine());
        }
        private static int[] ReadAndParseIntArr()
        {
            return Array.ConvertAll(Console.ReadLine().Split(' '), int.Parse);
        }
        private static long ReadAndParseLong()
        {
            return long.Parse(Console.ReadLine());
        }
        private static long[] ReadAndParseLongArr()
        {
            return Array.ConvertAll(Console.ReadLine().Split(' '), long.Parse);
        }
        #endregion
    }
