using System;
    class Program
    {
        static void Main(string[] args)
        {
            string[] input = Console.ReadLine().Split(' ');
            int l = int.Parse(input[0]);
            int n = int.Parse(input[1]);

            int[] x = new int[n];

            for(int i = 0; i < n; i++)
            {
                x[i] = int.Parse(Console.ReadLine());
            }
            int total = 0;
            int count = 0;
            int head = 0;
            int tail = n - 1;
            int nowX = 0;

            while(count < n)
            {
                if (x[head] > nowX)
                {
                    if (x[head] - nowX > l - x[tail] + nowX)
                    {
                        total += x[head] - nowX;
                        nowX = x[head];
                        head += 1;
                    }
                    else
                    {
                        total += l - x[tail] + nowX;
                        nowX = x[tail];
                        tail -= 1;
                    }
                }
                else
                {
                    if (x[head] + l - nowX > nowX - x[tail])
                    {
                        total += x[head] + l - nowX;
                        nowX = x[head];
                        head += 1;
                    }
                    else
                    {
                        total += nowX - x[tail];
                        nowX = x[tail];
                        tail -= 1;
                    }

                }
                count++;
            }

            Console.WriteLine(total);
        }
    }

