using System;
using System.Collections.Generic;
using System.Linq;

namespace Tree_Burning
{
    class Program
    {
        static void Main(string[] args)
        {
            var input = Console.ReadLine().Split(' ').Select(float.Parse);
            var length = input.ElementAt(0);
            var n = input.ElementAt(1);
            var trees = new List<float>();
            for (float i = 0; i < n; i++)
            {
                trees.Add(float.Parse(Console.ReadLine()));
            }
            float currentLocation = 0;
            float sum = 0;
            while (trees.Any())
            {
                float a;
                if (trees.First() < currentLocation)
                {
                    a = trees.First() + length - currentLocation;
                }
                else
                {
                    a = trees.First() - currentLocation;
                }
                float b;
                if (trees.Last() > currentLocation)
                {
                    b = currentLocation + (length - trees.Last());
                }
                else
                {
                    b = currentLocation - trees.Last();
                }

                if (a > b)
                {
                    sum += a;
                    currentLocation = trees.First();
                    trees.RemoveAt(0);
                }
                else
                {
                    sum += b;
                    currentLocation = trees.Last();
                    trees.RemoveAt(trees.Count - 1);
                }
            }

            Console.WriteLine(sum);
        }
    }
}

using System;
using System.Collections.Generic;
class Program
{
    static void Main(string[] args)
    {
        var input = Console.ReadLine().Split(' ');

        var L = int.Parse(input[0]);
        var N = int.Parse(input[1]);
        var xs = new List<int>();
        for (var i = 0; i < N; i++)
        {
            xs.Add(int.Parse(Console.ReadLine()));
        }

        var posId = 0;
        var negId = N - 1;
        var current = 0;

        var dir1Dis = Math.Abs(xs[posId] - current);
        var dir2Dis = Math.Abs(L - dir1Dis);
        var disPos = Math.Max(dir1Dis, dir2Dis);

        long sum = 0;

        for (var i = 0; i < N; i++)
        {
            int ld;
            if (current > xs[negId])
            {
                ld = xs[negId] - current;
            }
            else
            {
                ld = current + (L - xs[negId]);
            }

            int rd;
            if (current > xs[posId])
            {
                rd = xs[posId] + (L - current);
            }
            else
            {
                rd = xs[posId] - current;
            }

            if (ld > rd)
            {
                current = xs[negId];
                //Console.WriteLine(current.ToString() + ld.ToString());
                sum += ld;
                negId--;
            }
            else
            {
                current = xs[posId];
                //Console.WriteLine(current.ToString() + rd.ToString());
                sum += rd;
                posId++;
            }


        }

        Console.WriteLine(sum);
    }
}

using System;
using System.Text;
using System.Linq;
using System.Collections;
using System.Collections.Generic;
using static System.Console;
using static System.Math;

namespace AtCoder
{
    class Program
    {
        static void Main(string[] args)
        {
            new Program().Solve(new ConsoleInput(Console.In, ' '));
#if DEBUG
            ReadLine();
#endif
        }

        void Solve(ConsoleInput cin)
        {
            long len = cin.ReadLong;
            int n = cin.ReadInt;

            long[] rLen = new long[n + 1];
            long[] lLen = new long[n + 1];
            rLen[0] = 0;
            lLen[0] = 0;
            for (int i = 1; i <= n; i++)
            {
                rLen[i] = cin.ReadLong;
                lLen[n - i + 1] = len - rLen[i];
            }

            long[][][] dp = new long[n + 1][][];

            for (int i = 0; i < n + 1; i++)
            {
                dp[i] = new long[n + 1][];
                for (int j = 0; j < n + 1; j++)
                {
                    dp[i][j] = new long[2];
                }
            }

            for (int l = 0; l <= n; l++)
            {
                for (int r = 0; r <= n; r++)
                {
                    if (l + r > n)
                    {
                        break;
                    }

                    if (l > 0)
                    {
                        long valFromL = dp[l - 1][r][0] + lLen[l] - lLen[l - 1];
                        long valFromR = dp[l - 1][r][1] + lLen[l] + rLen[r];

                        dp[l][r][0] = Max(valFromL, valFromR);
                    }

                    if (r > 0)
                    {
                        long valFromL = dp[l][r - 1][0] + lLen[l] + rLen[r];
                        long valFromR = dp[l][r - 1][1] + rLen[r] - rLen[r - 1];

                        dp[l][r][1] = Max(valFromL, valFromR);
                    }
                }
            }

            long ans = 0;
            for (int l = 0; l <= n; l++)
            {
                int r = n - l;
                ans = Max(dp[l][r][0], ans);
                ans = Max(dp[l][r][1], ans);
            }

            Console.WriteLine(ans);
        }

        class ConsoleInput
        {
            private readonly System.IO.TextReader _stream;
            private char _separator = ' ';
            private Queue<string> inputStream;

            public ConsoleInput(System.IO.TextReader stream, char separator = ' ')
            {
                this._separator = separator;
                this._stream = stream;
                inputStream = new Queue<string>();
            }

            public string Read
            {
                get
                {
                    if (inputStream.Count != 0) return inputStream.Dequeue();
                    string[] tmp = _stream.ReadLine().Split(_separator);
                    for (int i = 0; i < tmp.Length; ++i)
                        inputStream.Enqueue(tmp[i]);
                    return inputStream.Dequeue();
                }
            }

            public string ReadLine { get { return _stream.ReadLine(); } }
            public int ReadInt { get { return int.Parse(Read); } }
            public long ReadLong { get { return long.Parse(Read); } }
            public double ReadDouble { get { return double.Parse(Read); } }
            public string[] ReadStrArray(long N) { var ret = new string[N]; for (long i = 0; i < N; ++i) ret[i] = Read; return ret; }
            public int[] ReadIntArray(long N) { var ret = new int[N]; for (long i = 0; i < N; ++i) ret[i] = ReadInt; return ret; }
            public long[] ReadLongArray(long N) { var ret = new long[N]; for (long i = 0; i < N; ++i) ret[i] = ReadLong; return ret; }
        }
    }
}

