class Myon
{
    public Myon() { }
    public static int Main()
    {
        new Myon().calc();
        return 0;
    }

    Scanner cin;

    long L;
    int N;

    void calc()
    {
        cin = new Scanner();
        L = cin.nextLong();
        N = cin.nextInt();
        long[] X = new long[N + 1];
        for (int i = 0; i < N; i++)
        {
            X[i] = cin.nextLong();
        }
        X[N] = L;

        long[] Llen = new long[N + 1];
        long[] Rlen = new long[N + 1];
        for (int i = 0; i < N; i++)
        {
            Llen[i + 1] = X[i];
            Rlen[i + 1] = L - X[N - i - 1];
        }

        long Lans = calc2(Llen, Rlen);
        long Rans = calc2(Rlen, Llen);
        Console.WriteLine(Math.Max(Lans, Rans));

    }

    long calc2(long[] L, long[] R)
    {

        long now = 0;
        for (int i = 0; i < N; i++)
        {
            now += (L[i + 1] - L[i]) * Math.Max((N) - i * 2, 0);
            now += (R[i + 1] - R[i]) * Math.Max((N) - i * 2 - 1, 0);
        }

        long ans = now;

        for (int i = 0; i < N; i++)
        {
            now += L[(N + i + 2) / 2];
            now -= L[i + 1] * 2;
            now -= R[(N - i) / 2];

            ans = Math.Max(ans, now);

        }


        return ans;
    }
}


