class Program
{
    public static void Main(string[] args)
    {

        string[] str = Console.ReadLine().Split(' ');
        int L = int.Parse(str[0]);
        int N = int.Parse(str[1]);
        int[] X = new int[N];
        for(int i = 0;i < N;i++)
        {
            X[i] = int.Parse(Console.ReadLine());
        }
        long cost = 0;
        int rightPos = -1;
        int leftPos = N;
        int pos;
        long Rcost;
        long Lcost;
        {
            pos = 0;
            rightPos = 0;
            cost += X[0];
        }
        while (leftPos - rightPos != 1)
        {
            int tmpR = seijoyo(X[rightPos + 1] - X[pos], L);
            int tmpL = seijoyo(X[pos] - X[leftPos - 1], L);
            if (tmpR > tmpL)
            {
                rightPos++;
                pos = rightPos;
                cost += tmpR;
            }
            else
            {
                leftPos--;
                pos = leftPos;
                cost += tmpL;
            }
        }
        Rcost = cost;

        {
            pos = N - 1;
            leftPos = N - 1;
            cost += L - X[N - 1];
        }
        while (leftPos - rightPos != 1)
        {
            int tmpR = seijoyo(X[rightPos + 1] - X[pos], L);
            int tmpL = seijoyo(X[pos] - X[leftPos - 1], L);
            if (tmpR > tmpL)
            {
                rightPos++;
                pos = rightPos;
                cost += tmpR;
            }
            else
            {
                leftPos--;
                pos = leftPos;
                cost += tmpL;
            }
        }
        Lcost = cost;

        if(Rcost > Lcost)
        {
            cost = Rcost;
        }

        Console.WriteLine(cost.ToString());
        return;
    }

    public static int seijoyo(int a,int b)
    {
        int tmp = a % b;
        if (tmp >= 0) return tmp;
        else
        {
            return tmp + b;
        }
    }
}

