    class Program
    {
        static void Main(string[] args)
        {
            string[] dataArr = Console.ReadLine().Split(' ');
            int len = int.Parse(dataArr[0]);
            int cnt = int.Parse(dataArr[1]);

            List<int> pointList = new List<int>();

            for (int i = 0; i < cnt; i++)
            {
                pointList.Add(int.Parse(Console.ReadLine()));
            }

            int retCnt = 0;
            CountCheck(new List<int>(pointList), len, 0, 0, ref retCnt);

            Console.WriteLine(retCnt);
        }

        static void CountCheck(List<int> pointList, int len, int nowPoint, int moveCnt, ref int retCnt)
        {

            if(0 == pointList.Count)
            {
                if (retCnt < moveCnt)
                {
                    retCnt = moveCnt;
                }
                return;
            }

            int p1 = 0;
            if (nowPoint <= pointList[0])
            {
                p1 = pointList[0] - nowPoint;
            }
            else
            {
                p1 = len - nowPoint + pointList[0];
            }

            int p2 = 0;
            if (nowPoint <= pointList[pointList.Count - 1])
            {
                p2 = len - pointList[pointList.Count - 1] + nowPoint;
            }
            else
            {
                p2 = nowPoint - pointList[pointList.Count - 1];
            }

            int nowPoint1 = pointList[0];
            int nowPoint2 = pointList[pointList.Count - 1];

            if (p2 < p1)
            {
                pointList.RemoveAt(0);
                CountCheck(pointList, len, nowPoint1, moveCnt + p1, ref retCnt);
            }
            else if (p1 < p2)
            {
                pointList.RemoveAt(pointList.Count - 1);
                CountCheck(pointList, len, nowPoint2, moveCnt + p2, ref retCnt);
            }
            else
            {
                List<int> tmpList1 = new List<int>(pointList);
                tmpList1.RemoveAt(0);
                CountCheck(tmpList1, len, nowPoint1, moveCnt + p1, ref retCnt);
                List<int> tmpList2 = new List<int>(pointList);
                tmpList2.RemoveAt(pointList.Count - 1);
                CountCheck(tmpList2, len, nowPoint2, moveCnt + p2, ref retCnt);
            }

        }
    }
}

