func main() {
	var L, N int
	fmt.Scanf("%d%d", &L, &N)
	A, B := 0, 0
	X := make([]int, N+1)
	for i := 1; i <= N/2; i++ {
		fmt.Scanf("%d", &X[i])
		A += 2 * X[i]
		B += 2 * X[i]
	}
	if N%2 == 1 {
		fmt.Scanf("%d", &X[(N+1)/2])
		A += X[(N+1)/2]
		B += (L - X[(N+1)/2])
	}
	for i := 1; i <= N/2; i++ {
		fmt.Scanf("%d", &X[(N+1)/2+i])
		A += 2 * (L - X[(N+1)/2+i])
		B += 2 * (L - X[(N+1)/2+i])
	}
	if N%2 == 0 {
		A -= L - X[N/2+1]
		B -= X[N/2]
	}
	ans := A
	if ans < B {
		ans = B
	}
	for i := 0; i < N/2; i++ {
		if (N-i)%2 == 0 {
			A += -2*X[1+i] - (L - X[(N-i)/2+1+i]) + X[(N-i)/2+1+i]
			B += -2*(L-X[N-i]) - X[(N-i)/2] + (L - X[(N-i)/2])
		} else {
			A += -2*X[1+i] - (L - X[(N+1-i)/2+1+i]) + X[(N+1-i)/2+i]
			B += -2*(L-X[N-i]) - X[(N-i)/2] + (L - X[(N+1-i)/2])
		}
		if ans < A {
			ans = A
		}
		if ans < B {
			ans = B
		}
	}
	fmt.Printf("%d\n", ans)
}

