// State is
type State struct {
	pos int
	sum int
	x   []int
}

func Copy(s State) State {
	var rtn State
	rtn.pos = s.pos
	rtn.sum = s.sum
	rtn.x = make([]int, len(s.x))
	copy(rtn.x, s.x)
	return rtn
}

type sStates []State

func (s sStates) Len() int {
	return len(s)
}

func (s sStates) Less(i, j int) bool {
	return s[i].sum < s[j].sum
}

func (s sStates) Swap(i, j int) {
	s[i], s[j] = s[j], s[i]
}

func beamSearch(start []int) {
	states := make([][]State, N+1)
	// log.Println(len(states))
	startState := State{pos: 0, sum: 0, x: start}
	states[0] = append(states[0], startState)
	for i := 0; i < N; i++ {
		if len(states[i]) == 0 {
			break
		}
		now := states[i][len(states[i])-1]
		// log.Println(now)
		states[i] = states[i][:len(states[i])-1]
		//
		a := Copy(now)
		a.pos = now.x[0]
		if now.pos < a.pos {
			a.sum += a.pos - now.pos
		} else {
			a.sum += now.pos + (L - a.pos)
		}
		a.x = now.x[1:]
		states[i+1] = append(states[i+1], a)
		//
		// if len(now.x) > 1 {
		b := Copy(now)
		b.pos = now.x[len(now.x)-1]
		if now.pos < b.pos {
			b.sum += now.pos + (L - b.pos)
		} else {
			b.sum += b.pos - now.pos
		}
		b.x = now.x[:len(now.x)-1]
		states[i+1] = append(states[i+1], b)
		// }
		sort.Sort(sStates(states[i+1]))
		// log.Println(states[i+1])
	}
	fmt.Println(states[N][len(states[N])-1].sum)
	// log.Println(states[N])
}

