  for i:=0;i<n;i++ { x[i] = input.NextInt() }
  var y,s int64
  m,h := 0,n-1
  for m <= h {
    dm := x[m]-y
    if dm < 0 { dm += l }
    dh := y-x[h]
    if dh < 0 { dh += l }
    if dm > dh {
      s += dm
      y = x[m]
      m++
    } else {
      s += dh
      y = x[h]
      h--
    }
  }
  fmt.Println(s)
}

type Input struct {
  reader *bufio.Reader
}
func(i *Input) NextLine() string {
  var buffer []byte
  for {
    line,isPrefix,err := i.reader.ReadLine()
    if err != nil { panic(err) }
    buffer = append(buffer,line...)
    if !isPrefix { break }
  }
  return string(buffer)
}
func(i *Input) NextInt() int64 {
  x,_ := strconv.ParseInt(i.NextLine(),10,64)
  return x
}
func(i *Input) NextInts() (int64,int) {
  s := strings.Split(i.NextLine()," ")
  x,_ := strconv.ParseInt(s[0],10,64)
  y,_ := strconv.Atoi(s[1])
  return x,y
}

