var lDist, n int

func newArray(ints []int) *array {
	return &array{ints[:]}
}

type array struct {
	ints []int
}

func (a *array) shift() int {
	var x int
	x, a.ints = a.ints[0], a.ints[1:]
	return x
}

func (a *array) pop() int {
	var x int
	x, a.ints = a.ints[len(a.ints)-1], a.ints[:len(a.ints)-1]
	return x
}

var results = make([]int, 0, 100000)

func walk(ints []int, curr, all int) {
	left := newArray(ints)
	right := newArray(ints)
	l := left.shift()
	r := right.pop()
	ld := l - curr
	if ld < 0 {
		ld += lDist
	}
	rd := curr - r
	if rd < 0 {
		rd += lDist
	}
	if len(ints) == 1 {
		results = append(results, all+ld)
		results = append(results, all+rd)
		return
	}
	walk(left.ints, l, all+ld)
	walk(right.ints, r, all+rd)
}

func main() {
	fmt.Scan(&lDist, &n)
	x := make([]int, n)
	for i := 0; i < n; i++ {
		fmt.Scan(&x[i])
	}
	walk(x, 0, 0)

	sort.Ints(results)
	fmt.Println(results[len(results)-1])
}

