		return (X[index] - position + L) % L
	}
	return (position - X[index] + L) % L
}
func guchoku(position, left, right int) int {
	if left+right == N {
		return max(getDistance(position, left, true), getDistance(position, left, false))
	}
	if_move_left := getDistance(position, left, true) + guchoku(X[left], left+1, right)
	if_move_right := getDistance(position, L-(right+1), false) + guchoku(X[L-right-1], left, right+1)
	fmt.Println(position, left, right, if_move_left, if_move_right)
	return max(if_move_left, if_move_right)
}

func solve() (ans int) {

	fmt.Scan(&L, &N)

	for n := 0; n < N; n++ {
		fmt.Scan(&X[n])
	}
	INF := 10000000
	// 300 points
	const V = 2001
	var dp [V][V][2] int;
	// dp[left][right][0_last_is_left]
	dp[1][0][0] = X[0]
	dp[1][0][1] = -INF
	dp[0][1][1] = L-X[N-1]
	dp[0][1][0] = -INF

	for total := 1; total < N; total++ {
		for left := 0; left <= total; left++ {

			right := total - left
			for last :=0 ;last <=1;last++{
				pos:= 0
				if last==0{
					if left==0{
						continue
					}
					pos = X[left-1]
				} else{
					if right==0{
						continue
					}
					pos = X[N-right]
				}

				// move left
				dp[left+1][right][0] = max(dp[left+1][right][0]  , dp[left][right][last]+getDistance(pos,left,true))
				// move right
				dp[left][right+1][1] = max(dp[left][right+1][1] , dp[left][right][last]+getDistance(pos,N-right-1,false))
			}
		}
	}
	for left:=0 ;left<= N; left++{
		right := N-left
		for last :=0 ;last <=1;last++ {
			update_if_over(&ans,dp[left][right][last])
		}
	}
	//ans = guchoku(0, 0, 0, )
	return ans
}

