func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Split(bufio.ScanWords)

	l := scanInt(sc)
	n := scanInt(sc)

	if n > 2000 {
		panic("give up!")
	}

	// 家から左回りでの距離
	xs := make([]int, n+2)

	// 家から右回りでの距離
	ys := make([]int, n+2)

	for i := 1; i <= n; i++ {
		xs[i] = scanInt(sc)
		ys[n+1-i] = l - xs[i]
	}

	// 家から左に i 本、右に j 本を燃やし、最後に到達したのが k 側 (0=左、1=右)
	// である時の最大移動距離を持つ dp[i][j][k].
	var dp [2002][2002][2]int

	// 家から左右への進み方を全て試す。 O(N^2)
	for i := 0; i <= n; i++ {
		for j := 0; j <= n; j++ {
			// 左側に進む場合
			chmax(&dp[i+1][j][0], dp[i][j][0]+xs[i+1]-xs[i])
			chmax(&dp[i+1][j][0], dp[i][j][1]+xs[i+1]+ys[j])

			// 右側に進む場合
			chmax(&dp[i][j+1][1], dp[i][j][1]+ys[j+1]-ys[j])
			chmax(&dp[i][j+1][1], dp[i][j][0]+xs[i]+ys[j+1])
		}
	}

	// 全部の木を燃やし終わるルートの移動距離のうち最大のものを探す。
	max := 0
	for i := 0; i <= n; i++ {
		chmax(&max, dp[i][n-i][0])
		chmax(&max, dp[i][n-i][1])
	}

	fmt.Println(max)
}

