package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

const (
	DIR_LEFT  = 0
	DIR_RIGHT = 1
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Split(bufio.ScanWords)

	l := scanInt(sc)
	n := scanInt(sc)

	// 家から左回りでの距離
	xs := make([]int, n+1)

	// 家から右回りでの距離
	ys := make([]int, n+1)

	for i := 1; i <= n; i++ {
		xs[i] = scanInt(sc)
		ys[n+1-i] = l - xs[i]
	}

	// それぞれの累積和
	cxs := make([]int, n+1)
	cys := make([]int, n+1)

	for i := 1; i <= n; i++ {
		cxs[i] = cxs[i-1] + xs[i]
		cys[i] = cys[i-1] + ys[i]
	}

	dirs := []int{DIR_LEFT, DIR_RIGHT}

	maxDist := 0
	for xt := 0; xt <= n; xt++ {
		yt := n - xt

		for _, startDir := range dirs {
			for _, endDir := range dirs {
				xm, ym := countMoves(startDir, endDir, xt, yt)
				if xm < 0 || ym < 0 {
					continue
				}

				var oneWay int
				if endDir == DIR_LEFT {
					oneWay = xs[xt]
				} else {
					oneWay = ys[yt]
				}

				roundTrips := (cxs[xt]-cxs[xt-xm])*2 + (cys[yt]-cys[yt-ym])*2
				dist := roundTrips - oneWay
				if dist > maxDist {
					maxDist = dist
				}
			}
		}
	}

	fmt.Println(maxDist)
}

func countMoves(startDir, endDir int, xt, yt int) (xm int, ym int) {
	switch startDir {
	case DIR_LEFT:
		switch endDir {
		case DIR_LEFT:
			// L,R,L,...,L
			xm = min(xt, yt+1)
			ym = min(xt-1, yt)
			return xm, ym

		case DIR_RIGHT:
			// L,R,L,...,R
			m := min(xt, yt)
			return m, m
		}
	case DIR_RIGHT:
		switch endDir {
		case DIR_LEFT:
			// R,L,R,...,L
			m := min(xt, yt)
			return m, m

		case DIR_RIGHT:
			// R,L,R,...,R
			xm = min(xt, yt-1)
			ym = min(xt+1, yt)
			return xm, ym
		}
	}

	panic("unreachable")
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func scanInt(sc *bufio.Scanner) int {
	sc.Scan()
	v, _ := strconv.Atoi(sc.Text())
	return v
}

