  }
  m := max64(x[n-1],y[n-1])
  for i:=n-1;i>0;i-- {
    j := n-i
    m = max64(m,x2[i-1]-x2[max32(i-j-1,0)]+y2[j]-y2[max32(j-i,0)]+x[i-1])
    m = max64(m,x2[i]-x2[max32(i-j,0)]+y2[j-1]-y2[max32(j-i-1,0)]+y[j-1])
  }
  fmt.Println(m)
