func solve(l, n int, a []int) int {
	count := 0
	var temp int
	for i := 0; i < len(a); i++ {
		if (a[i] - temp) > (a[n-1]-l-temp)*(-1) {
			count += a[i] - temp
			temp = a[i]
		} else if (a[i] - temp) < (a[n-1]-l-temp)*(-1) {
			count += (-1) * (a[n-1] - l - temp)
			temp = a[n-1] - l
		} else {
			if a[i+1]-temp > (a[n-2]-l-temp)*(-1) {
				count += a[i] - temp + a[i+1] - temp
				temp = a[i+1] - temp
				i++
			} else if a[i+1]-temp < (a[n-2]-l-temp)*(-1) {
				{
					count += a[i] - temp + (a[n-2]-l-temp)*(-1)
					temp = a[n-2] - l
					i++
				}

			}
		}
		fmt.Println(i, temp)
	}
	return count
}
