var lDist, n int

func newArray(ints []int) *array {
	return &array{ints[:]}
}

type array struct {
	ints []int
}

func (a *array) shift() int {
	var x int
	x, a.ints = a.ints[0], a.ints[1:]
	return x
}

func (a *array) pop() int {
	var x int
	x, a.ints = a.ints[len(a.ints)-1], a.ints[:len(a.ints)-1]
	return x
}

var results = make([]int, 0, 100000)

func walk(ints []int, curr, all int) {
	a := newArray(ints)
	l := ints[0]
	r := ints[len(ints)-1]
	ld := l - curr
	if ld < 0 {
		ld += lDist
	}
	rd := curr - r
	if rd < 0 {
		rd += lDist
	}
	if ld == rd {
		if len(ints) == 1 {
			results = append(results, all+ld)
			return
		}
		a.shift()
		walk(a.ints, l, all+ld)

		b := newArray(ints)
		b.pop()
		walk(b.ints, r, all+rd)
	}
	if ld > rd {
		if len(ints) == 1 {
			results = append(results, all+ld)
			return
		}
		a.shift()
		walk(a.ints, l, all+ld)
	} else {
		if len(ints) == 1 {
			results = append(results, all+rd)
			return
		}
		a.pop()
		walk(a.ints, r, all+rd)
	}
}

func main() {
	fmt.Scan(&lDist, &n)
	x := make([]int, n)
	for i := 0; i < n; i++ {
		fmt.Scan(&x[i])
	}
	walk(x, 0, 0)

	sort.Ints(results)
	fmt.Println(results[len(results)-1])
}

