#!/usr/bin/perl
my ($l,$n) = map { $_ - 0 } split(/\s+/,<STDIN>);
my @x=();
for(my $i=0;$i<$n;$i++){
  my ($x1) = map { $_ - 0 } split(/\s+/,<STDIN>);
  push(@x,$x1);
}
if( $n==1 ){
  print "$x[0]\n"; exit(0);
}
my $maxdist = -1;
for(my $i=0;$i<$n;$i++){  ## 最初にUターン場所を選ぶ
  for(my $d=-1;$d<=1;$d+=2){
    my $left = $n - 1;
    my $right = 0;
    my $cntb = 0;
    my $dist = 0;
    my $prev = -1;
    my $pos = -1;
    while($pos!=$i){
      $pos = ( ($prev==-1 ? ( $d<0 ? $n-1 : 0 ) : $pos + $d ) + $n ) % $n;
      $dist += ($prev==-1 ? ( $d<0 ? ($l-($x[$n-1])) : $x[0] ) : &dis($prev,$pos,$d) );
      $right ++ if $d>0;
      $left -- if $d<0;
      $cntb++;
      $prev = $pos;
    }
    my $td = -$d;
    while($cntb<$n){
      if( $td > 0 ){
        $pos = $right;
        $right = ($right + 1 ) % $n;
      } else {
        $pos = $left;
        $left  = ($left - 1 + $n) % $n;
      }
      $dist += &dis($prev,$pos,$td);
      $cntb++;
      $prev = $pos;
      $td = -$td;
    }
    $maxdist = $dist if $dist > $maxdist;
  }
}
print "$maxdist\n";
exit(0);

sub dis {
  my $prev = shift;
  my $pos = shift;
  my $d = shift;
  if( $pos > $prev ){
    return $x[$pos] - $x[$prev] if $d > 0;
    return $l - ($x[$pos] - $x[$prev]);
  } else {
    return $x[$prev]- $x[$pos] if $d < 0;
    return $l - ($x[$prev] - $x[$pos]);
  }
}

#!/usr/bin/env perl

use strict;
use warnings;
use feature 'say';

chomp(my $input = <STDIN>);
my ($ll, $nn) = split(/ /, $input);
my @xx;
for (1..$nn){
    chomp($input = <STDIN>);
    push(@xx ,$input);
}
my @jx = @xx;
my @gx = @xx;
my $jnow = shift(@jx);
my $gnow = pop(@gx);

my $jres = calc($ll, $nn - 1, \@jx, $jnow) + $jnow;
my $gres = calc($ll, $nn - 1, \@gx, $gnow) + $ll - $gnow;

if ($jres > $gres){
    say $jres;
}
else{
    say $gres;
}

sub calc{
    my $l = shift;
    my $n = shift;
    my $xx = shift;
    my @x = @$xx;
    my $now = shift;
    my $res = 0;
    my $pos = 0;
    my $jun;
    my $gyaku;

    for (1..$n){
        if ($x[0] > $now){
            $jun = $x[0] - $now;
        }else{
            $jun = $x[0] + ($l - $now);
        }
        if($x[-1] > $now){
            $gyaku = $now+ ($l - $x[-1]);
        }else{
            $gyaku = $now - $x[-1];
        }

        if ($jun > $gyaku){
            $pos = shift(@x);
            $res += $jun;
            $now = $pos;
#            say "t $res $pos"
        }
        else{
            $pos = pop(@x);
            $res += $gyaku;
            $now = $pos;
#            say "f $res $pos"
        }
    }
    return $res;
}

