sub calc{
    my $l = shift;
    my $x = shift;
    my $now = shift;
    my $d = shift;
    my @x = @$x;
    my $res = 0;
    my $r;
    while (@x > 0){
        if ($d eq 'l'){
            my $p = shift(@x);
            $r = $p > $now ? $p - $now : $l - $now + $p;
#            say "r: $r";
            $res += $r;
#            say "res: $res";
            $now = $p;
            $d = 'r';
#            say "---";
        }
        else{
