#!/usr/bin/perl
my ($l,$n) = map { $_ - 0 } split(/\s+/,<STDIN>);
my @x=();
for(my $i=0;$i<$n;$i++){
  my ($x1) = map { $_ - 0 } split(/\s+/,<STDIN>);
  push(@x,$x1);
}
if( $n==1 ){
  print "$x[0]\n"; exit(0);
}
my $maxdist = -1;
for(my $i=0;$i<$n;$i++){  ## 最初にUターン場所を選ぶ
  for(my $d=-1;$d<=1;$d+=2){
    my @b = (); $#b = $n-1;
    my $cntb = 0;
    my $dist = 0;
    my $prev = -1;
    my $pos = -1;
    while($pos!=$i){
      $pos = ( ($prev==-1 ? ( $d<0 ? $n-1 : 0 ) : $pos + $d ) + $n ) % $n;
      $dist += ($prev==-1 ? ( $d<0 ? ($l-($x[$n-1])) : $x[0] ) : &dis($prev,$pos,$d) );
      $b[$pos] = 1;
      $cntb++;
      $prev = $pos;
    }
    my $td = -$d;
    while($cntb<$n){
      while( $b[$pos] ){
        $pos = ( $pos + $td + $n ) % $n;
      }
      $dist += &dis($prev,$pos,$td);
      $b[$pos] = 1;
      $cntb++;
      $prev = $pos;
      $td = -$td;
    }
    $maxdist = $dist if $dist > $maxdist;
  }
}
print "$maxdist\n";
exit(0);

sub dis {
  my $prev = shift;
  my $pos = shift;
  my $d = shift;
  if( $pos > $prev ){
    return $x[$pos] - $x[$prev] if $d > 0;
    return $l - ($x[$pos] - $x[$prev]);
  } else {
    return $x[$prev]- $x[$pos] if $d < 0;
    return $l - ($x[$prev] - $x[$pos]);
  }
}

