	// 折り返さないのは i 番
	// sum xs[i - f .. i] * 2 + (l - xs[i]) + l * f * 2 - sum xs[i + 1 .. i + f] * 2

	long[] sum = [0]; // sum[i] は0からiの前までの和
	foreach(i; 0 .. n) sum ~= sum[$ - 1] + xs[i];

