long solve(int n, long L, long[] x) {
    auto y = x.map!(xi => L - xi).retro.array;

    auto xs = new long[](n + 1);
    foreach (i ; 0 .. n) {
        xs[i+1] = xs[i] + x[i];
    }

    auto ys = new long[](n + 1);
    foreach (i ; 0 .. n) {
        ys[i+1] = ys[i] + y[i];
    }

    debug {
        writeln("xs:", xs);
        writeln("y: ", y);
        writeln("ys:", ys);
    }

    long ans;

    foreach (i ; 1 .. n + 1) {
        int r = n - i;
        long tmp;

        if (i > r) {
            tmp = 2L * (xs[i] - xs[i - r - 1] + ys[r]) - x[i-1];
        }
        else {
            tmp = 2L * (xs[i] + ys[r] - ys[r - i]) - x[i-1];
        }

        debug {
            stderr.writefln("i: %d, tmp: %d", i, tmp);
        }

        ans = max(ans, tmp);
    }

    return ans;
}



























