string read(){ static string[] ss; while(!ss.length) ss = readln.chomp.split; string res = ss[0]; ss.popFront; return res; }

void main(){
	long l = read.to!long;
	long n = read.to!long;

	long[] xs;
	foreach(i; 0 .. n) xs ~= read.to!long;

	long[][] p; // 今原点より右にいて、右側i本と左側j本を焼いたときの最大値がp[k][i] // 0 < i; 0 <= j; i + j <= n
	long[][] q; // 今原点より左にいて、右側i本と左側j本を焼いたときの最大値がq[k][j] // 0 <= i; 0 < j; i + j <= n
	foreach(i; 0 .. n + 1){
		long[] tmp1, tmp2;
		foreach(j; 0 .. n + 1){
			tmp1 ~= -1, tmp2 ~= -1;
		}
		p ~= tmp1, q ~= tmp2;
	}

	p[1][0] = xs[0];
	q[0][1] = l - xs[n - 1];

	// p[i][0] は p[i - 1][0] + (xs[i] - xs[i - 1])
	// q[0][j] は q[i - 1][j] + (xs[n - j] - xs[n - j + 1])

	foreach(i; 1 .. n + 1){
		if(i > 1) p[i][0] = p[i - 1][0] + (xs[i - 1] - xs[i - 2]);
		q[i][1] = p[i][0] + (xs[i - 1] + l - xs[n - 1]);
	}
	foreach(j; 1 .. n + 1){
		if(j > 1) q[0][j] = q[0][j - 1] + (xs[n - j + 1] - xs[n - j]);
		p[1][j] = q[0][j] + (xs[0] + l - xs[n - j]);
