def makeLinkedList(arr):
    linkedList= {}
    N=len(arr)
    for i in range(N):
        linkedList[arr[i]]={'Left':arr[i-1], 'Right':arr[(i+1)%N]}
    return linkedList

def linkedListPop(linkedList, key):
    left=linkedList[key]['Left']
    right=linkedList[key]['Right']

    linkedList[left]['Right']=right
    linkedList[right]['Left']=left
    linkedList.pop(key)
    return len(linkedList)

def walk(linkedList, now, dist, L):
    left=linkedList[now]['Left']
    right=linkedList[now]['Right']

    listN=linkedListPop(linkedList,now)
    if listN==0:
        return dist

    distL=now-left
    distR=right-now
    if distL<0:
        distL+=L
    if distR<0:
        distR+=L

    if distL>distR:
        return walk(linkedList, left, dist+distL,L)
    elif distL<distR:
        return walk(linkedList, right, dist+distR,L)
    else:
        linkedList2=copy.deepcopy(linkedList)
        return max(walk(linkedList, left, dist+distL,L),walk(linkedList2, right, dist+distR,L))

