def far(x):
    f = len(x)
    if f <3:
        return False
    else:
        s = 0
        while (x[s+1]-x[s]) == (x[f-s-1]-x[f-s-2]) and s < f//2:
            s += 1
        return (x[s+1]-x[s]) >= (x[f-s-1]-x[f-s-2])

def burn(x,p,w):
    if len(x) == 1:
        return w + max(abs(x[0]-p),abs(l-abs(x[0]-p)))
    elif p != 0:
        y = [] + x
        for i in range(len(x)):
            if x[i] > p:
                y[i] = x[i] -p
            else:
                y[i] = x[i] -p+l
        return burn(y,0,w)

    else:
        if x[0] > (l-x[len(x)-1]) or far(x):
            p = x[0]
            del x[0]
            w2 = w+p
            return burn(x,p,w2)
        else:
            p = x[len(x)-1]
            del x[len(x)-1]
            w2 = w+l-p
            return burn(x,p,w2)  

