        long long mid = L-X[i+1];
        long long right = 2*(-Y[i+k]+Y[i+1])+2*(k-1)*L;
        ret = max(ret, left+mid+right);
    }
    return ret;
}

long long solve1(long long N, long long L, vector<long long> &X){
    vector<long long> Y(N+2, 0);
    for(long long i=1; i<=N; i++)
        Y[i] = Y[i-1] + X[i];

    long long ret = 0;
    for(long long i=1; i<N; i++){
        long long k = min(i, N-i+1);
        long long left = X[i] + 2*(Y[i-1] - Y[i-k]);
        long long right = 2*(-Y[i+k-1]+Y[i])+2*(k-1)*L;
        ret = max(ret, left+right);
    }
    return ret;
}

