class obj():
    def __init__(self, x):
        self.x = x
        self.previous = None
        self.next = None

    def get_previous(self, taken):
        p = self.previous
        while p.x in taken:
            p = p.previous
        return p

    def get_next(self, taken):
        n = self.next
        while n.x in taken:
            n = n.next
        return n

    def __str__(self):
        return "%d (previous : %d, next : %d" % (self.x, self.previous.x, self.next.x)

    def far(self, L):
        p = L - self.previous.x + self.x
        n = self.next.x - self.x
        if p >= n:
            return p, self.previous
        else:
            return n, self.next


def solve(L, N, Xs):
    linkedlist = [obj(0)]
    for x in Xs:
        o = obj(x)
        if len(linkedlist):
            o.previous = linkedlist[-1]
            linkedlist[-1].next = o
        linkedlist.append(o)

    linkedlist[0].previous = linkedlist[-1]
    linkedlist[-1].next = linkedlist[0]

    i = linkedlist[0]
    ans = 0
    def dfs(i, taken, linkedlist, ans):
        if len(taken) == len(linkedlist):
            return ans
        pp = i.get_previous(taken)
        nn = i.get_next(taken)
        p_d = i.x - pp.x if pp.x < i.x else L - pp.x + i.x
        n_d = nn.x - i.x if nn.x > i.x else L - i.x + nn.x

        p = dfs(pp, taken + [pp.x], linkedlist, ans + p_d)
        n = dfs(nn, taken + [nn.x], linkedlist, ans + n_d)
        return max(p, n)
    return dfs(linkedlist[0], [0], linkedlist, 0)

