def solve(pos, trees, d):
    if not trees:
        return 0

    a = distance_anticlockwise(pos, trees[0], d) + solve(trees[0], trees[1:], d)
    b = distance_clockwise(pos, trees[-1], d) + solve(trees[-1], trees[:-1], d)
    return max(a, b)

def distance_anticlockwise(a, b, d):
    if a < b:
        return b - a
    else:
        return d - a + b

def distance_clockwise(a, b, d):
    if a > b:
        return a - b
    else:
        return a + d - b

