def sa(your_location, point, kaiten):
    global length
    if kaiten:
        if point > your_location:
            sasa = point - your_location
        else:
            sasa = length + point - your_location
    else:
        if point < your_location:
            sasa = your_location - point
        else:
            sasa = length + your_location - point
    return sasa


def serch_next(index, arrive_flg):
    global tree_num
    for i in range(1, tree_num):
        if arrive_flg[index - i] == 0:
            pre_locate = index - i
            break
    for i in range(1, tree_num):
        if arrive_flg[(index + i) % tree_num] == 0:
            next_locate = index + i
            break
    return pre_locate, next_locate


def go_tree(index, now_location, sum_walk, arrive_flg_ori, kaiten, pre_kaiten):
    global length, location, tree_num, ans
    arrive_flg = arrive_flg_ori.copy()
    # print(ans)
    sum_walk += sa(now_location, location[index], kaiten)
    arrive_flg[index] = 1
    # print(arrive_flg)
    if all(arrive_flg):
        if sum_walk > ans:
            ans = sum_walk
        return
    pre_locate, next_locate = serch_next(index, arrive_flg)

    if kaiten == 0 and pre_kaiten == 0:
        go_tree(next_locate, location[index], sum_walk, arrive_flg, 1, kaiten)
    elif kaiten == 1 and pre_kaiten == 1:
        go_tree(pre_locate, location[index], sum_walk, arrive_flg, 0, kaiten)
    else:
        go_tree(pre_locate, location[index], sum_walk, arrive_flg, 0, kaiten)
        go_tree(next_locate, location[index], sum_walk, arrive_flg, 1, kaiten)



