class obj():
    def __init__(self, x):
        self.x = x
        self.previous = None
        self.next = None

    def objcopy(self):
        o = obj(self.x)
        o.next = self.next
        o.previous = self.previous
        return o

    def __str__(self):
        return "%d (previous : %d, next : %d" % (self.x, self.previous.x, self.next.x)


def slow_solve(L, N, Xs):
    linkedlist = [obj(0)]
    for x in Xs:
        o = obj(x)
        if len(linkedlist):
            o.previous = linkedlist[-1]
            linkedlist[-1].next = o
        linkedlist.append(o)
    linkedlist[0].previous = linkedlist[-1]
    linkedlist[-1].next = linkedlist[0]
    memo = {}

    def dfs(i, taken):
        if len(taken) == N + 1:
            return 0
        key = (i.x, tuple(sorted(taken)))
        if key in memo:
            return memo[key]
        pp = i.previous.objcopy()
        nn = i.next.objcopy()
        p_d = i.x - pp.x if pp.x < i.x else L - pp.x + i.x
        n_d = nn.x - i.x if nn.x > i.x else L - i.x + nn.x

        pp.next = i.next
        nn.previous = i.previous
        p = dfs(pp, taken + [pp.x]) + p_d
        n = dfs(nn, taken + [nn.x]) + n_d
        memo[key] = max(p, n)
        return memo[key]

    return dfs(linkedlist[0], [0])


