def max_dist(now = 0, subset = X):
    if len(subset) == 1:
        return max(dist(now, subset[0], 0), dist(now, subset[0], 1))

    c_clock = dist(now, subset[0], 0) + max_dist(subset[0], subset[1:])
    clock = dist(now, subset[-1], 1) + max_dist(subset[-1], subset[:-1])
    return max(clock, c_clock)

