    }
    std::mem::swap(&mut xs_sums, &mut l_xs_sums);
    let mut xs_sums = vec![0; n + 1];
    for i in 1..n + 1 {
        xs_sums[i] = xs_sums[i - 1] + xs[n - i];
    }
