macro_rules! my_write {
  ($writer:expr, $args:expr) => {
    $writer.write($args).unwrap()
  };
  ($writer:expr, $($args:expr),*) => {
    {
      let mut buf = Vec::new();
      $(buf.write($args).unwrap();)*
      $writer.write(&buf).unwrap()
    }
  };
}

use std::io::{ stdin, stdout, Write };

#[inline(always)]
fn agc030_b() {
  let stdin  = stdin();
  let stdout = stdout();
  let mut scanner = my::Scanner::with_capacity(12, stdin.lock());
  let mut writer  = stdout.lock();
  let mut itoa    = my::ItoA::with_capacity(10);

  let l = my::atoui::<usize>(scanner.read_until(my::SP));
  let n = my::atoui::<usize>(scanner.read_until(my::LF));

  let mut vec = scanner.fold(n, my::LF, Vec::with_capacity(n), | mut v, s | {
    v.push(my::atoui::<usize>(s));
    v
  });

  let mut ans = 0;
  let mut pos = 0;

  let mut i = 0;
  let mut j = vec.len() - 1;
  let mut x = 0;
  let mut y = 0;


  if vec[i] >= l - vec[j] {
    pos = vec.remove(0);
    ans += pos;
  } else {
    ans += l - vec[j];
    pos = vec.remove(j);
  }
  if vec.len() > 0 {
    j = vec.len() - 1;
  }

  while vec.len() > 0 {
    if vec[i] < pos {
      x = l - pos + vec[i];
      y = pos - vec[j];
    } else {
      x = vec[i] - pos;
      y = l - vec[j] + pos;
    }

    if x >= y {
      pos  = vec.remove(0);
      ans += x;
    } else {
      ans += y;
      pos = vec.remove(j);
    }
    if vec.len() > 0 {
      j = vec.len() - 1;
    }
  }

  my_write!(writer, itoa.from_usize(ans), b"\n");
  writer.flush().unwrap();
}

fn main() {
  agc030_b();
}

