impl Sub {

fn burning_tree(&self, trees :&Vec<u32>, is_cclock :bool, sp :u32) -> u64
{
    let mut cur = if {is_cclock} {0} else {self.l};
    let mut ans :u64 = 0;
    let mut tr_ac: Vec<_> = trees.iter().cloned().collect();
    let mut tr_st: Vec<_> = self.st.iter().cloned().collect();
    //tr_st.sort_unstable();
    //println!("{:?}", trees);
    for ni in 0..self.n {
        let next = tr_ac[0];
        let head = tr_st[0];
        let tail = match tr_st.last() {Some(v) =>{*v}, None => {0}, };
        let mut m = 0;
        let mut d_anti = m;
        //let mut d_cloc = m;
        //println!("tr_ac: {:?}", tr_ac);
        //println!("(C, H, T) = ({}, {}, {})", cur, head, tail);
        if ni >= sp {
            //println!("trace1 : {} -> {}", cur, next);
            //let d_anti = if {next == head} {
            d_anti = if {next == head} {
                    if {next > cur} {next - cur} else {(self.l-cur) + next}
                } else {0};
            let d_cloc = if {next == tail} {
                    if {next < cur} {cur - next} else {(self.l-next) + cur}
                } else {0};
            let ds = [d_anti, d_cloc];
            //println!("ds :{:?}", ds);
            let tm = ds.iter().max().unwrap();
            m = *tm;
        } else {
            //println!("trace2 : {}", ni);
            if is_cclock {
                m = next - cur;
                d_anti = m;
            } else {
                m = cur - next;
                //d_cloc = m;
            }
        }
        ans += m as u64;
        //println!("m = {} -> ans = {}", m, ans);
        cur = tr_ac[0];
        tr_ac.remove(0);
        if {m == d_anti} {
            tr_st.remove(0);
        } else {
            tr_st.pop();
        }
    }
    ans
}

