fn dfs(xs: &Vec<i64>, length: i64, memo: &mut Vec<Vec<Vec<i64>>>, l: usize, r: usize, prev_is_right: bool) -> i64 {
    if memo[l][r][ite!(prev_is_right,1,0)] >= 0 {
        return memo[l][r][ite!(prev_is_right,1,0)];
    }
    let prev = if prev_is_right {
        r - 1
    } else {
        l + 1
    };
    if l == r {
        let t = (xs[prev] - xs[l]).abs();
        return max(t, length - t);
    }
    // clockwise
    let t1 = (xs[r] - xs[prev] + 3 * length) % length;
    let res1 = dfs(xs, length, memo, l, r+1, true) + t1;
    // counter clockwise
    let t2 = (xs[prev] - xs[l] + 3 * length) % length;
    let res2 = dfs(xs, length, memo, l-1, r, false) + t2;
    let res = max(res1, res2);
    memo[l][r][ite!(prev_is_right,1,0)] = res;
    return res;
}

fn main() {
    input! {
        length: i64,
        n: usize,
        xs: [i64; n],
    }
    if n == 1 {
        let t = xs[0];
        let res = max(t, length - t);
        println!("{}", res);
        return;
    }
    if n <= 3000 {
        let mut memo = vec![vec![vec![-1; 2]; n]; n];
        let res1 = dfs(&xs, length, &mut memo, n-1, 1, true) + xs[0];
        let res2 = dfs(&xs, length, &mut memo, n-2, 0, false) + (length - xs[n-1]);
        let res = max(res1, res2);
        println!("{}", res);
    }
    else {
        println!("-1");
    }
}

