fn solve(l: isize, x: &[isize]) -> isize {
    fn get(l: isize, c: isize, x: &[isize]) -> isize {
        if x.len() == 0 {
            return 0;
        }
        let x0 = x[0];
        let x1 = x[x.len() - 1] - l;

        let d0 = x0 - c;
        let d1 = -(x1 - c);
        max(get(l, x0, &x[1..]) + d0, get(l, x1, &x[..x.len() - 1]) + d1)
    }
    get(l, 0, x)
}

