use std::cmp;
use std::collections::{BTreeMap, VecDeque};

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { reader: s.lock() };
    let l: usize = sc.read();
    let n = sc.read();
    assert!(n <= 2000);
    let x: Vec<usize> = sc.read_vec(n);
    let mut map: BTreeMap<(usize, usize, usize), usize> = BTreeMap::new();
    let mut q = VecDeque::new();
    let mut ans = 0;
    q.push_back((0, n - 1, 0, 0));
    map.insert((0, n - 1, 0), 0);
    while let Some((head, tail, pos, score)) = q.pop_back() {
        if *map.get(&(head, tail, pos)).unwrap() != score {
            continue;
        }
        if head == tail {
            let add = if x[tail] < pos {
                cmp::max(pos - x[tail], l - pos + x[tail])
            } else {
                cmp::max(x[tail] - pos, pos + l - x[tail])
            };
            ans = cmp::max(ans, score + add);
        } else {
            let (right, left) = if pos > x[tail] {
                (x[head] + l - pos, pos - x[tail])
            } else {
                (x[head] - pos, l - x[tail] + pos)
            };

            let cur_right = *map.entry((head + 1, tail, x[head])).or_insert(0);
            if cur_right < score + right {
                map.insert((head + 1, tail, x[head]), score + right);
                q.push_back((head + 1, tail, x[head], score + right));
            }

            let cur_left = *map.entry((head, tail - 1, x[head])).or_insert(0);
            if cur_left < score + left {
                map.insert((head, tail - 1, x[tail]), score + left);
                q.push_back((head, tail - 1, x[tail], score + left));
            }
        }
    }

    println!("{}", ans);
}

pub struct Scanner<R> {
    reader: R,
}

impl<R: std::io::Read> Scanner<R> {
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .reader
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n')
            .take_while(|&b| b != b' ' && b != b'\n')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn read_vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

