    for i in 1..(nn+1) {
        scramble_vec(&mut xtree, i);
        let a = sub.burning_tree(&xtree, false, (xtree.len() as u32) - i);
        //println!(": {}", a);
        if a > dmax2 {
            dmax2 = a;
        } else {
            break;
        }
    }
    //println!("{}", dmax2);

    let dmx = if {dmax1 > dmax2} {dmax1} else {dmax2};
    println!("{}", dmx);
}

use std::cmp::*;
use std::io::*;
use std::str::FromStr;
use utils::*;

pub fn main() {
    let i = stdin();
    let mut o = Vec::new();
    run(i.lock(), &mut o);
    stdout().write_all(&o).unwrap();
}

fn run<R: BufRead, W: Write>(i: R, o: &mut W) {
    let mut i = CpReader::new(i);
    let (l, n) = i.read2::<isize, usize>();
    let mut x = Vec::new();
    for _ in 0..n {
        x.push(i.read::<isize>());
    }

    writeln!(o, "{}", solve(l, &x)).unwrap();
}
fn solve(l: isize, x: &[isize]) -> isize {
    let inf = isize::min_value();

    let count = x.len();

    let mut x = x.to_vec();
    x.insert(0, 0);
    x.insert(0, 0);
    x.push(l);
    x.push(l);

    // r[n] 順方向にn本、逆方向にi-n本焼いた場合の総移動距離
    // r[n].0 : 最後に順方向に焼いた場合
    // r[n].1 : 最後に逆方向に焼いた場合
    let mut r = vec![(inf, inf); x.len() + 1];
    r[1] = (0, 0);

    // i : 燃した木の本数（スコープの後の状態）
    for i in 1..count + 1 {
        // 逆方向に燃やした木の本数（スコープの後の状態）
        for j in (0..i + 1).rev() {
            let b = j + 1;
            let b0 = i - j + 1; // 最後に順方向に燃やした木のインデックス（スコープ後の状態）
            let b1 = count - j + 2; // 最後に逆方向に燃やした木のインデックス（スコープ後の状態）

            // 順方向に燃やす
            r[b].0 = max(
                r[b].0 + x[b0] - x[b0 - 1],   // 順→順
                r[b].1 + x[b0] + (l - x[b1]), // 逆→順
            );

            // 逆方向に燃やす
            r[b].1 = max(
                r[b - 1].0 + (l - x[b1]) + x[b0],           // 順→逆
                r[b - 1].1 + (l - x[b1]) - (l - x[b1 + 1]), // 逆→逆
            );
        }
    }
    let mut m = isize::min_value();
    for i in r {
        m = max(m, i.0);
        m = max(m, i.1);
    }
    m
}

mod utils {
    use super::*;

    pub struct CpReader<R: BufRead> {
        r: R,
        s: String,
    }

    macro_rules! fn_read {
        { $f:ident($($t:ident),*) } => {
            #[allow(dead_code)]
            pub fn $f<$($t: FromStr),*>(&mut self) -> ($($t),*) {
                let i = &mut self.read_line().split(' ');
                ($(read_next::<$t,_>(i)),*)
            }
        };
    }

    impl<R: BufRead> CpReader<R> {
        pub fn new(r: R) -> Self {
            CpReader {
                r: r,
                s: String::new(),
            }
        }
        pub fn read_line(&mut self) -> &str {
            self.s.clear();
            self.r.read_line(&mut self.s).unwrap();
            self.s.trim()
        }

        pub fn read<T: FromStr>(&mut self) -> T {
            self.read_line().parse().ok().unwrap()
        }
        fn_read! { read2(T1, T2) }
        fn_read! { read3(T1, T2, T3) }
        fn_read! { read4(T1, T2, T3, T4) }
        fn_read! { read5(T1, T2, T3, T4, T5) }
    }
    fn read_next<'a, T: FromStr, I: Iterator<Item = &'a str>>(i: &mut I) -> T {
        i.next().unwrap().parse().ok().unwrap()
    }

}

fn read<T: std::str::FromStr>() -> T {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).ok();
    s.trim().parse().ok().unwrap()
}

fn read_vec<T: std::str::FromStr>() -> Vec<T> {
    read::<String>()
        .split_whitespace()
        .map(|e| e.parse().ok().unwrap())
        .collect()
}

fn main() {
    let v = read_vec::<u64>();
    let (l, n) = (v[0], v[1]);
    let n = n as usize;
    let mut xs: Vec<u64> = (0..n).map(|_| read::<u64>()).collect();
    let mut l_xs: Vec<u64> = (0..n).map(|i| l - xs[i]).collect();

    if n == 1 {
        println!("{:?}", std::cmp::max(xs[0], l_xs[0]));
        return;
    }

    let mut xs_sums = vec![0u64; n + 1];
    for i in 1..n + 1 {
        xs_sums[i] = xs_sums[i - 1] + xs[i - 1];
    }

    let mut l_xs_sums = vec![0u64; n + 1];
    for i in 1..n + 1 {
        l_xs_sums[i] = l_xs_sums[i - 1] + l_xs[i - 1];
    }

    let mut ans = 0;
    for i in 0..n {
        let mut temp_ans = 0;
        temp_ans += 2 * (xs_sums[(n - 2 + i) / 2 + 1] - xs_sums[i]);
        temp_ans += 2 * (l_xs_sums[n - 1 + 1] - l_xs_sums[(n + i) / 2  + 1]);
        if (n + i) % 2 == 0 {
            temp_ans += l_xs[(n + i) / 2];
        } else {
            temp_ans += xs[(n + i) / 2];
        }
        // println!("{:?}", temp_ans);
        ans = std::cmp::max(ans, temp_ans);
    }
    xs.reverse();
    l_xs.reverse();
    std::mem::swap(&mut xs, &mut l_xs);

    let mut xs_sums = vec![0u64; n + 1];
    for i in 1..n + 1 {
        xs_sums[i] = xs_sums[i - 1] + xs[i - 1];
    }

    let mut l_xs_sums = vec![0u64; n + 1];
    for i in 1..n + 1 {
        l_xs_sums[i] = l_xs_sums[i - 1] + l_xs[i - 1];
    }

    for i in 0..n {
        let mut temp_ans = 0;
        temp_ans += 2 * (xs_sums[(n - 2 + i) / 2 + 1] - xs_sums[i]);
        temp_ans += 2 * (l_xs_sums[n - 1 + 1] - l_xs_sums[(n + i) / 2  + 1]);
        if (n + i) % 2 == 0 {
            temp_ans += l_xs[(n + i) / 2];
        } else {
            temp_ans += xs[(n + i) / 2];
        }
        // println!("l temp {:?}", temp_ans);
        ans = std::cmp::max(ans, temp_ans);
    }

    println!("{:?}", ans);
}

